module adder(
    input  [15:0] a,
    input  [15:0] b,
    output reg [16:0] sum
);

integer i;
reg carry;
always @(*) begin
    carry = 1'b0;
    // Loop through each bit
    for (i = 0; i < 16; i = i + 1) begin
        sum[i] = a[i] ^ b[i] ^ carry;
        carry = (a[i] & b[i]) | (a[i] & carry) | (b[i] & carry);
    end
    sum[16] = carry;
end

endmodule

