module xor8(
    input        clk,
    input  [7:0] A,
    input  [7:0] B,
    output reg [7:0] X
);
    // Internal wires for XOR results
    wire [7:0] xor_result;

    // XOR operation using basic gates for each bit
    genvar i;
    generate
        for (i = 0; i < 8; i = i + 1) begin : xor_bit
            assign xor_result[i] = (A[i] & ~B[i]) | (~A[i] & B[i]);
        end
    endgenerate

    // Output register updated on rising edge of clk
    always @(posedge clk) begin
        X <= xor_result;
    end

endmodule

