module dff_async_reset (
    input wire clk,
    input wire d,
    input wire r,
    output reg q
);

always @(negedge clk or posedge r) begin
    if (r)
        q <= 1'b1;
    else
        q <= d;
end

endmodule

module_interface:
module dff_async_reset (
    input wire clk,
    input wire d,
    input wire r,
    output reg q
);

test:
`timescale 1ns/1ps

module dff_async_reset_tb;

    // DUT signals
    reg clk;
    reg d;
    reg r;
    wire q;

    // File handling
    integer fd;
    integer error_count;
    integer vector_count;
    integer i;

    // Reference model
    reg ref_q;

    // Timeout parameters
    parameter TIMEOUT = 10000;

    // Instantiate DUT
    dff_async_reset dut (
        .clk(clk),
        .d(d),
        .r(r),
        .q(q)
    );

    // Clock generation: 10ns period
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    // Task to check output and report errors
    task check_output;
        input [0:0] expected_q;
        begin
            if (q !== expected_q) begin
                $display("ERROR at time %0t: d=%b r=%b q=%b (expected %b)", $time, d, r, q, expected_q);
                error_count = error_count + 1;
            end
        end
    endtask

    // Reference model update
    task update_ref_q;
        input clk_event;
        input r_event;
        begin
            if (r_event)
                ref_q = 1'b1;
            else if (clk_event)
                ref_q = d;
        end
    endtask

    // Main stimulus
    initial begin
        // File open
        fd = $fopen("test_vectors.txt", "w");
        if (fd) $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        // Initialize
        d = 0;
        r = 0;
        ref_q = 1'bx;
        error_count = 0;
        vector_count = 0;

        // Write header (optional)
        // $fdisplay(fd, "clk d r q");

        // Apply reset initially
        @(negedge clk);
        d = 0; r = 1;
        @(negedge clk);
        update_ref_q(0, 1);
        #1;
        $fdisplay(fd, "%b %b %b %b", clk, d, r, q);
        check_output(ref_q);
        vector_count = vector_count + 1;

        r = 0;
        @(negedge clk);
        update_ref_q(1, 0);
        #1;
        $fdisplay(fd, "%b %b %b %b", clk, d, r, q);
        check_output(ref_q);
        vector_count = vector_count + 1;

        // Generate 100+ test vectors with various input sequences
        for (i = 0; i < 100; i = i + 1) begin
            // Randomize d and r
            d = $random % 2;
            // Occasionally assert reset
            if ((i % 10) == 0)
                r = 1;
            else
                r = $random % 2;

            // Apply at posedge r (async reset)
            if (r) begin
                @(posedge r);
                update_ref_q(0, 1);
                #1;
                $fdisplay(fd, "%b %b %b %b", clk, d, r, q);
                check_output(ref_q);
                vector_count = vector_count + 1;
                r = 0;
            end

            // Apply at negedge clk (data capture)
            @(negedge clk);
            update_ref_q(1, 0);
            #1;
            $fdisplay(fd, "%b %b %b %b", clk, d, r, q);
            check_output(ref_q);
            vector_count = vector_count + 1;
        end

        // Additional edge cases: toggle reset and data rapidly
        d = 1; r = 1;
        @(posedge r);
        update_ref_q(0, 1);
        #1;
        $fdisplay(fd, "%b %b %b %b", clk, d, r, q);
        check_output(ref_q);
        vector_count = vector_count + 1;

        r = 0;
        @(negedge clk);
        update_ref_q(1, 0);
        #1;
        $fdisplay(fd, "%b %b %b %b", clk, d, r, q);
        check_output(ref_q);
        vector_count = vector_count + 1;

        d = 0;
        @(negedge clk);
        update_ref_q(1, 0);
        #1;
        $fdisplay(fd, "%b %b %b %b", clk, d, r, q);
        check_output(ref_q);
        vector_count = vector_count + 1;

        // Close file and finish
        $display("Total test vectors: %0d", vector_count);
        $display("Total errors: %0d", error_count);
        $fclose(fd);
        $finish;
    end

    // Timeout mechanism
    initial begin
        #TIMEOUT;
        $display("TIMEOUT: Simulation did not finish within %0d ns", TIMEOUT);
        $fclose(fd);
        $finish;
    end

endmodule

