module magnitude_comparison (
  input [3:0] A,
  input [3:0] B,
  output reg eq,
  output reg gt
);

  always @(*) begin
    eq = (A == B);
    gt = (A > B);
  end

endmodule

module_interface:
module magnitude_comparison (
  input [3:0] A,
  input [3:0] B,
  output reg eq,
  output reg gt
);

test:
`timescale 1ns/1ps

module magnitude_comparison_tb;

  // Inputs
  reg [3:0] A;
  reg [3:0] B;

  // Outputs
  wire eq;
  wire gt;

  // Internal variables
  integer fd;
  integer i, j;
  integer test_count;
  integer error_count;
  reg expected_eq;
  reg expected_gt;

  // Timeout parameters
  parameter TIMEOUT = 10000;

  // Instantiate the Unit Under Test (UUT)
  magnitude_comparison uut (
    .A(A),
    .B(B),
    .eq(eq),
    .gt(gt)
  );

  // Task to check outputs and report errors
  task check_outputs;
    input [3:0] A_in;
    input [3:0] B_in;
    input eq_out;
    input gt_out;
    input exp_eq;
    input exp_gt;
    begin
      if ((eq_out !== exp_eq) || (gt_out !== exp_gt)) begin
        $display("ERROR: A=%0d B=%0d | eq=%0d(gt=%0d) expected eq=%0d(gt=%0d) at time %0t", 
                  A_in, B_in, eq_out, gt_out, exp_eq, exp_gt, $time);
        error_count = error_count + 1;
      end
    end
  endtask

  // Timeout mechanism
  initial begin
    #TIMEOUT;
    $display("ERROR: Simulation timed out at time %0t", $time);
    $finish;
  end

  // Main test process
  initial begin
    fd = $fopen("test_vectors.txt", "w");
    if (fd) $display("File opened successfully");
    else begin
      $display("Failed to open file");
      $finish;
    end

    error_count = 0;
    test_count = 0;

    // Test all possible combinations for 4-bit inputs (256 vectors)
    for (i = 0; i < 16; i = i + 1) begin
      for (j = 0; j < 16; j = j + 1) begin
        A = i;
        B = j;
        #1; // Wait for combinational logic to settle

        // Compute expected outputs
        expected_eq = (A == B);
        expected_gt = (A > B);

        // Write test vector to file: A B eq gt
        $fdisplay(fd, "%0d %0d %0d %0d", A, B, eq, gt);

        // Check outputs
        check_outputs(A, B, eq, gt, expected_eq, expected_gt);

        test_count = test_count + 1;
      end
    end

    $display("Test completed: %0d vectors tested, %0d errors found.", test_count, error_count);

    $fclose(fd);
    $finish;
  end

endmodule

