                2'b00: get_expected = {din[2:0], 1'b0};             // Logical left shift by 1
                2'b01: get_expected = {1'b0, din[3:1]};             // Logical right shift by 1
                2'b10: get_expected = {din[2:0], din[3]};           // Rotate left by 1
