module async_reset_release (
  input rst,
  input clk,
  input enable,
  output reg rst_release
);

parameter delay_count = 10;

reg [7:0] delay_counter;

always @(posedge clk) begin
  if (rst) begin
    rst_release <= 0;
    delay_counter <= 0;
  end else if (enable) begin
    if (delay_counter < delay_count) begin
      delay_counter <= delay_counter + 1;
    end else begin
      rst_release <= 1;
    end
  end
end

endmodule

module_interface:
module async_reset_release (
  input rst,
  input clk,
  input enable,
  output reg rst_release
);

test:
`timescale 1ns/1ps

module async_reset_release_tb;

  // DUT signals
  reg rst;
  reg clk;
  reg enable;
  wire rst_release;

  // Parameters
  parameter delay_count = 10;

  // File handling
  integer fd;
  integer error_count;
  integer vector_count;

  // Timeout
  integer TIMEOUT = 10000;

  // Instantiate DUT
  async_reset_release #(.delay_count(delay_count)) dut (
    .rst(rst),
    .clk(clk),
    .enable(enable),
    .rst_release(rst_release)
  );

  // Clock generation
  initial begin
    clk = 0;
    forever #5 clk = ~clk;
  end

  // Testbench variables
  reg [7:0] expected_delay_counter;
  reg expected_rst_release;
  reg [7:0] observed_delay_counter;
  reg [7:0] i;
  reg [7:0] j;
  reg [7:0] k;

  // Internal access to DUT's delay_counter for checking (SystemVerilog would use hierarchical reference, but for pure Verilog, we skip this)
  // Instead, we track expected behavior in the testbench

  // Task to check outputs
  task check_outputs;
    input reg exp_rst_release;
    begin
      if (rst_release !== exp_rst_release) begin
        $display("ERROR at time %0t: rst=%b clk=%b enable=%b | rst_release=%b (expected %b)", $time, rst, clk, enable, rst_release, exp_rst_release);
        error_count = error_count + 1;
      end
    end
  endtask

  // Timeout mechanism
  initial begin
    #TIMEOUT;
    $display("TIMEOUT: Simulation exceeded %0d time units", TIMEOUT);
    $fclose(fd);
    $finish;
  end

  // Main test process
  initial begin
    error_count = 0;
    vector_count = 0;
    rst = 0;
    enable = 0;

    // Open file
    fd = $fopen("test_vectors.txt", "w");
    if (fd) $display("File opened successfully");
    else begin
      $display("Failed to open file");
      $finish;
    end

    // Write header (optional)
    // $fdisplay(fd, "rst clk enable | rst_release");

    // 1. Test reset behavior
    @(negedge clk);
    rst = 1; enable = 0;
    @(negedge clk);
    $fdisplay(fd, "%b %b %b %b", rst, clk, enable, rst_release);
    check_outputs(0);
    vector_count = vector_count + 1;

    // Keep reset asserted for a few cycles
    for (i = 0; i < 3; i = i + 1) begin
      @(negedge clk);
      $fdisplay(fd, "%b %b %b %b", rst, clk, enable, rst_release);
      check_outputs(0);
      vector_count = vector_count + 1;
    end

    // 2. Release reset, enable low
    rst = 0; enable = 0;
    @(negedge clk);
    $fdisplay(fd, "%b %b %b %b", rst, clk, enable, rst_release);
    check_outputs(0);
    vector_count = vector_count + 1;

    // 3. Enable high, count up to delay_count
    enable = 1;
    expected_rst_release = 0;
    for (i = 0; i < delay_count; i = i + 1) begin
      @(negedge clk);
      $fdisplay(fd, "%b %b %b %b", rst, clk, enable, rst_release);
      check_outputs(0);
      vector_count = vector_count + 1;
    end

    // After delay_count cycles, rst_release should go high
    @(negedge clk);
    expected_rst_release = 1;
    $fdisplay(fd, "%b %b %b %b", rst, clk, enable, rst_release);
    check_outputs(1);
    vector_count = vector_count + 1;

    // Keep enable high, rst_release should stay high
    for (i = 0; i < 5; i = i + 1) begin
      @(negedge clk);
      $fdisplay(fd, "%b %b %b %b", rst, clk, enable, rst_release);
      check_outputs(1);
      vector_count = vector_count + 1;
    end

    // 4. De-assert enable, rst_release should stay high
    enable = 0;
    for (i = 0; i < 3; i = i + 1) begin
      @(negedge clk);
      $fdisplay(fd, "%b %b %b %b", rst, clk, enable, rst_release);
      check_outputs(1);
      vector_count = vector_count + 1;
    end

    // 5. Assert reset again, should clear rst_release and counter
    rst = 1;
    @(negedge clk);
    $fdisplay(fd, "%b %b %b %b", rst, clk, enable, rst_release);
    check_outputs(0);
    vector_count = vector_count + 1;

    // Keep reset asserted for a few cycles
    for (i = 0; i < 2; i = i + 1) begin
      @(negedge clk);
      $fdisplay(fd, "%b %b %b %b", rst, clk, enable, rst_release);
      check_outputs(0);
      vector_count = vector_count + 1;
    end

    // 6. Release reset, enable high, repeat count
    rst = 0; enable = 1;
    for (i = 0; i < delay_count; i = i + 1) begin
      @(negedge clk);
      $fdisplay(fd, "%b %b %b %b", rst, clk, enable, rst_release);
      check_outputs(0);
      vector_count = vector_count + 1;
    end
    @(negedge clk);
    $fdisplay(fd, "%b %b %b %b", rst, clk, enable, rst_release);
    check_outputs(1);
    vector_count = vector_count + 1;

    // 7. Randomized test vectors for more coverage
    for (j = 0; j < 30; j = j + 1) begin
      rst = $random % 2;
      enable = $random % 2;
      @(negedge clk);
      $fdisplay(fd, "%b %b %b %b", rst, clk, enable, rst_release);
      // Cannot check expected output here without internal state, so just record
      vector_count = vector_count + 1;
    end

    // 8. Edge case: enable toggling during count
    rst = 1; enable = 0;
    @(negedge clk);
    rst = 0; enable = 1;
    for (k = 0; k < delay_count/2; k = k + 1) begin
      @(negedge clk);
      $fdisplay(fd, "%b %b %b %b", rst, clk, enable, rst_release);
      vector_count = vector_count + 1;
    end
    enable = 0;
    @(negedge clk);
    $fdisplay(fd, "%b %b %b %b", rst, clk, enable, rst_release);
    vector_count = vector_count + 1;
    enable = 1;
    for (k = 0; k < delay_count; k = k + 1) begin
      @(negedge clk);
      $fdisplay(fd, "%b %b %b %b", rst, clk, enable, rst_release);
      vector_count = vector_count + 1;
    end

    // Ensure at least 100 vectors
    while (vector_count < 100) begin
      rst = $random % 2;
      enable = $random % 2;
      @(negedge clk);
      $fdisplay(fd, "%b %b %b %b", rst, clk, enable, rst_release);
      vector_count = vector_count + 1;
    end

    // Close file and finish
    $display("Test completed with %0d vectors and %0d errors", vector_count, error_count);
    $fclose(fd);
    $finish;
  end

endmodule

