module adder(
  input [7:0] A,
  input [7:0] B,
  input C,
  output reg [7:0] sum
);

  reg [8:0] temp_sum;    // Temporary sum to capture overflow

  always @(*) begin
    // Compute the sum, discard MSB if overflow
    temp_sum = A + B;

    if (C == 0) begin
      // Output as binary, discard overflow
      sum = temp_sum[7:0];
    end else begin
      // Output as two's complement, interpret as signed 8-bit
      sum = $signed(temp_sum[7:0]);
    end
  end

endmodule

