module dff_ar(
    input  wire clk,
    input  wire d,
    input  wire reset,
    output reg  q,
    output reg  q_n
);

always @(posedge clk or posedge reset) begin
    if (reset) begin
        q   <= 1'b0;
        q_n <= 1'b0;
    end else begin
        q   <= d;
        q_n <= ~d;
    end
end

endmodule

