        a_vec[5] = -8; b_vec[5] = -8; op_vec[5] = 2'b01; // min - min
        a_vec[6] = 7;  b_vec[6] = 7;  op_vec[6] = 2'b01; // max - max
        a_vec[7] = -8; b_vec[7] = 7;  op_vec[7] = 2'b01; // min - max
        a_vec[8] = 7;  b_vec[8] = -8; op_vec[8] = 2'b01; // max - min
        a_vec[9] = 0;  b_vec[9] = 0;  op_vec[9] = 2'b01; // 0 - 0
        a_vec[10] = -8; b_vec[10] = -8; op_vec[10] = 2'b10; // min * min
        a_vec[11] = 7;  b_vec[11] = 7;  op_vec[11] = 2'b10; // max * max
        a_vec[12] = -8; b_vec[12] = 7;  op_vec[12] = 2'b10; // min * max
        a_vec[13] = 7;  b_vec[13] = -8; op_vec[13] = 2'b10; // max * min
        a_vec[14] = 0;  b_vec[14] = 0;  op_vec[14] = 2'b10; // 0 * 0
        a_vec[15] = -8; b_vec[15] = -8; op_vec[15] = 2'b11; // min / min
        a_vec[16] = 7;  b_vec[16] = 7;  op_vec[16] = 2'b11; // max / max
        a_vec[17] = -8; b_vec[17] = 7;  op_vec[17] = 2'b11; // min / max
        a_vec[18] = 7;  b_vec[18] = -8; op_vec[18] = 2'b11; // max / min
        a_vec[19] = 0;  b_vec[19] = 1;  op_vec[19] = 2'b11; // 0 / 1

        // Division by zero cases
        a_vec[20] = 5;  b_vec[20] = 0;  op_vec[20] = 2'b11;
        a_vec[21] = -8; b_vec[21] = 0;  op_vec[21] = 2'b11;
        a_vec[22] = 0;  b_vec[22] = 0;  op_vec[22] = 2'b11;

        // Random and systematic cases
        for (i = 23; i < 100; i = i + 1) begin
            a_vec[i] = $random % 16 - 8; // -8 to 7
            b_vec[i] = $random % 16 - 8;
            op_vec[i] = $random % 4;
        end
    end

    // Error checking task
    task check_result;
        input signed [3:0] a_in;
        input signed [3:0] b_in;
        input [1:0] op_in;
        input signed [3:0] dut_result;
        output reg signed [3:0] exp_result;
        output reg error_flag;
        begin
            error_flag = 0;
            case(op_in)
                2'b00: begin
                    exp_result = a_in + b_in;
                end
                2'b01: begin
                    exp_result = a_in - b_in;
                end
                2'b10: begin
                    mul_temp = a_in * b_in;
                    exp_result = mul_temp[3:0];
                end
                2'b11: begin
                    if (b_in == 0) begin
                        exp_result = 4'bxxxx;
                    end else begin
                        exp_result = a_in / b_in;
                    end
                end
                default: begin
                    exp_result = 4'bxxxx;
                end
            endcase
            if (op_in == 2'b11 && b_in == 0) begin
                // Division by zero: don't compare, but check for x or don't count as error
                error_flag = 0;
            end else if (dut_result !== exp_result) begin
                error_flag = 1;
            end
        end
    endtask

    // Main test process
    initial begin : main_test
        error_count = 0;
        test_count = 0;
        fd = $fopen("test_vectors.txt", "w");
        if (fd)
            $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        // Write header (optional)
        // $fdisplay(fd, "a b op result");

        for (i = 0; i < 100; i = i + 1) begin
            a = a_vec[i];
            b = b_vec[i];
            op = op_vec[i];
            #1; // Allow combinational logic to settle

            check_result(a, b, op, result, expected_result, k);

            // Write to file: a b op result
            $fdisplay(fd, "%0d %0d %0d %0d", a, b, op, result);

            // Assertion
