                // Division by zero: skip error check
                $display("Test %0d: a=%0d b=%0d op=%0d result=%0d (DIV BY ZERO)", i, a, b, op, result);
            end else if (result !== expected_result) begin
                error_count = error_count + 1;
                $display("ERROR at test %0d: a=%0d b=%0d op=%0d result=%0d expected=%0d", i, a, b, op, result, expected_result);
            end else begin
                // $display("PASS at test %0d: a=%0d b=%0d op=%0d result=%0d", i, a, b, op, result);
            end
            test_count = test_count + 1;
        end

