module comparator_4bit (
  input clk,
  input reset,
  input [3:0] A,
  input [3:0] B,
  output reg greater,
  output reg less,
  output reg equal
);

  always @(posedge clk) begin
    if (reset) begin
      greater <= 0;
      less <= 0;
      equal <= 0;
    end
    else begin
      if (A > B) begin
        greater <= 1;
        less <= 0;
        equal <= 0;
      end
      else if (A < B) begin
        greater <= 0;
        less <= 1;
        equal <= 0;
      end
      else begin
        greater <= 0;
        less <= 0;
        equal <= 1;
      end
    end
  end

endmodule

test:
`timescale 1ns/1ps

module comparator_4bit_tb;

  // Inputs
  reg clk;
  reg reset;
  reg [3:0] A;
  reg [3:0] B;

  // Outputs
  wire greater;
  wire less;
  wire equal;

  // File descriptor
  integer fd;
  integer error_count;
  integer test_count;
  integer i, j;
  reg [3:0] exp_A, exp_B;
  reg exp_greater, exp_less, exp_equal;

  // Timeout
  parameter TIMEOUT = 10000;

  // Instantiate the Unit Under Test (UUT)
  comparator_4bit uut (
    .clk(clk),
    .reset(reset),
    .A(A),
    .B(B),
    .greater(greater),
    .less(less),
    .equal(equal)
  );

  // Clock generation
  initial begin
    clk = 0;
    forever #5 clk = ~clk;
  end

  // Timeout mechanism
  initial begin
    #TIMEOUT;
    $display("ERROR: Simulation timed out at time %0t", $time);
    $finish;
  end

  // Task to check outputs and report errors
  task check_outputs;
    input [3:0] inA, inB;
    input out_greater, out_less, out_equal;
    input exp_greater, exp_less, exp_equal;
    begin
      if ((out_greater !== exp_greater) ||
          (out_less !== exp_less) ||
          (out_equal !== exp_equal)) begin
        $display("ASSERTION FAILED at time %0t: A=%0d B=%0d | Got: greater=%b less=%b equal=%b | Expected: greater=%b less=%b equal=%b",
                  $time, inA, inB, out_greater, out_less, out_equal, exp_greater, exp_less, exp_equal);
        error_count = error_count + 1;
      end
    end
  endtask

  // Main stimulus and file writing
  initial begin
    fd = $fopen("test_vectors.txt", "w");
    if (fd) $display("File opened successfully");
    else begin
      $display("Failed to open file");
      $finish;
    end

    error_count = 0;
    test_count = 0;

    // Reset sequence
    reset = 1;
    A = 0;
    B = 0;
    @(negedge clk);
    @(negedge clk);
    reset = 0;

    // Test all combinations for A and B (16x16 = 256)
    // But limit to at least 100 vectors (here, we do all 256)
    for (i = 0; i < 16; i = i + 1) begin
      for (j = 0; j < 16; j = j + 1) begin
        @(negedge clk);
        A = i[3:0];
        B = j[3:0];
        // Wait for posedge clk to latch inputs
        @(posedge clk);
        // Wait for outputs to settle (registered)
        #1;
        // Expected results
        exp_A = i[3:0];
        exp_B = j[3:0];
        if (exp_A > exp_B) begin
          exp_greater = 1;
          exp_less = 0;
          exp_equal = 0;
        end else if (exp_A < exp_B) begin
          exp_greater = 0;
          exp_less = 1;
          exp_equal = 0;
        end else begin
          exp_greater = 0;
          exp_less = 0;
          exp_equal = 1;
        end
        // Write to file: A B greater less equal
        $fdisplay(fd, "%b %b %b %b %b %b %b", A, B, reset, greater, less, equal, clk);
        // Check outputs
        check_outputs(A, B, greater, less, equal, exp_greater, exp_less, exp_equal);
