module binary_output(
  input [9:0] binary_in,
  output reg [21*8-1:0] binary_out  // 21 chars, 8 bits each
);

  integer i;
  reg [10*8-1:0] padded;       // "0000000000"
  reg [10*8-1:0] minimal;      // non-zero digits
  reg [3:0]      msb_idx;      // position of highest set bit
  reg [7:0]      pipe = "|";
  reg [7:0]      zero = "0";
  reg [7:0]      one  = "1";
  reg [7:0]      blank = 8'd0;

  always @* begin
    // Build padded: always 10 chars, each '0' or '1'
    for(i=0; i<10; i=i+1) begin
      padded[(9-i)*8 +: 8] = binary_in[9-i] ? one : zero;
    end

    // Find MSB index
    msb_idx = 0;
    for(i=9; i>=0; i=i-1) begin
      if (binary_in[i] && msb_idx == 0)
        msb_idx = i+1; // position is i+1
    end

    // Build minimal
    if (binary_in == 0) begin
      // minimal = "0"
      for(i=0; i<10; i=i+1)
        minimal[i*8 +:8] = blank;
      minimal[0 +:8] = zero;
    end
    else begin
      // Copy from msb_idx-1 downto 0
      for(i=0; i<10; i=i+1)
        minimal[i*8 +:8] = blank;
      for(i=0; i<msb_idx; i=i+1)
        minimal[i*8 +:8] = binary_in[msb_idx-1-i] ? one : zero;
    end

    // Compose output: |minimal|padded|
    // Format: |minimal| padded|
    // Output is |minimal| | padded|
    // Output length: 1+10+1+10=22 max, or 1+n+1+10, n: minimal length
    // To keep it fixed 21 chars, always fill up, paddings are zeros or blanks

    // Build binary_out: "|" + minimal + "|" + padded + "|"
    for(i=0; i<21; i=i+1)
      binary_out[i*8 +:8] = blank;

    binary_out[0 +:8] = pipe;
    for(i=0; i<10; i=i+1)
      binary_out[(i+1)*8 +:8] = minimal[i*8 +:8];
    binary_out[11*8 +:8] = pipe;
    for(i=0; i<10; i=i+1)
      binary_out[(i+12)*8 +:8] = padded[i*8 +:8];
    // Final result:
    // |minimal| padded
    // The output can be printed as a string of 21 characters
  end

endmodule

