    integer fd;
    integer error_count;
    integer i;
    integer test_num;
    reg [BITS-1:0] expected_count;

    // Timeout
    integer start_time;
    integer TIMEOUT = 10000;

    // Instantiate DUT
    binary_counter #(.BITS(BITS)) uut (
        .clk(clk),
        .rst(rst),
        .count(count)
    );

    // Clock generation
    initial begin
        clk = 0;
        forever #(CLK_PERIOD/2) clk = ~clk;
    end

    // Error check task
    task check_output;
        input [BITS-1:0] expected;
        input [BITS-1:0] actual;
        input integer test_id;
        begin
            if (expected !== actual) begin
                $display("ERROR at test %0d: expected %0d, got %0d at time %0t", test_id, expected, actual, $time);
                error_count = error_count + 1;
            end
        end
    endtask

    // Main stimulus
    initial begin
        fd = $fopen("test_vectors.txt", "w");
        if (fd) $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        error_count = 0;
        test_num = 0;
        start_time = $time;

        // Initial values
        rst = 1;
        @(negedge clk);

        // Test 1: Reset behavior
        expected_count = 0;
        @(negedge clk);
        $fdisplay(fd, "%b %b %b", clk, rst, count);
        check_output(expected_count, count, test_num);
        test_num = test_num + 1;

        // Release reset and check counting
        rst = 0;
        expected_count = 0;
        for (i = 0; i < 100; i = i + 1) begin
            @(negedge clk);
            // After reset, first increment occurs
            if (i == 0)
                expected_count = 1;
            else
                expected_count = expected_count + 1;
            $fdisplay(fd, "%b %b %b", clk, rst, count);
            check_output(expected_count, count, test_num);
            test_num = test_num + 1;
            // Timeout check
            if (($time - start_time) > TIMEOUT) begin
                $display("TIMEOUT at time %0t", $time);
                $fclose(fd);
                $finish;
            end
        end

        // Test 2: Assert reset in the middle of counting
        rst = 1;
        @(negedge clk);
        expected_count = 0;
        $fdisplay(fd, "%b %b %b", clk, rst, count);
        check_output(expected_count, count, test_num);
        test_num = test_num + 1;

        // Release reset again and check counting resumes from zero
        rst = 0;
        expected_count = 0;
        for (i = 0; i < 10; i = i + 1) begin
            @(negedge clk);
            if (i == 0)
                expected_count = 1;
            else
                expected_count = expected_count + 1;
            $fdisplay(fd, "%b %b %b", clk, rst, count);
            check_output(expected_count, count, test_num);
            test_num = test_num + 1;
            if (($time - start_time) > TIMEOUT) begin
                $display("TIMEOUT at time %0t", $time);
                $fclose(fd);
                $finish;
            end
        end

        // Test 3: Multiple resets in quick succession
        rst = 1;
        @(negedge clk);
        expected_count = 0;
        $fdisplay(fd, "%b %b %b", clk, rst, count);
        check_output(expected_count, count, test_num);
        test_num = test_num + 1;

        rst = 0;
        @(negedge clk);
        expected_count = 1;
        $fdisplay(fd, "%b %b %b", clk, rst, count);
        check_output(expected_count, count, test_num);
        test_num = test_num + 1;

        rst = 1;
        @(negedge clk);
        expected_count = 0;
        $fdisplay(fd, "%b %b %b", clk, rst, count);
        check_output(expected_count, count, test_num);
        test_num = test_num + 1;

        rst = 0;
        @(negedge clk);
        expected_count = 1;
        $fdisplay(fd, "%b %b %b", clk, rst, count);
        check_output(expected_count, count, test_num);
        test_num = test_num + 1;

        // Final report
        if (error_count == 0)
            $display("All tests PASSED.");
        else
            $display("TEST FAILED with %0d errors.", error_count);

        $fclose(fd);
        $finish;
    end

    // Timeout mechanism
    initial begin
        #TIMEOUT;
        $display("Simulation TIMEOUT after %0d time units.", TIMEOUT);
        $fclose(fd);
        $finish;
    end

endmodule

