module shift_register_tb;

  // Inputs
  reg clk;
  reg reset;
  reg load;
  reg [7:0] data_in;

  // Output
  wire data_out;

  // Internal variables
  integer fd;
  integer i, j, test_count, error_count;
  reg [7:0] expected_shift_reg;
  reg expected_data_out;
  reg [7:0] test_data [0:9]; // 10 different data patterns
  reg [7:0] golden_shift_reg;
  reg golden_data_out;

  // Instantiate the DUT
  shift_register uut (
    .clk(clk),
    .reset(reset),
    .load(load),
    .data_in(data_in),
    .data_out(data_out)
  );

  // Clock generation
  initial begin
    clk = 0;
    forever #5 clk = ~clk; // 10ns period
  end

  // Timeout mechanism
  initial begin
    #10000;
    $display("ERROR: Simulation timed out at time %0t", $time);
    $finish;
  end

  // Error checking task
  task check_output;
    input [7:0] exp_shift_reg;
    input exp_data_out;
    begin
      if (uut.shift_reg !== exp_shift_reg) begin
        $display("ASSERTION FAILED at time %0t: shift_reg = %b, expected = %b", $time, uut.shift_reg, exp_shift_reg);
        error_count = error_count + 1;
      end
      if (data_out !== exp_data_out) begin
        $display("ASSERTION FAILED at time %0t: data_out = %b, expected = %b", $time, data_out, exp_data_out);
        error_count = error_count + 1;
      end
    end
  endtask

  // Testbench main process
  initial begin
    // Initialize
    fd = $fopen("test_vectors.txt", "w");
    if (fd) $display("File opened successfully");
    else begin
      $display("Failed to open file");
      $finish;
    end

    error_count = 0;
    test_count = 0;

    // Prepare test data patterns
    test_data[0] = 8'b00000000;
    test_data[1] = 8'b11111111;
    test_data[2] = 8'b10101010;
    test_data[3] = 8'b01010101;
    test_data[4] = 8'b10000001;
    test_data[5] = 8'b01111110;
    test_data[6] = 8'b11001100;
    test_data[7] = 8'b00110011;
    test_data[8] = 8'b11110000;
    test_data[9] = 8'b00001111;

    // Apply reset
    reset = 1;
    load = 0;
    data_in = 8'b0;
    @(negedge clk);
    @(negedge clk);
    expected_shift_reg = 8'b0;
    expected_data_out = 1'b0;
    $fdisplay(fd, "%b %b %b %b %b", clk, reset, load, data_in, data_out);
    check_output(expected_shift_reg, expected_data_out);

    // Release reset
    reset = 0;
    @(negedge clk);

    // Main test loop: For each test pattern, load and shift 8 times
    for (i = 0; i < 10; i = i + 1) begin
      // Parallel load
      load = 1;
      data_in = test_data[i];
      @(negedge clk);
      expected_shift_reg = test_data[i];
      expected_data_out = expected_shift_reg[7];
      $fdisplay(fd, "%b %b %b %b %b", clk, reset, load, data_in, data_out);
      check_output(expected_shift_reg, expected_data_out);
      test_count = test_count + 1;

      // Deassert load
      load = 0;
      data_in = 8'bx;

      // Shift left 8 times
      for (j = 0; j < 8; j = j + 1) begin
        @(negedge clk);
        expected_shift_reg = {expected_shift_reg[6:0], 1'b0};
        expected_data_out = expected_shift_reg[7];
        $fdisplay(fd, "%b %b %b %b %b", clk, reset, load, uut.shift_reg, data_out);
        check_output(expected_shift_reg, expected_data_out);
        test_count = test_count + 1;
      end

      // Randomly assert reset in the middle of the test
      if (i == 4) begin
        reset = 1;
        @(negedge clk);
        expected_shift_reg = 8'b0;
        expected_data_out = 1'b0;
        $fdisplay(fd, "%b %b %b %b %b", clk, reset, load, uut.shift_reg, data_out);
        check_output(expected_shift_reg, expected_data_out);
        test_count = test_count + 1;
        reset = 0;
        @(negedge clk);
      end
    end

    // Additional random tests for more coverage
    for (i = 0; i < 80; i = i + 1) begin
      // Random load or shift
      load = $random % 2;
      data_in = $random;
      if (load) begin
        @(negedge clk);
        golden_shift_reg = data_in;
        golden_data_out = golden_shift_reg[7];
        $fdisplay(fd, "%b %b %b %b %b", clk, reset, load, data_in, data_out);
        check_output(golden_shift_reg, golden_data_out);
        test_count = test_count + 1;
      end else begin
        @(negedge clk);
        golden_shift_reg = uut.shift_reg;
        golden_shift_reg = {golden_shift_reg[6:0], 1'b0};
        golden_data_out = golden_shift_reg[7];
        @(negedge clk);
        $fdisplay(fd, "%b %b %b %b %b", clk, reset, load, uut.shift_reg, data_out);
        check_output(golden_shift_reg, golden_data_out);
        test_count = test_count + 1;
      end
      // Occasionally assert reset
      if ((i % 20) == 0) begin
        reset = 1;
        @(negedge clk);
        $fdisplay(fd, "%b %b %b %b %b", clk, reset, load, uut.shift_reg, data_out);
        check_output(8'b0, 1'b0);
        reset = 0;
        @(negedge clk);
      end
    end

    $display("Testbench completed: %0d test vectors applied, %0d errors detected.", test_count, error_count);
    $fclose(fd);
    $finish;
  end

endmodule

