module simple_counter (
    input  wire clk,
    input  wire rst,
    output reg [2:0] count
);

    reg [2:0] next_count;

    // Combinational block to determine the next value
    always @(*) begin
        if (rst)
            next_count = 3'd0;
        else if (count == 3'd7)
            next_count = 3'd0;
        else
            next_count = count + 3'd1;
    end

    // Sequential block to update the counter
    always @(posedge clk or posedge rst) begin
        if (rst)
            count <= 3'd0;
        else
            count <= next_count;
    end

endmodule

