    initial begin
        fd = $fopen("test_vectors.txt", "w");
        if (fd) $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        error_count = 0;
        vector_count = 0;

        // Initialize
        rst = 1;
        @(negedge clk);
        @(negedge clk);
