            else if (prev_count == 3'd7)
                expected_count = 3'd0;
            else
                expected_count = prev_count + 3'd1;

            if (count !== expected_count) begin
                $display("ASSERTION FAILED after mid-reset at time %0t: count=%0d, expected=%0d (cycle %0d)", $time, count, expected_count, i);
                error_count = error_count + 1;
            end

            count_history[vector_count] = count;
            expected_history[vector_count] = expected_count;
            vector_count = vector_count + 1;

            prev_count = count;
        end

        // Test reset pulse for one clock
        rst = 1;
        @(negedge clk);
        $fdisplay(fd, "%b %b %03b", clk, rst, count);
        if (count !== 3'd0) begin
            $display("ASSERTION FAILED after single reset pulse at time %0t: count=%0d, expected=0", $time, count);
            error_count = error_count + 1;
        end
        count_history[vector_count] = count;
        expected_history[vector_count] = 3'd0;
        vector_count = vector_count + 1;

        rst = 0;
        prev_count = 3'd0;
        // Continue for 10 more cycles after single reset pulse
        for (i = 0; i < 10; i = i + 1) begin
            @(negedge clk);
            $fdisplay(fd, "%b %b %03b", clk, rst, count);
            if (rst)
                expected_count = 3'd0;
            else if (prev_count == 3'd7)
                expected_count = 3'd0;
            else
                expected_count = prev_count + 3'd1;

            if (count !== expected_count) begin
                $display("ASSERTION FAILED after single reset pulse at time %0t: count=%0d, expected=%0d (cycle %0d)", $time, count, expected_count, i);
                error_count = error_count + 1;
            end

            count_history[vector_count] = count;
            expected_history[vector_count] = expected_count;
            vector_count = vector_count + 1;

            prev_count = count;
        end

        // Final report
        check_errors();

        $fclose(fd);
        $display("Testbench completed. Total vectors: %0d, Errors: %0d", vector_count, error_count);
        $finish;
    end

    // Error checking task
    task check_errors;
        integer j;
        begin
            for (j = 0; j < vector_count; j = j + 1) begin
                if (count_history[j] !== expected_history[j]) begin
                    $display("ERROR: Mismatch at vector %0d: got %0d, expected %0d", j, count_history[j], expected_history[j]);
                end
            end
            if (error_count == 0)
                $display("All test vectors passed.");
            else
                $display("Total errors: %0d", error_count);
        end
    endtask

