// Half Adder Module
module half_adder(
    input  wire A,
    input  wire B,
    output wire S,
    output wire C
);
    // Sum is A XOR B
    assign S = A ^ B;

    // Carry is A AND B
    assign C = A & B;
endmodule

// Full Adder Module
module full_adder(
    input  wire A,
    input  wire B,
    input  wire Cin,
    output wire S,
    output wire Cout
);
    // Two-input XOR for intermediate sum
    wire xor1_out;

    assign xor1_out = A ^ B;     // First XOR gate

    // Sum is (A XOR B) XOR Cin
    assign S = xor1_out ^ Cin;

    // Carry-out: (A AND B) OR (Cin AND (A XOR B))
    assign Cout = (A & B) | (Cin & xor1_out);
endmodule

