module half_adder_tb;

    // Inputs for half adder
    reg ha_A, ha_B;
    wire ha_S, ha_C;

    // Inputs for full adder
    reg fa_A, fa_B, fa_Cin;
    wire fa_S, fa_Cout;

    // Error counter
    integer errors;
    integer fd;
    integer i, j, k, test_num;

    // Timeout parameters
    integer start_time;
    parameter TIMEOUT = 10000;

    // Instantiate half adder
    half_adder uut_ha (
        .A(ha_A),
        .B(ha_B),
        .S(ha_S),
        .C(ha_C)
    );

    // Instantiate full adder
    full_adder uut_fa (
        .A(fa_A),
        .B(fa_B),
        .Cin(fa_Cin),
        .S(fa_S),
        .Cout(fa_Cout)
    );

    // Task to check half adder
    task check_half_adder;
        input reg A, B;
        input reg S, C;
        begin
            if (S !== (A ^ B)) begin
                $display("Half Adder SUM ERROR: A=%b B=%b S=%b (expected %b) at time %0t", A, B, S, (A^B), $time);
                errors = errors + 1;
            end
            if (C !== (A & B)) begin
                $display("Half Adder CARRY ERROR: A=%b B=%b C=%b (expected %b) at time %0t", A, B, C, (A&B), $time);
                errors = errors + 1;
            end
        end
    endtask

    // Task to check full adder
    task check_full_adder;
        input reg A, B, Cin;
        input reg S, Cout;
        reg expected_S, expected_Cout;
        begin
            expected_S = A ^ B ^ Cin;
            expected_Cout = (A & B) | (Cin & (A ^ B));
            if (S !== expected_S) begin
                $display("Full Adder SUM ERROR: A=%b B=%b Cin=%b S=%b (expected %b) at time %0t", A, B, Cin, S, expected_S, $time);
                errors = errors + 1;
            end
            if (Cout !== expected_Cout) begin
                $display("Full Adder CARRY ERROR: A=%b B=%b Cin=%b Cout=%b (expected %b) at time %0t", A, B, Cin, Cout, expected_Cout, $time);
                errors = errors + 1;
            end
        end
    endtask

    // Timeout mechanism
    initial begin
        start_time = $time;
        forever begin
            #100;
            if (($time - start_time) > TIMEOUT) begin
                $display("TIMEOUT: Simulation exceeded %0d time units.", TIMEOUT);
                $finish;
            end
        end
    end

    // Main test process
    initial begin
        errors = 0;
        test_num = 0;
        fd = $fopen("test_vectors.txt", "w");
        if (fd) $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        // Header for test vector file
        $fdisplay(fd, "HA_A HA_B HA_S HA_C FA_A FA_B FA_Cin FA_S FA_Cout");

        // Exhaustive test for half adder (2 inputs: 4 combinations)
        for (i = 0; i < 2; i = i + 1) begin
            for (j = 0; j < 2; j = j + 1) begin
                ha_A = i;
                ha_B = j;
                #1;
                check_half_adder(ha_A, ha_B, ha_S, ha_C);
                // Write to file: HA_A HA_B HA_S HA_C FA_A FA_B FA_Cin FA_S FA_Cout (FA fields X for now)
                $fdisplay(fd, "%b %b %b %b X X X X X", ha_A, ha_B, ha_S, ha_C);
                test_num = test_num + 1;
            end
        end

        // Exhaustive test for full adder (3 inputs: 8 combinations)
        for (i = 0; i < 2; i = i + 1) begin
            for (j = 0; j < 2; j = j + 1) begin
                for (k = 0; k < 2; k = k + 1) begin
                    fa_A = i;
                    fa_B = j;
                    fa_Cin = k;
                    #1;
                    check_full_adder(fa_A, fa_B, fa_Cin, fa_S, fa_Cout);
                    // Write to file: HA fields X for now, FA_A FA_B FA_Cin FA_S FA_Cout
                    $fdisplay(fd, "X X X X %b %b %b %b %b", fa_A, fa_B, fa_Cin, fa_S, fa_Cout);
                    test_num = test_num + 1;
                end
            end
        end

        // Generate additional random test vectors (at least 100 total)
        // Already have 4+8=12, so generate 88 more
        for (i = 0; i < 88; i = i + 1) begin
            // Random for half adder
            ha_A = $random % 2;
            ha_B = $random % 2;
            #1;
            check_half_adder(ha_A, ha_B, ha_S, ha_C);

            // Random for full adder
            fa_A = $random % 2;
            fa_B = $random % 2;
            fa_Cin = $random % 2;
            #1;
            check_full_adder(fa_A, fa_B, fa_Cin, fa_S, fa_Cout);

            // Write both to file
            $fdisplay(fd, "%b %b %b %b %b %b %b %b %b",
                ha_A, ha_B, ha_S, ha_C,
                fa_A, fa_B, fa_Cin, fa_S, fa_Cout);
            test_num = test_num + 1;
        end

        $display("Total tests performed: %0d", test_num);
        if (errors == 0)
            $display("All tests passed!");
        else
            $display("Total errors: %0d", errors);

        $fclose(fd);
        $finish;
    end

endmodule

