test:
`timescale 1ns/1ps

module up_down_counter_tb;

  // Inputs
  reg clk;
  reg up_down;
  reg load;
  wire [3:0] count;

  // DUT instantiation
  up_down_counter uut (
    .clk(clk),
    .up_down(up_down),
    .load(load),
    .count(count)
  );

  // File handling
  integer fd;
  integer error_count;
  integer test_num;
  reg [3:0] expected_count;
  reg [3:0] prev_count;
  reg [7:0] i;
  reg [7:0] j;

  // Timeout mechanism
  parameter TIMEOUT = 10000;
  initial begin
    #TIMEOUT;
    $display("ERROR: Simulation timed out at time %0t", $time);
    $finish;
  end

  // Clock generation
  initial begin
    clk = 0;
    forever #5 clk = ~clk;
  end

  // Error check task
  task check_output;
    input [3:0] exp_count;
    begin
      if (count !== exp_count) begin
        $display("ASSERTION FAILED at time %0t: up_down=%b load=%b prev_count=%b expected_count=%b actual_count=%b", $time, up_down, load, prev_count, exp_count, count);
        error_count = error_count + 1;
      end
    end
  endtask

  // Main stimulus
  initial begin
    fd = $fopen("test_vectors.txt", "w");
    if (fd) $display("File opened successfully");
    else begin
      $display("Failed to open file");
      $finish;
    end

    error_count = 0;
    test_num = 0;
    up_down = 0;
    load = 0;

    // Wait for global reset
    @(negedge clk);

    // Test 1: Load operation (reset to 0)
    load = 1;
    up_down = 0;
    prev_count = count;
    @(negedge clk);
    expected_count = 4'b0000;
    $fdisplay(fd, "%b %b %b %b", clk, up_down, load, count);
    check_output(expected_count);

    // Test 2: Up counting from 0 to 15 and wrap to 0
    load = 0;
    up_down = 1;
    for (i = 0; i < 17; i = i + 1) begin
      prev_count = count;
      @(negedge clk);
      if (i == 0) expected_count = 4'b0001;
      else if (prev_count == 4'b1111) expected_count = 4'b0000;
      else expected_count = prev_count + 1;
      $fdisplay(fd, "%b %b %b %b", clk, up_down, load, count);
      check_output(expected_count);
    end

    // Test 3: Down counting from current value to 0 and wrap to 15
    up_down = 0;
    for (i = 0; i < 17; i = i + 1) begin
      prev_count = count;
      @(negedge clk);
      if (prev_count == 4'b0000) expected_count = 4'b1111;
      else expected_count = prev_count - 1;
      $fdisplay(fd, "%b %b %b %b", clk, up_down, load, count);
      check_output(expected_count);
    end

    // Test 4: Load in the middle of counting
    up_down = 1;
    load = 0;
    @(negedge clk);
    prev_count = count;
    @(negedge clk);
    prev_count = count;
    load = 1;
    @(negedge clk);
    expected_count = 4'b0000;
    $fdisplay(fd, "%b %b %b %b", clk, up_down, load, count);
    check_output(expected_count);
    load = 0;

    // Test 5: Alternate up/down with random patterns
    for (i = 0; i < 40; i = i + 1) begin
      up_down = $random % 2;
      load = (i == 20) ? 1 : 0; // force a load at i==20
      prev_count = count;
      @(negedge clk);
      if (load) expected_count = 4'b0000;
      else if (up_down) begin
        if (prev_count == 4'b1111) expected_count = 4'b0000;
        else expected_count = prev_count + 1;
      end else begin
        if (prev_count == 4'b0000) expected_count = 4'b1111;
        else expected_count = prev_count - 1;
      end
      $fdisplay(fd, "%b %b %b %b", clk, up_down, load, count);
      check_output(expected_count);
      load = 0;
    end

    // Test 6: All possible input combinations for a few cycles
    for (i = 0; i < 4; i = i + 1) begin
      for (j = 0; j < 4; j = j + 1) begin
        up_down = i[0];
        load = i[1];
        prev_count = count;
        @(negedge clk);
        if (load) expected_count = 4'b0000;
        else if (up_down) begin
          if (prev_count == 4'b1111) expected_count = 4'b0000;
          else expected_count = prev_count + 1;
        end else begin
          if (prev_count == 4'b0000) expected_count = 4'b1111;
          else expected_count = prev_count - 1;
        end
        $fdisplay(fd, "%b %b %b %b", clk, up_down, load, count);
        check_output(expected_count);
      end
    end

    $display("Testbench completed with %0d errors.", error_count);
    $fclose(fd);
    $finish;
  end

