module arithmetic_module_tb;

  parameter WIDTH = 32;

  // DUT signals
  reg  [1:0] op;
  reg  [WIDTH-1:0] a, b;
  wire [WIDTH-1:0] out;

  // File descriptor
  integer fd;
  integer i, j, k, test_count, error_count;
  reg [WIDTH-1:0] expected_out;
  reg [WIDTH-1:0] a_vec, b_vec;
  reg [1:0] op_vec;
  reg [WIDTH-1:0] div_result;
  reg div_by_zero;

  // Instantiate DUT
  arithmetic_module #(WIDTH) dut (
    .op(op),
    .a(a),
    .b(b),
    .out(out)
  );

  // Timeout mechanism
  initial begin
    #10000;
    $display("ERROR: Simulation timeout at time %0t ns", $time);
    $finish;
  end

  // Error check task
  task check_result;
    input [1:0] op_t;
    input [WIDTH-1:0] a_t, b_t, out_t, expected_t;
    begin
      if (out_t !== expected_t) begin
        $display("ASSERTION FAILED: op=%b a=%h b=%h out=%h expected=%h at time %0t", op_t, a_t, b_t, out_t, expected_t, $time);
        error_count = error_count + 1;
      end
    end
  endtask

  // Main test process
  initial begin
    fd = $fopen("test_vectors.txt", "w");
    if (fd) $display("File opened successfully");
    else begin
      $display("Failed to open file");
      $finish;
    end

    error_count = 0;
    test_count = 0;

    // Write header (optional)
    // $fdisplay(fd, "op a b out");

    // Exhaustive for small values, random for the rest
    // Test all op codes with edge and random values
    for (k = 0; k < 4; k = k + 1) begin
      op_vec = k[1:0];
      // Edge cases
      for (i = 0; i < 4; i = i + 1) begin
        case (i)
          0: a_vec = 0;
          1: a_vec = 32'hFFFFFFFF;
          2: a_vec = 32'h80000000;
          3: a_vec = 32'h7FFFFFFF;
        endcase
        for (j = 0; j < 4; j = j + 1) begin
          case (j)
            0: b_vec = 0;
            1: b_vec = 32'hFFFFFFFF;
            2: b_vec = 32'h80000000;
            3: b_vec = 32'h7FFFFFFF;
          endcase

          op = op_vec;
          a = a_vec;
          b = b_vec;
          #1;

          // Compute expected result
          div_by_zero = 0;
          case (op_vec)
            2'b00: expected_out = a_vec + b_vec;
            2'b01: expected_out = a_vec - b_vec;
            2'b10: expected_out = a_vec * b_vec;
            2'b11: begin
              if (b_vec == 0) begin
                expected_out = 0;
                div_by_zero = 1;
              end else begin
                expected_out = a_vec / b_vec;
              end
            end
          endcase

          // Write to file: op a b out
          $fdisplay(fd, "%b %h %h %h", op_vec, a_vec, b_vec, out);

          // Assertion
          if (!div_by_zero) check_result(op_vec, a_vec, b_vec, out, expected_out);

          test_count = test_count + 1;
        end
      end
    end

    // Generate random test vectors to reach at least 100 tests
    for (i = test_count; i < 100; i = i + 1) begin
      op_vec = $random % 4;
      a_vec = $random;
      b_vec = $random;
      op = op_vec;
      a = a_vec;
      b = b_vec;
      #1;

      div_by_zero = 0;
      case (op_vec)
        2'b00: expected_out = a_vec + b_vec;
        2'b01: expected_out = a_vec - b_vec;
        2'b10: expected_out = a_vec * b_vec;
        2'b11: begin
          if (b_vec == 0) begin
            expected_out = 0;
            div_by_zero = 1;
          end else begin
            expected_out = a_vec / b_vec;
          end
        end
      endcase

      $fdisplay(fd, "%b %h %h %h", op_vec, a_vec, b_vec, out);

      if (!div_by_zero) check_result(op_vec, a_vec, b_vec, out, expected_out);

      test_count = test_count + 1;
    end

    $display("Test completed: %0d vectors, %0d errors", test_count, error_count);
    $fclose(fd);
    $finish;
  end

