            expected_data_out = expected_mem[address];
            #1;
            $fdisplay(fd, "%05h %04h %1b %04h", address, data_in, 1'b1, data_out);
            if (data_out !== expected_data_out) begin
                $display("ERROR: Write/Read Mismatch at address %0d: expected %04h, got %04h (time %0t)", address, expected_data_out, data_out, $time);
                error_count = error_count + 1;
            end
            test_count = test_count + 1;
        end

        // --- TEST 3: Read Without Write (addresses 2000-2019, should be zero) ---
        for (i = 2000; i < 2020; i = i + 1) begin
            @(negedge clock);
            address = i[14:0];
            data_in = 16'hxxxx;
            write_en = 1'b0;
            @(posedge clock);
            expected_data_out = expected_mem[address];
            #1;
            $fdisplay(fd, "%05h %04h %1b %04h", address, 16'hxxxx, 1'b0, data_out);
            if (data_out !== expected_data_out) begin
                $display("ERROR: Read Mismatch at address %0d: expected %04h, got %04h (time %0t)", address, expected_data_out, data_out, $time);
                error_count = error_count + 1;
            end
            test_count = test_count + 1;
        end

        // --- TEST 4: Overwrite and Readback (addresses 0-9) ---
        for (i = 0; i < 10; i = i + 1) begin
            @(negedge clock);
            address = i[14:0];
            data_in = $random(seed);
            write_en = 1'b1;
            @(posedge clock);
            expected_mem[address] = data_in;
            @(negedge clock);
            write_en = 1'b0;
            @(posedge clock);
            expected_data_out = expected_mem[address];
