            if (data_out !== expected_data_out) begin
                $display("ERROR: Overwrite/Readback Mismatch at address %0d: expected %04h, got %04h (time %0t)", address, expected_data_out, data_out, $time);
                error_count = error_count + 1;
            end
            test_count = test_count + 1;
        end

        // --- TEST 5: Random Access Pattern (50 random accesses) ---
        for (i = 0; i < 50; i = i + 1) begin
            @(negedge clock);
            addr = $random(seed) & 15'h7FFF;
            address = addr[14:0];
            data_in = $random(seed);
            write_en = $random(seed) & 1'b1;
            @(posedge clock);
            if (write_en)
                expected_mem[address] = data_in;
            @(negedge clock);
            write_en = 1'b0;
            @(posedge clock);
            expected_data_out = expected_mem[address];
            #1;
            $fdisplay(fd, "%05h %04h %1b %04h", address, data_in, write_en, data_out);
            if (data_out !== expected_data_out) begin
                $display("ERROR: Random Access Mismatch at address %0d: expected %04h, got %04h (time %0t)", address, expected_data_out, data_out, $time);
                error_count = error_count + 1;
            end
            test_count = test_count + 1;
        end

        // --- TEST 6: Edge Address Test (lowest and highest addresses) ---
        // Lowest address
        @(negedge clock);
        address = 15'b0;
        data_in = 16'hA5A5;
        write_en = 1'b1;
        @(posedge clock);
        expected_mem[address] = data_in;
        @(negedge clock);
        write_en = 1'b0;
        @(posedge clock);
        expected_data_out = expected_mem[address];
        #1;
        $fdisplay(fd, "%05h %04h %1b %04h", address, data_in, 1'b1, data_out);
        if (data_out !== expected_data_out) begin
            $display("ERROR: Edge Address (0) Mismatch: expected %04h, got %04h (time %0t)", expected_data_out, data_out, $time);
            error_count = error_count + 1;
        end
        test_count = test_count + 1;

        // Highest address
        @(negedge clock);
        address = 15'h7FFF;
        data_in = 16'h5A5A;
        write_en = 1'b1;
        @(posedge clock);
        expected_mem[address] = data_in;
        @(negedge clock);
        write_en = 1'b0;
        @(posedge clock);
        expected_data_out = expected_mem[address];
        #1;
        $fdisplay(fd, "%05h %04h %1b %04h", address, data_in, 1'b1, data_out);
        if (data_out !== expected_data_out) begin
            $display("ERROR: Edge Address (32767) Mismatch: expected %04h, got %04h (time %0t)", expected_data_out, data_out, $time);
            error_count = error_count + 1;
        end
        test_count = test_count + 1;

        // --- End of Tests ---
