module priority_encoder_4bit (
    input  wire [3:0] in,      // 4 input bits
    output wire [1:0] out      // 2-bit output representing highest priority
);

    // Highest priority is in[3], then in[2], then in[1], then in[0]
    assign out = (in[3]) ? 2'b11 :
                 (in[2]) ? 2'b10 :
                 (in[1]) ? 2'b01 :
                 (in[0]) ? 2'b00 :
                 2'b00;

endmodule

