      check_output(expected_tr_data, tr_data, test_count);
      prev_tr_data = tr_data;
      test_count = test_count + 1;
    end

    // Test 4: Toggle enable
    en = 0;
    @(posedge clk);
    #1;
    expected_tr_data = prev_tr_data;
    $fdisplay(fd, "%b %b %b %h", clk, rst, en, tr_data);
    check_output(expected_tr_data, tr_data, test_count);
    test_count = test_count + 1;

    en = 1;
