    else
      expected_tr_data = prev_tr_data * 3 + 1;
    if (expected_tr_data >= 36'h1000000000)
      expected_tr_data = 0;
    $fdisplay(fd, "%b %b %b %h", clk, rst, en, tr_data);
    check_output(expected_tr_data, tr_data, test_count);
    prev_tr_data = tr_data;
    test_count = test_count + 1;

    // Test 5: Assert reset in the middle
    rst = 1;
    @(posedge clk);
    #1;
    expected_tr_data = 0;
    $fdisplay(fd, "%b %b %b %h", clk, rst, en, tr_data);
    check_output(expected_tr_data, tr_data, test_count);
    test_count = test_count + 1;
    rst = 0;

    // Continue for a few more cycles after reset
    en = 1;
    prev_tr_data = tr_data;
    for (i = 0; i < 10; i = i + 1) begin
      @(posedge clk);
