    end

    // Close file and finish
    $display("Testbench completed with %0d errors out of %0d tests.", error_count, test_count);
    $fclose(fd);
    $finish;
  end

  // Timeout mechanism
  initial begin
    #TIMEOUT;
    $display("ERROR: Simulation timed out at time %0t", $time);
    $fclose(fd);
    $finish;
  end

