module ripple_carry_adder_4bit (
    input  [3:0] A,
    input  [3:0] B,
    input        CIN,
    output [3:0] SUM,
    output       COUT
);
    wire [3:0] carry;

    // First bit addition
    assign {carry[0], SUM[0]} = A[0] + B[0] + CIN;
    // Second bit
    assign {carry[1], SUM[1]} = A[1] + B[1] + carry[0];
    // Third bit
    assign {carry[2], SUM[2]} = A[2] + B[2] + carry[1];
    // Fourth bit
    assign {carry[3], SUM[3]} = A[3] + B[3] + carry[2];

    // Final carry-out
    assign COUT = carry[3];

endmodule

