        input reg exp_q;
        input reg exp_qn;
        begin
            if (q !== exp_q) begin
                $display("ERROR at time %0t: q expected %b, got %b", $time, exp_q, q);
                error_count = error_count + 1;
            end
            if (qn !== exp_qn) begin
                $display("ERROR at time %0t: qn expected %b, got %b", $time, exp_qn, qn);
                error_count = error_count + 1;
            end
        end
    endtask

    // Main stimulus
