        @(negedge clk);
        expected_q = 1;
        expected_qn = 0;
        #1;
        $fdisplay(fd, "%b %b %b %b %b %b", clk, rst, set, d, q, qn);
        check_outputs(expected_q, expected_qn);
        test_count = test_count + 1;

        // Release set, check d input
        set = 0; rst = 0; d = 0;
        @(negedge clk);
        expected_q = 0;
        expected_qn = 1;
        #1;
        $fdisplay(fd, "%b %b %b %b %b %b", clk, rst, set, d, q, qn);
        check_outputs(expected_q, expected_qn);
        test_count = test_count + 1;

        d = 1;
        @(negedge clk);
        expected_q = 1;
        expected_qn = 0;
        #1;
        $fdisplay(fd, "%b %b %b %b %b %b", clk, rst, set, d, q, qn);
        check_outputs(expected_q, expected_qn);
        test_count = test_count + 1;

        d = 0;
        @(negedge clk);
        expected_q = 0;
        expected_qn = 1;
        #1;
        $fdisplay(fd, "%b %b %b %b %b %b", clk, rst, set, d, q, qn);
        check_outputs(expected_q, expected_qn);
        test_count = test_count + 1;

        // Set dominates over reset
        set = 1; rst = 1; d = 0;
        @(negedge clk);
        expected_q = 1;
        expected_qn = 0;
        #1;
        $fdisplay(fd, "%b %b %b %b %b %b", clk, rst, set, d, q, qn);
        check_outputs(expected_q, expected_qn);
        test_count = test_count + 1;

        // Test asynchronous set (posedge set)
        set = 0; rst = 0; d = 0;
        @(negedge clk);
        #1;
        set = 1;
        #1; // async set
        expected_q = 1;
        expected_qn = 0;
        $fdisplay(fd, "%b %b %b %b %b %b", clk, rst, set, d, q, qn);
        check_outputs(expected_q, expected_qn);
        test_count = test_count + 1;
        set = 0;
        #1;

        // Test asynchronous reset (after set)
        rst = 1;
        @(negedge clk);
        expected_q = 0;
        expected_qn = 1;
        #1;
        $fdisplay(fd, "%b %b %b %b %b %b", clk, rst, set, d, q, qn);
        check_outputs(expected_q, expected_qn);
        test_count = test_count + 1;
        rst = 0;

        // Sweep all input combinations for several cycles
        for (i = 0; i < 100; i = i + 1) begin
            // Randomize inputs
            rst = $random % 2;
            set = $random % 2;
            d   = $random % 2;
            @(negedge clk);
            // Compute expected_q
            if (set) expected_q = 1;
            else if (rst) expected_q = 0;
            else expected_q = d;
            expected_qn = ~expected_q;
            #1;
            $fdisplay(fd, "%b %b %b %b %b %b", clk, rst, set, d, q, qn);
            check_outputs(expected_q, expected_qn);
            test_count = test_count + 1;
        end

        // Additional edge cases: set and rst toggling
        rst = 0; set = 0; d = 0;
        @(negedge clk);
        set = 1;
        #1;
        expected_q = 1;
        expected_qn = 0;
        $fdisplay(fd, "%b %b %b %b %b %b", clk, rst, set, d, q, qn);
        check_outputs(expected_q, expected_qn);
        test_count = test_count + 1;
        set = 0;
        rst = 1;
        @(negedge clk);
        expected_q = 0;
        expected_qn = 1;
        #1;
        $fdisplay(fd, "%b %b %b %b %b %b", clk, rst, set, d, q, qn);
        check_outputs(expected_q, expected_qn);
        test_count = test_count + 1;
        rst = 0;

        // Close file and finish
        $display("Test completed with %0d tests and %0d errors.", test_count, error_count);
        $fclose(fd);
        $finish;
