module mux_2_to_1 (
    Y,
    A,
    B,
    S
);

    // Module ports
    output Y;
    input  A;
    input  B;
    input  S;

    // Local signals
    wire not_S;
    wire A_and_not_S;
    wire B_and_S;

    // Inverted select signal
    not not_gate (not_S, S);

    // AND gates
    and and_gate_1 (A_and_not_S, A, not_S);
    and and_gate_2 (B_and_S, B, S);

    // Output
    assign Y = A_and_not_S | B_and_S;

endmodule

