module shift_register_4bit_tb;

    // Inputs
    reg clk;
    reg rst;
    reg [3:0] D;
    reg LD;
    reg SH;

    // Outputs
    wire [3:0] Q;

    // File descriptor
    integer fd;
    integer error_count;
    integer test_count;
    integer i, j, k, l, m;
    reg [3:0] expected_Q;
    reg [3:0] Q_prev;

    // Instantiate the DUT
    shift_register_4bit dut (
        .clk(clk),
        .rst(rst),
        .D(D),
        .LD(LD),
        .SH(SH),
        .Q(Q)
    );

    // Clock generation
    initial begin
        clk = 0;
        forever #5 clk = ~clk; // 10ns period
    end

    // Timeout mechanism
    initial begin
        #10000;
        $display("ERROR: Simulation timeout at time %0t", $time);
        $finish;
    end

    // Error checking task
    task check_output;
        input [3:0] expected;
        input [3:0] actual;
        input [3:0] D_in;
        input LD_in;
        input SH_in;
        input rst_in;
        begin
            if (expected !== actual) begin
                $display("ASSERTION FAILED at time %0t: rst=%b D=%b LD=%b SH=%b | Q=%b (expected %b)", $time, rst_in, D_in, LD_in, SH_in, actual, expected);
                error_count = error_count + 1;
            end
        end
    endtask

    // Main stimulus and test vector generation
    initial begin
        // Open file
        fd = $fopen("test_vectors.txt", "w");
        if (fd) $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        // Write header (optional)
        $fdisplay(fd, "rst D[3] D[2] D[1] D[0] LD SH | Q[3] Q[2] Q[1] Q[0]");

        // Initialize
        error_count = 0;
        test_count = 0;
        rst = 0; D = 4'b0; LD = 0; SH = 0;
        Q_prev = 4'b0;
        expected_Q = 4'b0;

        // Apply reset and check
        @(negedge clk);
        rst = 1; LD = 0; SH = 0; D = 4'b0000;
        @(negedge clk);
        expected_Q = 4'b0000;
        #1;
        $fdisplay(fd, "%b %b %b %b %b %b %b | %b %b %b %b", rst, D[3], D[2], D[1], D[0], LD, SH, Q[3], Q[2], Q[1], Q[0]);
        check_output(expected_Q, Q, D, LD, SH, rst);
        test_count = test_count + 1;

        // Deassert reset
        rst = 0;
        @(negedge clk);

        // Test all load operations (LD=1, SH=0), for all D
        for (i = 0; i < 16; i = i + 1) begin
            D = i[3:0];
            LD = 1;
            SH = 0;
            @(negedge clk);
            expected_Q = D;
            #1;
            $fdisplay(fd, "%b %b %b %b %b %b %b | %b %b %b %b", rst, D[3], D[2], D[1], D[0], LD, SH, Q[3], Q[2], Q[1], Q[0]);
            check_output(expected_Q, Q, D, LD, SH, rst);
            test_count = test_count + 1;
        end

        // Test all shift operations (LD=0, SH=1) after loading a value
        for (i = 0; i < 16; i = i + 1) begin
            // Load value
            D = i[3:0];
            LD = 1; SH = 0;
            @(negedge clk);
            expected_Q = D;
            #1;
            $fdisplay(fd, "%b %b %b %b %b %b %b | %b %b %b %b", rst, D[3], D[2], D[1], D[0], LD, SH, Q[3], Q[2], Q[1], Q[0]);
            check_output(expected_Q, Q, D, LD, SH, rst);
            test_count = test_count + 1;

            // Shift 4 times
            LD = 0;
            for (j = 0; j < 4; j = j + 1) begin
                SH = 1;
                @(negedge clk);
                expected_Q = {expected_Q[2:0], 1'b0};
                #1;
                $fdisplay(fd, "%b %b %b %b %b %b %b | %b %b %b %b", rst, D[3], D[2], D[1], D[0], LD, SH, Q[3], Q[2], Q[1], Q[0]);
                check_output(expected_Q, Q, D, LD, SH, rst);
                test_count = test_count + 1;
            end
            SH = 0;
        end

        // Test simultaneous LD and SH (LD has priority)
        for (i = 0; i < 4; i = i + 1) begin
            D = i[3:0];
            LD = 1; SH = 1;
            @(negedge clk);
            expected_Q = D;
            #1;
            $fdisplay(fd, "%b %b %b %b %b %b %b | %b %b %b %b", rst, D[3], D[2], D[1], D[0], LD, SH, Q[3], Q[2], Q[1], Q[0]);
            check_output(expected_Q, Q, D, LD, SH, rst);
            test_count = test_count + 1;
        end

        // Test reset during operation
        D = 4'b1010; LD = 1; SH = 0;
        @(negedge clk);
        expected_Q = D;
        #1;
        $fdisplay(fd, "%b %b %b %b %b %b %b | %b %b %b %b", rst, D[3], D[2], D[1], D[0], LD, SH, Q[3], Q[2], Q[1], Q[0]);
        check_output(expected_Q, Q, D, LD, SH, rst);
        test_count = test_count + 1;

        LD = 0; SH = 1;
        @(negedge clk);
        expected_Q = {expected_Q[2:0], 1'b0};
        #1;
        $fdisplay(fd, "%b %b %b %b %b %b %b | %b %b %b %b", rst, D[3], D[2], D[1], D[0], LD, SH, Q[3], Q[2], Q[1], Q[0]);
        check_output(expected_Q, Q, D, LD, SH, rst);
        test_count = test_count + 1;

        rst = 1;
        @(negedge clk);
        expected_Q = 4'b0000;
        #1;
        $fdisplay(fd, "%b %b %b %b %b %b %b | %b %b %b %b", rst, D[3], D[2], D[1], D[0], LD, SH, Q[3], Q[2], Q[1], Q[0]);
        check_output(expected_Q, Q, D, LD, SH, rst);
        test_count = test_count + 1;
        rst = 0;

        // Randomized test cases for additional coverage
        for (i = 0; i < 40; i = i + 1) begin
            D = $random % 16;
            LD = $random % 2;
            SH = $random % 2;
            rst = (i == 10) ? 1 : 0;
            Q_prev = Q;
            @(negedge clk);
            if (rst)
                expected_Q = 4'b0000;
            else if (LD)
                expected_Q = D;
            else if (SH)
                expected_Q = {Q_prev[2:0], 1'b0};
            else
                expected_Q = Q_prev;
            #1;
            $fdisplay(fd, "%b %b %b %b %b %b %b | %b %b %b %b", rst, D[3], D[2], D[1], D[0], LD, SH, Q[3], Q[2], Q[1], Q[0]);
            check_output(expected_Q, Q, D, LD, SH, rst);
            test_count = test_count + 1;
            rst = 0;
        end

        // Close file and report
        $fclose(fd);
        $display("Testbench completed: %0d tests, %0d errors", test_count, error_count);
        $finish;
    end

endmodule

