module sky130_fd_sc_hs__or4_4 (
    X,
    A,
    B,
    C,
    D
);

    output X;
    input  A;
    input  B;
    input  C;
    input  D;

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;

    wire AB, CD, ABCD;

    // Simple 2-input OR gate as a local module
    or u_or1 (AB, A, B);   // AB = A | B
    or u_or2 (CD, C, D);   // CD = C | D
    or u_or3 (ABCD, AB, CD); // ABCD = AB | CD

    assign X = ABCD;

endmodule

