        $display("ERROR at time %0t: ena=%b d=%b rst=%b | q=%b expected=%b", $time, ena, d, rst, q, expected_q);
        error_count = error_count + 1;
      end

      prev_q = expected_q;
      vector_count = vector_count + 1;
    end

    // Additional edge case: toggle reset in the middle of enable
    ena = 1;
    d = 1;
    rst = 0;
    @(negedge clk);
    @(posedge clk);
    #1;
    if (ena)
      expected_q = d;
    else
      expected_q = prev_q;
    $fdisplay(fd, "%b %b %b %b %b", clk, ena, d, rst, q);
    if (q !== expected_q) begin
      $display("ERROR at time %0t: ena=%b d=%b rst=%b | q=%b expected=%b", $time, ena, d, rst, q, expected_q);
      error_count = error_count + 1;
    end
    prev_q = expected_q;
    vector_count = vector_count + 1;

    rst = 1;
    @(negedge clk);
    @(posedge clk);
    #1;
    expected_q = 0;
    $fdisplay(fd, "%b %b %b %b %b", clk, ena, d, rst, q);
    if (q !== expected_q) begin
      $display("ERROR at time %0t: ena=%b d=%b rst=%b | q=%b expected=%b", $time, ena, d, rst, q, expected_q);
      error_count = error_count + 1;
    end
    prev_q = expected_q;
    vector_count = vector_count + 1;

    rst = 0;
    ena = 0;
    d = 0;
    @(negedge clk);
    @(posedge clk);
    #1;
    if (ena)
      expected_q = d;
    else
      expected_q = prev_q;
    $fdisplay(fd, "%b %b %b %b %b", clk, ena, d, rst, q);
    if (q !== expected_q) begin
      $display("ERROR at time %0t: ena=%b d=%b rst=%b | q=%b expected=%b", $time, ena, d, rst, q, expected_q);
      error_count = error_count + 1;
    end
    prev_q = expected_q;
    vector_count = vector_count + 1;

    // Close file
    $fclose(fd);

    // Report results
    if (error_count == 0)
      $display("All %0d test vectors passed.", vector_count);
    else
      $display("Testbench completed with %0d errors out of %0d vectors.", error_count, vector_count);

    $finish;
  end

endmodule

