    input reg expected_Q;
    begin
      if (Q !== expected_Q) begin
        $display("ERROR at time %0t: D=%b RESET=%b Q=%b (expected %b)", $time, D, RESET, Q, expected_Q);
        error_count = error_count + 1;
      end
    end
  endtask

