      $display("Failed to open file");
      $finish;
    end

    error_count = 0;
    test_count = 0;

    // Initialize all signals
    D = 0;
    RESET = 1;
    // Wait for global reset
    #2;

    // Test asynchronous reset (RESET low)
    D = 1;
    RESET = 0;
    @(negedge CLK); #1;
    $fdisplay(fd, "%b %b %b %b", D, RESET, CLK, Q);
    check_output(1'b0);
