    D = 1;
    @(posedge CLK); #1;
    $fdisplay(fd, "%b %b %b %b", D, RESET, CLK, Q);
    check_output(1'b1);
    test_count = test_count + 1;

    // Toggle D, check Q updates only on posedge CLK
    for (i = 0; i < 48; i = i + 1) begin
      D = $random % 2;
      RESET = 1;
      @(posedge CLK); #1;
      $fdisplay(fd, "%b %b %b %b", D, RESET, CLK, Q);
      check_output(D);
      test_count = test_count + 1;
    end

    // Test asynchronous reset during operation
    D = 1;
    RESET = 1;
    @(posedge CLK); #1;
    $fdisplay(fd, "%b %b %b %b", D, RESET, CLK, Q);
    check_output(1'b1);
    test_count = test_count + 1;

    D = 0;
    RESET = 0; // Assert reset asynchronously
    #2;
    $fdisplay(fd, "%b %b %b %b", D, RESET, CLK, Q);
    check_output(1'b0);
    test_count = test_count + 1;

    RESET = 1;
    @(posedge CLK); #1;
    $fdisplay(fd, "%b %b %b %b", D, RESET, CLK, Q);
    check_output(D);
    test_count = test_count + 1;

    // Test multiple resets and D toggles
    for (i = 0; i < 48; i = i + 1) begin
      D = $random % 2;
