      else RESET = 1;
      @(posedge CLK); #1;
      $fdisplay(fd, "%b %b %b %b", D, RESET, CLK, Q);
      if (!RESET)
        check_output(1'b0);
      else
        check_output(D);
      test_count = test_count + 1;
    end

    // Final test: hold RESET low for several cycles
    D = 1;
    RESET = 0;
    repeat (3) begin
      @(posedge CLK); #1;
      $fdisplay(fd, "%b %b %b %b", D, RESET, CLK, Q);
      check_output(1'b0);
      test_count = test_count + 1;
    end

    // Release RESET and check normal operation
    RESET = 1;
    D = 1;
    @(posedge CLK); #1;
    $fdisplay(fd, "%b %b %b %b", D, RESET, CLK, Q);
    check_output(1'b1);
    test_count = test_count + 1;

    $display("Testbench completed: %0d tests, %0d errors", test_count, error_count);
    $fclose(fd);
    $finish;
  end

  // Timeout mechanism
  initial begin
    #TIMEOUT;
    $display("TIMEOUT: Simulation exceeded %0d time units", TIMEOUT);
    $fclose(fd);
    $finish;
  end

endmodule

