                    A_in, B_in, sub_in, dut_result, exp_result, $time);
                error_count = error_count + 1;
            end
            // Assertion (SystemVerilog style, but also works in Verilog-2001)
            if (dut_result !== exp_result) begin
                $stop;
            end
        end
    endtask

    // Main stimulus
    initial begin
        error_count = 0;
        test_count = 0;

