                    else
                        expected_result = (A - B) & 4'hF;

                    // Write test vector: A B sub result
                    $fdisplay(fd, "%0d %0d %0d %0d", A, B, sub, result);

                    // Check result
                    check_result(A, B, sub, result, expected_result);

