module add_with_enable (
    input wire A,
    input wire B,
    input wire enable,
    output reg C
);

always @ (posedge enable or posedge A or posedge B) begin
    if (enable)
        C <= A ^ B; // sum with no carry, XOR for 1-bit inputs
end

// Hold value if enable is low; no assignment on enable==0,
// so C retains its previous value.

endmodule

