    task check_output;
        input reg exp_C;
        begin
            if (C !== exp_C) begin
                $display("ERROR at time %0t: A=%b B=%b enable=%b | Expected C=%b, Got C=%b", $time, A, B, enable, exp_C, C);
                error_count = error_count + 1;
            end
        end
    endtask

    // Timeout mechanism
    initial begin
        timeout_flag = 0;
        #(TIMEOUT);
        timeout_flag = 1;
        $display("TIMEOUT: Simulation exceeded %0d time units.", TIMEOUT);
        $finish;
    end

    // Main test process
    initial begin
        error_count = 0;
        fd = $fopen("test_vectors.txt", "w");
        if (fd)
            $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        // Initialize signals
        A = 0; B = 0; enable = 0;
        #5;

        // 1. Exhaustive test of all input combinations with enable transitions
        for (i = 0; i < 8; i = i + 1) begin
            // Inputs: [A][B][enable]
            A = (i >> 2) & 1'b1;
            B = (i >> 1) & 1'b1;
            enable = i & 1'b1;
            #2; // settle

            // Rising edge of enable
            enable = 0; #2;
            enable = 1; #2;

            expected_C = A ^ B;
            #1;
            $fdisplay(fd, "%b %b %b %b", A, B, enable, C);
            check_output(expected_C);

            // Lower enable, check C holds
            enable = 0; #2;
            $fdisplay(fd, "%b %b %b %b", A, B, enable, C);
            check_output(expected_C);
        end

        // 2. Randomized test vectors (to reach at least 100 vectors)
        repeat (92) begin
            A = $random % 2;
            B = $random % 2;
            enable = 0;
            #2;
            // Randomly pulse enable
            if ($random % 2) begin
                enable = 1; #1;
                expected_C = A ^ B;
                #1;
                $fdisplay(fd, "%b %b %b %b", A, B, enable, C);
                check_output(expected_C);
                enable = 0; #1;
            end else begin
                // No enable, C should hold previous value
                #1;
                $fdisplay(fd, "%b %b %b %b", A, B, enable, C);
                // No check_output here, as C should hold previous value
            end
        end

        // 3. Test C holds value when enable is low and A/B change
        A = 1; B = 0; enable = 1; #2;
        expected_C = 1 ^ 0;
        #1;
        $fdisplay(fd, "%b %b %b %b", A, B, enable, C);
        check_output(expected_C);

        enable = 0; #2;
        A = 0; B = 1; #2;
        $fdisplay(fd, "%b %b %b %b", A, B, enable, C);
        check_output(expected_C); // C should not change

        // 4. Test multiple enable pulses
        A = 0; B = 0; enable = 1; #2;
        expected_C = 0 ^ 0;
        #1;
        $fdisplay(fd, "%b %b %b %b", A, B, enable, C);
        check_output(expected_C);

        enable = 0; #2;
        A = 1; B = 1; #2;
        enable = 1; #2;
        expected_C = 1 ^ 1;
        #1;
        $fdisplay(fd, "%b %b %b %b", A, B, enable, C);
        check_output(expected_C);

        // 5. Test enable pulse with no A/B change
        enable = 0; #2;
        enable = 1; #2;
        $fdisplay(fd, "%b %b %b %b", A, B, enable, C);
        check_output(expected_C);

        // Finish
        $display("Testbench completed with %0d errors.", error_count);
        $fclose(fd);
        $finish;
    end

endmodule

