module add5_4bit (
    input [3:0] A,
    output [3:0] Y
);

    // 4-bit adder: Y = A + 5 (5 = 4'b0101)
    // Only bitwise, logical, and conditional operators allowed

    wire c0, c1, c2, c3;
    wire a0, a1, a2, a3;

    assign a0 = A[0];
    assign a1 = A[1];
    assign a2 = A[2];
    assign a3 = A[3];

    // Add 1 (A[0] + 1)
    assign Y[0] = a0 ^ 1'b1;
    assign c0   = a0 & 1'b1;

    // Add 0 (A[1] + 0 + c0)
    assign Y[1] = a1 ^ c0;
    assign c1   = a1 & c0;

    // Add 1 (A[2] + 1 + c1)
    assign Y[2] = a2 ^ 1'b1 ^ c1;
    assign c2   = (a2 & c1) | (a2 & 1'b1) | (c1 & 1'b1);

    // Add 0 (A[3] + 0 + c2)
    assign Y[3] = a3 ^ c2;
    // c3 is the carry out (ignored for 4-bit output)

endmodule

