module clock_generator (
    input  wire clk_in,    // 10 MHz input clock
    output reg  clk_out    // 100 MHz output clock
);

    // Internal counter: counts from 0 to 4 (total 5 states for 10 MHz / 100 MHz)
    reg [2:0] counter;

    initial begin
        counter = 0;
        clk_out = 0;
    end

    always @(posedge clk_in) begin
        counter <= 0;
        clk_out <= 1;
    end

    always @(negedge clk_in) begin
        counter <= counter + 1;
        if (counter < 4)
            clk_out <= ~clk_out;
        else
            clk_out <= 0;
    end

endmodule

