            else
                expected_Q = D;
            #1; // Allow Q to settle

            $fdisplay(fd, "%b %b %b %b", D, C, R, Q);

            if (Q !== expected_Q) begin
                $display("ERROR at test %0d: D=%b R=%b C=%b | Q=%b (expected %b) at time %0t", test_num, D, R, C, Q, expected_Q, $time);
                error_count = error_count + 1;
            end
            test_num = test_num + 1;
        end

        // Additional edge case: assert reset asynchronously
        @(negedge C);
        D = 1'b1;
        R = 1'b1;
        #1;
        $fdisplay(fd, "%b %b %b %b", D, C, R, Q);
        if (Q !== 1'b0) begin
            $display("ERROR at reset edge case: D=%b R=%b C=%b | Q=%b (expected 0) at time %0t", D, R, C, Q, $time);
            error_count = error_count + 1;
        end
        test_num = test_num + 1;

        // Release reset, check D is captured
        @(negedge C);
        D = 1'b1;
        R = 1'b0;
        #1;
        $fdisplay(fd, "%b %b %b %b", D, C, R, Q);
        if (Q !== 1'b1) begin
            $display("ERROR at release reset: D=%b R=%b C=%b | Q=%b (expected 1) at time %0t", D, R, C, Q, $time);
            error_count = error_count + 1;
        end
        test_num = test_num + 1;

        // Close file and finish
        $fclose(fd);
        $display("Testbench completed with %0d errors after %0d test vectors.", error_count, test_num);
        $finish;
    end

endmodule

