// Module: binary_to_gray
// Description: Converts a 4-bit binary input to 4-bit Gray code output using combinational logic

module binary_to_gray(
    input  [3:0] binary_in,
    output [3:0] gray_out
);

    // Gray code conversion logic
    assign gray_out[3] = binary_in[3];
    assign gray_out[2] = binary_in[3] ^ binary_in[2];
    assign gray_out[1] = binary_in[2] ^ binary_in[1];
    assign gray_out[0] = binary_in[1] ^ binary_in[0];

endmodule

