        $fdisplay(fd, "%b %b %b %b %b %b %b", D, CLK, RESET, SET, EN, Q, QBAR);
        check_outputs(1, 0);
        vector_count = vector_count + 1;

        // 3. Both RESET and SET asserted (RESET has priority)
        D = 1; EN = 1; SET = 1; RESET = 1;
        @(negedge CLK);
        #1;
        $fdisplay(fd, "%b %b %b %b %b %b %b", D, CLK, RESET, SET, EN, Q, QBAR);
        check_outputs(0, 1);
        vector_count = vector_count + 1;

        // 4. Deassert RESET and SET
        D = 0; EN = 1; SET = 0; RESET = 0;
        @(negedge CLK);
        #1;
        $fdisplay(fd, "%b %b %b %b %b %b %b", D, CLK, RESET, SET, EN, Q, QBAR);
        // Q should remain as previous value (from SET or RESET)
        vector_count = vector_count + 1;

        // 5. EN=0, D changes, no effect
        D = 1; EN = 0; SET = 0; RESET = 0;
        @(negedge CLK);
        @(posedge CLK); #1;
        $fdisplay(fd, "%b %b %b %b %b %b %b", D, CLK, RESET, SET, EN, Q, QBAR);
        // Q should remain unchanged
        vector_count = vector_count + 1;

        // 6. EN=1, D changes, Q follows D on posedge CLK
        for (i = 0; i < 4; i = i + 1) begin
            D = i[0];
            EN = 1;
            SET = 0;
            RESET = 0;
            @(negedge CLK);
            @(posedge CLK); #1;
            $fdisplay(fd, "%b %b %b %b %b %b %b", D, CLK, RESET, SET, EN, Q, QBAR);
            check_outputs(D, ~D);
            vector_count = vector_count + 1;
        end

        // 7. EN=1, D toggles, SET asserted asynchronously
        D = 0; EN = 1; SET = 1; RESET = 0;
        @(negedge CLK);
        #1;
        $fdisplay(fd, "%b %b %b %b %b %b %b", D, CLK, RESET, SET, EN, Q, QBAR);
        check_outputs(1, 0);
        vector_count = vector_count + 1;

        // 8. EN=1, D toggles, RESET asserted asynchronously
        D = 1; EN = 1; SET = 0; RESET = 1;
        @(negedge CLK);
        #1;
        $fdisplay(fd, "%b %b %b %b %b %b %b", D, CLK, RESET, SET, EN, Q, QBAR);
        check_outputs(0, 1);
        vector_count = vector_count + 1;

        // 9. EN=1, D toggles, SET and RESET both asserted (RESET priority)
        D = 1; EN = 1; SET = 1; RESET = 1;
        @(negedge CLK);
        #1;
        $fdisplay(fd, "%b %b %b %b %b %b %b", D, CLK, RESET, SET, EN, Q, QBAR);
        check_outputs(0, 1);
        vector_count = vector_count + 1;

        // 10. EN=0, D toggles, SET asserted asynchronously
        D = 1; EN = 0; SET = 1; RESET = 0;
        @(negedge CLK);
        #1;
        $fdisplay(fd, "%b %b %b %b %b %b %b", D, CLK, RESET, SET, EN, Q, QBAR);
        check_outputs(1, 0);
        vector_count = vector_count + 1;

        // 11. EN=0, D toggles, RESET asserted asynchronously
        D = 0; EN = 0; SET = 0; RESET = 1;
        @(negedge CLK);
        #1;
        $fdisplay(fd, "%b %b %b %b %b %b %b", D, CLK, RESET, SET, EN, Q, QBAR);
        check_outputs(0, 1);
        vector_count = vector_count + 1;

        // 12. EN=0, D toggles, SET and RESET both asserted (RESET priority)
        D = 0; EN = 0; SET = 1; RESET = 1;
        @(negedge CLK);
        #1;
        $fdisplay(fd, "%b %b %b %b %b %b %b", D, CLK, RESET, SET, EN, Q, QBAR);
        check_outputs(0, 1);
        vector_count = vector_count + 1;

        // 13. EN=1, D toggles, SET and RESET both deasserted, check Q follows D on CLK
        for (i = 0; i < 8; i = i + 1) begin
            D = i[0];
            EN = 1;
            SET = 0;
            RESET = 0;
            @(negedge CLK);
            @(posedge CLK); #1;
            $fdisplay(fd, "%b %b %b %b %b %b %b", D, CLK, RESET, SET, EN, Q, QBAR);
            check_outputs(D, ~D);
            vector_count = vector_count + 1;
        end

        // 14. Randomized test vectors for more coverage
        for (i = 0; i < 80; i = i + 1) begin
            D = $random % 2;
            EN = $random % 2;
            SET = $random % 2;
            RESET = $random % 2;
            @(negedge CLK);
            // Apply async signals at random times
            if (SET || RESET) begin
                #1;
                $fdisplay(fd, "%b %b %b %b %b %b %b", D, CLK, RESET, SET, EN, Q, QBAR);
                if (RESET)
                    check_outputs(0, 1);
                else if (SET)
                    check_outputs(1, 0);
            end else if (EN) begin
                @(posedge CLK); #1;
                $fdisplay(fd, "%b %b %b %b %b %b %b", D, CLK, RESET, SET, EN, Q, QBAR);
                check_outputs(D, ~D);
            end else begin
                @(posedge CLK); #1;
                $fdisplay(fd, "%b %b %b %b %b %b %b", D, CLK, RESET, SET, EN, Q, QBAR);
                // Q should remain unchanged, cannot assert without tracking previous Q
            end
            vector_count = vector_count + 1;
        end

        $display("Test completed with %0d vectors, %0d errors.", vector_count, error_count);
        $fclose(fd);
        $finish;
    end

