        D_vec[2] = 2'b10;
        D_vec[3] = 2'b11;
        load_vec[0] = 1'b0;
        load_vec[1] = 1'b1;
        rst_vec[0] = 1'b0;
        rst_vec[1] = 1'b1;

        // Initialize
        rst = 1;
        load = 0;
        D = 2'b00;
        error_count = 0;
        expected_Q = 2'b00;
        Q_prev = 2'b00;

        // Apply reset
        @(negedge clk);
        rst = 1;
        load = 0;
        D = 2'b00;
        @(negedge clk);
        rst = 0;

        // Main test loop: generate at least 100 test vectors
        t = 0;
        for (i = 0; i < 25; i = i + 1) begin
            // Randomize inputs for variety
            rst = $random % 2;
            load = $random % 2;
            D = $random % 4;

            // Save previous Q for expected value calculation
            Q_prev = expected_Q;

            // Wait for next clock edge
            @(negedge clk);

            // Compute expected Q
            if (rst) begin
                expected_Q = 2'b00;
            end else if (load) begin
                expected_Q = D;
            end else begin
                expected_Q = Q_prev + D;
            end

            // Wait for Q to update
            @(posedge clk);

            // Write test vector to file: clk rst load D[1] D[0] Q[1] Q[0]
            $fdisplay(fd, "%b %b %b %b%b %b%b", clk, rst, load, D[1], D[0], Q[1], Q[0]);
            t = t + 1;

            // Assertion
            if (Q !== expected_Q) begin
                $display("ERROR at time %0t: rst=%b load=%b D=%b Q=%b expected_Q=%b", $time, rst, load, D, Q, expected_Q);
                error_count = error_count + 1;
            end
        end

        // Systematic test: all combinations of rst, load, D for several cycles
        expected_Q = 2'b00;
        rst = 1;
        load = 0;
        D = 2'b00;
        @(negedge clk);
        rst = 0;
        @(negedge clk);

        for (i = 0; i < 2; i = i + 1) begin // rst
            for (j = 0; j < 2; j = j + 1) begin // load
                for (k = 0; k < 4; k = k + 1) begin // D
                    rst = rst_vec[i];
                    load = load_vec[j];
