                    Q_prev = expected_Q;

                    @(negedge clk);

                    if (rst) begin
                        expected_Q = 2'b00;
                    end else if (load) begin
                        expected_Q = D;
                    end else begin
                        expected_Q = Q_prev + D;
                    end

                    @(posedge clk);

                    $fdisplay(fd, "%b %b %b %b%b %b%b", clk, rst, load, D[1], D[0], Q[1], Q[0]);
                    t = t + 1;

                    if (Q !== expected_Q) begin
