                        error_count = error_count + 1;
                    end
                end
            end
        end

        // Sequential operation: test accumulation
        expected_Q = 2'b00;
        rst = 1;
        load = 0;
        D = 2'b00;
        @(negedge clk);
        rst = 0;
        @(negedge clk);

        for (i = 0; i < 20; i = i + 1) begin
