                error_count = error_count + 1;
            end
        end

        // Test reset functionality
        expected_Q = 2'b11;
        rst = 0;
        load = 1;
        D = 2'b11;
        @(negedge clk);
        @(posedge clk);
        $fdisplay(fd, "%b %b %b %b%b %b%b", clk, rst, load, D[1], D[0], Q[1], Q[0]);
        t = t + 1;

        rst = 1;
        load = 0;
        D = 2'b10;
        Q_prev = Q;
        @(negedge clk);

        expected_Q = 2'b00;

        @(posedge clk);

        $fdisplay(fd, "%b %b %b %b%b %b%b", clk, rst, load, D[1], D[0], Q[1], Q[0]);
        t = t + 1;

        if (Q !== expected_Q) begin
            $display("ERROR at time %0t: rst=%b load=%b D=%b Q=%b expected_Q=%b", $time, rst, load, D, Q, expected_Q);
            error_count = error_count + 1;
        end

        // Ensure at least 100 test vectors
        while (t < 100) begin
            rst = $random % 2;
            load = $random % 2;
            D = $random % 4;
            Q_prev = expected_Q;

            @(negedge clk);

