        check_result(CLK, D, SET, CLR, Q, expected_Q, fd);

        // Set Q to 1
        CLR = 0; SET = 1; D = 0;
        @(negedge CLK);
        @(posedge CLK);
        #1;
        expected_Q = 1;
        check_result(CLK, D, SET, CLR, Q, expected_Q, fd);

        // Clear Q to 0 again
        CLR = 1; SET = 0; D = 0;
        @(negedge CLK);
        @(posedge CLK);
        #1;
        expected_Q = 0;
        check_result(CLK, D, SET, CLR, Q, expected_Q, fd);

        // Test all input combinations over 100 cycles
        for (i = 0; i < 100; i = i + 1) begin
            @(negedge CLK);
            // Randomize inputs
            D   = $random % 2;
            SET = $random % 2;
            CLR = $random % 2;

            @(posedge CLK);
            #1;

            // Compute expected_Q
            if (SET)
                expected_Q = 1;
            else if (CLR)
                expected_Q = 0;
            else
                expected_Q = D;

            check_result(CLK, D, SET, CLR, Q, expected_Q, fd);
        end

        // Deterministic exhaustive test for all input combinations (8 combinations)
        for (D = 0; D <= 1; D = D + 1) begin
            for (SET = 0; SET <= 1; SET = SET + 1) begin
                for (CLR = 0; CLR <= 1; CLR = CLR + 1) begin
                    @(negedge CLK);
                    @(posedge CLK);
                    #1;
                    if (SET)
                        expected_Q = 1;
                    else if (CLR)
                        expected_Q = 0;
                    else
                        expected_Q = D;
                    check_result(CLK, D, SET, CLR, Q, expected_Q, fd);
                end
            end
        end

        $display("Test completed with %0d errors out of %0d tests.", error_count, test_count);
        $fclose(fd);
        $finish;
    end

    // Task to check result, write to file, and count errors
    task check_result;
        input clk_v;
        input d_v;
        input set_v;
        input clr_v;
        input q_v;
        input expected_q_v;
        input integer fd_v;
        begin
            test_count = test_count + 1;
            // Write test vector: CLK D SET CLR Q
            $fdisplay(fd_v, "%b %b %b %b %b", clk_v, d_v, set_v, clr_v, q_v);
            // Assertion
            if (q_v !== expected_q_v) begin
                error_count = error_count + 1;
                $display("Error at time %0t: CLK=%b D=%b SET=%b CLR=%b Q=%b (expected %b)", $time, clk_v, d_v, set_v, clr_v, q_v, expected_q_v);
            end
        end
    endtask

endmodule

