module mux4to1 (
    input A,
    input B,
    input C,
    input D,
    input S0,
    input S1,
    output Y
);

    wire not_s0;
    wire not_s1;
    wire y_a, y_b, y_c, y_d;

    assign not_s0 = ~S0;
    assign not_s1 = ~S1;

    assign y_a = A & not_s1 & not_s0;
    assign y_b = B & not_s1 & S0;
    assign y_c = C & S1 & not_s0;
    assign y_d = D & S1 & S0;

    assign Y = y_a | y_b | y_c | y_d;

endmodule

