    wire Q;

    // Instantiate the Unit Under Test (UUT)
    binary_latch_with_reset uut (
        .CLK(CLK),
        .RST(RST),
        .D(D),
        .Q(Q)
    );

    // File descriptor for test vector output
    integer fd;
    integer error_count;
    integer vector_count;
    reg expected_Q;
    reg prev_Q;

    // Timeout mechanism
    parameter TIMEOUT = 10000;

    // Clock generation
    initial begin
        CLK = 0;
        forever #5 CLK = ~CLK;
    end

    // Open file and initialize
    initial begin
        fd = $fopen("test_vectors.txt", "w");
        if (fd) $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end
        error_count = 0;
        vector_count = 0;
    end

    // Test vector application
    initial begin
        RST = 0;
        D = 0;
        prev_Q = 0;
        expected_Q = 0;
        @(negedge CLK); // Wait for first negative edge to synchronize
        // Apply all combinations for at least 100 vectors
        repeat (100) begin
            // Randomize inputs for coverage
            RST = $random % 2;
            D   = $random % 2;
            // Wait for positive clock edge
            @(posedge CLK);
            // Compute expected Q
            if (RST == 1)
                expected_Q = 0;
            else
                expected_Q = D;
            // Wait for output to settle
            #1;
            // Write test vector: CLK RST D Q
            $fdisplay(fd, "%b %b %b %b", CLK, RST, D, Q);
            // Check output
            check_output(expected_Q, Q, CLK, RST, D, vector_count);
            prev_Q = Q;
            vector_count = vector_count + 1;
        end

        // Additional corner cases: reset assertion/deassertion, D changes
        // Reset asserted
        RST = 1; D = 1; @(posedge CLK); #1;
        $fdisplay(fd, "%b %b %b %b", CLK, RST, D, Q);
        check_output(0, Q, CLK, RST, D, vector_count); vector_count = vector_count + 1;

        // Reset deasserted, D=1
        RST = 0; D = 1; @(posedge CLK); #1;
        $fdisplay(fd, "%b %b %b %b", CLK, RST, D, Q);
        check_output(1, Q, CLK, RST, D, vector_count); vector_count = vector_count + 1;

        // D=0
        RST = 0; D = 0; @(posedge CLK); #1;
        $fdisplay(fd, "%b %b %b %b", CLK, RST, D, Q);
        check_output(0, Q, CLK, RST, D, vector_count); vector_count = vector_count + 1;

        // Reset asserted again
        RST = 1; D = 0; @(posedge CLK); #1;
        $fdisplay(fd, "%b %b %b %b", CLK, RST, D, Q);
        check_output(0, Q, CLK, RST, D, vector_count); vector_count = vector_count + 1;

        // D toggling while reset low
        RST = 0;
        D = 0; @(posedge CLK); #1;
        $fdisplay(fd, "%b %b %b %b", CLK, RST, D, Q);
        check_output(0, Q, CLK, RST, D, vector_count); vector_count = vector_count + 1;
        D = 1; @(posedge CLK); #1;
        $fdisplay(fd, "%b %b %b %b", CLK, RST, D, Q);
        check_output(1, Q, CLK, RST, D, vector_count); vector_count = vector_count + 1;
        D = 0; @(posedge CLK); #1;
        $fdisplay(fd, "%b %b %b %b", CLK, RST, D, Q);
        check_output(0, Q, CLK, RST, D, vector_count); vector_count = vector_count + 1;

        // End of test
        $display("Test completed with %0d errors out of %0d vectors.", error_count, vector_count);
        $fclose(fd);
        $finish;
    end

    // Timeout mechanism
    initial begin
        #TIMEOUT;
        $display("Timeout reached at time %0t. Simulation stopped.", $time);
        $fclose(fd);
        $finish;
    end

    // Error checking task
    task check_output;
        input reg exp_Q;
        input reg act_Q;
        input reg clk_in;
        input reg rst_in;
        input reg d_in;
        input integer vec_num;
        begin
            if (act_Q !== exp_Q) begin
                error_count = error_count + 1;
                $display("ERROR at vector %0d: CLK=%b RST=%b D=%b | Expected Q=%b, Got Q=%b at time %0t",
