// Description:
//   Implements a 3-input AND gate with an inverted B1 input, and an active-low
//   enable (C1). If C1 is high, Y = 0. If C1 is low, Y = A1 & A2 & A3 & ~B1.

module and_gate_with_inverter (
    output Y,      // Output of the logic
    input  A1,     // AND gate input 1
    input  A2,     // AND gate input 2
    input  A3,     // AND gate input 3
    input  B1,     // Input to be inverted
    input  C1      // Control input (active HIGH disables output)
);

