    wire B1_inv;
    assign B1_inv = ~B1;

    // Intermediate AND of A1, A2, A3, and B1_inv
    wire and_result;
    assign and_result = A1 & A2 & A3 & B1_inv;

    // Output logic based on C1
    assign Y = (C1) ? 1'b0 : and_result;

endmodule

