module calculator_tb;

    // Inputs
    reg [7:0] num1;
    reg [7:0] num2;
    reg [1:0] opcode;

    // Output
    wire [7:0] result;

    // Instantiate the calculator module
    calculator uut (
        .num1(num1),
        .num2(num2),
        .opcode(opcode),
        .result(result)
    );

    // File descriptor for test vector output
    integer fd;
    integer i;
    integer error_count;
    reg [7:0] expected_result;
    reg [7:0] test_num1, test_num2;
    reg [1:0] test_opcode;

    // Timeout mechanism
    initial begin
        #10000;
        $display("Timeout reached at time %0t. Ending simulation.", $time);
        $finish;
    end

    // Task to check result and report errors
    task check_result;
        input [7:0] exp;
        input [7:0] got;
        input [7:0] n1;
        input [7:0] n2;
        input [1:0] opc;
        begin
            if (exp !== got) begin
                $display("ERROR: num1=%0d num2=%0d opcode=%0d Expected=%0d Got=%0d at time %0t", n1, n2, opc, exp, got, $time);
                error_count = error_count + 1;
            end
        end
    endtask

    // Main stimulus
    initial begin
        error_count = 0;
        fd = $fopen("test_vectors.txt", "w");
        if (fd)
            $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        // Write header (optional, can be commented out if not needed)
        // $fdisplay(fd, "num1 num2 opcode result");

        // Test all opcodes with a variety of values, including edge cases
        // 25 tests per opcode, total 100 tests

        // Addition tests (opcode 00)
        for (i = 0; i < 25; i = i + 1) begin
            if (i == 0) begin test_num1 = 8'd0; test_num2 = 8'd0; end
            else if (i == 1) begin test_num1 = 8'd255; test_num2 = 8'd255; end
            else if (i == 2) begin test_num1 = 8'd128; test_num2 = 8'd128; end
            else if (i == 3) begin test_num1 = 8'd1; test_num2 = 8'd254; end
            else if (i == 4) begin test_num1 = 8'd127; test_num2 = 8'd1; end
            else begin
                test_num1 = $random % 256;
                test_num2 = $random % 256;
            end
            test_opcode = 2'b00;
            num1 = test_num1;
            num2 = test_num2;
            opcode = test_opcode;
            #1;
            expected_result = test_num1 + test_num2;
            check_result(expected_result, result, test_num1, test_num2, test_opcode);
            $fdisplay(fd, "%0d %0d %0d %0d", test_num1, test_num2, test_opcode, result);
        end

        // Subtraction tests (opcode 01)
        for (i = 0; i < 25; i = i + 1) begin
            if (i == 0) begin test_num1 = 8'd0; test_num2 = 8'd0; end
            else if (i == 1) begin test_num1 = 8'd255; test_num2 = 8'd255; end
            else if (i == 2) begin test_num1 = 8'd128; test_num2 = 8'd127; end
            else if (i == 3) begin test_num1 = 8'd1; test_num2 = 8'd2; end
            else if (i == 4) begin test_num1 = 8'd0; test_num2 = 8'd255; end
            else begin
                test_num1 = $random % 256;
                test_num2 = $random % 256;
            end
            test_opcode = 2'b01;
            num1 = test_num1;
            num2 = test_num2;
            opcode = test_opcode;
            #1;
            expected_result = test_num1 - test_num2;
            check_result(expected_result, result, test_num1, test_num2, test_opcode);
            $fdisplay(fd, "%0d %0d %0d %0d", test_num1, test_num2, test_opcode, result);
        end

        // Multiplication tests (opcode 10)
        for (i = 0; i < 25; i = i + 1) begin
            if (i == 0) begin test_num1 = 8'd0; test_num2 = 8'd0; end
            else if (i == 1) begin test_num1 = 8'd255; test_num2 = 8'd1; end
            else if (i == 2) begin test_num1 = 8'd16; test_num2 = 8'd16; end
            else if (i == 3) begin test_num1 = 8'd2; test_num2 = 8'd128; end
            else if (i == 4) begin test_num1 = 8'd10; test_num2 = 8'd25; end
            else begin
                test_num1 = $random % 256;
                test_num2 = $random % 256;
            end
            test_opcode = 2'b10;
            num1 = test_num1;
            num2 = test_num2;
            opcode = test_opcode;
            #1;
            expected_result = test_num1 * test_num2;
            check_result(expected_result, result, test_num1, test_num2, test_opcode);
            $fdisplay(fd, "%0d %0d %0d %0d", test_num1, test_num2, test_opcode, result);
        end

        // Division tests (opcode 11)
        for (i = 0; i < 25; i = i + 1) begin
            if (i == 0) begin test_num1 = 8'd0; test_num2 = 8'd1; end // avoid div by zero
