module adder4 (
    input  wire [3:0] A,
    input  wire [3:0] B,
    input  wire       enable,
    output wire [3:0] sum,
    output wire       overflow
);

    wire [4:0] sum_full;

    // Perform addition when enabled
    assign sum_full = enable ? (A + B) : 5'b00000;

    // Output lower 4 bits as sum
    assign sum = sum_full[3:0];

    // Overflow if 5th bit is set (i.e., sum > 15)
    assign overflow = sum_full[4];

endmodule

