module fifo_counter_tb;

  // Inputs
  reg empty;
  reg ge2_free;
  reg ge3_free;
  reg [1:0] input_tm_cnt;

  // Output
  wire [4:0] fifo_cnt_inc;

  // DUT instantiation
  fifo_counter dut (
    .empty(empty),
    .ge2_free(ge2_free),
    .ge3_free(ge3_free),
    .input_tm_cnt(input_tm_cnt),
    .fifo_cnt_inc(fifo_cnt_inc)
  );

  // File descriptor for test vector output
  integer fd;
  integer error_count;
  integer test_count;
  integer i, j, k, l;
  reg [4:0] expected_fifo_cnt_inc;

  // Timeout mechanism
  initial begin
    #10000;
    $display("Timeout reached at time %0t. Finishing simulation.", $time);
    $finish;
  end

  // Task to check output and report errors
  task check_output;
    input [4:0] expected;
    input [4:0] actual;
    input [7:0] vector_num;
    begin
      if (expected !== actual) begin
        $display("ERROR at vector %0d: Inputs: empty=%b ge2_free=%b ge3_free=%b input_tm_cnt=%b | Expected fifo_cnt_inc=%d, Got %d at time %0t",
          vector_num, empty, ge2_free, ge3_free, input_tm_cnt, expected, actual, $time);
        error_count = error_count + 1;
      end
      // Assertion (SystemVerilog style, but also works as if-statement in Verilog)
      if (expected !== actual) begin
        $stop;
      end
    end
  endtask

  // Function to compute expected output
  function [4:0] compute_expected;
    input empty_f;
    input ge2_free_f;
    input ge3_free_f;
    input [1:0] input_tm_cnt_f;
    begin
      if (empty_f) begin
        compute_expected = input_tm_cnt_f;
      end
      else if (ge3_free_f && (input_tm_cnt_f == 2'b11)) begin
        compute_expected = 2;
      end
      else if (ge2_free_f && (input_tm_cnt_f >= 2)) begin
        compute_expected = 1;
      end
      else if (input_tm_cnt_f >= 1) begin
        compute_expected = 0;
      end
      else begin
        compute_expected = 31;
      end
    end
  endfunction

  // Main stimulus and checking
  initial begin
    error_count = 0;
    test_count = 0;
    fd = $fopen("test_vectors.txt", "w");
    if (fd) $display("File opened successfully");
    else begin
      $display("Failed to open file");
      $finish;
    end

    // Header for test_vectors.txt (optional, can be commented out)
    // $fdisplay(fd, "empty ge2_free ge3_free input_tm_cnt[1] input_tm_cnt[0] fifo_cnt_inc[4:0]");

    // Generate all combinations for small input space (2*2*2*4 = 32)
    for (i = 0; i < 2; i = i + 1) begin
      for (j = 0; j < 2; j = j + 1) begin
        for (k = 0; k < 2; k = k + 1) begin
          for (l = 0; l < 4; l = l + 1) begin
            empty = i[0];
            ge2_free = j[0];
            ge3_free = k[0];
            input_tm_cnt = l[1:0];
            #1; // allow combinational logic to settle
            expected_fifo_cnt_inc = compute_expected(empty, ge2_free, ge3_free, input_tm_cnt);
            check_output(expected_fifo_cnt_inc, fifo_cnt_inc, test_count);
            $fdisplay(fd, "%b %b %b %b%b %05b", empty, ge2_free, ge3_free, input_tm_cnt[1], input_tm_cnt[0], fifo_cnt_inc);
            test_count = test_count + 1;
          end
        end
      end
    end

    // Generate additional random test vectors to reach at least 100 tests
    for (i = test_count; i < 100; i = i + 1) begin
      empty = $random % 2;
      ge2_free = $random % 2;
      ge3_free = $random % 2;
      input_tm_cnt = $random % 4;
      #1;
      expected_fifo_cnt_inc = compute_expected(empty, ge2_free, ge3_free, input_tm_cnt);
      check_output(expected_fifo_cnt_inc, fifo_cnt_inc, i);
      $fdisplay(fd, "%b %b %b %b%b %05b", empty, ge2_free, ge3_free, input_tm_cnt[1], input_tm_cnt[0], fifo_cnt_inc);
    end

    $display("Testbench completed with %0d errors out of %0d tests.", error_count, test_count+ (100-test_count));
    $fclose(fd);
    $finish;
  end

