module adder_tb;

    // Inputs
    reg [3:0] A;
    reg [3:0] B;
    reg RESET_B;
    reg CLK;

    // Output
    wire [3:0] SUM;

    // File descriptor
    integer fd;
    integer error_count;
    integer i;
    integer j;
    integer test_num;

    // Instantiate the adder module
    adder uut (
        .A(A),
        .B(B),
        .RESET_B(RESET_B),
        .CLK(CLK),
        .SUM(SUM)
    );

    // Clock generation
    initial begin
        CLK = 0;
        forever #5 CLK = ~CLK;
    end

    // Timeout mechanism
    initial begin
        #10000;
        $display("ERROR: Simulation timeout at time %0t ns", $time);
        $finish;
    end

    // Error checking task
    task check_result;
        input [3:0] expected_sum;
        begin
            if (SUM !== expected_sum) begin
                $display("ASSERTION FAILED at time %0t: A=%0d B=%0d RESET_B=%b SUM=%0d (expected %0d)", $time, A, B, RESET_B, SUM, expected_sum);
                error_count = error_count + 1;
            end
        end
    endtask

    // Main stimulus and file writing
    initial begin
        fd = $fopen("test_vectors.txt", "w");
        if (fd)
            $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        error_count = 0;
        test_num = 0;

        // Apply reset first
        RESET_B = 0;
        A = 0;
        B = 0;
        @(negedge CLK);
        @(posedge CLK);
        #1; // Wait for SUM to update
        $fdisplay(fd, "%b %b %b %b", A, B, RESET_B, SUM);
        check_result(4'b0000);

        // Release reset
        RESET_B = 1;
        @(negedge CLK);

        // Exhaustive test for first 32 vectors (A=0..3, B=0..7)
        for (i = 0; i < 4; i = i + 1) begin
            for (j = 0; j < 8; j = j + 1) begin
                A = i[3:0];
                B = j[3:0];
                @(negedge CLK);
                @(posedge CLK);
                #1;
                $fdisplay(fd, "%b %b %b %b", A, B, RESET_B, SUM);
                check_result((A + B) & 4'hF);
                test_num = test_num + 1;
            end
        end

        // Randomized test vectors to reach at least 100 vectors
        for (i = test_num; i < 100; i = i + 1) begin
            A = $random % 16;
            B = $random % 16;
            // Randomly assert/deassert RESET_B
            if ((i % 20) == 0) RESET_B = 0;
            else RESET_B = 1;
            @(negedge CLK);
            @(posedge CLK);
            #1;
            if (RESET_B == 0)
                check_result(4'b0000);
            else
                check_result((A + B) & 4'hF);
            $fdisplay(fd, "%b %b %b %b", A, B, RESET_B, SUM);
        end

        // Final message and close file
        $display("Testbench completed with %0d errors.", error_count);
        $fclose(fd);
        $finish;
    end

endmodule

