module boolean_logic(
    input [2:0] a,
    input [2:0] b,
    input [2:0] c,
    output and1,
    output and2,
    output and3,
    output or1,
    output or2,
    output or3,
    output not1,
    output not2,
    output true_val,
    output false_val
);

assign and1 = a[0] & b[0];
assign and2 = a[0] & c[0];
assign and3 = b[0] & c[0];

assign or1 = a[0] | b[0];
assign or2 = a[0] | c[0];
assign or3 = b[0] | c[0];

assign not1 = ~a[0];
assign not2 = ~b[0];

assign true_val = 1'b1;
assign false_val = 1'b0;

endmodule

