`timescale 1ns/1ps

module boolean_logic_tb;

    // Inputs
    reg [2:0] a;
    reg [2:0] b;
    reg [2:0] c;

    // Outputs
    wire and1;
    wire and2;
    wire and3;
    wire or1;
    wire or2;
    wire or3;
    wire not1;
    wire not2;
    wire true_val;
    wire false_val;

    // DUT instantiation
    boolean_logic uut (
        .a(a),
        .b(b),
        .c(c),
        .and1(and1),
        .and2(and2),
        .and3(and3),
        .or1(or1),
        .or2(or2),
        .or3(or3),
        .not1(not1),
        .not2(not2),
        .true_val(true_val),
        .false_val(false_val)
    );

    // File descriptor
    integer fd;
    integer error_count;
    integer test_count;
    integer i, j, k;
    reg expected_and1, expected_and2, expected_and3;
    reg expected_or1, expected_or2, expected_or3;
    reg expected_not1, expected_not2;
    reg expected_true_val, expected_false_val;

    // Timeout mechanism
    initial begin
        #10000;
        $display("ERROR: Simulation timeout at time %0t ns", $time);
        $finish;
    end

    // Error checking task
    task check_outputs;
        input [2:0] a_in;
        input [2:0] b_in;
        input [2:0] c_in;
        begin
            expected_and1 = a_in[0] & b_in[0];
            expected_and2 = a_in[0] & c_in[0];
            expected_and3 = b_in[0] & c_in[0];
            expected_or1  = a_in[0] | b_in[0];
            expected_or2  = a_in[0] | c_in[0];
            expected_or3  = b_in[0] | c_in[0];
            expected_not1 = ~a_in[0];
            expected_not2 = ~b_in[0];
            expected_true_val = 1'b1;
            expected_false_val = 1'b0;

            if (and1 !== expected_and1) begin
                $display("ASSERTION FAILED: and1 mismatch at a=%b b=%b c=%b (got %b, expected %b)", a_in, b_in, c_in, and1, expected_and1);
                error_count = error_count + 1;
            end
            if (and2 !== expected_and2) begin
                $display("ASSERTION FAILED: and2 mismatch at a=%b b=%b c=%b (got %b, expected %b)", a_in, b_in, c_in, and2, expected_and2);
                error_count = error_count + 1;
            end
            if (and3 !== expected_and3) begin
                $display("ASSERTION FAILED: and3 mismatch at a=%b b=%b c=%b (got %b, expected %b)", a_in, b_in, c_in, and3, expected_and3);
                error_count = error_count + 1;
            end
            if (or1 !== expected_or1) begin
                $display("ASSERTION FAILED: or1 mismatch at a=%b b=%b c=%b (got %b, expected %b)", a_in, b_in, c_in, or1, expected_or1);
                error_count = error_count + 1;
            end
            if (or2 !== expected_or2) begin
                $display("ASSERTION FAILED: or2 mismatch at a=%b b=%b c=%b (got %b, expected %b)", a_in, b_in, c_in, or2, expected_or2);
                error_count = error_count + 1;
            end
            if (or3 !== expected_or3) begin
                $display("ASSERTION FAILED: or3 mismatch at a=%b b=%b c=%b (got %b, expected %b)", a_in, b_in, c_in, or3, expected_or3);
                error_count = error_count + 1;
            end
            if (not1 !== expected_not1) begin
                $display("ASSERTION FAILED: not1 mismatch at a=%b b=%b c=%b (got %b, expected %b)", a_in, b_in, c_in, not1, expected_not1);
                error_count = error_count + 1;
            end
            if (not2 !== expected_not2) begin
                $display("ASSERTION FAILED: not2 mismatch at a=%b b=%b c=%b (got %b, expected %b)", a_in, b_in, c_in, not2, expected_not2);
                error_count = error_count + 1;
            end
            if (true_val !== expected_true_val) begin
                $display("ASSERTION FAILED: true_val mismatch at a=%b b=%b c=%b (got %b, expected %b)", a_in, b_in, c_in, true_val, expected_true_val);
                error_count = error_count + 1;
            end
            if (false_val !== expected_false_val) begin
                $display("ASSERTION FAILED: false_val mismatch at a=%b b=%b c=%b (got %b, expected %b)", a_in, b_in, c_in, false_val, expected_false_val);
                error_count = error_count + 1;
            end
        end
    endtask

    // Main stimulus and file writing
    initial begin
        error_count = 0;
        test_count = 0;

        fd = $fopen("test_vectors.txt", "w");
        if (fd)
            $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        // Write header (optional, can be commented out if not needed)
        // $fdisplay(fd, "a[2:0] b[2:0] c[2:0] and1 and2 and3 or1 or2 or3 not1 not2 true_val false_val");

        // Exhaustive test for a[0], b[0], c[0] (8 combinations)
        for (i = 0; i < 2; i = i + 1) begin
            for (j = 0; j < 2; j = j + 1) begin
                for (k = 0; k < 2; k = k + 1) begin
                    a = {1'b0, 1'b0, i[0]};
                    b = {1'b0, 1'b0, j[0]};
                    c = {1'b0, 1'b0, k[0]};
                    #1;
                    check_outputs(a, b, c);
                    $fdisplay(fd, "%b %b %b %b %b %b %b %b %b %b %b %b %b", a, b, c, and1, and2, and3, or1, or2, or3, not1, not2, true_val, false_val);
                    test_count = test_count + 1;
                end
            end
        end

        // Randomized and pattern-based tests for at least 92 more vectors
        for (i = 0; i < 92; i = i + 1) begin
            // Use a mix of patterns and random values
            case (i % 8)
                0: begin a = 3'b000; b = 3'b111; c = 3'b101; end
                1: begin a = 3'b001; b = 3'b010; c = 3'b100; end
                2: begin a = 3'b011; b = 3'b110; c = 3'b001; end
                3: begin a = 3'b101; b = 3'b011; c = 3'b010; end
                4: begin a = 3'b111; b = 3'b000; c = 3'b110; end
                5: begin a = 3'b100; b = 3'b101; c = 3'b011; end
                6: begin a = 3'b010; b = 3'b001; c = 3'b111; end
                7: begin a = 3'b110; b = 3'b100; c = 3'b000; end
            endcase
            // Add some randomness to lower bits
            a[0] = $random % 2;
            b[0] = $random % 2;
            c[0] = $random % 2;
            #1;
            check_outputs(a, b, c);
            $fdisplay(fd, "%b %b %b %b %b %b %b %b %b %b %b %b %b", a, b, c, and1, and2, and3, or1, or2, or3, not1, not2, true_val, false_val);
            test_count = test_count + 1;
        end

        $display("Testbench completed: %0d test vectors applied, %0d errors detected.", test_count, error_count);
        $fclose(fd);
        $finish;
