    $finish;
  end

  // Task to check output and report errors
  task check_output;
    input [7:0] expected;
    input [7:0] actual;
    input integer vector_num;
    begin
      if (expected !== actual) begin
        $display("ERROR at vector %0d: Expected %0h, Got %0h at time %0t", vector_num, expected, actual, $time);
        error_count = error_count + 1;
      end
      // Assertion (SystemVerilog style not supported in pure Verilog, so use if)
