      in0 = i;
      in1 = i ^ 8'hAA;
      in2 = i + 8'h55;
      in3 = ~i;

      for (j = 0; j < 4; j = j + 1) begin
        sel1 = j[1];
        sel0 = j[0];

        // Wait for combinational logic to settle
        #1;

        // Determine expected output
        case ({sel1, sel0})
          2'b00: expected_out = in0;
          2'b01: expected_out = in1;
          2'b10: expected_out = in2;
          2'b11: expected_out = in3;
          default: expected_out = 8'hxx;
        endcase

