        $fdisplay(fd, "%02x %02x %02x %02x %b %b %02x", in0, in1, in2, in3, sel1, sel0, out);

        // Check output
        check_output(expected_out, out, n);

        n = n + 1;
      end
    end

    // Add some random test vectors for more coverage
    for (k = 0; k < 20; k = k + 1) begin
      in0 = $random;
      in1 = $random;
      in2 = $random;
      in3 = $random;
      sel1 = $random % 2;
      sel0 = $random % 2;

