module and3_not_A (
    A,
    B,
    C,
    X
);

    // Inputs
    input A;
    input B;
    input C;

    // Outputs
    output X;

    // Intermediate signals
    wire not_A;
    wire and_B_C;

    // Logic gates (use positional port mapping)
    not u_not (not_A, A);
    and u_and (and_B_C, B, C);
    and u_and2 (X, not_A, and_B_C);

endmodule

