module counter(
    input        clk,        // 50 MHz clock
    input        rst,        // Active high synchronous reset
    input  [15:0] max_val,   // Maximum value to count to
    output [15:0] count      // Current count output
);

    // Internal register for counter value
    reg [15:0] count_reg;
    wire [15:0] next_count;

    // Combinational logic for next_count
    assign next_count = (rst)         ? 16'd0 :
                        (count_reg >= max_val) ? 16'd0 :
                        count_reg + 16'd1;

    // Synchronous update of count_reg on rising edge of clk
    always @(posedge clk) begin
        count_reg <= next_count;
    end

    // Output assignment
    assign count = count_reg;

endmodule

