module adder_subtractor_4bit (
    input  [3:0] A,
    input  [3:0] B,
    input        mode,  // 0: add, 1: subtract
    output [3:0] O,
    output       COUT
);

    wire [3:0] B_mod;
    wire       carry_in;
    wire [4:0] sum;

    // If mode == 0: addition (B_mod = B, carry_in = 0)
    // If mode == 1: subtraction (B_mod = ~B, carry_in = 1)  (A + (~B) + 1 = A - B)
    assign B_mod   = mode ? ~B : B;
    assign carry_in = mode;

    // Perform full addition (5-bit to capture carry out/borrow out)
    assign sum = {1'b0, A} + {1'b0, B_mod} + carry_in;

    assign O    = sum[3:0];
    assign COUT = sum[4];  // For subtraction, this is the "borrow out" (0 if borrow occurred in 2's complement)

endmodule

