module seq_gen (
   input clk,
   output reg toggle
);

    reg [3:0] counter; // counts from 1 to 10

    initial begin
        counter = 4'd1;
        toggle = 1'b0;
    end

    always @(posedge clk) begin
        // Toggle output every clock
        toggle <= ~toggle;

        // Increment counter from 1 to 10, then wrap back to 1
        if (counter == 4'd10)
            counter <= 4'd1;
        else
            counter <= counter + 4'd1;
    end

endmodule

