module mux4to1 (
    input A,
    input B,
    input C,
    input D,
    input S0,
    input S1,
    output Y
);

    wire w1, w2, w3, w4;

    assign w1 = (S1 & S0) ? D : 1'b0;
    assign w2 = (S1 & ~S0) ? C : 1'b0;
    assign w3 = (~S1 & S0) ? B : 1'b0;
    assign w4 = (~S1 & ~S0) ? A : 1'b0;

    assign Y = w1 | w2 | w3 | w4;

endmodule

test:
`timescale 1ns/1ps

module mux4to1_tb;

    // Inputs
    reg A, B, C, D;
    reg S0, S1;
    // Output
    wire Y;

    // Instantiate the mux4to1 module
    mux4to1 uut (
        .A(A),
        .B(B),
        .C(C),
        .D(D),
        .S0(S0),
        .S1(S1),
        .Y(Y)
    );

    // File descriptor for test vector output
    integer fd;
    integer error_count;
    integer test_count;
    integer i;
    reg expected_Y;

    // Timeout mechanism
    initial begin
        #10000;
        $display("TIMEOUT: Simulation exceeded time limit at time %0t", $time);
        $finish;
    end

    // Task to check output and report errors
    task check_output;
        input reg exp_Y;
        begin
            if (Y !== exp_Y) begin
                $display("ERROR at time %0t: Inputs: A=%b B=%b C=%b D=%b S1=%b S0=%b | Expected Y=%b, Got Y=%b", $time, A, B, C, D, S1, S0, exp_Y, Y);
                error_count = error_count + 1;
            end
        end
    endtask

    // Main stimulus and checking
    initial begin
        fd = $fopen("test_vectors.txt", "w");
        if (fd) $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        error_count = 0;
        test_count = 0;

        // Exhaustive test for all 6 inputs (2^6 = 64 combinations)
        for (i = 0; i < 64; i = i + 1) begin
            {A, B, C, D, S1, S0} = i[5:0];
            #1; // Allow signals to propagate

            // Compute expected output
            case ({S1, S0})
                2'b00: expected_Y = A;
                2'b01: expected_Y = B;
                2'b10: expected_Y = C;
                2'b11: expected_Y = D;
                default: expected_Y = 1'bx;
            endcase

            // Write test vector to file: A B C D S1 S0 Y
            $fdisplay(fd, "%b %b %b %b %b %b %b", A, B, C, D, S1, S0, Y);

            // Check output
            check_output(expected_Y);

            test_count = test_count + 1;
        end

        // Generate additional random test vectors to reach at least 100 vectors
        for (i = 0; i < 36; i = i + 1) begin
            {A, B, C, D, S1, S0} = $random;
            #1;

            case ({S1, S0})
                2'b00: expected_Y = A;
                2'b01: expected_Y = B;
                2'b10: expected_Y = C;
                2'b11: expected_Y = D;
                default: expected_Y = 1'bx;
            endcase

            $fdisplay(fd, "%b %b %b %b %b %b %b", A, B, C, D, S1, S0, Y);

            check_output(expected_Y);

            test_count = test_count + 1;
        end

        $display("Testbench completed. Total tests: %0d, Errors: %0d", test_count, error_count);
        $fclose(fd);
        $finish;
    end

endmodule

