`timescale 1ns/1ps

module Adder_tb;

    // Inputs
    reg [2:0] A;
    reg [2:0] B;
    reg CLK;
    reg RST;

    // Outputs
    wire [2:0] Q;

    // File descriptor
    integer fd;
    integer error_count;
    integer test_count;
    integer i, j, k;
    reg [2:0] expected_Q;

    // Instantiate the Adder module
    Adder uut (
        .A(A),
        .B(B),
        .CLK(CLK),
        .RST(RST),
        .Q(Q)
    );

    // Clock generation
    initial begin
        CLK = 0;
        forever #5 CLK = ~CLK;
    end

    // Timeout mechanism
    initial begin
        #10000;
        $display("ERROR: Simulation timed out at time %0t", $time);
        $finish;
    end

    // Task to check output and report errors
    task check_output;
        input [2:0] exp_Q;
        begin
            if (Q !== exp_Q) begin
                $display("ASSERTION FAILED at time %0t: A=%0d B=%0d RST=%0b Q=%0d (expected %0d)", $time, A, B, RST, Q, exp_Q);
                error_count = error_count + 1;
            end
        end
    endtask

    // Main stimulus and file writing
    initial begin
        fd = $fopen("test_vectors.txt", "w");
        if (fd) $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        error_count = 0;
        test_count = 0;

        // Apply reset and check
        RST = 1;
        A = 0;
        B = 0;
        @(negedge CLK);
        @(posedge CLK);
        #1;
        expected_Q = 0;
        $fdisplay(fd, "%b %b %b %b", A, B, RST, Q);
        check_output(expected_Q);
        test_count = test_count + 1;

        RST = 0;

        // Generate at least 100 test vectors
        // We'll do all 64 combinations of A and B, and 36 random ones with RST toggling
        for (i = 0; i < 8; i = i + 1) begin
            for (j = 0; j < 8; j = j + 1) begin
                // Normal operation
                A = i[2:0];
                B = j[2:0];
                RST = 0;
                @(negedge CLK);
                @(posedge CLK);
                #1;
                expected_Q = (A + B) & 3'b111;
                $fdisplay(fd, "%b %b %b %b", A, B, RST, Q);
                check_output(expected_Q);
                test_count = test_count + 1;

                // Occasionally test reset
                if ((i*8+j)%16 == 0) begin
                    RST = 1;
                    @(negedge CLK);
                    @(posedge CLK);
                    #1;
                    expected_Q = 0;
                    $fdisplay(fd, "%b %b %b %b", A, B, RST, Q);
                    check_output(expected_Q);
                    test_count = test_count + 1;
                    RST = 0;
                end
            end
        end

        // Add random test vectors with RST toggling
        for (k = 0; k < 36; k = k + 1) begin
            A = $random % 8;
            B = $random % 8;
            RST = $random % 2;
            @(negedge CLK);
            @(posedge CLK);
            #1;
            if (RST)
                expected_Q = 0;
            else
                expected_Q = (A + B) & 3'b111;
            $fdisplay(fd, "%b %b %b %b", A, B, RST, Q);
            check_output(expected_Q);
            test_count = test_count + 1;
        end

        $display("Testbench completed: %0d tests, %0d errors", test_count, error_count);
        $fclose(fd);
        $finish;
    end

endmodule

