module single_port_ram (
    input wire clk,
    input wire we,
    input wire [9:0] addr,
    input wire [7:0] data,
    output reg [7:0] q
);

    // Declare the RAM storage, initialized to 0
    reg [7:0] ram [0:1023];
    integer i;

    initial begin
        for (i = 0; i < 1024; i = i + 1)
            ram[i] = 8'b0;
    end

    always @(posedge clk) begin
        if (we) begin
            ram[addr] <= data;
        end
        else begin
            q <= ram[addr];
        end
    end

endmodule

test:
`timescale 1ns/1ps

module single_port_ram_tb;

    // Parameters
    localparam ADDR_WIDTH = 10;
    localparam DATA_WIDTH = 8;
    localparam RAM_DEPTH  = 1 << ADDR_WIDTH;
    localparam NUM_TESTS  = 100;
    localparam TIMEOUT    = 10000;

    // DUT signals
    reg clk;
    reg we;
    reg [ADDR_WIDTH-1:0] addr;
    reg [DATA_WIDTH-1:0] data;
    wire [DATA_WIDTH-1:0] q;

    // Internal reference model
    reg [DATA_WIDTH-1:0] ref_ram [0:RAM_DEPTH-1];
    reg [DATA_WIDTH-1:0] ref_q;

    // File handling
    integer fd;
    integer i;
    integer error_count;

    // Instantiate DUT
    single_port_ram dut (
        .clk(clk),
        .we(we),
        .addr(addr),
        .data(data),
        .q(q)
    );

    // Clock generation
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    // Timeout mechanism
    initial begin
        #TIMEOUT;
        $display("ERROR: Simulation timed out at time %0t", $time);
        $finish;
    end

    // Testbench main process
    initial begin
        // Initialize reference RAM
        for (i = 0; i < RAM_DEPTH; i = i + 1)
            ref_ram[i] = 8'b0;
        ref_q = 8'b0;
        error_count = 0;

        // Open file for writing test vectors
        fd = $fopen("test_vectors.txt", "w");
        if (fd)
            $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        // Reset signals
        we   = 0;
        addr = 0;
        data = 0;
        @(negedge clk);

        // TEST 1: Write to all addresses with random data
        for (i = 0; i < NUM_TESTS; i = i + 1) begin
            we   = 1;
            addr = $random % RAM_DEPTH;
            data = $random % 256;
            @(negedge clk);

            // Reference model update
            ref_ram[addr] = data;

            // Write test vector: clk we addr data q
            $fdisplay(fd, "%b %b %010b %08b %08b", clk, we, addr, data, q);

            // Assertion: On write, output q is don't care (but we can check RAM content later)
        end

        // TEST 2: Read from all addresses and check data
        for (i = 0; i < NUM_TESTS; i = i + 1) begin
            we   = 0;
            addr = $random % RAM_DEPTH;
            data = $random % 256; // data is ignored on read
            @(negedge clk);

            // Reference model output
            ref_q = ref_ram[addr];

            // Write test vector: clk we addr data q
            $fdisplay(fd, "%b %b %010b %08b %08b", clk, we, addr, data, q);

            // Assertion: On read, q should match reference
            if (q !== ref_q) begin
                $display("ERROR at time %0t: Read mismatch at addr=%0d. Expected %02x, Got %02x", $time, addr, ref_q, q);
                error_count = error_count + 1;
            end
        end

        // TEST 3: Write and immediate readback (write, then read same address)
        for (i = 0; i < NUM_TESTS; i = i + 1) begin
            // Write
            we   = 1;
            addr = $random % RAM_DEPTH;
            data = $random % 256;
            @(negedge clk);
            ref_ram[addr] = data;
            $fdisplay(fd, "%b %b %010b %08b %08b", clk, we, addr, data, q);

            // Read
            we   = 0;
            // addr remains the same
            data = $random % 256; // data ignored
            @(negedge clk);
            ref_q = ref_ram[addr];
            $fdisplay(fd, "%b %b %010b %08b %08b", clk, we, addr, data, q);

            if (q !== ref_q) begin
                $display("ERROR at time %0t: Immediate readback mismatch at addr=%0d. Expected %02x, Got %02x", $time, addr, ref_q, q);
                error_count = error_count + 1;
            end
        end

        // TEST 4: Edge cases (lowest and highest addresses)
        // Write to address 0
        we   = 1;
        addr = 0;
        data = 8'hAA;
        @(negedge clk);
        ref_ram[addr] = data;
        $fdisplay(fd, "%b %b %010b %08b %08b", clk, we, addr, data, q);

        // Read from address 0
        we   = 0;
        data = $random % 256;
        @(negedge clk);
        ref_q = ref_ram[addr];
        $fdisplay(fd, "%b %b %010b %08b %08b", clk, we, addr, data, q);
        if (q !== ref_q) begin
            $display("ERROR at time %0t: Edge case readback mismatch at addr=0. Expected %02x, Got %02x", $time, ref_q, q);
            error_count = error_count + 1;
        end

        // Write to address max
        we   = 1;
        addr = RAM_DEPTH-1;
        data = 8'h55;
        @(negedge clk);
        ref_ram[addr] = data;
        $fdisplay(fd, "%b %b %010b %08b %08b", clk, we, addr, data, q);

        // Read from address max
        we   = 0;
        data = $random % 256;
        @(negedge clk);
        ref_q = ref_ram[addr];
        $fdisplay(fd, "%b %b %010b %08b %08b", clk, we, addr, data, q);
        if (q !== ref_q) begin
            $display("ERROR at time %0t: Edge case readback mismatch at addr=%0d. Expected %02x, Got %02x", $time, addr, ref_q, q);
            error_count = error_count + 1;
        end

        // Close file
        $fclose(fd);

        // Report results
        if (error_count == 0)
            $display("All tests PASSED.");
        else
            $display("TEST FAILED with %0d errors.", error_count);

        $finish;
    end

endmodule

