module single_dff_reset_tb;

  // DUT signals
  reg clk;
  reg din;
  reg reset_n;
  wire dout;

  // File handling
  integer fd;
  integer error_count;
  integer vector_count;
  integer i;
  reg expected_dout;
  reg prev_dout;

  // Instantiate DUT
  single_dff_reset dut (
    .clk(clk),
    .din(din),
    .dout(dout),
    .reset_n(reset_n)
  );

  // Clock generation
  initial begin
    clk = 0;
    forever #5 clk = ~clk; // 100MHz clock
  end

  // Timeout mechanism
  initial begin
    #10000;
    $display("ERROR: Simulation timed out at time %0t", $time);
    $finish;
  end

  // Error checking task
  task check_output;
    input reg exp_dout;
    begin
      if (dout !== exp_dout) begin
        $display("ASSERTION FAILED at time %0t: din=%b reset_n=%b dout=%b expected=%b", $time, din, reset_n, dout, exp_dout);
        error_count = error_count + 1;
      end
    end
  endtask

  // Main stimulus
  initial begin
    fd = $fopen("test_vectors.txt", "w");
    if (fd) $display("File opened successfully");
    else begin
      $display("Failed to open file");
      $finish;
    end

    error_count = 0;
    vector_count = 0;
    din = 0;
    reset_n = 1;
    prev_dout = 0;

    // Apply reset at start
    @(negedge clk);
    reset_n = 0;
    din = 1'bx;
    @(negedge clk);
    // Write vector: clk, din, reset_n, dout
    $fdisplay(fd, "%b %b %b %b", clk, din, reset_n, dout);
    vector_count = vector_count + 1;
    expected_dout = 0;
    check_output(expected_dout);

    // Release reset
    reset_n = 1;
    din = 0;
    @(negedge clk);
    $fdisplay(fd, "%b %b %b %b", clk, din, reset_n, dout);
    vector_count = vector_count + 1;
    expected_dout = 0;
    check_output(expected_dout);

    // Generate at least 100 test vectors with various din/reset_n patterns
    for (i = 0; i < 100; i = i + 1) begin
      // Randomize din and occasionally toggle reset_n
      din = $random % 2;
      if ((i % 17) == 0) begin
        reset_n = 0;
      end else if ((i % 17) == 1) begin
        reset_n = 1;
      end

      @(negedge clk);
      $fdisplay(fd, "%b %b %b %b", clk, din, reset_n, dout);
      vector_count = vector_count + 1;

      // Compute expected output
      if (!reset_n)
        expected_dout = 0;
      else
        expected_dout = prev_dout;

      // On posedge clk, update expected_dout if not in reset
      @(posedge clk);
      if (!reset_n)
        expected_dout = 0;
      else
        expected_dout = din;

      // Write vector at posedge clk
      $fdisplay(fd, "%b %b %b %b", clk, din, reset_n, dout);
      vector_count = vector_count + 1;
      check_output(expected_dout);

      prev_dout = expected_dout;
    end

    $display("Test completed with %0d vectors. Errors: %0d", vector_count, error_count);
    $fclose(fd);
    $finish;
  end

endmodule

