module binary_counter_tb;

    // DUT signals
    reg clk;
    reg reset;
    reg enable;
    wire [3:0] count;

    // File handling
    integer fd;
    integer error_count;
    integer test_num;

    // For reference model
    reg [3:0] ref_count;

    // Timeout
    parameter TIMEOUT = 10000;

    // Instantiate DUT
    binary_counter uut (
        .clk(clk),
        .reset(reset),
        .enable(enable),
        .count(count)
    );

    // Clock generation
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    // Reference model update
    always @(posedge clk) begin
        if (reset)
            ref_count <= 4'b0;
        else if (enable)
            ref_count <= ref_count + 1;
    end

    // Error checking task
    task check_output;
        input integer vec_num;
        begin
            if (count !== ref_count) begin
                $display("ERROR at vector %0d: reset=%b enable=%b count=%b (expected %b) at time %0t", 
                    vec_num, reset, enable, count, ref_count, $time);
                error_count = error_count + 1;
            end
        end
