        RESET = 1;
        SET = 0;
        CE = 1;
        @(negedge CLK);
        @(posedge CLK);
        expected_Q = 0;
        #1;
        check_and_log();

        // Deassert reset
        RESET = 0;
        @(negedge CLK);
        @(posedge CLK);
        #1;
        expected_Q = 0;
        check_and_log();

