        #TIMEOUT;
        $display("ERROR: Simulation timed out at time %0t", $time);
        $finish;
    end

    // Clock generation
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    // Task to check output and report errors
    task check_output;
        input [3:0] expected;
        begin
            if (count !== expected) begin
                $display("ASSERTION FAILED at time %0t: Inputs: reset=%b load=%b data_in=%b | Expected count=%b, Got count=%b", $time, reset, load, data_in, expected, count);
                error_count = error_count + 1;
            end
        end
    endtask

    // Main stimulus
    initial begin
        fd = $fopen("test_vectors.txt", "w");
        if (fd)
            $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        error_count = 0;
        test_count = 0;

        // Initialize inputs
        reset = 0;
        load = 0;
        data_in = 4'b0000;

        // Wait for global reset
        #12;

        // Test 1: Reset functionality
        reset = 1;
        load = 0;
        data_in = 4'b0000;
        @(negedge clk);
        @(negedge clk);
        expected_count = 4'b0000;
        $fdisplay(fd, "%b %b %b %b %b", clk, reset, load, data_in, count);
        check_output(expected_count);
        test_count = test_count + 1;

        reset = 0;
        @(negedge clk);

        // Test 2: Load functionality (try all possible data_in values)
        for (i = 0; i < 16; i = i + 1) begin
            load = 1;
            data_in = i[3:0];
            @(negedge clk);
            expected_count = i[3:0];
            $fdisplay(fd, "%b %b %b %b %b", clk, reset, load, data_in, count);
            check_output(expected_count);
            test_count = test_count + 1;
            load = 0;
            @(negedge clk);
        end

        // Test 3: Counting up from a known value
        load = 1;
        data_in = 4'b0101;
        @(negedge clk);
        expected_count = 4'b0101;
        $fdisplay(fd, "%b %b %b %b %b", clk, reset, load, data_in, count);
        check_output(expected_count);
        test_count = test_count + 1;
        load = 0;

        // Count up for 10 cycles
        for (i = 1; i <= 10; i = i + 1) begin
            @(negedge clk);
            expected_count = (expected_count + 1) & 4'hF;
            $fdisplay(fd, "%b %b %b %b %b", clk, reset, load, data_in, count);
            check_output(expected_count);
            test_count = test_count + 1;
        end

        // Test 4: Reset during counting
        reset = 1;
        @(negedge clk);
        expected_count = 4'b0000;
        $fdisplay(fd, "%b %b %b %b %b", clk, reset, load, data_in, count);
        check_output(expected_count);
        test_count = test_count + 1;
        reset = 0;
        @(negedge clk);

        // Test 5: Load while counting
        load = 1;
        data_in = 4'b1111;
        @(negedge clk);
        expected_count = 4'b1111;
        $fdisplay(fd, "%b %b %b %b %b", clk, reset, load, data_in, count);
        check_output(expected_count);
        test_count = test_count + 1;
        load = 0;

        // Count up for 5 cycles
        for (i = 1; i <= 5; i = i + 1) begin
            @(negedge clk);
            expected_count = (expected_count + 1) & 4'hF;
            $fdisplay(fd, "%b %b %b %b %b", clk, reset, load, data_in, count);
            check_output(expected_count);
            test_count = test_count + 1;
        end

        // Test 6: Randomized test vectors
        for (j = 0; j < 60; j = j + 1) begin
            @(negedge clk);
            // Randomly select reset, load, data_in
            reset = $random % 2;
            load = $random % 2;
            data_in = $random % 16;
            prev_count = count;
            @(negedge clk);
            // Compute expected_count
            if (reset)
                expected_count = 4'b0000;
            else if (load)
                expected_count = data_in;
            else
                expected_count = (prev_count + 1) & 4'hF;
            $fdisplay(fd, "%b %b %b %b %b", clk, reset, load, data_in, count);
            check_output(expected_count);
            test_count = test_count + 1;
            reset = 0;
            load = 0;
        end

        $display("Testbench completed. Total tests: %0d, Errors: %0d", test_count, error_count);
        $fclose(fd);
        $finish;
    end

endmodule

`timescale 1ns/1ps

module dff_async_set_clr_tb;

    // Inputs
    reg CLK;
    reg D;
    reg SCD;
    reg SCE;

    // Output
    wire Q;

    // Internal variables
    integer fd;
    integer i;
    integer error_count;
    reg expected_Q;
    reg prev_Q;
    reg prev_D;
    reg prev_SCD;
    reg prev_SCE;

    // Instantiate the DUT
    dff_async_set_clr uut (
        .CLK(CLK),
        .D(D),
        .SCD(SCD),
        .SCE(SCE),
        .Q(Q)
    );

    // Clock generation
    initial begin
        CLK = 0;
        forever #5 CLK = ~CLK;
    end

    // Timeout mechanism
    initial begin
        #10000;
        $display("Timeout reached at time %0t. Finishing simulation.", $time);
        $finish;
    end

    // Main test process
    initial begin
        fd = $fopen("test_vectors.txt", "w");
        if (fd) $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        error_count = 0;
        // Initialize inputs
        D = 0;
        SCD = 0;
        SCE = 0;
        prev_Q = 0;
        prev_D = 0;
        prev_SCD = 0;
        prev_SCE = 0;

        // Wait for global reset
        #10;

        // Test all possible async set/clear combinations and clocked behavior
        // Generate at least 100 test vectors
        for (i = 0; i < 100; i = i + 1) begin
            // Randomize inputs
            D   = $random % 2;
            SCD = $random % 2;
            SCE = $random % 2;

            // Save previous Q
            prev_Q = Q;
            prev_D = D;
            prev_SCD = SCD;
            prev_SCE = SCE;

            // Apply async set/clear
            // If SCD or SCE is asserted, Q should update immediately
            if (SCD) begin
                // Wait for SCD posedge
                @(negedge CLK); #1;
                // Wait for a delta cycle to allow Q to update
                #1;
                expected_Q = 1'b0;
            end else if (SCE) begin
                @(negedge CLK); #1;
                #1;
                expected_Q = 1'b1;
            end else begin
                // No async, do a clock edge
                @(negedge CLK);
                @(posedge CLK); #1;
                expected_Q = D;
            end

            // Write test vector: D SCD SCE Q
            $fdisplay(fd, "%b %b %b %b", D, SCD, SCE, Q);

            // Assertion: check Q
            if (Q !== expected_Q) begin
                $display("ERROR at time %0t: D=%b SCD=%b SCE=%b Q=%b (expected %b)", $time, D, SCD, SCE, Q, expected_Q);
                error_count = error_count + 1;
            end

            // Deassert async signals for next test
            SCD = 0;
            SCE = 0;
            #2;
        end

        // Additional edge cases: overlapping set/clear
        // SCD and SCE both high: SCD has priority
        D = 1'b1;
        SCD = 1'b1;
        SCE = 1'b1;
        @(negedge CLK); #1;
        #1;
        expected_Q = 1'b0;
        $fdisplay(fd, "%b %b %b %b", D, SCD, SCE, Q);
        if (Q !== expected_Q) begin
            $display("ERROR (SCD & SCE both high) at time %0t: Q=%b (expected %b)", $time, Q, expected_Q);
            error_count = error_count + 1;
        end
        SCD = 0;
        SCE = 0;
        #2;

        // Test D changes at clock edge
        D = 1'b0;
        @(negedge CLK);
        @(posedge CLK); #1;
        expected_Q = D;
        $fdisplay(fd, "%b %b %b %b", D, SCD, SCE, Q);
        if (Q !== expected_Q) begin
            $display("ERROR (D change at clock) at time %0t: Q=%b (expected %b)", $time, Q, expected_Q);
            error_count = error_count + 1;
        end

        // Test async set while clocking
        D = 1'b0;
        SCE = 1'b1;
        @(negedge CLK); #1;
        #1;
        expected_Q = 1'b1;
        $fdisplay(fd, "%b %b %b %b", D, SCD, SCE, Q);
        if (Q !== expected_Q) begin
            $display("ERROR (async set) at time %0t: Q=%b (expected %b)", $time, Q, expected_Q);
            error_count = error_count + 1;
        end
        SCE = 0;
        #2;

        // Test async clear while clocking
        D = 1'b1;
        SCD = 1'b1;
        @(negedge CLK); #1;
        #1;
        expected_Q = 1'b0;
        $fdisplay(fd, "%b %b %b %b", D, SCD, SCE, Q);
        if (Q !== expected_Q) begin
            $display("ERROR (async clear) at time %0t: Q=%b (expected %b)", $time, Q, expected_Q);
            error_count = error_count + 1;
        end
        SCD = 0;
        #2;

        // Final report
        if (error_count == 0)
            $display("All tests PASSED.");
        else
            $display("Total errors: %0d", error_count);

        $fclose(fd);
        $finish;
    end

endmodule

