    $display("ERROR: Simulation timed out at time %0t", $time);
    $finish;
  end

  // Error checking task
  task check_output;
    input reg exp_q;
    input reg exp_q_n;
    begin
      if ((q !== exp_q) || (q_n !== exp_q_n)) begin
        $display("ASSERTION FAILED at time %0t: d=%b set=%b reset=%b | q=%b (exp %b) q_n=%b (exp %b)", $time, d, set, reset, q, exp_q, q_n, exp_q_n);
        error_count = error_count + 1;
      end
    end
  endtask

  // Main stimulus
