    @(negedge clk);
    #1;
    check_output(1'b1, 1'b0);
    $fdisplay(fd, "%b %b %b %b %b %b", clk, d, set, reset, q, q_n);
    vector_count = vector_count + 1;

    // 2. Async reset
    set = 1; reset = 0; d = 1;
    @(negedge clk);
    #1;
    check_output(1'b0, 1'b1);
    $fdisplay(fd, "%b %b %b %b %b %b", clk, d, set, reset, q, q_n);
    vector_count = vector_count + 1;

    // 3. Both async active (set and reset low) - set has priority
    set = 0; reset = 0; d = 1;
    @(negedge clk);
    #1;
    check_output(1'b1, 1'b0);
    $fdisplay(fd, "%b %b %b %b %b %b", clk, d, set, reset, q, q_n);
    vector_count = vector_count + 1;

    // 4. Back to normal
    set = 1; reset = 1; d = 0;
    @(negedge clk);
