    // For at least 100 vectors, repeat with varying d, set, reset, and randomize
    for (i = 0; i < 100; i = i + 1) begin
      // Cycle through all combinations for first 8 vectors
      if (i < 8) begin
        d     = i[0];
        set   = i[1];
        reset = i[2];
      end else begin
        // Randomized for more coverage
        d     = $random % 2;
        set   = $random % 2;
        reset = $random % 2;
      end

      // Avoid both set and reset low except for first 8 vectors
      if ((set === 0) && (reset === 0) && (i >= 8)) set = 1;

      @(negedge clk);
      #1;

      // Expected outputs
      if (!set) begin
        check_output(1'b1, 1'b0);
      end else if (!reset) begin
        check_output(1'b0, 1'b1);
      end else begin
        check_output(d, ~d);
      end

      $fdisplay(fd, "%b %b %b %b %b %b", clk, d, set, reset, q, q_n);
      vector_count = vector_count + 1;
    end

    // Test synchronous operation: toggle d on each clock
    set = 1; reset = 1;
    d = 0;
    repeat (10) begin
      @(negedge clk);
      #1;
      check_output(d, ~d);
      $fdisplay(fd, "%b %b %b %b %b %b", clk, d, set, reset, q, q_n);
      vector_count = vector_count + 1;
      d = ~d;
    end

    // Test async set during clock
    set = 1; reset = 1; d = 1;
    @(negedge clk);
    set = 0;
    @(negedge clk);
    #1;
    check_output(1'b1, 1'b0);
    $fdisplay(fd, "%b %b %b %b %b %b", clk, d, set, reset, q, q_n);
    vector_count = vector_count + 1;
    set = 1;

    // Test async reset during clock
    reset = 0;
    @(negedge clk);
    #1;
    check_output(1'b0, 1'b1);
    $fdisplay(fd, "%b %b %b %b %b %b", clk, d, set, reset, q, q_n);
    vector_count = vector_count + 1;
    reset = 1;

    // Finalize
    $display("Testbench completed with %0d vectors and %0d errors.", vector_count, error_count);
    $fclose(fd);
    $finish;
  end

endmodule

