module mul_add(
  input clk,
  input [7:0] a,
  input [7:0] b,
  input [7:0] c,
  output reg [15:0] sum,
  output reg [15:0] product
);
  wire [15:0] add_result;
  wire [15:0] mul_result;

  // 8-bit adder for a + b + c, extend to 16-bits for safe addition
  assign add_result = a + b + c;

  // 8-bit multiplier (result is 16 bits)
  assign mul_result = a * b;

  always @(posedge clk) begin
    sum     <= add_result;
    product <= mul_result;
  end

