module mul_add_tb;

  // Inputs
  reg clk;
  reg [7:0] a, b, c;

  // Outputs
  wire [15:0] sum, product;

  // File descriptor
  integer fd;
  integer i;
  integer error_count;
  integer test_count;

  // For random test vectors
  reg [7:0] rand_a, rand_b, rand_c;

  // Instantiate the DUT
  mul_add dut (
    .clk(clk),
    .a(a),
    .b(b),
    .c(c),
    .sum(sum),
    .product(product)
  );

  // Clock generation
  initial begin
    clk = 0;
    forever #5 clk = ~clk;
  end

  // Timeout mechanism
  initial begin
    #10000;
    $display("ERROR: Simulation timed out at time %0t", $time);
    $finish;
  end

  // Error checking task
  task check_outputs;
    input [7:0] ta, tb, tc;
    input [15:0] tsum, tproduct;
    begin
      if (tsum !== (ta + tb + tc)) begin
        $display("ASSERTION FAILED at time %0t: SUM: a=%0d b=%0d c=%0d sum=%0d (expected %0d)", $time, ta, tb, tc, tsum, ta+tb+tc);
        error_count = error_count + 1;
      end
      if (tproduct !== (ta * tb)) begin
        $display("ASSERTION FAILED at time %0t: PRODUCT: a=%0d b=%0d product=%0d (expected %0d)", $time, ta, tb, tproduct, ta*tb);
        error_count = error_count + 1;
      end
    end
  endtask

  // Main stimulus and checking
  initial begin
    error_count = 0;
    test_count = 0;

    // Open file for writing test vectors
    fd = $fopen("test_vectors.txt", "w");
    if (fd) $display("File opened successfully");
    else begin
      $display("Failed to open file");
      $finish;
    end

    // Write header (optional, can be commented out if not needed)
    // $fdisplay(fd, "a b c sum product");

    // Reset inputs
    a = 0; b = 0; c = 0;
    @(posedge clk);

    // 1. Test a few corner cases (all zeros, all ones, min/max)
    a = 8'd0; b = 8'd0; c = 8'd0;
    @(posedge clk);
    #1;
    $fdisplay(fd, "%0d %0d %0d %0d %0d", a, b, c, sum, product);
    check_outputs(a, b, c, sum, product);
    test_count = test_count + 1;

    a = 8'd255; b = 8'd255; c = 8'd255;
    @(posedge clk);
    #1;
    $fdisplay(fd, "%0d %0d %0d %0d %0d", a, b, c, sum, product);
    check_outputs(a, b, c, sum, product);
    test_count = test_count + 1;

    a = 8'd1; b = 8'd0; c = 8'd0;
    @(posedge clk);
    #1;
    $fdisplay(fd, "%0d %0d %0d %0d %0d", a, b, c, sum, product);
    check_outputs(a, b, c, sum, product);
    test_count = test_count + 1;

    a = 8'd0; b = 8'd1; c = 8'd0;
    @(posedge clk);
    #1;
    $fdisplay(fd, "%0d %0d %0d %0d %0d", a, b, c, sum, product);
    check_outputs(a, b, c, sum, product);
    test_count = test_count + 1;

    a = 8'd0; b = 8'd0; c = 8'd1;
    @(posedge clk);
    #1;
    $fdisplay(fd, "%0d %0d %0d %0d %0d", a, b, c, sum, product);
    check_outputs(a, b, c, sum, product);
    test_count = test_count + 1;

    a = 8'd128; b = 8'd128; c = 8'd128;
    @(posedge clk);
    #1;
    $fdisplay(fd, "%0d %0d %0d %0d %0d", a, b, c, sum, product);
    check_outputs(a, b, c, sum, product);
    test_count = test_count + 1;

    // 2. Sweep a and b, c=0 (partial exhaustive)
    for (i = 0; i < 10; i = i + 1) begin
      a = i*25;
      b = 255 - i*25;
      c = 0;
      @(posedge clk);
      #1;
      $fdisplay(fd, "%0d %0d %0d %0d %0d", a, b, c, sum, product);
      check_outputs(a, b, c, sum, product);
      test_count = test_count + 1;
    end

    // 3. Sweep c, a=0, b=255
    for (i = 0; i < 10; i = i + 1) begin
      a = 0;
      b = 255;
      c = i*25;
      @(posedge clk);
      #1;
      $fdisplay(fd, "%0d %0d %0d %0d %0d", a, b, c, sum, product);
      check_outputs(a, b, c, sum, product);
      test_count = test_count + 1;
    end

    // 4. Randomized test vectors
    for (i = 0; i < 74; i = i + 1) begin
      rand_a = $random;
      rand_b = $random;
      rand_c = $random;
      a = rand_a;
      b = rand_b;
      c = rand_c;
      @(posedge clk);
      #1;
      $fdisplay(fd, "%0d %0d %0d %0d %0d", a, b, c, sum, product);
      check_outputs(a, b, c, sum, product);
      test_count = test_count + 1;
    end

    // 5. Some edge cases
    a = 8'd255; b = 8'd0; c = 8'd0;
    @(posedge clk);
    #1;
    $fdisplay(fd, "%0d %0d %0d %0d %0d", a, b, c, sum, product);
    check_outputs(a, b, c, sum, product);
    test_count = test_count + 1;

    a = 8'd0; b = 8'd255; c = 8'd0;
    @(posedge clk);
