        // Next 90: random shift_in and data_in, reset deasserted
        test_data[10][0] = 0; // reset
        test_data[10][1] = 1; // data_in
        test_data[10][2] = 1; // shift_in
        test_data[10][3] = 8'b00000001; // expected after shift from reset

        for (i = 11; i < 100; i = i + 1) begin
            test_data[i][0] = 0; // reset
            test_data[i][1] = $random % 2;
            test_data[i][2] = $random % 2;
            test_data[i][3] = 8'hxx; // will be calculated during simulation
        end
    end

    // File handling and test execution
    initial begin
