module t_latch_async_reset (
    input  wire D,    // Data input
    input  wire G,    // Gate input
    input  wire RN,   // Asynchronous reset (active low)
    output reg  Q,    // Output
    output wire QN    // Complement of output
);

assign QN = ~Q;

always @(*) begin
