`timescale 1ns/1ps

module t_latch_async_reset_tb;

    // DUT signals
    reg D;
    reg G;
    reg RN;
    wire Q;
    wire QN;

    // For checking previous Q value (for latch hold)
    reg expected_Q;
    reg expected_QN;

    // File handling
    integer fd;
    integer error_count;
    integer vector_count;
    integer i;

    // Timeout mechanism
    parameter TIMEOUT = 10000;

    // Instantiate DUT
    t_latch_async_reset dut (
        .D(D),
        .G(G),
        .RN(RN),
        .Q(Q),
        .QN(QN)
    );

    // Task to check outputs and report errors
    task check_outputs;
        input [0:0] D_in;
        input [0:0] G_in;
        input [0:0] RN_in;
        input [0:0] Q_out;
        input [0:0] QN_out;
        input [0:0] exp_Q;
        input [0:0] exp_QN;
        begin
            if ((Q_out !== exp_Q) || (QN_out !== exp_QN)) begin
                $display("ERROR at time %0t: D=%b G=%b RN=%b | Q=%b QN=%b (expected Q=%b QN=%b)", $time, D_in, G_in, RN_in, Q_out, QN_out, exp_Q, exp_QN);
                error_count = error_count + 1;
            end
        end
    endtask

    // Timeout mechanism
    initial begin
        #TIMEOUT;
        $display("TIMEOUT: Simulation exceeded %0d time units.", TIMEOUT);
        $finish;
    end

    // Main stimulus and checking
    initial begin
        error_count = 0;
        vector_count = 0;
        expected_Q = 0;
        expected_QN = 1;

        fd = $fopen("test_vectors.txt", "w");
        if (fd)
            $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        // Write header (optional, can be commented out if not desired)
        // $fdisplay(fd, "D G RN Q QN");

        // Initialize all inputs
        D = 0; G = 0; RN = 1;
        #1;

        // Test all 8 input combinations (D, G, RN)
        for (i = 0; i < 8; i = i + 1) begin
            D  = (i >> 2) & 1'b1;
            G  = (i >> 1) & 1'b1;
            RN = (i >> 0) & 1'b1;
            #1;

            // Compute expected Q
            if (~RN) begin
                expected_Q = 0;
            end else if (G) begin
                expected_Q = D;
            end
            // else: expected_Q holds previous value

            expected_QN = ~expected_Q;

            // Write test vector to file
            $fdisplay(fd, "%b %b %b %b %b", D, G, RN, Q, QN);

            // Check outputs
            check_outputs(D, G, RN, Q, QN, expected_Q, expected_QN);

            vector_count = vector_count + 1;
        end

        // Now, generate more vectors to reach at least 100
        // We'll randomize inputs and also test hold behavior
        for (i = 0; i < 92; i = i + 1) begin
            // Randomize D, G, RN
            D  = $random % 2;
            G  = $random % 2;
            // Occasionally assert reset
            if (i % 10 == 0)
                RN = 0;
            else
                RN = 1;

            #1;

            // Compute expected Q
            if (~RN) begin
                expected_Q = 0;
            end else if (G) begin
                expected_Q = D;
            end
            // else: expected_Q holds previous value

            expected_QN = ~expected_Q;

            // Write test vector to file
            $fdisplay(fd, "%b %b %b %b %b", D, G, RN, Q, QN);

            // Check outputs
            check_outputs(D, G, RN, Q, QN, expected_Q, expected_QN);

            vector_count = vector_count + 1;
        end

        // Additional directed tests for edge cases
        // 1. Assert reset while G=1, D=1
        D = 1; G = 1; RN = 0; #1;
        expected_Q = 0; expected_QN = 1;
        $fdisplay(fd, "%b %b %b %b %b", D, G, RN, Q, QN);
        check_outputs(D, G, RN, Q, QN, expected_Q, expected_QN);
        vector_count = vector_count + 1;

        // 2. Release reset, G=1, D=1
        RN = 1; #1;
        expected_Q = 1; expected_QN = 0;
        $fdisplay(fd, "%b %b %b %b %b", D, G, RN, Q, QN);
        check_outputs(D, G, RN, Q, QN, expected_Q, expected_QN);
        vector_count = vector_count + 1;

        // 3. G=0, D=0, RN=1 (should hold previous Q)
        G = 0; D = 0; #1;
        // expected_Q remains unchanged
        expected_QN = ~expected_Q;
        $fdisplay(fd, "%b %b %b %b %b", D, G, RN, Q, QN);
        check_outputs(D, G, RN, Q, QN, expected_Q, expected_QN);
        vector_count = vector_count + 1;

        // 4. Change D while G=0, Q should not change
        D = 1; #1;
        // expected_Q remains unchanged
        expected_QN = ~expected_Q;
        $fdisplay(fd, "%b %b %b %b %b", D, G, RN, Q, QN);
        check_outputs(D, G, RN, Q, QN, expected_Q, expected_QN);
        vector_count = vector_count + 1;

        // 5. G=1, D=0, RN=1 (Q should update)
        G = 1; D = 0; #1;
        expected_Q = 0; expected_QN = 1;
        $fdisplay(fd, "%b %b %b %b %b", D, G, RN, Q, QN);
        check_outputs(D, G, RN, Q, QN, expected_Q, expected_QN);
        vector_count = vector_count + 1;

        // 6. Assert reset again
        RN = 0; #1;
        expected_Q = 0; expected_QN = 1;
        $fdisplay(fd, "%b %b %b %b %b", D, G, RN, Q, QN);
        check_outputs(D, G, RN, Q, QN, expected_Q, expected_QN);
        vector_count = vector_count + 1;

        // Close file
        $fclose(fd);

        $display("Testbench completed. Total vectors: %0d, Errors: %0d", vector_count, error_count);

        $finish;
    end

endmodule

