module combinational_circuit(
    input  [1:0] A1A2,
    input  [1:0] B1B2,
    input  [1:0] C1C2,
    output       Y
);

    wire [1:0] and_ab;
    wire [1:0] not_c;
    wire       and_ab_result;
    wire       not_c_result;

    assign and_ab = A1A2 & B1B2;         // Bitwise AND
    assign not_c  = ~C1C2;               // Bitwise NOT

    assign and_ab_result = and_ab[1] & and_ab[0]; // AND both bits together
    assign not_c_result  = not_c[1] | not_c[0];   // OR both bits together

    assign Y = and_ab_result | not_c_result;

endmodule

