module d_latch_en_tb;

    // Inputs
    reg D;
    reg EN;

    // Outputs
    wire Q;
    wire Q_bar;

    // Internal variables
    integer fd;
    integer i;
    integer error_count;
    reg expected_Q;
    reg expected_Q_bar;
    reg last_Q;
    reg last_D;
    reg last_EN;

    // Instantiate the DUT
    d_latch_en dut (
        .D(D),
        .EN(EN),
        .Q(Q),
        .Q_bar(Q_bar)
    );

    // Timeout mechanism
    initial begin
        #10000;
        $display("Timeout reached at time %0t. Finishing simulation.", $time);
        $finish;
    end

    // Task to check outputs and report errors
    task check_outputs;
        input [0:0] exp_Q;
        input [0:0] exp_Q_bar;
        begin
            if ((Q !== exp_Q) || (Q_bar !== exp_Q_bar)) begin
                $display("ERROR at time %0t: D=%b EN=%b | Q=%b (exp %b) Q_bar=%b (exp %b)", $time, D, EN, Q, exp_Q, Q_bar, exp_Q_bar);
                error_count = error_count + 1;
            end
        end
    endtask

    // Main stimulus and checking
    initial begin
        // Open file for writing test vectors
        fd = $fopen("test_vectors.txt", "w");
        if (fd) $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        error_count = 0;
        last_Q = 0;
        last_D = 0;
        last_EN = 0;

        // Initialize inputs
        D = 0;
        EN = 0;
        #5;

        // Reset Q_reg to known state by toggling EN
        EN = 1; D = 0; #5; EN = 0; #5;
        last_Q = 0;

        // Generate at least 100 test vectors with various patterns
        for (i = 0; i < 100; i = i + 1) begin
            // Generate D and EN patterns
            case (i % 8)
                0: begin D = 0; EN = 0; end
                1: begin D = 1; EN = 0; end
                2: begin D = 0; EN = 1; end
                3: begin D = 1; EN = 1; end
                4: begin D = ~D; EN = ~EN; end
                5: begin D = $random % 2; EN = $random % 2; end
                6: begin D = 1; EN = ~EN; end
                7: begin D = 0; EN = ~EN; end
            endcase

            #3; // Wait for input to settle

            // On EN rising edge, latch D
            if ((EN === 1'b1) && (last_EN === 1'b0)) begin
                expected_Q = D;
            end else begin
                expected_Q = last_Q;
            end
            expected_Q_bar = ~expected_Q;

            // Wait for DUT to update
            #1;

            // Write test vector to file: D EN Q Q_bar
            $fdisplay(fd, "%b %b %b %b", D, EN, Q, Q_bar);

            // Check outputs
            check_outputs(expected_Q, expected_Q_bar);

            // Update last values
            last_Q = expected_Q;
            last_D = D;
            last_EN = EN;

            #6; // Advance time to next test
        end

        // Final report
        if (error_count == 0)
            $display("All test cases passed.");
        else
            $display("Total errors: %0d", error_count);

        $fclose(fd);
        $finish;
    end

