module counter_tb;

    // Inputs
    reg clk;
    reg rst;
    reg en;
    reg ctrl;

    // Output
    wire [3:0] count;

    // Internal variables
    integer fd;
    integer i;
    integer error_count;
    reg [3:0] expected_count;
    reg [3:0] prev_count;

    // Instantiate the counter module
    counter uut (
        .clk(clk),
        .rst(rst),
        .en(en),
        .ctrl(ctrl),
        .count(count)
    );

    // Clock generation: 10ns period
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    // Timeout mechanism
    initial begin
        #10000;
        $display("Timeout reached at time %0t. Simulation stopped.", $time);
        $finish;
    end

    // Error checking task
    task check_output;
        input [3:0] exp_count;
        input [3:0] actual_count;
        input [31:0] vector_num;
        begin
            if (exp_count !== actual_count) begin
                $display("ERROR at vector %0d, time %0t: Expected count=%0d, Got count=%0d", vector_num, $time, exp_count, actual_count);
                error_count = error_count + 1;
            end
        end
    endtask

    // Main stimulus and test vector generation
    initial begin
        fd = $fopen("test_vectors.txt", "w");
        if (fd) $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        // Write header (optional, can be commented out if not needed)
        // $fdisplay(fd, "clk rst en ctrl count");

        // Initialize
        rst = 1;
        en = 0;
        ctrl = 0;
        expected_count = 4'b0000;
        error_count = 0;

        // Apply reset
        @(negedge clk);
        #1;
        $fdisplay(fd, "%b %b %b %b %b", clk, rst, en, ctrl, count);
        @(negedge clk);
        #1;
        rst = 0;

        // Test all combinations for en and ctrl, with and without reset
        // Generate at least 100 test vectors, including edge cases

        // 1. Basic up-counting
        for (i = 0; i < 20; i = i + 1) begin
            en = 1;
            ctrl = 0;
            prev_count = expected_count;
            @(negedge clk);
            #1;
            if (en) begin
                expected_count = prev_count + 1;
            end
            check_output(expected_count, count, i);
            $fdisplay(fd, "%b %b %b %b %b", clk, rst, en, ctrl, count);
        end

        // 2. Basic down-counting
        for (i = 20; i < 40; i = i + 1) begin
            en = 1;
            ctrl = 1;
            prev_count = expected_count;
            @(negedge clk);
            #1;
            if (en) begin
                expected_count = prev_count - 1;
            end
            check_output(expected_count, count, i);
            $fdisplay(fd, "%b %b %b %b %b", clk, rst, en, ctrl, count);
        end

        // 3. en = 0 (no counting)
        for (i = 40; i < 60; i = i + 1) begin
            en = 0;
            ctrl = $random % 2;
            prev_count = expected_count;
            @(negedge clk);
            #1;
            // expected_count should not change
            check_output(expected_count, count, i);
            $fdisplay(fd, "%b %b %b %b %b", clk, rst, en, ctrl, count);
        end

        // 4. Randomized test vectors
        for (i = 60; i < 90; i = i + 1) begin
            en = $random % 2;
            ctrl = $random % 2;
            prev_count = expected_count;
            @(negedge clk);
            #1;
            if (en) begin
                if (ctrl)
                    expected_count = prev_count - 1;
                else
                    expected_count = prev_count + 1;
            end
            check_output(expected_count, count, i);
            $fdisplay(fd, "%b %b %b %b %b", clk, rst, en, ctrl, count);
        end

        // 5. Test reset at various points
        for (i = 90; i < 100; i = i + 1) begin
            rst = 1;
            en = $random % 2;
            ctrl = $random % 2;
            @(negedge clk);
            #1;
            expected_count = 4'b0000;
            check_output(expected_count, count, i);
            $fdisplay(fd, "%b %b %b %b %b", clk, rst, en, ctrl, count);
            rst = 0;
        end

        // Final report
        $display("Test completed with %0d errors.", error_count);

        $fclose(fd);
        $finish;
    end

