    input signed [15:0] a_in;
    input signed [15:0] b_in;
    input [1:0] op_in;
    input signed [15:0] res_in;
    input signed [15:0] exp_in;
    begin
      if (res_in !== exp_in) begin
        $display("ERROR: a=%0d b=%0d op=%0d result=%0d expected=%0d at time %0t", a_in, b_in, op_in, res_in, exp_in, $time);
        error_count = error_count + 1;
      end
      // Assertion (SystemVerilog style, but for Verilog use if-statement)
      // assert (res_in === exp_in);
    end
  endtask

  // Main stimulus
  initial begin
    error_count = 0;
    fd = $fopen("test_vectors.txt", "w");
    if (fd)
      $display("File opened successfully");
    else begin
      $display("Failed to open file");
      $finish;
    end

    // Write header (optional)
