    // Generate at least 100 test vectors
    // We'll do exhaustive for small values, and random for the rest

    // 1. Exhaustive for small values
    for (i = -2; i <= 2; i = i + 1) begin
      for (j = -2; j <= 2; j = j + 1) begin
        for (k = 0; k < 4; k = k + 1) begin
          a = i;
          b = j;
          op = k[1:0];
          #1;
          // Compute expected result
          case (op)
            2'b00: expected_result = a + b;
            2'b01: expected_result = a - b;
            2'b10: expected_result = a * b;
            2'b11: if (b != 0) expected_result = a / b; else expected_result = 16'shxxxx;
            default: expected_result = 16'h0000;
          endcase
          // Write to file: a b op result
          $fdisplay(fd, "%0d %0d %0d %0d", a, b, op, result);
          // Check result (avoid checking division by zero)
          if (!(op == 2'b11 && b == 0))
            check_result(a, b, op, result, expected_result);
        end
      end
    end

    // 2. Randomized test vectors for wider coverage
    for (i = 0; i < 80; i = i + 1) begin
      a = $random;
