    expected_result = a + b;
    $fdisplay(fd, "%0d %0d %0d %0d", a, b, op, result);
    check_result(a, b, op, result, expected_result);

    a = -16'sh8000; b = -1; op = 2'b01; #1; // underflow
    expected_result = a - b;
    $fdisplay(fd, "%0d %0d %0d %0d", a, b, op, result);
    check_result(a, b, op, result, expected_result);

    a = 16'sh7FFF; b = 2; op = 2'b10; #1; // large multiplication
    expected_result = a * b;
    $fdisplay(fd, "%0d %0d %0d %0d", a, b, op, result);
    check_result(a, b, op, result, expected_result);

    a = -16'sh8000; b = 2; op = 2'b10; #1; // large negative multiplication
    expected_result = a * b;
    $fdisplay(fd, "%0d %0d %0d %0d", a, b, op, result);
    check_result(a, b, op, result, expected_result);

    a = 16'sh7FFF; b = 1; op = 2'b11; #1; // division
    expected_result = a / b;
    $fdisplay(fd, "%0d %0d %0d %0d", a, b, op, result);
