    a = -16'sh8000; b = -1; op = 2'b11; #1; // division
    expected_result = a / b;
    $fdisplay(fd, "%0d %0d %0d %0d", a, b, op, result);
    check_result(a, b, op, result, expected_result);

    $fclose(fd);

    if (error_count == 0)
      $display("All tests PASSED.");
    else
      $display("TEST FAILED with %0d errors.", error_count);

    $finish;
  end

