    test_count = 0;

    // Generate 100 test vectors using a pseudo-random and exhaustive approach
    // First, exhaustively test all 2^5 = 32 combinations for A1,A2,A3,B1,B2 with others 0
    for (i = 0; i < 32; i = i + 1) begin
