module bin2gray (
    input  [3:0] B,
    output [3:0] G
);

    // Gray code generation:
    // G[3] = B[3]
    // G[2] = B[3] ^ B[2]
    // G[1] = B[2] ^ B[1]
    // G[0] = B[1] ^ B[0]

    assign G[3] = B[3];
    assign G[2] = B[3] ^ B[2];
    assign G[1] = B[2] ^ B[1];
    assign G[0] = B[1] ^ B[0];

endmodule

