    .clk(clk),
    .ena(ena),
    .addr(addr),
    .din(din),
    .we(we),
    .dout(dout)
  );

  // Clock generation
  initial begin
    clk = 0;
    forever #5 clk = ~clk;
  end

  // Error checking task
  task check_output;
    input [7:0] expected;
    input [7:0] actual;
    input [11:0] t_addr;
    input [7:0] t_din;
    input t_ena;
    input t_we;
    begin
      if (expected !== actual) begin
        $display("ERROR at time %0t: addr=%h din=%h ena=%b we=%b expected=%h got=%h", $time, t_addr, t_din, t_ena, t_we, expected, actual);
        error_count = error_count + 1;
      end
    end
  endtask

  // Main stimulus
  initial begin
    // Initialize model memory
    for (i = 0; i < 4096; i = i + 1) begin
      mem_model[i] = 8'h00;
    end

    // Open file
    fd = $fopen("test_vectors.txt", "w");
    if (fd) $display("File opened successfully");
    else begin
      $display("Failed to open file");
      $finish;
    end

    error_count = 0;
    test_count = 0;

    // Reset signals
    ena = 0;
    addr = 0;
    din = 0;
    we = 0;

    // Wait for a few cycles
    repeat (2) @(posedge clk);

    // Test 1: Write and Readback (first 50 addresses)
    for (i = 0; i < 50; i = i + 1) begin
      // Write
      @(posedge clk);
      ena = 1;
      we = 1;
      addr = i[11:0];
      din = (i * 7) ^ 8'hA5;
      mem_model[addr] = din;
      // Write vector: clk ena addr din we dout
      @(negedge clk);
      $fdisplay(fd, "%b %b %h %h %b %h", clk, ena, addr, din, we, dout);
      test_count = test_count + 1;

      // Read
      @(posedge clk);
      ena = 1;
      we = 0;
      addr = i[11:0];
      din = 8'h00;
      expected_dout = mem_model[addr];
      @(negedge clk);
      $fdisplay(fd, "%b %b %h %h %b %h", clk, ena, addr, din, we, dout);
      check_output(expected_dout, dout, addr, din, ena, we);
      test_count = test_count + 1;
    end

    // Test 2: Write and Readback (random addresses, next 50)
    for (i = 0; i < 50; i = i + 1) begin
      @(posedge clk);
      ena = 1;
      we = 1;
      addr = {$random} % 4096;
      din = {$random} % 256;
