      ena = 1;
      we = 0;
      din = 8'h00;
      expected_dout = mem_model[addr];
      @(negedge clk);
      $fdisplay(fd, "%b %b %h %h %b %h", clk, ena, addr, din, we, dout);
      check_output(expected_dout, dout, addr, din, ena, we);
      test_count = test_count + 1;
    end

    // Test 3: Disabled (ena=0), should output 0
    for (i = 0; i < 5; i = i + 1) begin
      @(posedge clk);
      ena = 0;
      we = 0;
      addr = i[11:0];
      din = 8'h00;
      @(negedge clk);
      $fdisplay(fd, "%b %b %h %h %b %h", clk, ena, addr, din, we, dout);
      check_output(8'h00, dout, addr, din, ena, we);
      test_count = test_count + 1;
    end

    // Test 4: Disabled (ena=0, we=1), should output 0, memory not written
    for (i = 0; i < 5; i = i + 1) begin
      @(posedge clk);
      ena = 0;
      we = 1;
      addr = i[11:0];
      din = 8'hFF;
      @(negedge clk);
      $fdisplay(fd, "%b %b %h %h %b %h", clk, ena, addr, din, we, dout);
      check_output(8'h00, dout, addr, din, ena, we);
      if (mem_model[addr] !== 8'hFF) ; // No write should occur
      test_count = test_count + 1;
    end

    // Test 5: Overwrite and Readback
    for (i = 0; i < 5; i = i + 1) begin
      @(posedge clk);
      ena = 1;
      we = 1;
      addr = i[11:0];
      din = 8'hAA + i;
      mem_model[addr] = din;
      @(negedge clk);
