      check_output(expected_dout, dout, addr, din, ena, we);
      test_count = test_count + 1;
    end

    // Close file and report
    $fclose(fd);
    $display("Test completed: %0d tests, %0d errors", test_count, error_count);
    $finish;
  end

  // Timeout mechanism
