module dff_async_set_tb;

    // DUT signals
    reg D;
    reg S;
    reg clk;
    wire Q;

    // File handling
    integer fd;
    integer error_count;
    integer test_count;
    integer i;

    // For timeout
    parameter TIMEOUT = 10000;

    // Instantiate DUT
    dff_async_set uut (
        .D(D),
        .S(S),
        .clk(clk),
        .Q(Q)
    );

    // Clock generation: 10ns period
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    // Task to check expected output and report errors
    task check_output;
        input reg expected_Q;
        begin
            if (Q !== expected_Q) begin
                $display("ERROR at time %0t: D=%b S=%b Q=%b (expected %b)", $time, D, S, Q, expected_Q);
                error_count = error_count + 1;
            end
        end
    endtask

    // Test sequence
    initial begin
        // Open file
        fd = $fopen("test_vectors.txt", "w");
        if (fd) $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        // Initialize
        D = 0;
        S = 0;
        error_count = 0;
        test_count = 0;

        // Write header (optional, can be removed if not desired)
        // $fdisplay(fd, "D S clk Q");

        // Reset Q by toggling S
        @(negedge clk);
        S = 1;
        @(posedge clk);
        #1;
        $fdisplay(fd, "%b %b %b %b", D, S, clk, Q);
        check_output(1'b1);
        test_count = test_count + 1;

        S = 0;
        @(negedge clk);

        // Test all combinations of D and S at clk edge
        for (i = 0; i < 50; i = i + 1) begin
            // Randomize inputs
            D = $random % 2;
            S = $random % 2;

            // Apply S asynchronously
            if (S) begin
                #2; // Wait a little before asserting S
                S = 1;
                @(posedge S);
                #1;
                $fdisplay(fd, "%b %b %b %b", D, S, clk, Q);
                check_output(1'b1);
                test_count = test_count + 1;
                S = 0;
            end

            // Apply D at clk edge
            @(negedge clk);
            D = $random % 2;
            S = 0;
            @(posedge clk);
            #1;
            $fdisplay(fd, "%b %b %b %b", D, S, clk, Q);
            check_output(D);
            test_count = test_count + 1;
        end

        // Deterministic edge cases
        // 1. S asserted just before clk edge
        D = 0; S = 0;
        @(negedge clk);
        D = 1; S = 1;
        #2;
        @(posedge clk);
        #1;
        $fdisplay(fd, "%b %b %b %b", D, S, clk, Q);
        check_output(1'b1);
        test_count = test_count + 1;
        S = 0;

        // 2. S deasserted, D changes
        @(negedge clk);
        D = 0; S = 0;
        @(posedge clk);
        #1;
        $fdisplay(fd, "%b %b %b %b", D, S, clk, Q);
        check_output(1'b0);
        test_count = test_count + 1;

        // 3. S asserted and deasserted between clocks
        @(negedge clk);
        D = 1; S = 1;
        #2;
        S = 0;
        @(posedge clk);
        #1;
        $fdisplay(fd, "%b %b %b %b", D, S, clk, Q);
        check_output(D);
        test_count = test_count + 1;

        // 4. S asserted for multiple cycles
        @(negedge clk);
        D = 0; S = 1;
        @(posedge clk);
        #1;
        $fdisplay(fd, "%b %b %b %b", D, S, clk, Q);
        check_output(1'b1);
        test_count = test_count + 1;
        @(negedge clk);
        D = 1; S = 1;
        @(posedge clk);
        #1;
        $fdisplay(fd, "%b %b %b %b", D, S, clk, Q);
        check_output(1'b1);
        test_count = test_count + 1;
        S = 0;

        // 5. D toggling, S low
        repeat (10) begin
            @(negedge clk);
            D = ~D;
            S = 0;
            @(posedge clk);
            #1;
            $fdisplay(fd, "%b %b %b %b", D, S, clk, Q);
            check_output(D);
            test_count = test_count + 1;
        end

        // 6. S pulse between clocks
        @(negedge clk);
        D = 0; S = 0;
        #2;
        S = 1;
        #2;
        S = 0;
        @(posedge clk);
        #1;
        $fdisplay(fd, "%b %b %b %b", D, S, clk, Q);
        check_output(D);
        test_count = test_count + 1;

        // Ensure at least 100 test vectors
        while (test_count < 100) begin
            @(negedge clk);
            D = $random % 2;
            S = $random % 2;
            if (S) begin
                #1;
                S = 1;
                @(posedge S);
                #1;
                $fdisplay(fd, "%b %b %b %b", D, S, clk, Q);
                check_output(1'b1);
                test_count = test_count + 1;
                S = 0;
            end
            @(posedge clk);
            #1;
            $fdisplay(fd, "%b %b %b %b", D, S, clk, Q);
            check_output(D);
            test_count = test_count + 1;
        end

        $display("Test completed: %0d vectors, %0d errors", test_count, error_count);
        $fclose(fd);
        $finish;
    end

    // Timeout mechanism
    initial begin
        #TIMEOUT;
        $display("TIMEOUT: Simulation exceeded %0d time units", TIMEOUT);
        $fclose(fd);
        $finish;
    end

endmodule

