module delay_line #(
    parameter delay = 4 // Number of clock cycles to delay the signal
)(
    input  wire clk,     // Clock signal
    input  wire rst,     // Reset signal (active high)
    input  wire in,      // Input signal to delay
    output wire out      // Delayed output signal
);

    // Shift register to store delayed values
    reg [delay-1:0] shift_reg;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            shift_reg <= {delay{1'b0}};
        end else begin
            shift_reg <= {shift_reg[delay-2:0], in};
        end
    end

    assign out = shift_reg[delay-1];

endmodule

