        ref_out = 1'b0;

        // Apply reset
        rst = 1'b1;
        in = 1'b0;
        @(negedge clk);
        // Write test vector for reset
        $fdisplay(fd, "%b %b %b %b", clk, rst, in, out);
        @(negedge clk);
        rst = 1'b0;

