            // Randomize input
            in = $random % 2;

            // Wait for clock edge
            @(negedge clk);

            // Reference model update
            if (rst) begin
                ref_shift_reg = {delay{1'b0}};
            end else begin
                ref_shift_reg = {ref_shift_reg[delay-2:0], in};
            end
            ref_out = ref_shift_reg[delay-1];

            // Write test vector: clk rst in out
            $fdisplay(fd, "%b %b %b %b", clk, rst, in, out);

            // Assertion: check DUT output matches reference
            if (out !== ref_out) begin
                $display("ERROR at time %0t: i=%0d, in=%b, rst=%b, expected out=%b, got out=%b", $time, i, in, rst, ref_out, out);
                error_count = error_count + 1;
