// clk_delay.v
// Module to delay a 100 MHz clock by a programmable number of nanoseconds (0 - 10 ns)
// clk_in: input clock (100 MHz)
// clk_out: delayed clock output
// delay: delay value in nanoseconds (0 to 10), integer

module clk_delay #(
    parameter MAX_DELAY_NS = 10
) (
    input  wire clk_in,
    output wire clk_out,
    input  wire [3:0] delay   // Delay in nanoseconds: 0-10
);

    // At 100 MHz, clock period is 10 ns, time step is 1 ns (i.e., 10 steps per period)
    // Each "step" is 1 ns. We'll use a shift register to delay the clock edge.
    //
    // For example, to delay by N ns, register the input clk_in over N clk_in cycles,
    // using a shift register of length (MAX_DELAY_NS+1), and tap the output after N steps.

    reg [MAX_DELAY_NS:0] clk_shift = 0;

    always @(posedge clk_in) begin
        clk_shift <= {clk_shift[MAX_DELAY_NS-1:0], clk_in};
    end

    // Multiplexer to select the correct delayed tap
    reg clk_delayed;
    integer i;

    always @(*) begin
        clk_delayed = clk_shift[0]; // default: 0 ns delay
        for (i=0; i<=MAX_DELAY_NS; i=i+1) begin
            if (delay == i[3:0])
                clk_delayed = clk_shift[i];
        end
    end

    assign clk_out = clk_delayed;

endmodule

