module shift_register_4bit (
    input clk,
    input reset,
    input shift_in,
    input shift,           // 1 = shift right, 0 = shift left
    output reg shift_out,
    output reg [3:0] q
);

always @(posedge clk) begin
    if (reset) begin
        q <= 4'b0000;
        shift_out <= 1'b0;
    end else begin
        if (shift) begin
            // Shift Right
            shift_out <= q[0];
            q <= {shift_in, q[3:1]};
        end else begin
            // Shift Left
            shift_out <= q[3];
            q <= {q[2:0], shift_in};
        end
    end
end

endmodule

