    task check_outputs;
        input [3:0] expected_q_t;
        input expected_shift_out_t;
        begin
            if (q !== expected_q_t) begin
                $display("ASSERTION FAILED at time %0t: q = %b, expected %b", $time, q, expected_q_t);
                error_count = error_count + 1;
            end
            if (shift_out !== expected_shift_out_t) begin
                $display("ASSERTION FAILED at time %0t: shift_out = %b, expected %b", $time, shift_out, expected_shift_out_t);
                error_count = error_count + 1;
            end
        end
