module sky130_fd_sc_hd__mux2_1 (
    output Z,
    input  A,
    input  B,
    input  S
);
    // Module supplies
    supply1 VPWR;
    supply0 VGND;

    wire buf0_out;
    wire buf1_out;
    wire not0_out;
    wire and0_out;
    wire and1_out;

    buf buf0 (buf0_out, A);
    buf buf1 (buf1_out, B);
    not not0 (not0_out, S);
    and and0 (and0_out, buf0_out, not0_out);
    and and1 (and1_out, buf1_out, S);
    or  or0  (Z, and0_out, and1_out);

endmodule

module binary_counter(
    input clk,
    input rst,
    output reg [3:0] count
);

    // Module supplies
    supply1 VPWR;
    supply0 VGND;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            count <= 4'b0000;
        end else if (count == 4'b1111) begin
            count <= 4'b0000;
        end else begin
            count <= count + 4'b0001;
        end
    end

    // Instantiate sky130_fd_sc_hd__mux2_1 module for illustration
    wire mux_out;
    sky130_fd_sc_hd__mux2_1 mux_inst (
        .Z(mux_out), 
        .A(1'b0),         // Using 1 bit for A
        .B(count[0]),     // Lower bit of count as B
        .S(count[0])      // Use count[0] as selector
    );

endmodule

