module shift_register_4bit (
    input wire [3:0] data_in,
    input wire load,
    input wire clk,
    output reg [3:0] data_out
);

    reg [3:0] shift_reg;

    always @(posedge clk) begin
        if (load) begin
            shift_reg <= data_in;
        end else begin
            shift_reg <= {shift_reg[2:0], data_in[0]};
        end
    end

    always @(*) begin
        data_out = shift_reg;
    end

endmodule

