module register_4bit (
    input clk,
    input rst,
    input ld,
    input [3:0] d,
    input si,
    output so,
    output reg [3:0] q
);

assign so = q[3];

always @(posedge clk or posedge rst) begin
    if (rst) begin
        q <= 4'b0000;
    end else if (ld) begin
        q <= d;
    end else begin
        q <= {q[2:0], si};
    end
end

endmodule

