    initial begin
        #10000;
        $display("Timeout reached at time %0t. Finishing simulation.", $time);
        $finish;
    end

    // Task to check output and report errors
    task check_output;
        input [3:0] expected;
        input [3:0] actual;
        input [31:0] vector_num;
        begin
            if (expected !== actual) begin
                $display("ERROR at vector %0d, time %0t: expected count=%0d, got count=%0d", vector_num, $time, expected, actual);
                error_count = error_count + 1;
            end
        end
    endtask

    // Main stimulus and test vector generation
    initial begin
        // Open file
        fd = $fopen("test_vectors.txt", "w");
        if (fd) $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        // Initialize
        rst = 0;
        en = 0;
        error_count = 0;
        expected_count = 0;
        prev_count = 0;

        // Header (optional, can be commented out)
        // $fdisplay(fd, "clk rst en count");

        // Apply reset at start
        @(negedge clk);
        rst = 1;
        en = 0;
        @(negedge clk);
        // Write vector
        $fdisplay(fd, "%b %b %b %04b", clk, rst, en, count);
        expected_count = 0;
        check_output(expected_count, count, 0);

        // Release reset
        rst = 0;
        @(negedge clk);
        $fdisplay(fd, "%b %b %b %04b", clk, rst, en, count);
        check_output(expected_count, count, 1);

        // Test: Enable counting for 20 cycles
        en = 1;
        for (i = 2; i < 22; i = i + 1) begin
            @(negedge clk);
            if (en) expected_count = expected_count + 1;
            $fdisplay(fd, "%b %b %b %04b", clk, rst, en, count);
            check_output(expected_count, count, i);
        end

        // Test: Disable enable for 10 cycles
        en = 0;
        for (i = 22; i < 32; i = i + 1) begin
            @(negedge clk);
            // expected_count remains the same
            $fdisplay(fd, "%b %b %b %04b", clk, rst, en, count);
            check_output(expected_count, count, i);
        end

        // Test: Toggle enable every cycle for 20 cycles
        for (i = 32; i < 52; i = i + 1) begin
            en = ~en;
            @(negedge clk);
            if (en) expected_count = expected_count + 1;
            $fdisplay(fd, "%b %b %b %04b", clk, rst, en, count);
            check_output(expected_count, count, i);
        end

        // Test: Assert reset in the middle of counting
        en = 1;
        @(negedge clk);
        rst = 1;
        @(negedge clk);
        expected_count = 0;
        $fdisplay(fd, "%b %b %b %04b", clk, rst, en, count);
        check_output(expected_count, count, 52);

        // Release reset, keep enable high, count for 10 cycles
        rst = 0;
        for (i = 53; i < 63; i = i + 1) begin
            @(negedge clk);
            if (en) expected_count = expected_count + 1;
            $fdisplay(fd, "%b %b %b %04b", clk, rst, en, count);
            check_output(expected_count, count, i);
        end

        // Test: Multiple resets and enables
        for (i = 63; i < 73; i = i + 1) begin
            en = (i % 2);
            rst = (i == 68) ? 1 : 0;
            @(negedge clk);
            if (rst)
                expected_count = 0;
            else if (en)
                expected_count = expected_count + 1;
            $fdisplay(fd, "%b %b %b %04b", clk, rst, en, count);
            check_output(expected_count, count, i);
        end

        // Test: Count up to wrap-around
        rst = 1;
        en = 0;
        @(negedge clk);
        expected_count = 0;
        $fdisplay(fd, "%b %b %b %04b", clk, rst, en, count);
        check_output(expected_count, count, 73);

        rst = 0;
        en = 1;
        for (i = 74; i < 90; i = i + 1) begin
            @(negedge clk);
            if (en) expected_count = expected_count + 1;
            $fdisplay(fd, "%b %b %b %04b", clk, rst, en, count);
            check_output(expected_count, count, i);
        end

        // Randomized test for remaining vectors (to reach at least 100)
        for (i = 90; i < 100; i = i + 1) begin
            rst = $random % 2;
            en = $random % 2;
            @(negedge clk);
            if (rst)
                expected_count = 0;
            else if (en)
                expected_count = expected_count + 1;
            $fdisplay(fd, "%b %b %b %04b", clk, rst, en, count);
            check_output(expected_count, count, i);
        end

        // Close file
        $fclose(fd);

        // Report errors
        if (error_count == 0)
            $display("All test vectors passed.");
        else
            $display("Testbench completed with %0d errors.", error_count);

        $finish;
    end

