module calculator(
    input  wire [7:0] A,
    input  wire [7:0] B,
    input  wire [1:0] op,
    output wire [7:0] result
);

    // Internal wires for each operation
    wire [7:0] add_result;
    wire [7:0] sub_result;
    wire [7:0] mul_result;
    wire [7:0] div_result;

    // Addition
    assign add_result = A + B;
    // Subtraction
    assign sub_result = A - B;
    // Multiplication (truncate to 8 bits)
    assign mul_result = A * B;
    // Division; division by zero produces 8'b0
    assign div_result = (B == 8'b0) ? 8'b0 : A / B;

    // Select appropriate operation based on op
    assign result = (op == 2'b00) ? add_result :
                    (op == 2'b01) ? sub_result :
                    (op == 2'b10) ? mul_result :
                    /* op == 2'b11 */ div_result;

endmodule

