module async_set_reset_ff (
    input  wire D,         // Data input
    input  wire RESET_B,   // Asynchronous reset (active low)
    input  wire SET_B,     // Asynchronous set   (active low)
    input  wire CLK,       // Clock input
    output reg  Q,         // Output
    output wire Q_B        // Complementary output
);

    // Q_B is always the inverse of Q
    assign Q_B = ~Q;

    always @(posedge CLK or negedge RESET_B or negedge SET_B) begin
        if (!RESET_B) begin         // Asynchronous active low reset
            Q <= 1'b0;
        end else if (!SET_B) begin  // Asynchronous active low set
            Q <= 1'b1;
        end else begin              // Regular D flip-flop
            Q <= D;
        end
    end

endmodule

