`timescale 1ns/1ps

module async_set_reset_ff_tb;

    // Inputs
    reg D;
    reg RESET_B;
    reg SET_B;
    reg CLK;

    // Outputs
    wire Q;
    wire Q_B;

    // Instantiate the Unit Under Test (UUT)
    async_set_reset_ff uut (
        .D(D),
        .RESET_B(RESET_B),
        .SET_B(SET_B),
        .CLK(CLK),
        .Q(Q),
        .Q_B(Q_B)
    );

    // File descriptor for test vector output
    integer fd;
    integer error_count;
    integer test_count;
    integer i;

    // Timeout limit (in ns)
    parameter TIMEOUT = 10000;

    // Clock generation
    initial begin
        CLK = 0;
        forever #5 CLK = ~CLK; // 100MHz clock
    end

    // Task to check outputs and report errors
    task check_output;
        input reg expected_Q;
        input reg expected_Q_B;
        begin
            if (Q !== expected_Q) begin
                $display("ERROR at time %0t: Q mismatch. Expected: %b, Got: %b", $time, expected_Q, Q);
                error_count = error_count + 1;
            end
            if (Q_B !== expected_Q_B) begin
                $display("ERROR at time %0t: Q_B mismatch. Expected: %b, Got: %b", $time, expected_Q_B, Q_B);
                error_count = error_count + 1;
            end
        end
    endtask

    // Main stimulus
    initial begin
        // Open file for writing test vectors
        fd = $fopen("test_vectors.txt", "w");
        if (fd)
            $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        // Initialize
        D = 0;
        RESET_B = 1;
        SET_B = 1;
        error_count = 0;
        test_count = 0;

        // Wait for global reset
        #2;

        // Test asynchronous RESET (active low)
        RESET_B = 0; SET_B = 1; D = 1;
        #2;
        $fdisplay(fd, "%b %b %b %b %b", D, RESET_B, SET_B, Q, Q_B);
        check_output(1'b0, 1'b1); // Q should be 0
        test_count = test_count + 1;

        RESET_B = 1; // Release reset
        #2;

        // Test asynchronous SET (active low)
        SET_B = 0; RESET_B = 1; D = 0;
        #2;
        $fdisplay(fd, "%b %b %b %b %b", D, RESET_B, SET_B, Q, Q_B);
        check_output(1'b1, 1'b0); // Q should be 1
        test_count = test_count + 1;

        SET_B = 1; // Release set
        #2;

        // Test both RESET and SET active (RESET has priority)
        RESET_B = 0; SET_B = 0; D = 1;
        #2;
        $fdisplay(fd, "%b %b %b %b %b", D, RESET_B, SET_B, Q, Q_B);
        check_output(1'b0, 1'b1); // Q should be 0
        test_count = test_count + 1;

        RESET_B = 1; SET_B = 1; // Release both
        #2;

        // Test normal D flip-flop operation
        // Apply all combinations of D, RESET_B, SET_B at clock edge
        for (i = 0; i < 100; i = i + 1) begin
            // Randomize inputs
            D = $random % 2;
            RESET_B = 1;
            SET_B = 1;
            // Occasionally assert async controls
            if (i % 17 == 0) RESET_B = 0;
            if (i % 23 == 0) SET_B = 0;
            // Wait for setup time before clock
            #2;
            // Clock edge
            @(negedge CLK);
            // Wait for output to settle
            #1;
            $fdisplay(fd, "%b %b %b %b %b", D, RESET_B, SET_B, Q, Q_B);
            // Determine expected output
            if (!RESET_B)
                check_output(1'b0, 1'b1);
            else if (!SET_B)
                check_output(1'b1, 1'b0);
            else
                check_output(D, ~D);
            test_count = test_count + 1;
            // Release async controls
            RESET_B = 1;
            SET_B = 1;
            #1;
        end

        // Test all possible combinations of D, RESET_B, SET_B at clock edge (8 combinations)
        for (i = 0; i < 8; i = i + 1) begin
            D = (i >> 2) & 1;
            RESET_B = (i >> 1) & 1;
            SET_B = i & 1;
            #2;
            @(negedge CLK);
            #1;
            $fdisplay(fd, "%b %b %b %b %b", D, RESET_B, SET_B, Q, Q_B);
            if (!RESET_B)
                check_output(1'b0, 1'b1);
            else if (!SET_B)
                check_output(1'b1, 1'b0);
            else
                check_output(D, ~D);
            test_count = test_count + 1;
            RESET_B = 1;
            SET_B = 1;
            #1;
        end

        // Test asynchronous set/reset during clock transitions
        D = 0;
        RESET_B = 1;
        SET_B = 1;
        #2;
        // Assert RESET_B just before clock edge
        RESET_B = 0;
        #3;
        @(posedge CLK);
        #1;
        $fdisplay(fd, "%b %b %b %b %b", D, RESET_B, SET_B, Q, Q_B);
        check_output(1'b0, 1'b1);
        test_count = test_count + 1;
        RESET_B = 1;
        #2;

        // Assert SET_B just before clock edge
        SET_B = 0;
        #3;
        @(posedge CLK);
        #1;
        $fdisplay(fd, "%b %b %b %b %b", D, RESET_B, SET_B, Q, Q_B);
        check_output(1'b1, 1'b0);
        test_count = test_count + 1;
        SET_B = 1;
        #2;

        // Final report
        $display("Testbench completed. Total tests: %0d, Errors: %0d", test_count, error_count);
        $fclose(fd);
        $finish;
    end

    // Timeout mechanism
    initial begin
        #TIMEOUT;
        $display("ERROR: Simulation timed out at time %0t", $time);
        $fclose(fd);
        $finish;
    end

endmodule

