    integer test_count;
    integer i, j, k;
    reg [3:0] expected_result;

    // Instantiate the DUT
    barrel_shifter dut (
        .data(data),
        .shift_amount(shift_amount),
        .result(result)
    );

    // Timeout mechanism
    initial begin
        #10000;
        $display("ERROR: Simulation timeout at time %0t ns", $time);
        $finish;
    end

    // Task to check result and report errors
    task check_result;
        input [3:0] expected;
        input [3:0] actual;
        input [3:0] data_in;
        input [1:0] shift_in;
        begin
            if (expected !== actual) begin
                $display("ASSERTION FAILED: data=%b shift_amount=%b expected=%b got=%b at time %0t", data_in, shift_in, expected, actual, $time);
                error_count = error_count + 1;
            end
        end
    endtask

    // Function to compute expected result
    function [3:0] compute_expected;
        input [3:0] din;
        input [1:0] sa;
        begin
            case (sa)
                2'b00: compute_expected = din;
                2'b01: compute_expected = {din[2:0], din[3]};
                2'b10: compute_expected = {din[1:0], din[3:2]};
                2'b11: compute_expected = {din[0], din[3:1]};
                default: compute_expected = din;
            endcase
        end
    endfunction

    // Main stimulus and checking
    initial begin
        error_count = 0;
        test_count = 0;

        // Open file for writing test vectors
        fd = $fopen("test_vectors.txt", "w");
        if (fd) $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        // Exhaustive test for all input combinations (4'b0000 to 4'b1111, shift 00 to 11)
        for (i = 0; i < 16; i = i + 1) begin
            for (j = 0; j < 4; j = j + 1) begin
                data = i[3:0];
                shift_amount = j[1:0];
                #1; // Allow combinational logic to settle

                expected_result = compute_expected(data, shift_amount);

                // Write test vector: data shift_amount result
                $fdisplay(fd, "%b %b %b", data, shift_amount, result);

                // Assertion
                check_result(expected_result, result, data, shift_amount);

                test_count = test_count + 1;
            end
        end

        // Generate additional random test vectors to reach at least 100 total
        for (k = test_count; k < 100; k = k + 1) begin
            data = $random % 16;
            shift_amount = $random % 4;
            #1;

            expected_result = compute_expected(data, shift_amount);

            $fdisplay(fd, "%b %b %b", data, shift_amount, result);

            check_result(expected_result, result, data, shift_amount);
        end

        $display("Testbench completed: %0d tests run, %0d errors detected.", k, error_count);

        $fclose(fd);

        $finish;
    end

endmodule

