module max_val_module_tb;

  // DUT signals
  reg clk;
  reg [15:0] in;
  wire [15:0] max_val;

  // File handling
  integer fd;
  integer i;
  integer error_count;
  reg [15:0] expected_max;
  reg [15:0] test_vectors [0:199]; // 200 test vectors for randomness and coverage
  reg [15:0] ref_max [0:199];

  // Instantiate DUT
  max_val_module dut (
    .clk(clk),
    .in(in),
    .max_val(max_val)
  );

  // Clock generation
  initial begin
    clk = 0;
    forever #5 clk = ~clk; // 100MHz clock
  end

  // Timeout mechanism
  initial begin
    #10000;
    $display("ERROR: Simulation timeout at time %0t", $time);
    $finish;
  end

  // Testbench main process
  initial begin
    error_count = 0;
    expected_max = 0;
    // Open file
    fd = $fopen("test_vectors.txt", "w");
    if (fd) $display("File opened successfully");
    else begin
      $display("Failed to open file");
      $finish;
    end

    // Generate test vectors: mix of edge, random, and sequential values
    test_vectors[0] = 16'h0000;
    test_vectors[1] = 16'hFFFF;
    test_vectors[2] = 16'h8000;
    test_vectors[3] = 16'h7FFF;
    test_vectors[4] = 16'h0001;
    test_vectors[5] = 16'hFFFE;
    for (i = 6; i < 100; i = i + 1) begin
      test_vectors[i] = $random;
    end
    // Sequential increasing
    for (i = 100; i < 150; i = i + 1) begin
      test_vectors[i] = i * 100;
    end
    // Sequential decreasing
    for (i = 150; i < 200; i = i + 1) begin
      test_vectors[i] = 16'hFFFF - (i * 50);
    end

    // Reference model for expected max
    ref_max[0] = test_vectors[0];
    for (i = 1; i < 200; i = i + 1) begin
      if (test_vectors[i] > ref_max[i-1])
        ref_max[i] = test_vectors[i];
      else
        ref_max[i] = ref_max[i-1];
    end

    // Apply reset condition
    in = 0;
    @(negedge clk);
    // Initialize DUT's max_val to 0
    force dut.max_val = 0;
    @(negedge clk);
    release dut.max_val;

    // Apply test vectors
    for (i = 0; i < 200; i = i + 1) begin
      in = test_vectors[i];
      @(negedge clk); // Apply input at negedge, sample output at posedge
      @(posedge clk);
      // Write to file: input output
      $fdisplay(fd, "%h %h", in, max_val);

      // Check output
      if (max_val !== ref_max[i]) begin
        $display("ASSERTION FAILED at vector %0d: in=%h, expected max_val=%h, got max_val=%h at time %0t", i, in, ref_max[i], max_val, $time);
        error_count = error_count + 1;
      end
    end

    // Close file
    $fclose(fd);

    // Report results
    if (error_count == 0)
      $display("All test cases passed.");
    else
      $display("Testbench completed with %0d errors.", error_count);

    $finish;
  end

endmodule

