        timeout_limit = 10000;
        wait ($time > timeout_limit);
        $display("ERROR: Simulation timeout at time %0t", $time);
        $finish;
    end

    // Generate test vectors (at least 100)
    initial begin
        // Use a mix of all possible values and some randoms
        for (i = 0; i < 4; i = i + 1) begin
            test_data[i] = i[1:0];
        end
        for (i = 4; i < 100; i = i + 1) begin
            test_data[i] = $random % 4;
        end
    end

    // Main test process
    initial begin
        fd = $fopen("test_vectors.txt", "w");
        if (fd) $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
