        error_count = 0;
        num_tests = 100;
        data = 2'b00;
        prev_data = 2'b00;
        data_reg = 2'b00;

        // Wait for a few cycles before starting
        repeat (2) @(posedge clk);

        for (i = 0; i < num_tests; i = i + 1) begin
            @(negedge clk);
            data = test_data[i];
            data_reg = data;
