                error_count = error_count + 1;
            end

            prev_data = data_reg;
        end

        // Final test for last input
        @(negedge clk);
        data = 2'b00;
        data_reg = data;
        @(posedge clk);
        expected_q = prev_data[1];
        $fdisplay(fd, "%b %b %b %b", prev_data[1], prev_data[0], 1'b1, q);
        if (q !== expected_q) begin
            $display("ERROR at final test: data=%b, expected_q=%b, got q=%b at time %0t", prev_data, expected_q, q, $time);
            error_count = error_count + 1;
        end

        $fclose(fd);

        if (error_count == 0)
