  reg [3:0] shift_val;
  reg [3:0] test_data;
  reg [3:0] test_q;
  reg [3:0] test_q_expected;
  reg [3:0] test_q_actual;
  reg [3:0] test_q_prev;
  reg [3:0] test_q_next;
  reg [7:0] vector_count;
  reg [31:0] sim_start_time;

  // Clock generation
  initial begin
    clk = 0;
    forever #5 clk = ~clk;
  end

  // Timeout mechanism
  initial begin
    sim_start_time = $time;
    #10000;
    $display("ERROR: Simulation timeout at time %0t ns", $time);
    $finish;
  end

  // Task to check output and report errors
  task check_output;
    input [3:0] expected;
    input [3:0] actual;
    input [31:0] vec_num;
    begin
      if (expected !== actual) begin
        $display("ASSERTION FAILED at vector %0d: expected q=%b, got q=%b at time %0t", vec_num, expected, actual, $time);
        error_count = error_count + 1;
      end
    end
  endtask

  // Main stimulus and test vector generation
  initial begin
    fd = $fopen("test_vectors.txt", "w");
    if (fd)
      $display("File opened successfully");
    else begin
      $display("Failed to open file");
      $finish;
    end

    error_count = 0;
    vector_count = 0;

    // Reset q to 0
    load = 1'b1;
    data = 4'b0000;
    @(negedge clk);
    @(posedge clk);
    #1;
    // Write initial vector
    $fdisplay(fd, "%b %b %b %b", clk, load, data, q);

    // Test all load operations with all possible data values
    for (i = 0; i < 16; i = i + 1) begin
      load = 1'b1;
      data = i[3:0];
      @(negedge clk);
      @(posedge clk);
      #1;
      expected_q = i[3:0];
      check_output(expected_q, q, vector_count);
      $fdisplay(fd, "%b %b %b %b", clk, load, data, q);
      vector_count = vector_count + 1;
    end

    // Test shifting after loading a value
    for (i = 0; i < 8; i = i + 1) begin
      // Load a value
      load = 1'b1;
      data = (i * 3 + 5) & 4'hF;
      @(negedge clk);
      @(posedge clk);
      #1;
      expected_q = data;
      check_output(expected_q, q, vector_count);
      $fdisplay(fd, "%b %b %b %b", clk, load, data, q);
      vector_count = vector_count + 1;

      // Now shift 4 times
      for (j = 0; j < 4; j = j + 1) begin
        load = 1'b0;
        data = 4'bxxxx; // don't care
        q_prev = q;
        @(negedge clk);
        @(posedge clk);
        #1;
        expected_q = {q_prev[2:0], 1'b0};
        check_output(expected_q, q, vector_count);
        $fdisplay(fd, "%b %b %b %b", clk, load, data, q);
        vector_count = vector_count + 1;
      end
    end

    // Test alternating load and shift
    for (i = 0; i < 5; i = i + 1) begin
      // Load
      load = 1'b1;
      data = (i * 7 + 2) & 4'hF;
      @(negedge clk);
      @(posedge clk);
      #1;
      expected_q = data;
      check_output(expected_q, q, vector_count);
      $fdisplay(fd, "%b %b %b %b", clk, load, data, q);
      vector_count = vector_count + 1;

      // Shift
      load = 1'b0;
      data = 4'bxxxx;
      q_prev = q;
      @(negedge clk);
      @(posedge clk);
      #1;
      expected_q = {q_prev[2:0], 1'b0};
      check_output(expected_q, q, vector_count);
      $fdisplay(fd, "%b %b %b %b", clk, load, data, q);
      vector_count = vector_count + 1;
    end

    // Test holding value (no load, no shift)
    load = 1'b1;
    data = 4'b1010;
    @(negedge clk);
    @(posedge clk);
    #1;
    expected_q = 4'b1010;
    check_output(expected_q, q, vector_count);
    $fdisplay(fd, "%b %b %b %b", clk, load, data, q);
    vector_count = vector_count + 1;

    load = 1'b0;
    data = 4'bxxxx;
    repeat (3) begin
      q_prev = q;
      @(negedge clk);
      @(posedge clk);
      #1;
      expected_q = {q_prev[2:0], 1'b0};
      check_output(expected_q, q, vector_count);
      $fdisplay(fd, "%b %b %b %b", clk, load, data, q);
      vector_count = vector_count + 1;
    end

    // Randomized test vectors
    for (i = 0; i < 60; i = i + 1) begin
      load = $random % 2;
      data = $random % 16;
      q_prev = q;
      @(negedge clk);
      @(posedge clk);
      #1;
      if (load)
        expected_q = data;
      else
        expected_q = {q_prev[2:0], 1'b0};
      check_output(expected_q, q, vector_count);
      $fdisplay(fd, "%b %b %b %b", clk, load, data, q);
      vector_count = vector_count + 1;
    end

    $display("Testbench completed with %0d errors after %0d vectors.", error_count, vector_count);
    $fclose(fd);
    $finish;
  end

