module shift_register_tb;

    // Inputs
    reg clk;
    reg rst;
    reg load;
    reg [15:0] data_in;
    reg shift;
    reg enable;

    // Outputs
    wire [15:0] data_out;

    // Instantiate the Unit Under Test (UUT)
    shift_register uut (
        .clk(clk),
        .rst(rst),
        .load(load),
        .data_in(data_in),
        .shift(shift),
        .enable(enable),
        .data_out(data_out)
    );

    // File descriptor for test vector output
    integer fd;
    integer error_count;
    integer test_count;
    integer i;
    reg [15:0] expected_data;
    reg [15:0] golden_data;
    reg [15:0] test_vectors [0:99];
    reg [15:0] prev_data_out;

    // Clock generation
    initial begin
        clk = 0;
        forever #5 clk = ~clk; // 100MHz clock
    end

    // Timeout mechanism
    initial begin
        #10000;
        $display("ERROR: Simulation timed out at time %0t", $time);
        $finish;
    end

    // Error checking task
    task check_output;
        input [15:0] expected;
        input [15:0] actual;
        input [255:0] msg;
        begin
            if (expected !== actual) begin
                $display("ASSERTION FAILED at time %0t: %s Expected: %h, Got: %h", $time, msg, expected, actual);
                error_count = error_count + 1;
            end
        end
    endtask

    // Main stimulus
    initial begin
        fd = $fopen("test_vectors.txt", "w");
        if (fd) $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        error_count = 0;
        test_count = 0;

        // Initialize inputs
        rst = 0;
        load = 0;
        data_in = 16'h0000;
        shift = 0;
        enable = 0;
        expected_data = 16'h0000;
        prev_data_out = 16'h0000;

        // Apply reset
        @(negedge clk);
        rst = 1;
        @(negedge clk);
        rst = 0;
        @(negedge clk);

        // Test 1: Reset
        $fdisplay(fd, "%b %b %b %b %b %b %b", clk, rst, load, data_in, shift, enable, data_out);
        check_output(16'h0000, data_out, "Reset Test");

        // Test 2: Load various data patterns
        for (i = 0; i < 10; i = i + 1) begin
            data_in = 16'h1 << i;
            load = 1;
            @(negedge clk);
            load = 0;
            @(negedge clk);
            expected_data = data_in;
            $fdisplay(fd, "%b %b %b %b %b %b %b", clk, rst, load, data_in, shift, enable, data_out);
            check_output(expected_data, data_out, "Load Test");
            test_count = test_count + 1;
        end

        // Test 3: Shift right with enable
        data_in = 16'hA5A5;
        load = 1;
        @(negedge clk);
        load = 0;
        @(negedge clk);
        expected_data = data_in;
        for (i = 0; i < 10; i = i + 1) begin
            shift = 1;
            enable = 1;
            @(negedge clk);
            expected_data = {expected_data[0], expected_data[15:1]};
            $fdisplay(fd, "%b %b %b %b %b %b %b", clk, rst, load, data_in, shift, enable, data_out);
            check_output(expected_data, data_out, "Shift Test");
            test_count = test_count + 1;
        end
        shift = 0;
        enable = 0;

        // Test 4: Shift with enable low (should not shift)
        data_in = 16'hF0F0;
        load = 1;
        @(negedge clk);
        load = 0;
        @(negedge clk);
        expected_data = data_in;
        shift = 1;
        enable = 0;
        @(negedge clk);
        $fdisplay(fd, "%b %b %b %b %b %b %b", clk, rst, load, data_in, shift, enable, data_out);
        check_output(expected_data, data_out, "No Shift When Enable Low");
        test_count = test_count + 1;
        shift = 0;

        // Test 5: Shift with shift low (should not shift)
        data_in = 16'h0F0F;
        load = 1;
        @(negedge clk);
        load = 0;
        @(negedge clk);
        expected_data = data_in;
        shift = 0;
        enable = 1;
        @(negedge clk);
        $fdisplay(fd, "%b %b %b %b %b %b %b", clk, rst, load, data_in, shift, enable, data_out);
        check_output(expected_data, data_out, "No Shift When Shift Low");
        test_count = test_count + 1;
        enable = 0;

        // Test 6: Load while shifting (load has priority)
        data_in = 16'hAAAA;
        load = 1;
        shift = 1;
        enable = 1;
        @(negedge clk);
        load = 0;
        shift = 0;
        enable = 0;
        expected_data = 16'hAAAA;
        $fdisplay(fd, "%b %b %b %b %b %b %b", clk, rst, load, data_in, shift, enable, data_out);
        check_output(expected_data, data_out, "Load Priority Over Shift");
        test_count = test_count + 1;

        // Test 7: Reset during operation
        data_in = 16'h5555;
        load = 1;
        @(negedge clk);
        load = 0;
        @(negedge clk);
        rst = 1;
        @(negedge clk);
        rst = 0;
        expected_data = 16'h0000;
        $fdisplay(fd, "%b %b %b %b %b %b %b", clk, rst, load, data_in, shift, enable, data_out);
        check_output(expected_data, data_out, "Reset During Operation");
        test_count = test_count + 1;

        // Test 8: Randomized test vectors
        for (i = 0; i < 70; i = i + 1) begin
            // Randomize inputs
            rst = $random % 2;
            load = $random % 2;
            data_in = $random;
            shift = $random % 2;
            enable = $random % 2;

            // Save previous data_out for golden model
            prev_data_out = data_out;

            @(negedge clk);

            // Golden model
            if (rst) golden_data = 16'h0000;
            else if (load) golden_data = data_in;
            else if (enable && shift) golden_data = {prev_data_out[0], prev_data_out[15:1]};
            else golden_data = prev_data_out;

            $fdisplay(fd, "%b %b %b %b %b %b %b", clk, rst, load, data_in, shift, enable, data_out);
            check_output(golden_data, data_out, "Randomized Test");
            test_count = test_count + 1;
        end

        // Finish up
        $display("Total tests run: %0d", test_count);
        if (error_count == 0)
            $display("All tests passed!");
        else
            $display("Total errors: %0d", error_count);

        $fclose(fd);
        $finish;
    end

endmodule

