module magnitude_comparator #(
    parameter n = 8  // Default bit-width is 8
)(
    input  wire [n-1:0] num1,
    input  wire [n-1:0] num2,
    output reg  gt,    // num1 > num2
    output reg  eq,    // num1 == num2
    output reg  lt     // num1 < num2
);

integer i;
reg found;

// Combinational logic for magnitude comparison
always @* begin
    gt = 0;
    eq = 0;
    lt = 0;
    found = 0;
    for (i = n-1; i >= 0; i = i - 1) begin
        if (!found) begin
            if (num1[i] > num2[i]) begin
                gt = 1;
                found = 1;
            end else if (num1[i] < num2[i]) begin
                lt = 1;
                found = 1;
            end
        end
    end
    if (!found) begin
        eq = 1;
    end
end

endmodule

