module shift_register_tb;

    // Inputs
    reg clk;
    reg load;
    reg [3:0] in;

    // Outputs
    wire [3:0] out;

    // Internal variables
    integer fd;
    integer i, j, k, test_count, error_count;
    reg [3:0] expected_out;
    reg [3:0] reg_model;
    reg [3:0] in_vec [0:15];
    reg load_vec [0:1];
    reg [127:0] testname;

    // Instantiate the Unit Under Test (UUT)
    shift_register uut (
        .clk(clk),
        .load(load),
        .in(in),
        .out(out)
    );

    // Clock generation
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    // Timeout mechanism
    initial begin
        #10000;
        $display("ERROR: Simulation timeout at time %0t", $time);
        $finish;
    end

    // Error checking task
    task check_output;
        input [3:0] expected;
        input [3:0] actual;
        input [127:0] tname;
        begin
            if (expected !== actual) begin
                $display("ASSERTION FAILED at time %0t: %s Expected: %b, Got: %b", $time, tname, expected, actual);
                error_count = error_count + 1;
            end
        end
    endtask

    // Main stimulus
    initial begin
        // Initialize
        error_count = 0;
        test_count = 0;

        // Open file for writing test vectors
        fd = $fopen("test_vectors.txt", "w");
        if (fd) $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        // Write header (optional, can be commented out)
        // $fdisplay(fd, "clk load in[3:0] out[3:0]");

        // Initialize model
        reg_model = 4'b0000;

        // Preload test vectors
        for (i = 0; i < 16; i = i + 1) begin
            in_vec[i] = i[3:0];
        end
        load_vec[0] = 1'b0;
        load_vec[1] = 1'b1;

        // Reset sequence (not in DUT, but for model consistency)
        load = 0;
        in = 4'b0000;
        @(negedge clk);

        // Test 1: Load all possible values, then shift each for a few cycles
        for (i = 0; i < 16; i = i + 1) begin
            // Apply load
            load = 1;
            in = in_vec[i];
            @(negedge clk);
            // Model
            reg_model = in_vec[i];
            // Write vector
            $fdisplay(fd, "%b %b %b %b", clk, load, in, out);
            testname = {"Load value ", i[3:0]};
            check_output(reg_model, out, testname);
            test_count = test_count + 1;

            // Shift for 4 cycles
            load = 0;
            for (j = 0; j < 4; j = j + 1) begin
                @(negedge clk);
                reg_model = {reg_model[2:0], 1'b0};
                $fdisplay(fd, "%b %b %b %b", clk, load, in, out);
                testname = {"Shift after load ", i[3:0], " cycle ", j[1:0]};
                check_output(reg_model, out, testname);
                test_count = test_count + 1;
            end
        end

        // Test 2: Randomized load/shift sequence
        for (k = 0; k < 50; k = k + 1) begin
            load = $random % 2;
            in = $random % 16;
            @(negedge clk);
            if (load) begin
                reg_model = in;
                testname = {"Random load ", k[7:0]};
            end else begin
                reg_model = {reg_model[2:0], 1'b0};
                testname = {"Random shift ", k[7:0]};
            end
            $fdisplay(fd, "%b %b %b %b", clk, load, in, out);
            check_output(reg_model, out, testname);
            test_count = test_count + 1;
        end

        // Test 3: All zeros, all ones
        load = 1;
        in = 4'b0000;
        @(negedge clk);
        reg_model = 4'b0000;
        $fdisplay(fd, "%b %b %b %b", clk, load, in, out);
        check_output(reg_model, out, "All zeros load");
        test_count = test_count + 1;

        load = 1;
        in = 4'b1111;
        @(negedge clk);
        reg_model = 4'b1111;
        $fdisplay(fd, "%b %b %b %b", clk, load, in, out);
        check_output(reg_model, out, "All ones load");
        test_count = test_count + 1;

        // Shift all ones to zero
        load = 0;
        for (j = 0; j < 5; j = j + 1) begin
            @(negedge clk);
            reg_model = {reg_model[2:0], 1'b0};
            $fdisplay(fd, "%b %b %b %b", clk, load, in, out);
            testname = {"All ones shift ", j[2:0]};
            check_output(reg_model, out, testname);
            test_count = test_count + 1;
        end

        // Close file
        $fclose(fd);

        // Report results
        $display("Testbench completed. Total tests: %0d, Errors: %0d", test_count, error_count);

        $finish;
    end

endmodule

