module arithmetic_module (
    input  wire [7:0] A,
    input  wire [7:0] B,
    input  wire       operation,
    input  wire       reset,
    output reg  [7:0] C
);

    // Integer variable for computation (unnamed block)
    integer result;

    always @(*) begin
        if (reset) begin
            C = 8'd0;
        end else begin
            // Anonymous begin-end block for variable declaration
            begin
                result = 0;
                if (operation == 1'b0) begin
                    result = A + B;
