        2'b10: expected_out = a ^ b;
        2'b11: expected_out = ~(a & b);
        default: expected_out = 4'b0000;
      endcase
      $fdisplay(fd, "%b %b %b %b", a, b, ctrl, out);
      check_output(a, b, ctrl, out, expected_out);
    end

    // Now, generate 84 more random test vectors (for a total of 100)
    for (i = 0; i < 84; i = i + 1) begin
      a = $random % 16;
      b = $random % 16;
      ctrl = $random % 4;
      #1;
      case (ctrl)
        2'b00: expected_out = a & b;
        2'b01: expected_out = a | b;
        2'b10: expected_out = a ^ b;
        2'b11: expected_out = ~(a & b);
        default: expected_out = 4'b0000;
      endcase
      $fdisplay(fd, "%b %b %b %b", a, b, ctrl, out);
      check_output(a, b, ctrl, out, expected_out);

      if (timeout) begin
        $display("TIMEOUT at time %0t", $time);
        $fclose(fd);
        $finish;
      end
    end

    $display("Testing complete. Total errors: %0d", error_count);
    $fclose(fd);
    $finish;
  end

  // Timeout monitor
  always @(posedge timeout) begin
    $display("Simulation timed out at time %0t", $time);
    $fclose(fd);
    $finish;
  end

endmodule

