module dff_async_reset_enable_tb;

    // Inputs
    reg CLK;
    reg D;
    reg RESET;
    reg EN;

    // Outputs
    wire Q;
    wire Q_N;

    // File descriptor
    integer fd;
    integer error_count;
    integer test_count;
    integer i;

    // For timeout
    reg timeout_flag;

    // Instantiate the DUT
    dff_async_reset_enable dut (
        .CLK(CLK),
        .D(D),
        .RESET(RESET),
        .EN(EN),
        .Q(Q),
        .Q_N(Q_N)
    );

    // Clock generation: 10ns period
    initial begin
        CLK = 0;
        forever #5 CLK = ~CLK;
    end

    // Timeout mechanism
    initial begin
        timeout_flag = 0;
        #10000;
        timeout_flag = 1;
        $display("ERROR: Simulation timeout at time %0t ns", $time);
        $finish;
    end

    // Task to check outputs and report errors
    task check_output;
        input expected_Q;
        input expected_Q_N;
        begin
            if ((Q !== expected_Q) || (Q_N !== expected_Q_N)) begin
                $display("ASSERTION FAILED at time %0t: D=%b RESET=%b EN=%b | Q=%b (exp %b) Q_N=%b (exp %b)", $time, D, RESET, EN, Q, expected_Q, Q_N, expected_Q_N);
                error_count = error_count + 1;
            end
        end
    endtask

    // Main stimulus
    initial begin
        // Open file for writing test vectors
        fd = $fopen("test_vectors.txt", "w");
        if (fd) $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        error_count = 0;
        test_count = 0;

        // Write header (optional, comment out if not needed)
        // $fdisplay(fd, "CLK D RESET EN Q Q_N");

        // Initialize inputs
        D = 0;
        RESET = 1;
        EN = 1;

        // Apply asynchronous reset (active-low)
        @(negedge CLK);
        RESET = 0;
        EN = 1;
        D = 1;
        @(negedge CLK);
        // Check after async reset
        #1;
        check_output(1'b0, 1'b1);
        $fdisplay(fd, "%b %b %b %b %b %b", CLK, D, RESET, EN, Q, Q_N);
        test_count = test_count + 1;

        // Release reset
        RESET = 1;
        @(negedge CLK);

        // Test all input combinations for 2 cycles each
        for (i = 0; i < 100; i = i + 1) begin
            // Randomize inputs
            D = $random % 2;
            EN = $random % 2;
            // Occasionally assert async reset
            if ((i % 17) == 0) RESET = 0;
            else RESET = 1;

            @(negedge CLK);
            #1;

            // Expected behavior
            if (!RESET) begin
                check_output(1'b0, 1'b1);
            end else if (!EN) begin
                // Hold previous state, so no check (can't predict)
            end else begin
                check_output(D, ~D);
            end

            $fdisplay(fd, "%b %b %b %b %b %b", CLK, D, RESET, EN, Q, Q_N);
            test_count = test_count + 1;

            // Release reset after one cycle if it was asserted
            if (!RESET) begin
                RESET = 1;
                @(negedge CLK);
                #1;
                // After reset release, output should remain at reset value until EN allows update
                $fdisplay(fd, "%b %b %b %b %b %b", CLK, D, RESET, EN, Q, Q_N);
                test_count = test_count + 1;
            end
        end

        // Additional edge cases
        // EN=0 (hold), D toggling
        RESET = 1;
        EN = 0;
        D = 0;
        @(negedge CLK);
        #1;
        $fdisplay(fd, "%b %b %b %b %b %b", CLK, D, RESET, EN, Q, Q_N);
        test_count = test_count + 1;
        D = 1;
        @(negedge CLK);
        #1;
        $fdisplay(fd, "%b %b %b %b %b %b", CLK, D, RESET, EN, Q, Q_N);
        test_count = test_count + 1;

        // EN=1, D=1, then EN=0, D=0
        EN = 1;
        D = 1;
        @(negedge CLK);
        #1;
        check_output(1'b1, 1'b0);
        $fdisplay(fd, "%b %b %b %b %b %b", CLK, D, RESET, EN, Q, Q_N);
        test_count = test_count + 1;
        EN = 0;
        D = 0;
        @(negedge CLK);
        #1;
        // Should hold previous state
        $fdisplay(fd, "%b %b %b %b %b %b", CLK, D, RESET, EN, Q, Q_N);
        test_count = test_count + 1;

        // Final summary
        $display("Test completed: %0d vectors, %0d errors", test_count, error_count);

        $fclose(fd);

        // End simulation if not timed out
        if (!timeout_flag) $finish;
    end

endmodule

