```

reference_solution:
module adder_4bit (A, B, Cin, S, Cout);
input [3:0] A, B;
input Cin;
output [3:0] S;
output Cout;

wire [3:0] C;

full_adder fa0(A[0], B[0], Cin, S[0], C[0]);
full_adder fa1(A[1], B[1], C[0], S[1], C[1]);
full_adder fa2(A[2], B[2], C[1], S[2], C[2]);
full_adder fa3(A[3], B[3], C[2], S[3], Cout);

endmodule

module full_adder (A, B, Cin, S, Cout);
input A, B, Cin;
output S, Cout;

wire w1, w2;

xor (w1, A, B);
xor (S, w1, Cin);
and (w2, A, B);
or (Cout, w2, w1&Cin);

endmodule

