    enable = 0;
    load = 0;
    data_in = 4'b0000;
    @(negedge clk);
    reset = 0;
    enable = 1;
    for (i = 0; i < 20; i = i + 1) begin
      load = 0;
      @(negedge clk);
      check_and_log();
    end

    // Test 4: Enable=0, should hold value
    enable = 0;
    load = 0;
    data_in = 4'b1010;
    @(negedge clk);
    check_and_log();
    @(negedge clk);
    check_and_log();

    // Test 5: Load while enable=0 (should not load)
    load = 1;
    data_in = 4'b1111;
    @(negedge clk);
    check_and_log();
    load = 0;
    @(negedge clk);
    check_and_log();

    // Test 6: Randomized test vectors
    for (i = 0; i < 50; i = i + 1) begin
      reset = $random % 2;
      enable = $random % 2;
      load = $random % 2;
      data_in = $random % 16;
      @(negedge clk);
      check_and_log();
    end

    // Test 7: Multiple resets during operation
    enable = 1;
    load = 0;
    for (i = 0; i < 5; i = i + 1) begin
      @(negedge clk);
      check_and_log();
    end
    reset = 1;
    @(negedge clk);
    check_and_log();
    reset = 0;
    for (i = 0; i < 5; i = i + 1) begin
      @(negedge clk);
      check_and_log();
    end

    // Finish up
    $display("Testbench completed: %0d tests, %0d errors.", test_count, error_count);
    $fclose(fd);
    $finish;
  end

  // Timeout mechanism
  initial begin
    #TIMEOUT;
    $display("ERROR: Simulation timed out at time %0t", $time);
    $fclose(fd);
    $finish;
  end

  // Task to check and log results
  task check_and_log;
    reg [3:0] exp_count;
    begin
      // Compute expected count
      if (reset) begin
        exp_count = 4'b0000;
      end else if (enable) begin
        if (load) begin
          exp_count = data_in;
        end else begin
          exp_count = prev_count + 1;
        end
      end else begin
        exp_count = prev_count;
      end

      // Log test vector and result
      $fdisplay(fd, "%b %b %b %b %b%b%b%b | %b%b%b%b",
        clk, reset, enable, load,
        data_in[3], data_in[2], data_in[1], data_in[0],
        count[3], count[2], count[1], count[0]
      );

      // Assertion
      if (count !== exp_count) begin
        $display("ERROR at time %0t: Inputs: clk=%b reset=%b enable=%b load=%b data_in=%b | Expected count=%b, Got count=%b",
          $time, clk, reset, enable, load, data_in, exp_count, count);
        error_count = error_count + 1;
      end

      prev_count = count;
      test_count = test_count + 1;
    end
  endtask

  // Initialize prev_count
  initial begin
    prev_count = 4'b0000;
  end

endmodule

