module debounce(
    input clk,
    input PB,
    output reg PB_state
);

reg init_state = 1'b0;
reg [11:0] PB_cnt = 12'd0;
wire PB_cnt_max = &PB_cnt;
wire PB_idle = (PB_cnt == 12'd0);
wire PB_changed = (PB != init_state);

always @(posedge clk)
if(PB_idle & PB_changed)
begin
    init_state = PB;
    PB_cnt = 12'd1;
end
else if(PB_cnt_max)
begin
    PB_state = init_state;
    PB_cnt = 12'd0;
end
else if(~PB_idle)
    PB_cnt = PB_cnt + 12'd1;

endmodule

module_interface:
module debounce(
    input clk,
    input PB,
    output reg PB_state
);

test:
`timescale 1ns/1ps

module debounce_tb;

    // Inputs
    reg clk;
    reg PB;

    // Outputs
    wire PB_state;

    // Instantiate the debounce module
    debounce uut (
        .clk(clk),
        .PB(PB),
        .PB_state(PB_state)
    );

    // File descriptor for test vector output
    integer fd;
    integer error_count;
    integer vector_count;
    integer i;
    reg expected_PB_state;
    reg [11:0] debounce_cnt;
    reg last_PB;
    reg [31:0] timeout_cycles;

    // Clock generation
    initial begin
        clk = 0;
        forever #5 clk = ~clk; // 100MHz clock
    end

    // Timeout mechanism
    initial begin
        timeout_cycles = 0;
        forever begin
            #10;
            timeout_cycles = timeout_cycles + 1;
            if (timeout_cycles > 10000) begin
                $display("ERROR: Simulation timeout at time %0t", $time);
                $finish;
            end
        end
    end

    // Main test process
    initial begin
        fd = $fopen("test_vectors.txt", "w");
        if (fd)
            $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        error_count = 0;
        vector_count = 0;

        // Initialize
        PB = 0;
        expected_PB_state = 0;
        debounce_cnt = 0;
        last_PB = 0;

        // Wait for reset
        #20;

        // Test 1: No press, PB stays low
        repeat (10) begin
            @(negedge clk);
            PB = 0;
            update_expected(0);
            write_vector();
        end

        // Test 2: Single clean press (PB goes high and stays high)
        PB = 1;
        repeat (15) begin
            @(negedge clk);
            update_expected(1);
            write_vector();
        end

        // Test 3: Release (PB goes low and stays low)
        PB = 0;
        repeat (15) begin
            @(negedge clk);
            update_expected(0);
            write_vector();
        end

        // Test 4: Bouncing press (simulate bouncing on press)
        for (i = 0; i < 10; i = i + 1) begin
            PB = (i % 2 == 0) ? 1 : 0;
            @(negedge clk);
            update_expected(PB);
            write_vector();
        end
        // Now stable high
        PB = 1;
        repeat (15) begin
            @(negedge clk);
            update_expected(1);
            write_vector();
        end

        // Test 5: Bouncing release (simulate bouncing on release)
        for (i = 0; i < 10; i = i + 1) begin
            PB = (i % 2 == 0) ? 0 : 1;
            @(negedge clk);
            update_expected(PB);
            write_vector();
        end
        // Now stable low
        PB = 0;
        repeat (15) begin
            @(negedge clk);
            update_expected(0);
            write_vector();
        end

        // Test 6: Rapid toggling (should not register as valid presses)
        for (i = 0; i < 20; i = i + 1) begin
            PB = ~PB;
            @(negedge clk);
            update_expected(PB);
            write_vector();
        end

        // Test 7: Long press
        PB = 1;
        repeat (30) begin
            @(negedge clk);
            update_expected(1);
            write_vector();
        end

        // Test 8: Long release
        PB = 0;
        repeat (30) begin
            @(negedge clk);
            update_expected(0);
            write_vector();
        end

        // Test 9: Random pattern
        for (i = 0; i < 20; i = i + 1) begin
            PB = $random % 2;
            @(negedge clk);
            update_expected(PB);
            write_vector();
        end

        $display("Testbench completed with %0d vectors and %0d errors.", vector_count, error_count);
        $fclose(fd);
        $finish;
    end

    // Task: Update expected PB_state based on debounce logic
    task update_expected(input reg PB_in);
        begin
            if ((debounce_cnt == 0) && (PB_in != last_PB)) begin
                last_PB = PB_in;
                debounce_cnt = 1;
            end else if (debounce_cnt == 12'hFFF) begin
                expected_PB_state = last_PB;
                debounce_cnt = 0;
            end else if (debounce_cnt != 0) begin
                debounce_cnt = debounce_cnt + 1;
            end
        end
    endtask

    // Task: Write vector and check result
    task write_vector;
        begin
            $fdisplay(fd, "%b %b %b", clk, PB, PB_state);
