module SUB_tb;

    // Inputs
    reg [15:0] a;
    reg [15:0] b;

    // Outputs
    wire [15:0] sub;
    wire carry;
    wire overflow;

    // File descriptor
    integer fd;
    integer i, j, test_count, error_count;
    reg [15:0] expected_sub;
    reg expected_carry;
    reg expected_overflow;

    // Timeout mechanism
    reg timeout_flag;
    initial begin
        timeout_flag = 0;
        #100000;
        timeout_flag = 1;
        $display("TIMEOUT: Simulation exceeded allowed time.");
        $finish;
    end

    // Instantiate the Unit Under Test (UUT)
    SUB uut (
        .a(a), 
        .b(b), 
        .sub(sub), 
        .carry(carry), 
        .overflow(overflow)
    );

    // Task to compute expected outputs
    task calc_expected;
        input [15:0] ta, tb;
        output [15:0] tsub;
        output tcarry;
        output toverflow;
        reg [16:0] diff;
        begin
            diff = {1'b0, ta} - {1'b0, tb};
            tcarry = (ta < tb) ? 1'b1 : 1'b0;
            tsub = ta - tb;
            if (ta < tb)
                tsub = tsub + 16'h10000;
            // Overflow for signed subtraction
            toverflow = ((tsub[15] != ta[15]) && (tsub[15] != tb[15])) ? 1'b1 : 1'b0;
        end
    endtask

    // Task to check outputs and report errors
    task check_outputs;
        input [15:0] ta, tb, tsub;
        input tcarry, toverflow;
        begin
            if ((sub !== tsub) || (carry !== tcarry) || (overflow !== toverflow)) begin
                $display("ERROR: a=%h b=%h | sub=%h (exp %h) carry=%b (exp %b) overflow=%b (exp %b) at time %0t", 
                    ta, tb, sub, tsub, carry, tcarry, overflow, toverflow, $time);
                error_count = error_count + 1;
            end
        end
    endtask

    // Main test process
    initial begin
        fd = $fopen("test_vectors.txt", "w");
        if (fd)
            $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        test_count = 0;
        error_count = 0;

        // Test some corner cases explicitly
        a = 16'h0000; b = 16'h0000; #1;
        calc_expected(a, b, expected_sub, expected_carry, expected_overflow);
        $fdisplay(fd, "%h %h %h %b %b", a, b, sub, carry, overflow);
        check_outputs(a, b, expected_sub, expected_carry, expected_overflow);
        test_count = test_count + 1;

        a = 16'hFFFF; b = 16'h0000; #1;
        calc_expected(a, b, expected_sub, expected_carry, expected_overflow);
        $fdisplay(fd, "%h %h %h %b %b", a, b, sub, carry, overflow);
        check_outputs(a, b, expected_sub, expected_carry, expected_overflow);
        test_count = test_count + 1;

        a = 16'h0000; b = 16'hFFFF; #1;
        calc_expected(a, b, expected_sub, expected_carry, expected_overflow);
        $fdisplay(fd, "%h %h %h %b %b", a, b, sub, carry, overflow);
        check_outputs(a, b, expected_sub, expected_carry, expected_overflow);
        test_count = test_count + 1;

        a = 16'h8000; b = 16'h0001; #1;
        calc_expected(a, b, expected_sub, expected_carry, expected_overflow);
        $fdisplay(fd, "%h %h %h %b %b", a, b, sub, carry, overflow);
        check_outputs(a, b, expected_sub, expected_carry, expected_overflow);
        test_count = test_count + 1;

        a = 16'h7FFF; b = 16'h8000; #1;
        calc_expected(a, b, expected_sub, expected_carry, expected_overflow);
        $fdisplay(fd, "%h %h %h %b %b", a, b, sub, carry, overflow);
        check_outputs(a, b, expected_sub, expected_carry, expected_overflow);
        test_count = test_count + 1;

        a = 16'h8000; b = 16'h7FFF; #1;
        calc_expected(a, b, expected_sub, expected_carry, expected_overflow);
        $fdisplay(fd, "%h %h %h %b %b", a, b, sub, carry, overflow);
        check_outputs(a, b, expected_sub, expected_carry, expected_overflow);
        test_count = test_count + 1;

        // Systematic test for lower 8 bits (for full coverage of small values)
        for (i = 0; i < 16; i = i + 1) begin
            for (j = 0; j < 16; j = j + 1) begin
                a = i; b = j; #1;
