        rst = 1; en = 0;
        @(negedge clk);
        expected_count = 0;
        $fdisplay(fd, "%b %b %b %b", clk, rst, en, count);
        check_output(expected_count);

        // Release reset
        rst = 0;
        @(negedge clk);
        $fdisplay(fd, "%b %b %b %b", clk, rst, en, count);
        check_output(expected_count);

        // Test: Enable counting for 20 cycles
        en = 1;
        for (i = 0; i < 20; i = i + 1) begin
            @(negedge clk);
            if (rst)
                expected_count = 0;
            else if (en)
                expected_count = expected_count + 1;
            $fdisplay(fd, "%b %b %b %b", clk, rst, en, count);
            check_output(expected_count);
        end

        // Test: Disable enable for 10 cycles (count should hold)
        en = 0;
        for (i = 0; i < 10; i = i + 1) begin
            @(negedge clk);
            // expected_count stays the same
            $fdisplay(fd, "%b %b %b %b", clk, rst, en, count);
            check_output(expected_count);
        end

        // Test: Assert reset in the middle
