        // Test: Toggle enable every cycle for 20 cycles
        for (i = 0; i < 20; i = i + 1) begin
            en = ~en;
            @(negedge clk);
            if (rst)
                expected_count = 0;
            else if (en)
                expected_count = expected_count + 1;
            $fdisplay(fd, "%b %b %b %b", clk, rst, en, count);
            check_output(expected_count);
        end

        // Test: Multiple resets
        for (i = 0; i < 5; i = i + 1) begin
            rst = 1;
            @(negedge clk);
            expected_count = 0;
            $fdisplay(fd, "%b %b %b %b", clk, rst, en, count);
