module mux_2to1 (
    input A,         // Input signal A
    input B,         // Input signal B
    input SEL,       // Select signal
    output Y         // Output signal Y
);

    // Define internal net for the output
    wire Y_wire;

    // Voltage supply signals for enhanced simulation readability
    supply1 VDD;     // Logic High (1)
    supply0 VSS;     // Logic Low (0)

    // Internal register for output in always block
    reg Y_reg;

    // Combinational logic using always block and if-else statement
    always @(*) begin
        if (SEL == 1'b0) begin
            Y_reg = A;    // If SEL is 0, output A
        end else begin
            Y_reg = B;    // If SEL is 1, output B
        end
    end

    // Continuous assignment of register to output wire
    assign Y_wire = Y_reg;

    // Assign internal wire to output port
    assign Y = Y_wire;

endmodule

