                $display("ASSERTION FAILED at vector %0d, time %0t: expected %0d, got %0d", vec_num, $time, expected, actual);
                error_count = error_count + 1;
            end
        end
    endtask

    // Main test process
    initial begin
        fd = $fopen("test_vectors.txt", "w");
        if (fd) $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        error_count = 0;
        reset = 1;
        expected_count = 0;
        prev_count = 0;

        // Apply reset
        @(negedge clk);
        $fdisplay(fd, "%b %b %b", clk, reset, count);
        @(negedge clk);
        reset = 0;
        $fdisplay(fd, "%b %b %b", clk, reset, count);

        // Test 1: After reset, counter should be zero
        check_output(0, count, 1);

        // Test 2: Count up for 100 cycles, no reset
        for (i = 0; i < 100; i = i + 1) begin
            @(negedge clk);
            $fdisplay(fd, "%b %b %b", clk, reset, count);
            if (i == 0)
                expected_count = 1;
            else
                expected_count = prev_count + 1;
            if (prev_count == 8'd255)
                expected_count = 0;
            check_output(expected_count, count, i+2);
            prev_count = count;
        end

        // Test 3: Assert reset in the middle of counting
        @(negedge clk);
        reset = 1;
        $fdisplay(fd, "%b %b %b", clk, reset, count);
        @(negedge clk);
        reset = 0;
        $fdisplay(fd, "%b %b %b", clk, reset, count);
        // After reset, count should be 0
        check_output(0, count, 102);

        // Test 4: Count up to 255 and check wrap-around
        for (i = 0; i < 260; i = i + 1) begin
            @(negedge clk);
            $fdisplay(fd, "%b %b %b", clk, reset, count);
            if (i == 0)
                expected_count = 1;
            else
                expected_count = prev_count + 1;
            if (prev_count == 8'd255)
                expected_count = 0;
            check_output(expected_count, count, i+104);
            prev_count = count;
        end

        // Test 5: Multiple resets
        for (i = 0; i < 5; i = i + 1) begin
            @(negedge clk);
            reset = 1;
            $fdisplay(fd, "%b %b %b", clk, reset, count);
            @(negedge clk);
            reset = 0;
            $fdisplay(fd, "%b %b %b", clk, reset, count);
            check_output(0, count, 365 + i*2);
            prev_count = count;
            @(negedge clk);
            $fdisplay(fd, "%b %b %b", clk, reset, count);
            expected_count = prev_count + 1;
            check_output(expected_count, count, 366 + i*2);
            prev_count = count;
        end

        $display("Testbench completed with %0d error(s).", error_count);
        $fclose(fd);
        $finish;
    end

