        @(negedge clk);
        d = 0;
        load = 1;
        @(posedge clk);
        #1;
        check_and_log();

        // Test 3: load=0, d=1 (should hold previous q)
        @(negedge clk);
        d = 1;
        load = 0;
        @(posedge clk);
        #1;
        check_and_log();

        // Test 4: load=1, d=1
        @(negedge clk);
        d = 1;
        load = 1;
        @(posedge clk);
        #1;
        check_and_log();

        // Test 5: load=0, d=0 (should hold previous q)
        @(negedge clk);
        d = 0;
        load = 0;
        @(posedge clk);
        #1;
        check_and_log();

        // Test 6: Assert reset in the middle
        @(negedge clk);
        reset = 1;
        @(posedge clk);
        #1;
        check_and_log();

        // Deassert reset, load=0, d=1
        @(negedge clk);
        reset = 0;
        d = 1;
        load = 0;
        @(posedge clk);
        #1;
        check_and_log();

        // Test 7: load=1, d=0
        @(negedge clk);
        d = 0;
        load = 1;
        @(posedge clk);
        #1;
        check_and_log();

        // Test 8: load=1, d=1
        @(negedge clk);
        d = 1;
        load = 1;
        @(posedge clk);
        #1;
        check_and_log();

        // Test 9: load=0, d=0
        @(negedge clk);
        d = 0;
        load = 0;
        @(posedge clk);
        #1;
        check_and_log();

        // Test 10: Multiple resets
        repeat (3) begin
            @(negedge clk);
            reset = 1;
            @(posedge clk);
            #1;
            check_and_log();
            @(negedge clk);
            reset = 0;
            d = $random % 2;
            load = $random % 2;
            @(posedge clk);
            #1;
            check_and_log();
        end

        // Exhaustive test for all input combinations over 2 cycles
        for (i = 0; i < 32; i = i + 1) begin
            @(negedge clk);
            d     = i[0];
            load  = i[1];
            reset = i[2];
            // Randomize previous state by toggling q
            if (i[3]) begin
                // Set q to 1 by loading d=1, load=1, reset=0
                d = 1; load = 1; reset = 0;
                @(posedge clk); #1; check_and_log();
            end
            // Now apply current test vector
            d     = i[0];
            load  = i[1];
            reset = i[2];
            @(posedge clk);
            #1;
            check_and_log();
        end

