    zigbee_transmitter dut (
        .clk(clk),
        .rst(rst),
        .data_in(data_in),
        .data_out(data_out)
    );

    // Clock generation: 10ns period
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    // Error checking task
    task check_output;
        input reg expected;
        begin
            if (data_out !== expected) begin
                $display("ERROR at time %0t: rst=%b data_in=%b => data_out=%b (expected %b)", $time, rst, data_in, data_out, expected);
                error_count = error_count + 1;
            end
            // Assertion (SystemVerilog style for simulation, or use if-statement for Verilog-2001)
            if (data_out !== expected) begin
                $display("ASSERTION FAILED at time %0t: rst=%b data_in=%b => data_out=%b (expected %b)", $time, rst, data_in, data_out, expected);
