// Schmitt Trigger Module
// Compatible with iverilog

module schmitt_trigger #(
    parameter real vth = 2.5,   // High threshold voltage
    parameter real vtl = 0.5    // Hysteresis voltage
)(
    input  real in,    // Analog input signal
    output reg  out    // Digital output
);

    // Internal register to store previous state, initialized to 0
    initial begin
        out = 1'b0;
    end

    always @(*) begin
        if (out == 1'b0) begin
            // Output is low, check if input rises above threshold
            if (in > vth)
                out = 1'b1;
            else
                out = 1'b0;
        end else begin
            // Output is high, check if input falls below lower threshold
            if (in < (vth - vtl))
                out = 1'b0;
            else
                out = 1'b1;
        end
    end

endmodule

