    reg expected_out;
    reg prev_out;
    real lower_threshold;
    real upper_threshold;
    integer test_num;

    // Instantiate the Schmitt Trigger
    schmitt_trigger #(.vth(vth), .vtl(vtl)) dut (
        .in(in),
        .out(out)
    );

    // Timeout mechanism
    initial begin
        #10000;
        $display("Timeout reached at time %0t ns. Simulation stopped.", $time);
        $finish;
    end

    // Generate test input sequence (covering rising, falling, and edge cases)
    initial begin
        // Sweep up from 0 to 5V
        for (i = 0; i < 40; i = i + 1) begin
            test_inputs[i] = i * 0.125; // 0.0, 0.125, ..., 4.875
        end
        // Sweep down from 5V to 0
        for (i = 40; i < 80; i = i + 1) begin
            test_inputs[i] = 5.0 - ((i-40) * 0.125); // 5.0, 4.875, ..., 0.0
        end
        // Edge cases around thresholds
        test_inputs[80] = vth - 0.01;
        test_inputs[81] = vth + 0.01;
        test_inputs[82] = vth - vtl - 0.01;
        test_inputs[83] = vth - vtl + 0.01;
        test_inputs[84] = vth;
        test_inputs[85] = vth - vtl;
        test_inputs[86] = 0.0;
        test_inputs[87] = 5.0;
        test_inputs[88] = 2.0;
        test_inputs[89] = 3.0;
        // Random values
        test_inputs[90] = 1.23;
        test_inputs[91] = 2.49;
        test_inputs[92] = 2.51;
        test_inputs[93] = 0.49;
        test_inputs[94] = 0.51;
        test_inputs[95] = 4.99;
        test_inputs[96] = 0.99;
        test_inputs[97] = 1.99;
        test_inputs[98] = 3.99;
        test_inputs[99] = 4.01;
    end

    // Task to check output and report errors
    task check_output;
        input integer test_idx;
        input real in_val;
        input reg expected;
        input reg actual;
        begin
            if (expected !== actual) begin
                $display("ERROR at test %0d: in=%0.3f, expected out=%b, got out=%b at time %0t", test_idx, in_val, expected, actual, $time);
                error_count = error_count + 1;
            end
        end
    endtask

    // Main test process
    initial begin
        fd = $fopen("test_vectors.txt", "w");
        if (fd)
            $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        error_count = 0;
        prev_out = 1'b0; // Initial output state
        expected_out = 1'b0;
        lower_threshold = vth - vtl;
        upper_threshold = vth;

        // Write header (optional, can be commented out)
        // $fdisplay(fd, "in out");

        for (test_num = 0; test_num < 100; test_num = test_num + 1) begin
            in = test_inputs[test_num];
            #1; // Allow combinational logic to settle

            // Compute expected output based on Schmitt Trigger logic
            if (prev_out == 1'b0) begin
                if (in > upper_threshold)
                    expected_out = 1'b1;
                else
                    expected_out = 1'b0;
            end else begin
                if (in < lower_threshold)
                    expected_out = 1'b0;
                else
                    expected_out = 1'b1;
            end

            // Write test vector to file: input followed by output
            $fdisplay(fd, "%0.3f %b", in, out);

            // Assertion/check
            check_output(test_num, in, expected_out, out);

            // Update prev_out for next expected calculation
            prev_out = expected_out;
        end

        $display("Testing complete. Total errors: %0d", error_count);
        $fclose(fd);
        $finish;
    end

endmodule

