module dff_asynchronous_set_tb;

    // Inputs
    reg CLK;
    reg D;
    reg SET_B;

    // Output
    wire Q;

    // Internal variables
    integer fd;
    integer i;
    integer error_count;
    reg expected_Q;
    reg prev_SET_B;
    reg prev_CLK;
    reg [1:0] test_case;
    reg [7:0] vector_count;

    // Instantiate the DUT
    dff_asynchronous_set dut (
        .CLK(CLK),
        .D(D),
        .SET_B(SET_B),
        .Q(Q)
    );

    // Clock generation
    initial begin
        CLK = 0;
        forever #5 CLK = ~CLK; // 10ns period
    end

    // Timeout mechanism
    initial begin
        #10000;
        $display("Timeout reached at time %0t ns. Simulation stopped.", $time);
        $finish;
    end

    // Testbench logic
    initial begin
        fd = $fopen("test_vectors.txt", "w");
        if (fd)
            $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        // Write header
        $fdisplay(fd, "CLK D SET_B | Q");

        // Initialize
        D = 0;
        SET_B = 1;
        prev_SET_B = 1;
        prev_CLK = 0;
        expected_Q = 0;
        error_count = 0;
        vector_count = 0;

        // Reset Q to known state
        SET_B = 0;
        @(negedge CLK);
        #1;
        $fdisplay(fd, "%b %b %b | %b", CLK, D, SET_B, Q);
        if (Q !== 1'b1) begin
            $display("ASSERTION FAILED at time %0t: Asynchronous set failed. Q=%b, expected 1", $time, Q);
            error_count = error_count + 1;
        end
        vector_count = vector_count + 1;

        SET_B = 1;
        @(negedge CLK);
        #1;

        // Main test loop: generate at least 100 test vectors
        for (i = 0; i < 100; i = i + 1) begin
            // Randomize inputs
            D = $random % 2;
            // SET_B is toggled randomly, but ensure at least some negedges
            if (i % 13 == 0)
                SET_B = 0;
            else if (i % 17 == 0)
                SET_B = 1;
            else
                SET_B = $random % 2;

            // Save previous values for edge detection
            prev_SET_B = SET_B;
            prev_CLK = CLK;

            // Wait for either posedge CLK or negedge SET_B
            if (!SET_B) begin
                // Asynchronous set
                @(negedge SET_B);
                #1;
                expected_Q = 1'b1;
            end else begin
                @(posedge CLK);
                #1;
                expected_Q = D;
            end

            // Write test vector to file
            $fdisplay(fd, "%b %b %b | %b", CLK, D, SET_B, Q);

            // Assertion
            if (Q !== expected_Q) begin
                $display("ASSERTION FAILED at time %0t: Q=%b, expected %b (D=%b, SET_B=%b, CLK=%b)", $time, Q, expected_Q, D, SET_B, CLK);
                error_count = error_count + 1;
            end

            vector_count = vector_count + 1;
        end

        // Additional edge cases
        // 1. SET_B goes low while CLK is high, D is 0
        D = 0;
        SET_B = 1;
        @(posedge CLK);
        #1;
        SET_B = 0;
        #1;
        $fdisplay(fd, "%b %b %b | %b", CLK, D, SET_B, Q);
        if (Q !== 1'b1) begin
            $display("ASSERTION FAILED (async set) at time %0t: Q=%b, expected 1", $time, Q);
            error_count = error_count + 1;
        end
        vector_count = vector_count + 1;

        // 2. SET_B is held low, toggle CLK and D
        SET_B = 0;
        D = 1;
        @(posedge CLK);
        #1;
        $fdisplay(fd, "%b %b %b | %b", CLK, D, SET_B, Q);
        if (Q !== 1'b1) begin
            $display("ASSERTION FAILED (SET_B held low) at time %0t: Q=%b, expected 1", $time, Q);
            error_count = error_count + 1;
        end
        vector_count = vector_count + 1;

        // 3. SET_B returns high, D = 0, check normal DFF operation
        SET_B = 1;
        D = 0;
        @(posedge CLK);
        #1;
        $fdisplay(fd, "%b %b %b | %b", CLK, D, SET_B, Q);
        if (Q !== 1'b0) begin
            $display("ASSERTION FAILED (normal DFF after SET_B high) at time %0t: Q=%b, expected 0", $time, Q);
            error_count = error_count + 1;
        end
        vector_count = vector_count + 1;

        // 4. SET_B returns high, D = 1, check normal DFF operation
        D = 1;
        @(posedge CLK);
        #1;
        $fdisplay(fd, "%b %b %b | %b", CLK, D, SET_B, Q);
        if (Q !== 1'b1) begin
            $display("ASSERTION FAILED (normal DFF after SET_B high) at time %0t: Q=%b, expected 1", $time, Q);
            error_count = error_count + 1;
        end
        vector_count = vector_count + 1;

        // 5. SET_B pulse low for one cycle
        D = 0;
        SET_B = 1;
        @(posedge CLK);
        #1;
        SET_B = 0;
        #1;
        $fdisplay(fd, "%b %b %b | %b", CLK, D, SET_B, Q);
        if (Q !== 1'b1) begin
            $display("ASSERTION FAILED (SET_B pulse low) at time %0t: Q=%b, expected 1", $time, Q);
            error_count = error_count + 1;
        end
        vector_count = vector_count + 1;
        SET_B = 1;
        @(posedge CLK);
        #1;

        // End of test
        $display("Testbench completed. Total vectors: %0d, Errors: %0d", vector_count, error_count);
        $fclose(fd);
        $finish;
    end

endmodule

