module adder_subtractor_4bit (
    input  [3:0] A,
    input  [3:0] B,
    input        SUB,
    output [3:0] SUM,
    output       CARRY
);
    wire [3:0] B_mod;
    wire       carry_in;
    wire [4:0] result;

    // If SUB==1, invert B and set carry_in to 1 for two's complement (A-B)
    // If SUB==0, pass B and set carry_in to 0 (A+B)
    assign B_mod   = B ^ {4{SUB}};
    assign carry_in = SUB;

    assign result = {1'b0, A} + {1'b0, B_mod} + carry_in;
    assign SUM   = result[3:0];
    assign CARRY = result[4]; // carry out for addition or borrow for subtraction

endmodule

