    wire [3:0] SUM;
    wire       CARRY;

    // DUT instantiation
    adder_subtractor_4bit dut (
        .A(A),
        .B(B),
        .SUB(SUB),
        .SUM(SUM),
        .CARRY(CARRY)
    );

    // File descriptor
    integer fd;
