    task check_result;
        input [3:0] A_in;
        input [3:0] B_in;
        input       SUB_in;
        input [3:0] SUM_out;
        input       CARRY_out;
        input [3:0] exp_SUM;
        input       exp_CARRY;
        begin
            if ((SUM_out !== exp_SUM) || (CARRY_out !== exp_CARRY)) begin
                $display("ERROR: A=%b B=%b SUB=%b | SUM=%b (exp %b) CARRY=%b (exp %b) at time %0t",
                         A_in, B_in, SUB_in, SUM_out, exp_SUM, CARRY_out, exp_CARRY, $time);
                error_count = error_count + 1;
            end
        end
    endtask

    // Main test process
    initial begin
        fd = $fopen("test_vectors.txt", "w");
