            expected_Q = prev_Q + 1;
            check_output(expected_Q, Q, test_count);
            test_count = test_count + 1;
        end

        // Test down counting (DIR=1)
        DIR = 1;
        for (i = 0; i < 20; i = i + 1) begin
            prev_Q = Q;
            @(negedge CLK);
            $fdisplay(fd, "%b %b %b %b", CLK, RST, DIR, Q);
