module digital_circuit_tb;

    // Inputs
    reg D;
    reg SET_B;
    reg CLK;
    reg VPWR;
    reg VGND;

    // Output
    wire Q;

    // File descriptor
    integer fd;
    integer error_count;
    integer test_count;
    integer i;
    reg expected_Q;
    reg prev_Q;

    // Instantiate the Unit Under Test (UUT)
    digital_circuit uut (
        .D(D),
        .SET_B(SET_B),
        .CLK(CLK),
        .VPWR(VPWR),
        .VGND(VGND),
        .Q(Q)
    );

    // Clock generation
    initial begin
        CLK = 0;
        forever #5 CLK = ~CLK; // 10ns period
    end

    // Timeout mechanism
    initial begin
        #10000;
        $display("Timeout reached at time %0t. Finishing simulation.", $time);
        $finish;
    end

    // Task to check output and report errors
    task check_output;
        input reg exp_Q;
        begin
            if (Q !== exp_Q) begin
                $display("ERROR at time %0t: Inputs: D=%b SET_B=%b CLK=%b VPWR=%b VGND=%b | Expected Q=%b, Got Q=%b", $time, D, SET_B, CLK, VPWR, VGND, exp_Q, Q);
                error_count = error_count + 1;
            end
        end
    endtask

    // Main stimulus
    initial begin
        // Initialize
        D = 0;
        SET_B = 0;
        VPWR = 1;
        VGND = 0;
        error_count = 0;
        test_count = 0;
        prev_Q = 0;

        // Open file for writing test vectors
        fd = $fopen("test_vectors.txt", "w");
        if (fd) $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        // Reset Q to known state
        @(negedge CLK);
        #1;
        prev_Q = Q;

        // Generate at least 100 test vectors (cover all input combinations multiple times)
        for (i = 0; i < 100; i = i + 1) begin
            // Randomize inputs
            D     = $random % 2;
            SET_B = $random % 2;
            VPWR  = 1; // Always powered for functional test
            VGND  = 0;

            // Wait for next rising edge of CLK
            @(posedge CLK);
            #1; // Allow Q to settle

            // Compute expected Q
            if (SET_B)
                expected_Q = 1;
            else
                expected_Q = D;

            // Check output
            check_output(expected_Q);

            // Write test vector: D SET_B CLK VPWR VGND Q
            $fdisplay(fd, "%b %b %b %b %b %b", D, SET_B, CLK, VPWR, VGND, Q);

            prev_Q = Q;
            test_count = test_count + 1;
        end

        // Additional: Exhaustive test for all input combinations (D, SET_B)
        for (D = 0; D <= 1; D = D + 1) begin
            for (SET_B = 0; SET_B <= 1; SET_B = SET_B + 1) begin
                VPWR = 1;
                VGND = 0;
                @(posedge CLK);
                #1;
                if (SET_B)
                    expected_Q = 1;
                else
                    expected_Q = D;
                check_output(expected_Q);
                $fdisplay(fd, "%b %b %b %b %b %b", D, SET_B, CLK, VPWR, VGND, Q);
                test_count = test_count + 1;
            end
        end

        // Test with VPWR=0 (power off), Q should not change (but in real silicon, output is undefined)
        VPWR = 0;
        VGND = 0;
        D = 1;
        SET_B = 0;
        @(posedge CLK);
        #1;
        // No assertion for Q, just record
        $fdisplay(fd, "%b %b %b %b %b %b", D, SET_B, CLK, VPWR, VGND, Q);
        test_count = test_count + 1;

        // Test with VGND=1 (ground fault), Q should not change (but in real silicon, output is undefined)
        VPWR = 1;
        VGND = 1;
        D = 0;
        SET_B = 1;
        @(posedge CLK);
