module reg3bit_parallel_load_clear (
    input  wire [2:0] D,   // 3-bit input data
    input  wire       CLK, // Clock input
    input  wire [1:0] AR,  // 2-bit async reset control
    input  wire       LD,  // Load enable
    output reg  [2:0] Q    // 3-bit output (register value)
);

always @(posedge CLK) begin
    if (AR != 2'b00)       // If any bit of AR is high, clear register
        Q <= 3'b000;
    else if (LD)           // If load enable is high, load D
        Q <= D;
    else                   // Otherwise, hold value
        Q <= Q;
end

endmodule

