            if (!rst) begin
                expected_count = 4'b0;
            end else if (prev_count == 4'b1111) begin
                expected_count = 4'b0;
            end else begin
                expected_count = prev_count + 1;
            end

            // Assertion
            if (count !== expected_count) begin
                $display("ASSERTION FAILED at time %0t: count expected %b, got %b (i=%0d)", $time, expected_count, count, i);
                error_count = error_count + 1;
            end

            // Write test vector
            $fdisplay(fd, "%b %b %b", clk, rst, count);

            prev_count = count;

            // Insert a reset at i=30 and i=70 to test reset during operation
            if (i == 29 || i == 69) begin
                rst = 0;
                @(negedge clk);
                #1;
                if (count !== 4'b0) begin
                    $display("ASSERTION FAILED at time %0t: count should be 0 after mid-test reset, got %b", $time, count);
                    error_count = error_count + 1;
                end
                $fdisplay(fd, "%b %b %b", clk, rst, count);
                rst = 1;
                @(negedge clk);
                #1;
                prev_count = count;
                $fdisplay(fd, "%b %b %b", clk, rst, count);
            end

            // Timeout check
            if ($time > TIMEOUT) begin
                $display("TIMEOUT: Simulation exceeded %0d time units", TIMEOUT);
                $fclose(fd);
                $finish;
            end
        end

        $display("Test completed with %0d error(s).", error_count);
        $fclose(fd);
        $finish;
