module twos_complement (
    input  [3:0] in,
    output [3:0] out
);

wire [3:0] flipped_in;
assign flipped_in = ~in;

// Ripple-carry adder to add 1 without '+'
wire c0, c1, c2, c3;
// Bit 0: add flipped_in[0] + 1
assign out[0] = flipped_in[0] ^ 1'b1;
assign c0 = flipped_in[0] & 1'b1;
// Bit 1
assign out[1] = flipped_in[1] ^ c0;
assign c1 = flipped_in[1] & c0;
// Bit 2
assign out[2] = flipped_in[2] ^ c1;
assign c2 = flipped_in[2] & c1;
// Bit 3
assign out[3] = flipped_in[3] ^ c2;
// No need for carry out

endmodule

