module dff_srsc_ap (
    input  wire clk,
    input  wire d,
    input  wire set,
    input  wire reset,
    input  wire preset,
    output reg  q,
    output wire q_bar
);

// Asynchronous preset has highest priority
always @(posedge clk or posedge preset) begin
    if (preset)
        q <= 1'b1;             // Asynchronous preset
    else if (reset)
        q <= 1'b0;             // Synchronous reset (clear)
    else if (set)
        q <= 1'b1;             // Synchronous set
    else
        q <= d;                // Normal D flip-flop operation
end

assign q_bar = ~q;

endmodule

