module up_counter_4bit (
    input wire clk,
    input wire reset,
    input wire enable,
    output reg [3:0] count
);

    reg [3:0] next_count;

    // Combinational logic to determine the next count value
    always @(*) begin
        if (reset) begin
            next_count = 4'b0000;
        end else if (enable) begin
            next_count = count + 1'b1;
        end else begin
            next_count = count;
        end
    end

    // Clocked process to update the count on rising edge of clk
    always @(posedge clk) begin
        count <= next_count;
    end

endmodule

