        @(negedge clk);
        apply_and_check(reset, enable);

        @(negedge clk);
        reset = 0;
        enable = 0;
        apply_and_check(reset, enable);

        // Test: Hold enable low, count should not change
        for (i = 0; i < 5; i = i + 1) begin
            @(negedge clk);
            apply_and_check(reset, enable);
        end

        // Test: Enable counting
        enable = 1;
        for (i = 0; i < 20; i = i + 1) begin
            @(negedge clk);
            apply_and_check(reset, enable);
        end

        // Test: Toggle enable
        for (i = 0; i < 10; i = i + 1) begin
            enable = ~enable;
            @(negedge clk);
            apply_and_check(reset, enable);
        end

        // Test: Assert reset in the middle of counting
        enable = 1;
        @(negedge clk);
        apply_and_check(reset, enable);

        reset = 1;
        @(negedge clk);
        apply_and_check(reset, enable);

        reset = 0;
        @(negedge clk);
        apply_and_check(reset, enable);

        // Test: Count up to wrap-around
        for (i = 0; i < 20; i = i + 1) begin
            @(negedge clk);
            apply_and_check(reset, enable);
        end

        // Randomized test vectors
        for (i = 0; i < 40; i = i + 1) begin
