module parity_check (
    input clk,
    input reset_n,
    input [7:0] data_in,
    output reg parity_out
);

    always @(posedge clk) begin
        if (!reset_n) begin
            parity_out <= 1'b0;
        end else begin
            // Even parity: parity_out = 1 if number of 1's is even (i.e., XOR of all bits is 0)
            // Odd parity: parity_out = 1 if number of 1's is odd (i.e., XOR of all bits is 1)
            // Here, we output 1 for odd parity, 0 for even parity
            parity_out <= ^data_in;
        end
    end

endmodule

