  wire [3:0] out;

  // Instantiate the Unit Under Test (UUT)
  binary_counter uut (
    .clk(clk),
    .rst(rst),
    .out(out)
  );

  // File descriptor for test vector output
  integer fd;
  integer i;
  integer error_count;
  reg [3:0] expected_out;

  // Clock generation
  initial begin
    clk = 0;
    forever #5 clk = ~clk; // 10ns period
  end

  // Timeout mechanism
  initial begin
    #10000;
    $display("ERROR: Simulation timed out at time %0t", $time);
    $finish;
  end

  // Task to check output and report errors
  task check_output;
    input [3:0] expected;
    input [3:0] actual;
    input integer vector_num;
    begin
      if (expected !== actual) begin
        $display("ASSERTION FAILED at vector %0d, time %0t: expected %b, got %b", vector_num, $time, expected, actual);
        error_count = error_count + 1;
      end
    end
  endtask

  // Main stimulus and test vector generation
  initial begin
    fd = $fopen("test_vectors.txt", "w");
    if (fd)
      $display("File opened successfully");
    else begin
      $display("Failed to open file");
      $finish;
    end

    error_count = 0;

    // Initialize
    rst = 1;
    expected_out = 4'b0000;

    // Apply reset (active low) for 2 cycles
    @(negedge clk);
    rst = 0;
    @(negedge clk);
    rst = 0;
    @(negedge clk);
    rst = 1; // Deassert reset

    // Wait for reset to propagate
    @(posedge clk);
    expected_out = 4'b0000;
    $fdisplay(fd, "%b %b", {clk, rst}, out);
    check_output(expected_out, out, 0);

    // Run at least 100 test vectors (clock cycles)
    for (i = 1; i <= 100; i = i + 1) begin
      @(posedge clk);
      // After reset, counter increments on each clock
      if (rst == 1)
        expected_out = expected_out + 1;
      else
        expected_out = 4'b0000;

      $fdisplay(fd, "%b %b", {clk, rst}, out);
      check_output(expected_out, out, i);
    end

    // Test reset in the middle of operation
    @(negedge clk);
    rst = 0;
    @(negedge clk);
    rst = 1;
    @(posedge clk);
    expected_out = 4'b0000;
    $fdisplay(fd, "%b %b", {clk, rst}, out);
    check_output(expected_out, out, 101);

    // Continue for a few more cycles after reset
    for (i = 102; i <= 110; i = i + 1) begin
      @(posedge clk);
      if (rst == 1)
        expected_out = expected_out + 1;
      else
        expected_out = 4'b0000;

      $fdisplay(fd, "%b %b", {clk, rst}, out);
      check_output(expected_out, out, i);
    end

    $display("Test completed with %0d errors.", error_count);
    $fclose(fd);
    $finish;
  end

endmodule

