module shift_register_16 (
    input        clk,
    input        reset,
    input        load,            // If high, parallel load data_in on rising clk
    input        shift,           // If high, shift left with new bit at LSB on clk
    input [15:0] data_in,         // Parallel data input
    input        new_bit,         // Bit to shift in at LSB during shift
    output [15:0] data_out        // Current shift register contents
);

    reg [15:0] shift_reg;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            shift_reg <= 16'b0;
        end else if (load) begin
            shift_reg <= data_in;
        end else if (shift) begin
            shift_reg <= {shift_reg[14:0], new_bit};
        end
    end

    assign data_out = shift_reg;

endmodule

