module dff (
    input CLK,
    input D,
    input SCD,
    input SCE,
    input RESET_B,
    output reg Q,
    output Q_B
);

    // Q is declared as output reg so that it can be driven in the always block.
    // Q_B is declared as output and driven by continuous assignment.

    assign Q_B = ~Q;

    always @(posedge CLK or negedge RESET_B) begin
        if (!RESET_B) begin
            Q <= 1'b0;
        end else if (SCD) begin
            Q <= 1'b1;
        end else if (SCE) begin
            Q <= D;
        end
        // retain value if SCE is not asserted and SCD is not asserted
    end

endmodule

