        expected_Q = 1;
        expected_Q_B = 0;
        $fdisplay(fd, "%b %b %b %b %b %b %b", CLK, D, SCD, SCE, RESET_B, Q, Q_B);
        check_output(expected_Q, expected_Q_B);
        prev_Q = expected_Q;
        vector_count = vector_count + 1;

        // Test SCE high, D=0
        D = 0; SCD = 0; SCE = 1; RESET_B = 1;
        @(negedge CLK); #1;
        @(posedge CLK); #1;
        expected_Q = 0;
        expected_Q_B = 1;
        $fdisplay(fd, "%b %b %b %b %b %b %b", CLK, D, SCD, SCE, RESET_B, Q, Q_B);
        check_output(expected_Q, expected_Q_B);
        prev_Q = expected_Q;
        vector_count = vector_count + 1;

        // Test SCE high, D=1
        D = 1; SCD = 0; SCE = 1; RESET_B = 1;
        @(negedge CLK); #1;
        @(posedge CLK); #1;
        expected_Q = 1;
        expected_Q_B = 0;
        $fdisplay(fd, "%b %b %b %b %b %b %b", CLK, D, SCD, SCE, RESET_B, Q, Q_B);
        check_output(expected_Q, expected_Q_B);
        prev_Q = expected_Q;
        vector_count = vector_count + 1;

        // Test both SCD and SCE high (SCD has priority)
        D = 0; SCD = 1; SCE = 1; RESET_B = 1;
        @(negedge CLK); #1;
        @(posedge CLK); #1;
        expected_Q = 1;
        expected_Q_B = 0;
        $fdisplay(fd, "%b %b %b %b %b %b %b", CLK, D, SCD, SCE, RESET_B, Q, Q_B);
        check_output(expected_Q, expected_Q_B);
        prev_Q = expected_Q;
        vector_count = vector_count + 1;

        // Test hold (SCD=0, SCE=0)
        D = 1; SCD = 0; SCE = 0; RESET_B = 1;
        @(negedge CLK); #1;
        @(posedge CLK); #1;
        expected_Q = prev_Q;
        expected_Q_B = ~expected_Q;
        $fdisplay(fd, "%b %b %b %b %b %b %b", CLK, D, SCD, SCE, RESET_B, Q, Q_B);
        check_output(expected_Q, expected_Q_B);
        prev_Q = expected_Q;
        vector_count = vector_count + 1;

        // At least 100 vectors
        while (vector_count < 100) begin
            D = $random % 2;
            SCD = $random % 2;
            SCE = $random % 2;
            RESET_B = 1;
            @(negedge CLK); #1;
            @(posedge CLK); #1;
            if (!RESET_B)
                expected_Q = 0;
            else if (SCD)
                expected_Q = 1;
            else if (SCE)
                expected_Q = D;
            else
                expected_Q = prev_Q;
            expected_Q_B = ~expected_Q;
            $fdisplay(fd, "%b %b %b %b %b %b %b", CLK, D, SCD, SCE, RESET_B, Q, Q_B);
            check_output(expected_Q, expected_Q_B);
            prev_Q = expected_Q;
            vector_count = vector_count + 1;
        end

        $display("Test completed with %0d vectors. Errors: %0d", vector_count, error_count);
        $fclose(fd);
        $finish;
    end

endmodule

