        if (fd) $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        error_count = 0;
        rst_n = 0;
        expected_counter = 4'b0000;
        prev_counter = 4'bxxxx;

        // Apply reset for 2 cycles
        @(negedge clk);
        @(negedge clk);
        rst_n = 1;

        // Test 1: After reset, counter should increment for 100 cycles
        for (i = 0; i < 100; i = i + 1) begin
            @(negedge clk);
            // Write test vector: clk rst_n counter_out
            $fdisplay(fd, "%b %b %b", clk, rst_n, counter_out);

            // Check expected value
            if (i == 0) begin
                expected_counter = 4'b0001;
            end else begin
                expected_counter = (expected_counter + 1) & 4'b1111;
            end

            // Assertion
            if (counter_out !== expected_counter) begin
                $display("ERROR at time %0t: counter_out=%b, expected=%b", $time, counter_out, expected_counter);
                error_count = error_count + 1;
            end
        end

        // Test 2: Apply asynchronous reset in the middle
        @(negedge clk);
        rst_n = 0;
        @(negedge clk);
        $fdisplay(fd, "%b %b %b", clk, rst_n, counter_out);
        // Assertion for reset
        if (counter_out !== 4'b0000) begin
            $display("ERROR at time %0t: counter_out=%b, expected=0000 after reset", $time, counter_out);
            error_count = error_count + 1;
        end

        // Release reset and check increment again
        @(negedge clk);
        rst_n = 1;
        @(negedge clk);
        $fdisplay(fd, "%b %b %b", clk, rst_n, counter_out);
        if (counter_out !== 4'b0001) begin
            $display("ERROR at time %0t: counter_out=%b, expected=0001 after reset release", $time, counter_out);
            error_count = error_count + 1;
        end

        // Continue counting for 10 more cycles
        expected_counter = 4'b0001;
        for (i = 0; i < 10; i = i + 1) begin
            @(negedge clk);
            $fdisplay(fd, "%b %b %b", clk, rst_n, counter_out);
            expected_counter = (expected_counter + 1) & 4'b1111;
            if (counter_out !== expected_counter) begin
                $display("ERROR at time %0t: counter_out=%b, expected=%b", $time, counter_out, expected_counter);
                error_count = error_count + 1;
            end
        end

        // Test 3: Multiple resets in quick succession
        repeat (3) begin
            @(negedge clk);
            rst_n = 0;
            @(negedge clk);
            $fdisplay(fd, "%b %b %b", clk, rst_n, counter_out);
            if (counter_out !== 4'b0000) begin
                $display("ERROR at time %0t: counter_out=%b, expected=0000 after reset", $time, counter_out);
                error_count = error_count + 1;
            end
            @(negedge clk);
            rst_n = 1;
            @(negedge clk);
            $fdisplay(fd, "%b %b %b", clk, rst_n, counter_out);
            if (counter_out !== 4'b0001) begin
                $display("ERROR at time %0t: counter_out=%b, expected=0001 after reset release", $time, counter_out);
                error_count = error_count + 1;
            end
        end

        // Final report
        check_errors();

        $fclose(fd);
        $display("Testbench completed at time %0t. Total errors: %0d", $time, error_count);
        $finish;
    end

    // Error checking task
    task check_errors;
        begin
            if (error_count == 0)
                $display("All test cases passed.");
            else
                $display("Total errors detected: %0d", error_count);
        end
    endtask

endmodule

