// clock_gate_d_ff_en.v
module clock_gate_d_ff_en (
  input CLK,     // clock signal
  input EN,      // enable signal
  input TE,      // transparent enable signal
  output reg ENCLK // gated clock signal
);

  always @(posedge CLK) begin
    if (TE)
      ENCLK <= CLK;         // When TE is high, ENCLK follows CLK (on rising edge, so always 1)
    else if (EN)
      ENCLK <= CLK;         // When TE is low and EN is high, ENCLK follows CLK (on rising edge, so always 1)
    else
      ENCLK <= 1'b0;        // When TE is low and EN is low, ENCLK is low
  end

endmodule

// Testbench for clock_gate_d_ff_en
module tb_clock_gate_d_ff_en;
  reg CLK;
  reg EN;
  reg TE;
  wire ENCLK;

  // Instantiate the module
  clock_gate_d_ff_en uut (
    .CLK(CLK),
    .EN(EN),
    .TE(TE),
    .ENCLK(ENCLK)
  );

  // Clock generation: 10ns period (50MHz), 50% duty cycle
  initial begin
    CLK = 0;
    forever #5 CLK = ~CLK;
  end

  // Stimulus
  initial begin
    $display("Time\tTE EN CLK | ENCLK");
    $monitor("%4t\t%b  %b  %b  |   %b", $time, TE, EN, CLK, ENCLK);

    // Initialize inputs
    EN = 0;
    TE = 0;

    // Wait some time
    #12;

    // TE=0, EN=0: ENCLK should be low
    EN = 0; TE = 0;
    #13;

    // TE=0, EN=1: ENCLK should follow CLK (at posedge, ENCLK goes to 1 then 0 at next posedge if EN=0)
    EN = 1; TE = 0;
    #17;

    // TE=1, EN=0: ENCLK should follow CLK (at posedge, ENCLK goes to 1)
    EN = 0; TE = 1;
    #15;

    // TE=1, EN=1: ENCLK should follow CLK (at posedge, ENCLK goes to 1)
    EN = 1; TE = 1;
    #10;

    // TE=0, EN=0 again: ENCLK should return to low
    EN = 0; TE = 0;
    #15;

    // Rapid toggling
    EN = 1; TE = 0;
    #5;
    EN = 0; TE = 1;
    #5;
    EN = 1; TE = 1;
    #5;
    EN = 0; TE = 0;
    #10;

    $finish;
  end
endmodule

