  task check_output;
    input reg exp_ENCLK;
    begin
      if (ENCLK !== exp_ENCLK) begin
        $display("ASSERTION FAILED at time %0t: TE=%b EN=%b CLK=%b | ENCLK=%b (expected %b)", $time, TE, EN, CLK, ENCLK, exp_ENCLK);
        error_count = error_count + 1;
      end
    end
  endtask

  // Main stimulus and test vector generation
  initial begin
    fd = $fopen("test_vectors.txt", "w");
    if (fd) $display("File opened successfully");
    else begin
      $display("Failed to open file");
      $finish;
    end

    error_count = 0;
    vector_count = 0;

    // Write header (optional, comment out if not needed)
    // $fdisplay(fd, "TE EN CLK ENCLK");

    // Initialize
    EN = 0;
    TE = 0;
    #1;

    // Systematic test: For 100+ vectors, sweep TE, EN, and apply at posedge and negedge of CLK
    // For each combination, test at both edges and with some random toggling
    for (i = 0; i < 2; i = i + 1) begin // TE
      for (j = 0; j < 2; j = j + 1) begin // EN
        for (k = 0; k < 10; k = k + 1) begin // 10 cycles per combination
          // Set inputs
          TE = i;
          EN = j;
          // Wait for posedge
          @(negedge CLK);
          #1; // small delay to avoid race
          // At posedge, ENCLK will be updated
          @(posedge CLK);
          #1;
          // Compute expected ENCLK
          if (TE)
            expected_ENCLK = 1'b1;
          else if (EN)
            expected_ENCLK = 1'b1;
          else
            expected_ENCLK = 1'b0;
          // Write vector: TE EN CLK ENCLK
          $fdisplay(fd, "%b %b %b %b", TE, EN, CLK, ENCLK);
          vector_count = vector_count + 1;
          // Assertion
          check_output(expected_ENCLK);
          // Wait a bit before next vector
          #2;
          // Also test at negedge
          @(negedge CLK);
          #1;
          // ENCLK should not change at negedge, but log anyway for completeness
          $fdisplay(fd, "%b %b %b %b", TE, EN, CLK, ENCLK);
          vector_count = vector_count + 1;
          // Assertion (ENCLK should remain as before)
          check_output(ENCLK);
          #2;
        end
      end
    end

    // Additional random toggling for more coverage
    repeat (20) begin
      @(negedge CLK);
      TE = $random % 2;
      EN = $random % 2;
      #1;
      @(posedge CLK);
      #1;
      if (TE)
        expected_ENCLK = 1'b1;
      else if (EN)
        expected_ENCLK = 1'b1;
      else
        expected_ENCLK = 1'b0;
      $fdisplay(fd, "%b %b %b %b", TE, EN, CLK, ENCLK);
      vector_count = vector_count + 1;
      check_output(expected_ENCLK);
      #2;
    end

    // Final summary
    $display("Test completed: %0d vectors written. Errors: %0d", vector_count, error_count);
    $fclose(fd);
    $finish;
  end

endmodule

