  // DUT instantiation
  karnaugh_map dut (
    .A(A),
    .B(B),
    .C(C),
    .D(D),
    .E(E),
    .F(F)
  );

  // File descriptor
  integer fd;
  integer error_count;
  integer test_count;
  integer i;
  reg expected_F;

  // Timeout mechanism
  initial begin
    #10000;
    $display("ERROR: Simulation timeout at time %0t ns!", $time);
    $finish;
  end

  // Task to compute expected output
  task automatic compute_expected;
    input [4:0] vec;
    output reg exp_F;
    begin
      case (vec)
        5'b00000: exp_F = 1;
        5'b00001: exp_F = 0;
        5'b00011: exp_F = 1;
        5'b00010: exp_F = 0;
        5'b00110: exp_F = 0;
        5'b00111: exp_F = 1;
        5'b00101: exp_F = 0;
        5'b00100: exp_F = 1;
        5'b01100: exp_F = 0;
        5'b01101: exp_F = 1;
        5'b01111: exp_F = 0;
        5'b01110: exp_F = 1;
        5'b01010: exp_F = 0;
        5'b01011: exp_F = 1;
        5'b01001: exp_F = 0;
        5'b01000: exp_F = 1;
        default: exp_F = 0;
      endcase
    end
  endtask

  // Task to check result and report errors
  task automatic check_result;
    input [4:0] vec;
    input dut_F;
    input exp_F;
    begin
      if (dut_F !== exp_F) begin
        $display("ERROR: Mismatch at time %0t: Inputs = %b, DUT F = %b, Expected F = %b", $time, vec, dut_F, exp_F);
        error_count = error_count + 1;
      end
    end
  endtask

  // Main stimulus and checking
