    for (i = 0; i < 32; i = i + 1) begin
      {A, B, C, D, E} = i[4:0];
      #1; // Allow propagation

      compute_expected(i[4:0], expected_F);
      check_result(i[4:0], F, expected_F);

      // Write to file: A B C D E F (space separated)
      $fdisplay(fd, "%b %b %b %b %b %b", A, B, C, D, E, F);

      test_count = test_count + 1;
    end

    // Generate at least 68 more random test vectors (total >= 100)
    for (i = 0; i < 68; i = i + 1) begin
      {A, B, C, D, E} = $random;
      #1;

      compute_expected({A, B, C, D, E}, expected_F);
      check_result({A, B, C, D, E}, F, expected_F);

      $fdisplay(fd, "%b %b %b %b %b %b", A, B, C, D, E, F);

      test_count = test_count + 1;
    end

    $display("Testbench completed: %0d tests run, %0d errors detected.", test_count, error_count);

    $fclose(fd);
    $finish;
  end

