module counter_4bit_tb;

    // Inputs
    reg clk;
    reg reset;
    reg enable;

    // Outputs
    wire [3:0] Q;

    // File descriptor
    integer fd;
    integer error_count;
    integer i;
    reg [3:0] expected_Q;

    // Instantiate the Unit Under Test (UUT)
    counter_4bit uut (
        .clk(clk),
        .reset(reset),
        .enable(enable),
        .Q(Q)
    );

    // Clock generation: 10ns period
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    // Timeout mechanism
    initial begin
        #10000;
        $display("Timeout reached at time %0t. Simulation stopped.", $time);
        $finish;
    end

    // Task to check output and report errors
    task check_output;
        input [3:0] expected;
        begin
            if (Q !== expected) begin
                $display("ERROR at time %0t: reset=%b enable=%b Q=%b expected=%b", $time, reset, enable, Q, expected);
                error_count = error_count + 1;
            end
            // Assertion (SystemVerilog style for simulators that support it)
            // assert (Q === expected) else $error("Assertion failed at time %0t", $time);
        end
    endtask

    // Main stimulus
    initial begin
        // Open file for writing test vectors
        fd = $fopen("test_vectors.txt", "w");
        if (fd) $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        error_count = 0;
        reset = 0;
        enable = 0;
        expected_Q = 4'b0000;

        // Initial reset
        @(negedge clk);
        reset = 1;
        enable = 0;
        @(negedge clk);
        reset = 0;
        enable = 0;
        expected_Q = 4'b0000;
        @(posedge clk);
        #1;
        $fdisplay(fd, "%b %b %b %b", clk, reset, enable, Q);
        check_output(expected_Q);

        // Test: Counter increments with enable
        for (i = 0; i < 20; i = i + 1) begin
            @(negedge clk);
            enable = 1;
            reset = 0;
            @(posedge clk);
            #1;
            expected_Q = expected_Q + 1;
            $fdisplay(fd, "%b %b %b %b", clk, reset, enable, Q);
            check_output(expected_Q);
        end

        // Test: Counter holds when enable is low
        @(negedge clk);
        enable = 0;
        @(posedge clk);
        #1;
        $fdisplay(fd, "%b %b %b %b", clk, reset, enable, Q);
        check_output(expected_Q);

        // Test: Reset during counting
        @(negedge clk);
        reset = 1;
        enable = 1;
        @(posedge clk);
        #1;
        expected_Q = 4'b0000;
        $fdisplay(fd, "%b %b %b %b", clk, reset, enable, Q);
        check_output(expected_Q);

        // Test: Enable after reset
