            @(negedge clk);
            enable = 1;
            @(posedge clk);
            #1;
            expected_Q = expected_Q + 1;
            $fdisplay(fd, "%b %b %b %b", clk, reset, enable, Q);
            check_output(expected_Q);
        end

        // Test: Multiple resets
        for (i = 0; i < 3; i = i + 1) begin
            @(negedge clk);
