        // Edge cases
        test_A[0] = 8'h00; test_B[0] = 8'h00; // 0 + 0
        test_A[1] = 8'hFF; test_B[1] = 8'h01; // 255 + 1 (overflow)
        test_A[2] = 8'h7F; test_B[2] = 8'h01; // 127 + 1
        test_A[3] = 8'h80; test_B[3] = 8'h80; // 128 + 128
        test_A[4] = 8'hFF; test_B[4] = 8'hFF; // 255 + 255 (overflow)
        test_A[5] = 8'h01; test_B[5] = 8'hFF; // 1 + 255 (overflow)
