module synchronous_counter_tb;

    // Inputs
    reg clk;
    reg rst;

    // Outputs
    wire [3:0] count;

    // Instantiate the Unit Under Test (UUT)
    synchronous_counter uut (
        .clk(clk),
        .rst(rst),
        .count(count)
    );

    // File descriptor for test vector output
    integer fd;
    integer i;
    integer error_count;
    reg [3:0] expected_count;
    reg [3:0] prev_count;

    // Timeout mechanism
    parameter TIMEOUT = 10000;

    // Clock generation: 10ns period
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    // Open file and initialize
    initial begin
        fd = $fopen("test_vectors.txt", "w");
        if (fd) $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end
        // Write header
        $fdisplay(fd, "clk rst count");
    end

    // Main stimulus and checking
    initial begin
        error_count = 0;
        rst = 1;
        expected_count = 0;
        prev_count = 0;

        // Apply reset for 2 clock cycles
        @(negedge clk);
        @(negedge clk);
        rst = 0;

        // Test normal counting for at least 100 cycles
        for (i = 0; i < 100; i = i + 1) begin
            @(negedge clk);
            // Save previous count for expected calculation
            prev_count = expected_count;

            // Calculate expected count
            if (rst) begin
                expected_count = 0;
            end else if (prev_count == 4'b1001) begin
                expected_count = 0;
            end else begin
                expected_count = prev_count + 1;
            end

            // Write test vector to file
            $fdisplay(fd, "%b %b %b", clk, rst, count);

            // Assertion: check output
            if (count !== expected_count) begin
                $display("ERROR at time %0t: clk=%b rst=%b count=%b (expected %b)", $time, clk, rst, count, expected_count);
                error_count = error_count + 1;
            end
        end

        // Test reset in the middle of counting
        @(negedge clk);
        rst = 1;
        @(negedge clk);
        // After reset, count should be 0
        $fdisplay(fd, "%b %b %b", clk, rst, count);
        if (count !== 4'b0000) begin
            $display("ERROR after reset at time %0t: count=%b (expected 0000)", $time, count);
            error_count = error_count + 1;
        end
        rst = 0;
        expected_count = 0;

        // Continue counting for 10 more cycles
        for (i = 0; i < 10; i = i + 1) begin
            @(negedge clk);
            prev_count = expected_count;
            if (rst) begin
                expected_count = 0;
            end else if (prev_count == 4'b1001) begin
                expected_count = 0;
            end else begin
                expected_count = prev_count + 1;
            end
            $fdisplay(fd, "%b %b %b", clk, rst, count);
            if (count !== expected_count) begin
                $display("ERROR at time %0t: clk=%b rst=%b count=%b (expected %b)", $time, clk, rst, count, expected_count);
                error_count = error_count + 1;
            end
        end

        // Report results
        if (error_count == 0)
            $display("All test cases passed.");
        else
            $display("Total errors: %0d", error_count);

        // Close file and finish
        $fclose(fd);
        $finish;
    end

    // Timeout mechanism
    initial begin
        #TIMEOUT;
        $display("Simulation timed out at %0t", $time);
        $fclose(fd);
        $finish;
    end

