    initial SIM_TIMEOUT = 10000;

    // Instantiate the DUT
    dff_async_set_reset dut (
        .clk(clk),
        .reset(reset),
        .set(set),
        .d(d),
        .q(q),
        .qb(qb)
    );

    // Clock generation
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    // Task to check outputs and report errors
    task check_outputs;
        input reg exp_q;
        input reg exp_qb;
        begin
            if ((q !== exp_q) || (qb !== exp_qb)) begin
                $display("ERROR at time %0t: reset=%b set=%b d=%b | q=%b qb=%b (expected q=%b qb=%b)", $time, reset, set, d, q, qb, exp_q, exp_qb);
                error_count = error_count + 1;
            end
        end
    endtask

    // Main stimulus
    initial begin
        fd = $fopen("test_vectors.txt", "w");
        if (fd) $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        error_count = 0;
        test_count = 0;

        // Initialize inputs
        reset = 1;
        set = 1;
        d = 0;

        // Wait for global reset
        #10;

        // Test asynchronous reset (active low)
        reset = 0; set = 1; d = 1;
        #2;
        $fdisplay(fd, "%b %b %b %b %b %b", clk, reset, set, d, q, qb);
        check_outputs(1'b0, 1'b0);
        test_count = test_count + 1;

        reset = 1; set = 1; d = 1;
        #8;

        // Test asynchronous set (active low)
        reset = 1; set = 0; d = 0;
        #2;
        $fdisplay(fd, "%b %b %b %b %b %b", clk, reset, set, d, q, qb);
        check_outputs(1'b1, 1'b1);
        test_count = test_count + 1;

        reset = 1; set = 1; d = 0;
        #8;

        // Test both reset and set active (reset has priority)
        reset = 0; set = 0; d = 1;
        #2;
        $fdisplay(fd, "%b %b %b %b %b %b", clk, reset, set, d, q, qb);
        check_outputs(1'b0, 1'b0);
        test_count = test_count + 1;

        reset = 1; set = 1; d = 0;
        #8;

        // Test normal operation (reset=1, set=1), try all d values on posedge clk
        for (i = 0; i < 20; i = i + 1) begin
            d = i[0];
            @(negedge clk);
            reset = 1; set = 1;
            @(posedge clk);
            #1;
            $fdisplay(fd, "%b %b %b %b %b %b", clk, reset, set, d, q, qb);
            check_outputs(d, ~d);
            test_count = test_count + 1;
        end

        // Test asynchronous reset/set during normal operation
        // Toggle reset and set at random times
        for (i = 0; i < 20; i = i + 1) begin
            d = $random % 2;
            @(negedge clk);
            case (i % 4)
                0: begin reset = 0; set = 1; end // reset active
                1: begin reset = 1; set = 0; end // set active
                2: begin reset = 0; set = 0; end // both active
                3: begin reset = 1; set = 1; end // normal
            endcase
            @(posedge clk);
            #1;
            // Expected outputs
            if (!reset)
                check_outputs(1'b0, 1'b0);
            else if (!set)
                check_outputs(1'b1, 1'b1);
            else
                check_outputs(d, ~d);
            $fdisplay(fd, "%b %b %b %b %b %b", clk, reset, set, d, q, qb);
            test_count = test_count + 1;
            // Restore reset/set for next cycle
            reset = 1; set = 1;
            #1;
        end

        // Exhaustive test for all input combinations (reset, set, d) on posedge clk
        for (i = 0; i < 8; i = i + 1) begin
            @(negedge clk);
            reset = (i[2]) ? 1'b1 : 1'b0;
            set   = (i[1]) ? 1'b1 : 1'b0;
            d     = (i[0]) ? 1'b1 : 1'b0;
            @(posedge clk);
            #1;
            if (!reset)
                check_outputs(1'b0, 1'b0);
            else if (!set)
                check_outputs(1'b1, 1'b1);
            else
                check_outputs(d, ~d);
            $fdisplay(fd, "%b %b %b %b %b %b", clk, reset, set, d, q, qb);
            test_count = test_count + 1;
            // Restore for next
            reset = 1; set = 1;
            #1;
        end

        // Randomized test vectors
        for (i = 0; i < 60; i = i + 1) begin
            @(negedge clk);
            reset = $random % 2;
            set   = $random % 2;
            d     = $random % 2;
            @(posedge clk);
            #1;
            if (!reset)
                check_outputs(1'b0, 1'b0);
            else if (!set)
                check_outputs(1'b1, 1'b1);
            else
                check_outputs(d, ~d);
            $fdisplay(fd, "%b %b %b %b %b %b", clk, reset, set, d, q, qb);
            test_count = test_count + 1;
            // Restore for next
            reset = 1; set = 1;
            #1;
        end

        $display("Total tests run: %0d", test_count);
        $display("Total errors: %0d", error_count);

        $fclose(fd);
        $finish;
    end

    // Timeout mechanism
    initial begin
        #SIM_TIMEOUT;
        $display("ERROR: Simulation timed out at time %0t", $time);
        $fclose(fd);
        $finish;
    end

endmodule

