module shift_register_4bit_parallel_load (
    input  wire A,
    input  wire B,
    input  wire C,
    input  wire D,
    input  wire load,
    input  wire clk,
    output reg  [3:0] Q
);

always @(posedge clk) begin
    if (load) begin
        Q[3] <= A;
        Q[2] <= B;
        Q[1] <= C;
        Q[0] <= D;
    end else begin
        Q[3] <= Q[2];
        Q[2] <= Q[1];
        Q[1] <= Q[0];
        Q[0] <= 1'b0;
    end
end

endmodule

