module shift_register_4bit_parallel_load_tb;

    // Inputs
    reg A, B, C, D;
    reg load;
    reg clk;

    // Output
    wire [3:0] Q;

    // Internal variables
    integer fd;
    integer i, j;
    reg [3:0] parallel_data;
    reg [3:0] expected_Q;
    integer error_count;
    integer test_count;
    reg [3:0] shift_data;
    reg [3:0] Q_prev;

    // Instantiate the DUT
    shift_register_4bit_parallel_load dut (
        .A(A),
        .B(B),
        .C(C),
        .D(D),
        .load(load),
        .clk(clk),
        .Q(Q)
    );

    // Clock generation
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    // Timeout mechanism
    initial begin
        #10000;
        $display("ERROR: Simulation timeout at time %0t", $time);
        $finish;
    end

    // Main test process
    initial begin
        fd = $fopen("test_vectors.txt", "w");
        if (fd)
            $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        error_count = 0;
        test_count = 0;

        // Initialize inputs
        A = 0; B = 0; C = 0; D = 0; load = 0;

        // Wait for global reset
        #12;

        // --- Test 1: All possible parallel loads (16 combinations) ---
        for (i = 0; i < 16; i = i + 1) begin
            parallel_data = i[3:0];
            {A, B, C, D} = parallel_data;
            load = 1;
            @(negedge clk); // Setup inputs before clock edge
            @(posedge clk); // Apply load
            #1;
            expected_Q = parallel_data;
            test_count = test_count + 1;
            $fdisplay(fd, "%b %b %b %b %b %b %b", A, B, C, D, load, clk, Q);
            if (Q !== expected_Q) begin
                $display("ASSERTION ERROR at time %0t: Parallel load failed. Inputs: %b%b%b%b, Q: %b, Expected: %b", $time, A, B, C, D, Q, expected_Q);
                error_count = error_count + 1;
            end
            // Deassert load for next test
            load = 0;
            @(negedge clk);
        end

        // --- Test 2: Shift operation after parallel load ---
        for (i = 0; i < 8; i = i + 1) begin
            // Load a random value
            parallel_data = $random % 16;
            {A, B, C, D} = parallel_data;
            load = 1;
            @(negedge clk);
            @(posedge clk);
            #1;
            expected_Q = parallel_data;
            $fdisplay(fd, "%b %b %b %b %b %b %b", A, B, C, D, load, clk, Q);
            if (Q !== expected_Q) begin
                $display("ASSERTION ERROR at time %0t: Parallel load before shift failed. Inputs: %b%b%b%b, Q: %b, Expected: %b", $time, A, B, C, D, Q, expected_Q);
                error_count = error_count + 1;
            end
            load = 0;
            // Now shift 4 times, check each shift
            shift_data = parallel_data;
            for (j = 0; j < 4; j = j + 1) begin
                @(negedge clk);
                @(posedge clk);
                #1;
                shift_data = {shift_data[2:0], 1'b0};
                expected_Q = shift_data;
                test_count = test_count + 1;
                $fdisplay(fd, "%b %b %b %b %b %b %b", A, B, C, D, load, clk, Q);
                if (Q !== expected_Q) begin
                    $display("ASSERTION ERROR at time %0t: Shift failed. Shift #%0d, Q: %b, Expected: %b", $time, j+1, Q, expected_Q);
                    error_count = error_count + 1;
                end
            end
        end

        // --- Test 3: Alternate load and shift ---
        for (i = 0; i < 8; i = i + 1) begin
            // Load a value
            parallel_data = i[3:0];
            {A, B, C, D} = parallel_data;
            load = 1;
            @(negedge clk);
            @(posedge clk);
            #1;
            expected_Q = parallel_data;
            $fdisplay(fd, "%b %b %b %b %b %b %b", A, B, C, D, load, clk, Q);
            if (Q !== expected_Q) begin
                $display("ASSERTION ERROR at time %0t: Alternate load failed. Inputs: %b%b%b%b, Q: %b, Expected: %b", $time, A, B, C, D, Q, expected_Q);
                error_count = error_count + 1;
            end
            // Shift once
            load = 0;
            @(negedge clk);
            @(posedge clk);
            #1;
            expected_Q = {expected_Q[2:0], 1'b0};
            test_count = test_count + 1;
            $fdisplay(fd, "%b %b %b %b %b %b %b", A, B, C, D, load, clk, Q);
            if (Q !== expected_Q) begin
                $display("ASSERTION ERROR at time %0t: Alternate shift failed. Q: %b, Expected: %b", $time, Q, expected_Q);
                error_count = error_count + 1;
            end
        end

        // --- Test 4: Randomized test vectors ---
        for (i = 0; i < 68; i = i + 1) begin
            // Randomize inputs
            {A, B, C, D} = $random;
            load = $random % 2;
            Q_prev = Q;
            @(negedge clk);
            @(posedge clk);
            #1;
            if (load) begin
                expected_Q = {A, B, C, D};
            end else begin
                expected_Q = {Q_prev[2:0], 1'b0};
            end
            test_count = test_count + 1;
            $fdisplay(fd, "%b %b %b %b %b %b %b", A, B, C, D, load, clk, Q);
            if (Q !== expected_Q) begin
                $display("ASSERTION ERROR at time %0t: Random test failed. Inputs: %b%b%b%b, load: %b, Q: %b, Expected: %b", $time, A, B, C, D, load, Q, expected_Q);
                error_count = error_count + 1;
            end
        end

        // --- Summary ---
        $display("Testbench completed: %0d tests, %0d errors.", test_count, error_count);
        $fclose(fd);
        $finish;
    end

endmodule

