        // Exhaustive for C=0/1, O=0..15, A=0..15 (256*2=512 tests, but limit to 100+ for requirement)
        // We'll do all for C=0, O=0..7, A=0..7 (64), and random for the rest

        // Deterministic subset
        for (k = 0; k <= 1; k = k + 1) begin
            for (i = 0; i < 8; i = i + 1) begin
                for (j = 0; j < 8; j = j + 1) begin
                    O = i[3:0];
