                        expected_S = O + A;
                        expected_D = 4'b0;
                        expected_B = 1'b0;
                    end else begin
                        expected_S = 4'b0;
                        if (O < A) begin
                            expected_D = (O + 16) - A;
                            expected_B = 1'b1;
                        end else begin
                            expected_D = O - A;
                            expected_B = 1'b0;
                        end
                    end

