                    // Check outputs
                    check_outputs(O, A, C, S, D, B, expected_S, expected_D, expected_B);

                    test_count = test_count + 1;
                end
            end
        end

        // Randomized additional vectors to reach at least 100
        for (i = test_count; i < 120; i = i + 1) begin
            O = $random % 16;
            A = $random % 16;
            C = $random % 2;
            #1;

            // Calculate expected outputs
            if (C == 1'b1) begin
                expected_S = O + A;
                expected_D = 4'b0;
                expected_B = 1'b0;
            end else begin
