module barrel_shifter (
    input [3:0] a,
    input [3:0] b,
    input [1:0] mode,
    output reg [3:0] out
);

    wire [1:0] shift_amt;
    assign shift_amt = b[1:0]; // shift amount limited to 0~3

    always @(*) begin
        case (mode)
            2'b00: out = a << shift_amt;                      // logical left shift
            2'b01: out = a >> shift_amt;                      // logical right shift
            2'b10: out = $signed(a) >>> shift_amt;            // arithmetic right shift
            2'b11: begin                                      // rotate right
                case (shift_amt)
                    2'd0: out = a;
                    2'd1: out = {a[0], a[3:1]};
                    2'd2: out = {a[1:0], a[3:2]};
                    2'd3: out = {a[2:0], a[3]};
                    default: out = a;
                endcase
            end
            default: out = a;
        endcase
    end

endmodule

