module simple_calculator (
    input        clk,
    input        rst,
    input  [1:0] op,
    input  [7:0] a,
    input  [7:0] b,
    output reg [7:0] result,
    output reg      valid
);

    // Internal signals for calculation
    reg [7:0] calc_result;
    reg       next_valid;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            result <= 8'd0;
            valid  <= 1'b0;
        end else begin
            if (!valid) begin
                // Perform operation only if valid is low
                case (op)
                    2'b00: calc_result = a + b;                        // Addition
                    2'b01: calc_result = a - b;                        // Subtraction
                    2'b10: calc_result = a * b;                        // Multiplication
                    2'b11: calc_result = (b != 8'd0) ? (a / b) : 8'd0; // Division, output 0 on divide by zero
                    default: calc_result = 8'd0;
                endcase

                result <= calc_result;
                valid  <= 1'b1;
            end else begin
                // Wait for external clear via rst to become ready for a new operation
                // Remain in valid state
                result <= result;
                valid  <= valid;
            end
        end
    end

endmodule

