module simple_calculator_tb;

    // DUT inputs
    reg        clk;
    reg        rst;
    reg  [1:0] op;
    reg  [7:0] a;
    reg  [7:0] b;

    // DUT outputs
    wire [7:0] result;
    wire       valid;

    // File descriptor
    integer fd;
    integer error_count;
    integer test_count;
    integer i, j, k, l;

    // For checking expected results
    reg [7:0] expected_result;
    reg       expected_valid;

    // Timeout
    parameter TIMEOUT = 10000;

    // Instantiate DUT
    simple_calculator dut (
        .clk(clk),
        .rst(rst),
        .op(op),
        .a(a),
        .b(b),
        .result(result),
        .valid(valid)
    );

    // Clock generation
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    // Task to check result and report errors
    task check_result;
        input [1:0] op_t;
        input [7:0] a_t;
        input [7:0] b_t;
        input [7:0] result_t;
        input       valid_t;
        input [7:0] expected_result_t;
        input       expected_valid_t;
        begin
            if ((result_t !== expected_result_t) || (valid_t !== expected_valid_t)) begin
                $display("ERROR: op=%b a=%h b=%h result=%h(valid=%b) expected=%h(valid=%b) at time %0t",
                         op_t, a_t, b_t, result_t, valid_t, expected_result_t, expected_valid_t, $time);
                error_count = error_count + 1;
            end
        end
    endtask

    // Main stimulus
    initial begin
        fd = $fopen("test_vectors.txt", "w");
        if (fd)
            $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        error_count = 0;
        test_count = 0;

        // Reset DUT
        rst = 1;
        op = 0;
        a = 0;
        b = 0;
        @(negedge clk);
        @(negedge clk);
        rst = 0;

        // Test all opcodes with representative values (at least 100 vectors)
        // op: 2'b00 (add), 2'b01 (sub), 2'b10 (mul), 2'b11 (div)
        // For each op, test a variety of a, b including edge cases

        // Addition
        for (i = 0; i < 8; i = i + 1) begin
            for (j = 0; j < 8; j = j + 1) begin
                op = 2'b00;
                a = i * 32; // 0,32,64,96,128,160,192,224
                b = j * 31; // 0,31,62,93,124,155,186,217
                apply_and_check(op, a, b);
            end
        end

        // Subtraction
        for (i = 0; i < 8; i = i + 1) begin
            for (j = 0; j < 8; j = j + 1) begin
                op = 2'b01;
                a = i * 32;
                b = j * 31;
                apply_and_check(op, a, b);
            end
        end

        // Multiplication
        for (i = 0; i < 5; i = i + 1) begin
            for (j = 0; j < 5; j = j + 1) begin
                op = 2'b10;
                a = i * 51; // 0,51,102,153,204
                b = j * 53; // 0,53,106,159,212
                apply_and_check(op, a, b);
            end
        end

        // Division (including divide by zero)
        for (i = 0; i < 8; i = i + 1) begin
            for (j = 0; j < 8; j = j + 1) begin
                op = 2'b11;
                a = i * 32;
                b = j * 31; // b=0 will test divide by zero
                apply_and_check(op, a, b);
            end
        end

        // Some random vectors for extra coverage
        for (l = 0; l < 20; l = l + 1) begin
            op = $random % 4;
            a = $random;
            b = $random;
            apply_and_check(op, a, b);
        end

        $display("Total tests: %0d, Errors: %0d", test_count, error_count);
        $fclose(fd);
        $finish;
    end

    // Timeout mechanism
    initial begin
        #TIMEOUT;
        $display("ERROR: Simulation timed out at time %0t", $time);
        $fclose(fd);
        $finish;
    end

    // Task to apply stimulus, wait for result, check, and log
    task apply_and_check;
        input [1:0] op_in;
        input [7:0] a_in;
        input [7:0] b_in;
        begin
            // Apply inputs
            @(negedge clk);
            op = op_in;
            a = a_in;
            b = b_in;
            rst = 0;

            // Wait for valid to go high
            wait_for_valid();

            // Compute expected result
            case (op_in)
                2'b00: expected_result = a_in + b_in;
                2'b01: expected_result = a_in - b_in;
                2'b10: expected_result = a_in * b_in;
                2'b11: expected_result = (b_in != 8'd0) ? (a_in / b_in) : 8'd0;
                default: expected_result = 8'd0;
            endcase
            expected_valid = 1'b1;

            // Check result
            check_result(op_in, a_in, b_in, result, valid, expected_result, expected_valid);

            // Write to file: op[1:0] a[7:0] b[7:0] result[7:0] valid
            $fdisplay(fd, "%02b %02x %02x %02x %1b", op_in, a_in, b_in, result, valid);

            test_count = test_count + 1;

            // Deassert rst to clear valid for next operation
            @(negedge clk);
            rst = 1;
            @(negedge clk);
            rst = 0;
        end
    endtask

    // Task to wait for valid output
    task wait_for_valid;
        integer timeout_count;
        begin
            timeout_count = 0;
            while (valid !== 1'b1) begin
                @(negedge clk);
                timeout_count = timeout_count + 1;
                if (timeout_count > 20) begin
                    $display("ERROR: Timeout waiting for valid at time %0t", $time);
                    error_count = error_count + 1;
                    disable wait_for_valid;
                end
            end
        end
    endtask

endmodule

