module dff_async_reset_enable (
    input CLK,
    input D,
    input RESET_N,
    input ENABLE,
    output Q,
    output Q_N
);

    reg q_reg;

    assign Q = q_reg;
    assign Q_N = ~q_reg;

    always @(negedge RESET_N or posedge CLK) begin
        if (!RESET_N) begin
            q_reg <= 1'b0;
        end else begin
            if (ENABLE) begin
                q_reg <= D;
            end
            // If ENABLE is low, hold value (do nothing)
        end
    end

endmodule

test:
`timescale 1ns/1ps

module dff_async_reset_enable_tb;

    // Inputs
    reg CLK;
    reg D;
    reg RESET_N;
    reg ENABLE;

    // Outputs
    wire Q;
    wire Q_N;

    // Internal variables
    integer fd;
    integer error_count;
    integer test_count;
    integer i;
    reg expected_Q;
    reg expected_Q_N;
    reg q_model;

    // Instantiate the DUT
    dff_async_reset_enable dut (
        .CLK(CLK),
        .D(D),
        .RESET_N(RESET_N),
        .ENABLE(ENABLE),
        .Q(Q),
        .Q_N(Q_N)
    );

    // Clock generation
    initial begin
        CLK = 0;
        forever #5 CLK = ~CLK; // 10ns period
    end

    // Timeout mechanism
    initial begin
        #10000;
        $display("ERROR: Simulation timed out at time %0t", $time);
        $finish;
    end

    // Task to check DUT output against expected values
    task check_output;
        input [3:0] vector_num;
        begin
            if ((Q !== expected_Q) || (Q_N !== expected_Q_N)) begin
                $display("ASSERTION FAILED at time %0t: Test %0d: D=%b RESET_N=%b ENABLE=%b | Q=%b (exp %b) Q_N=%b (exp %b)",
                    $time, vector_num, D, RESET_N, ENABLE, Q, expected_Q, Q_N, expected_Q_N);
                error_count = error_count + 1;
            end
        end
    endtask

    // Main stimulus and checking
    initial begin
        // Open file for writing test vectors
        fd = $fopen("test_vectors.txt", "w");
        if (fd) $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        // Initialize
        error_count = 0;
        test_count = 0;
        D = 0;
        RESET_N = 1;
        ENABLE = 0;
        q_model = 0;
        expected_Q = 0;
        expected_Q_N = 1;

        // Apply initial reset
        @(negedge CLK);
        RESET_N = 0;
        @(negedge CLK);
        RESET_N = 1;
        @(negedge CLK);

        // Write header (optional, can be commented out)
        // $fdisplay(fd, "D RESET_N ENABLE Q Q_N");

        // Generate at least 100 test vectors with various input combinations
        for (i = 0; i < 100; i = i + 1) begin
            // Randomize inputs, but also cover all corners
            if (i < 16) begin
                // Exhaustive for first 16 vectors
                D       = (i >> 0) & 1;
                RESET_N = (i >> 1) & 1;
                ENABLE  = (i >> 2) & 1;
            end else begin
                // Random for rest
                D       = $random % 2;
                RESET_N = $random % 2;
                ENABLE  = $random % 2;
            end

            // Apply RESET_N asynchronously sometimes
            if (i % 20 == 0) begin
                RESET_N = 0;
                @(negedge CLK);
                // Model: reset
                q_model = 0;
                expected_Q = 0;
                expected_Q_N = 1;
                // Write vector
                $fdisplay(fd, "%b %b %b %b %b", D, RESET_N, ENABLE, Q, Q_N);
                check_output(i);
                RESET_N = 1;
                @(negedge CLK);
            end

            // Wait for clock edge, apply inputs
            @(negedge CLK);

            // Model behavior
            if (!RESET_N) begin
                q_model = 0;
            end else begin
                if (ENABLE) begin
                    q_model = D;
                end
                // else hold
            end
            expected_Q = q_model;
            expected_Q_N = ~q_model;

            // Write test vector to file: D RESET_N ENABLE Q Q_N
            $fdisplay(fd, "%b %b %b %b %b", D, RESET_N, ENABLE, Q, Q_N);

            // Assertion
            check_output(i);

            test_count = test_count + 1;
        end

        // Final report
        $display("Test completed: %0d vectors, %0d errors", test_count, error_count);

        $fclose(fd);
        $finish;
    end

endmodule

