  integer i;
  integer error_count;
  integer vector_count;
  reg [31:0] expected_counter;
  reg expected_clk_out;
  reg [31:0] counter_ref;
  reg clk_out_ref;

  // Timeout parameters
  integer TIMEOUT = 10000;

  // Instantiate DUT
  clock_divider #(.div(div)) uut (
    .clk_in(clk_in),
    .rst(rst),
    .clk_out(clk_out)
  );

  // Clock generation
  initial begin
    clk_in = 0;
    forever #5 clk_in = ~clk_in; // 10ns period
  end

  // Reference model for checking
  initial begin
    counter_ref = 0;
    clk_out_ref = 0;
    forever begin
      @(posedge clk_in or posedge rst);
      if (rst) begin
        counter_ref = 0;
        clk_out_ref = 0;
      end else begin
        if (counter_ref == div-1) begin
          counter_ref = 0;
          clk_out_ref = ~clk_out_ref;
        end else begin
          counter_ref = counter_ref + 1;
        end
      end
    end
  end

  // Task to check outputs
  task check_output;
    input reg actual_clk_out;
    input reg expected_clk_out;
    input integer vector_num;
    begin
      if (actual_clk_out !== expected_clk_out) begin
        $display("ERROR at vector %0d: clk_out=%b, expected=%b at time %0t", vector_num, actual_clk_out, expected_clk_out, $time);
        error_count = error_count + 1;
      end
    end
  endtask

  // Test sequence
  initial begin
    fd = $fopen("test_vectors.txt", "w");
    if (fd) $display("File opened successfully");
    else begin
      $display("Failed to open file");
      $finish;
    end

    error_count = 0;
    vector_count = 0;

    // Apply reset
    rst = 1;
    @(negedge clk_in);
    #1;
    $fdisplay(fd, "%b %b %b", clk_in, rst, clk_out);
    vector_count = vector_count + 1;
    @(negedge clk_in);
    #1;
    rst = 0;

    // Wait for reset deassertion
    @(negedge clk_in);
    #1;

    // Main test loop: generate at least 100 test vectors
    for (i = 0; i < 100; i = i + 1) begin
      // Randomly assert/deassert reset occasionally
      if ((i % 25) == 0 && i != 0) begin
        rst = 1;
        @(negedge clk_in);
        #1;
        $fdisplay(fd, "%b %b %b", clk_in, rst, clk_out);
        vector_count = vector_count + 1;
        @(negedge clk_in);
        #1;
        rst = 0;
      end

      @(negedge clk_in);
      #1;
      // Write test vector: clk_in rst clk_out
      $fdisplay(fd, "%b %b %b", clk_in, rst, clk_out);
      vector_count = vector_count + 1;

      // Check output
      check_output(clk_out, clk_out_ref, i);
    end

    // Additional test: hold reset for several cycles
    rst = 1;
    repeat (3) begin
      @(negedge clk_in);
      #1;
      $fdisplay(fd, "%b %b %b", clk_in, rst, clk_out);
      vector_count = vector_count + 1;
      check_output(clk_out, 0, vector_count);
    end
    rst = 0;

    // Run a few more cycles after reset
    repeat (10) begin
      @(negedge clk_in);
      #1;
      $fdisplay(fd, "%b %b %b", clk_in, rst, clk_out);
      vector_count = vector_count + 1;
      check_output(clk_out, clk_out_ref, vector_count);
    end

    $display("Test completed with %0d errors out of %0d vectors.", error_count, vector_count);
    $fclose(fd);
    $finish;
  end

  // Timeout mechanism
  initial begin
    #TIMEOUT;
    $display("ERROR: Simulation timed out at time %0t", $time);
    $fclose(fd);
    $finish;
  end

endmodule

