module synchronous_counter_tb;

    // Inputs
    reg clk;
    reg reset;
    reg enable;
    reg control;

    // Output
    wire [3:0] count;

    // File descriptor
    integer fd;
    integer i;
    integer error_count;
    reg [3:0] expected_count;
    reg [3:0] prev_count;

    // Instantiate the Unit Under Test (UUT)
    synchronous_counter uut (
        .clk(clk),
        .reset(reset),
        .enable(enable),
        .control(control),
        .count(count)
    );

    // Clock generation: 10ns period
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    // Timeout mechanism: finish after 10000ns
    initial begin
        #10000;
        $display("Timeout reached at time %0t. Finishing simulation.", $time);
        $finish;
    end

    // Error checking task
    task check_output;
        input [3:0] expected;
        input [3:0] actual;
        input [31:0] vector_num;
        begin
            if (expected !== actual) begin
                $display("ERROR at vector %0d, time %0t: expected %0d, got %0d", vector_num, $time, expected, actual);
                error_count = error_count + 1;
            end
        end
    endtask

    // Main stimulus and checking
    initial begin
        // Open file for writing test vectors
        fd = $fopen("test_vectors.txt", "w");
        if (fd)
            $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        error_count = 0;
        expected_count = 0;
        prev_count = 0;

        // Initialize inputs
        reset = 1;
        enable = 0;
        control = 0;

        // Apply reset
        @(negedge clk);
        @(negedge clk);
        reset = 0;

        // Test 1: Check reset
        @(negedge clk);
        reset = 1;
        enable = 0;
        control = 0;
        @(negedge clk);
        expected_count = 0;
        $fdisplay(fd, "%b %b %b %b %b", clk, reset, enable, control, count);
        check_output(expected_count, count, 1);

        // Release reset
        reset = 0;
        @(negedge clk);

        // Test 2: Enable counting up
        enable = 1;
        control = 1;
        for (i = 2; i <= 26; i = i + 1) begin
            prev_count = expected_count;
            if (reset)
                expected_count = 0;
            else if (enable) begin
                if (control)
                    expected_count = prev_count + 1;
                else
                    expected_count = prev_count - 1;
            end
            else
                expected_count = prev_count;

            @(negedge clk);
            $fdisplay(fd, "%b %b %b %b %b", clk, reset, enable, control, count);
            check_output(expected_count, count, i);
        end

        // Test 3: Enable counting down
        control = 0;
        for (i = 27; i <= 51; i = i + 1) begin
            prev_count = expected_count;
            if (reset)
                expected_count = 0;
            else if (enable) begin
                if (control)
                    expected_count = prev_count + 1;
                else
                    expected_count = prev_count - 1;
            end
            else
                expected_count = prev_count;

            @(negedge clk);
            $fdisplay(fd, "%b %b %b %b %b", clk, reset, enable, control, count);
            check_output(expected_count, count, i);
        end

        // Test 4: Disable enable, should hold value
        enable = 0;
        for (i = 52; i <= 61; i = i + 1) begin
            prev_count = expected_count;
            if (reset)
                expected_count = 0;
            else if (enable) begin
                if (control)
                    expected_count = prev_count + 1;
                else
                    expected_count = prev_count - 1;
            end
            else
                expected_count = prev_count;

            @(negedge clk);
            $fdisplay(fd, "%b %b %b %b %b", clk, reset, enable, control, count);
            check_output(expected_count, count, i);
        end

        // Test 5: Randomized test vectors
        for (i = 62; i <= 100; i = i + 1) begin
            reset = $random % 2;
            enable = $random % 2;
            control = $random % 2;
            prev_count = expected_count;

            @(negedge clk);

            if (reset)
                expected_count = 0;
            else if (enable) begin
                if (control)
                    expected_count = prev_count + 1;
                else
                    expected_count = prev_count - 1;
            end
            else
                expected_count = prev_count;

            $fdisplay(fd, "%b %b %b %b %b", clk, reset, enable, control, count);
            check_output(expected_count, count, i);
        end

        // Close file and finish
        $fclose(fd);
        $display("Test completed with %0d errors.", error_count);
        $finish;
    end

