`timescale 1ns/1ps

module dff_sr_tb;

    // DUT signals
    reg  D;
    reg  CLK;
    reg  SET_B;
    reg  RESET_B;
    wire Q;
    wire Q_N;

    // File handling
    integer fd;
    integer error_count;
    integer vector_count;
    integer i;

    // For reference model
    reg ref_Q;
    reg ref_Q_N;

    // Timeout
    parameter TIMEOUT = 10000;

    // Instantiate DUT
    dff_sr dut (
        .Q(Q),
        .Q_N(Q_N),
        .D(D),
        .CLK(CLK),
        .SET_B(SET_B),
        .RESET_B(RESET_B)
    );

    // Clock generation
    initial begin
        CLK = 0;
        forever #5 CLK = ~CLK;
    end

    // Reference model: mimics the DUT's behavior for checking
    task ref_model;
        input D_in, CLK_in, SET_B_in, RESET_B_in;
        inout ref_Q;
        begin
            if (~RESET_B_in)
                ref_Q = 1'b0;
            else if (~SET_B_in)
                ref_Q = 1'b1;
            else if (CLK_in)
                ref_Q = D_in;
        end
    endtask

    // Error check task
    task check_outputs;
        input [31:0] vec_num;
        begin
            if ((Q !== ref_Q) || (Q_N !== ~ref_Q)) begin
                $display("Mismatch at vector %0d: Inputs: D=%b CLK=%b SET_B=%b RESET_B=%b | DUT: Q=%b Q_N=%b | REF: Q=%b Q_N=%b | Time=%0t",
                    vec_num, D, CLK, SET_B, RESET_B, Q, Q_N, ref_Q, ~ref_Q, $time);
                error_count = error_count + 1;
            end
        end
    endtask

    // Main stimulus
    initial begin
        fd = $fopen("test_vectors.txt", "w");
        if (fd) $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        error_count = 0;
        vector_count = 0;
        ref_Q = 0;
        ref_Q_N = 1;

        // Initialize inputs
        D = 0;
        SET_B = 1;
        RESET_B = 1;

        // Wait for reset
        #2;

        // Test asynchronous RESET_B and SET_B
        // RESET_B asserted (active low)
        D = 1; SET_B = 1; RESET_B = 0; #3;
        @(negedge CLK);
        ref_model(D, CLK, SET_B, RESET_B, ref_Q);
        $fdisplay(fd, "%b %b %b %b %b %b", D, CLK, SET_B, RESET_B, Q, Q_N);
        check_outputs(vector_count); vector_count = vector_count + 1;

        // SET_B asserted (active low), RESET_B deasserted
        D = 0; SET_B = 0; RESET_B = 1; #3;
        @(negedge CLK);
        ref_model(D, CLK, SET_B, RESET_B, ref_Q);
        $fdisplay(fd, "%b %b %b %b %b %b", D, CLK, SET_B, RESET_B, Q, Q_N);
        check_outputs(vector_count); vector_count = vector_count + 1;

        // Both asserted (RESET_B has priority)
        D = 1; SET_B = 0; RESET_B = 0; #3;
        @(negedge CLK);
        ref_model(D, CLK, SET_B, RESET_B, ref_Q);
        $fdisplay(fd, "%b %b %b %b %b %b", D, CLK, SET_B, RESET_B, Q, Q_N);
        check_outputs(vector_count); vector_count = vector_count + 1;

        // Both deasserted
        D = 0; SET_B = 1; RESET_B = 1; #3;
        @(negedge CLK);
        ref_model(D, CLK, SET_B, RESET_B, ref_Q);
        $fdisplay(fd, "%b %b %b %b %b %b", D, CLK, SET_B, RESET_B, Q, Q_N);
        check_outputs(vector_count); vector_count = vector_count + 1;

        // Now, test all combinations over 100 vectors
        for (i = 0; i < 100; i = i + 1) begin
            // Randomize inputs
            D = $random % 2;
            SET_B = $random % 2;
            RESET_B = $random % 2;

            // Wait for a clock edge or async event
            #2;
            if (~RESET_B || ~SET_B) begin
                // Async event
                ref_model(D, CLK, SET_B, RESET_B, ref_Q);
                #1;
                $fdisplay(fd, "%b %b %b %b %b %b", D, CLK, SET_B, RESET_B, Q, Q_N);
                check_outputs(vector_count); vector_count = vector_count + 1;
            end else begin
                // Synchronous event: wait for posedge CLK
                @(posedge CLK);
                ref_model(D, 1'b1, SET_B, RESET_B, ref_Q);
                #1;
                $fdisplay(fd, "%b %b %b %b %b %b", D, CLK, SET_B, RESET_B, Q, Q_N);
                check_outputs(vector_count); vector_count = vector_count + 1;
            end

            // Timeout check
            if ($time > TIMEOUT) begin
                $display("Timeout reached at time %0t", $time);
                $fclose(fd);
                $finish;
            end
        end

        $display("Simulation completed. Total vectors: %0d, Errors: %0d", vector_count, error_count);
        $fclose(fd);
        $finish;
    end

    // Timeout mechanism
    initial begin
        #TIMEOUT;
        $display("Simulation timeout after %0d ns", TIMEOUT);
        $fclose(fd);
        $finish;
    end

endmodule

