        input reg exp_sum;
        input reg exp_cout;
        begin
            if (SUM !== exp_sum) begin
                $display("ERROR at time %0t: A=%b B=%b CIN=%b VPWR=%b VGND=%b VPB=%b VNB=%b | SUM=%b (expected %b)", 
                    $time, A, B, CIN, VPWR, VGND, VPB, VNB, SUM, exp_sum);
                error_count = error_count + 1;
            end
            if (COUT !== exp_cout) begin
                $display("ERROR at time %0t: A=%b B=%b CIN=%b VPWR=%b VGND=%b VPB=%b VNB=%b | COUT=%b (expected %b)", 
                    $time, A, B, CIN, VPWR, VGND, VPB, VNB, COUT, exp_cout);
                error_count = error_count + 1;
            end
        end
    endtask

    // Main stimulus
    initial begin
        error_count = 0;
        test_count = 0;

        fd = $fopen("test_vectors.txt", "w");
        if (fd) $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        // Write header
        $fdisplay(fd, "A B CIN VPWR VGND VPB VNB COUT SUM");

        // Exhaustive test for logic inputs (A, B, CIN) and representative supply combinations
        // For 100+ vectors, use all 8 logic combinations and 16 supply combinations (8*16=128)
        for (i = 0; i < 128; i = i + 1) begin
            abc = i[2:0];
            supply_vec = i[6:3];

            // Assign logic inputs
            A    = abc[2];
            B    = abc[1];
            CIN  = abc[0];

            // Assign supply pins
            VPWR = supply_vec[3];
            VGND = supply_vec[2];
            VPB  = supply_vec[1];
            VNB  = supply_vec[0];

            // Wait for signals to propagate
            #1;

            // Compute expected outputs only if supply is valid (VPWR=1, VGND=0)
            if (VPWR === 1'b1 && VGND === 1'b0) begin
                expected_sum  = A ^ B ^ CIN;
                expected_cout = (A & B) | (B & CIN) | (A & CIN);
