      $finish;
    end

    error_count = 0;
    test_num = 0;

    // Initialize inputs
    rst = 0;
    set = 0;
    en = 0;
    expected_cnt = 6'b0;

    // Wait for global reset
    #12;

    // Test 1: Reset functionality
    rst = 1;
    set = 0;
    en = 0;
    @(negedge clk);
    @(negedge clk);
    expected_cnt = 6'b0;
    write_vector_and_check();
    rst = 0;

    // Test 2: Set functionality
    set = 1;
    en = 0;
    @(negedge clk);
    expected_cnt = 6'b111111;
    write_vector_and_check();
    set = 0;

    // Test 3: Enable counting from set value
    en = 1;
    repeat (5) begin
      @(negedge clk);
      expected_cnt = expected_cnt + 1;
      write_vector_and_check();
    end
    en = 0;

    // Test 4: Reset while counting
    rst = 1;
    @(negedge clk);
    expected_cnt = 6'b0;
    write_vector_and_check();
    rst = 0;

    // Test 5: Set while counting
    set = 1;
    @(negedge clk);
    expected_cnt = 6'b111111;
    write_vector_and_check();
    set = 0;

    // Test 6: Enable counting from set value, wrap around
    en = 1;
    repeat (3) begin
      @(negedge clk);
      expected_cnt = expected_cnt + 1;
      write_vector_and_check();
    end
    en = 0;

    // Test 7: No enable, counter should hold
    repeat (3) begin
      @(negedge clk);
      write_vector_and_check();
    end

    // Test 8: Simultaneous rst and set (rst has priority)
    rst = 1;
    set = 1;
    en = 1;
    @(negedge clk);
    expected_cnt = 6'b0;
    write_vector_and_check();
    rst = 0;
    set = 0;
    en = 0;

    // Test 9: Simultaneous set and en (set has priority)
    set = 1;
    en = 1;
    @(negedge clk);
    expected_cnt = 6'b111111;
    write_vector_and_check();
    set = 0;
    en = 0;

    // Test 10: Counting up to wrap around (from 6'b111111 to 6'b000000)
    en = 1;
    repeat (2) begin
      @(negedge clk);
      expected_cnt = expected_cnt + 1;
      write_vector_and_check();
    end
    en = 0;

    // Test 11: Randomized test vectors (at least 90 more)
    for (i = 0; i < 90; i = i + 1) begin
      // Randomize inputs
      rst = $random % 2;
      set = $random % 2;
      en  = $random % 2;
