module comparator_2bit (
    input [1:0] A,
    input [1:0] B,
    output [1:0] EQ,
    output [1:0] GT
);

    // EQ[1] = ~(A[1] ^ B[1])
    wire x1;
    xor (x1, A[1], B[1]);
    not (EQ[1], x1);

    // EQ[0] = ~(A[0] ^ B[0])
    wire x0;
    xor (x0, A[0], B[0]);
    not (EQ[0], x0);

    // GT[1] = A[1] & ~B[1]
    wire nb1;
    not (nb1, B[1]);
    and (GT[1], A[1], nb1);

    // GT[0] = A[0] & ~B[0]
    wire nb0;
    not (nb0, B[0]);
    and (GT[0], A[0], nb0);

endmodule

