module shift_register (
    input wire clk,
    input wire rst,
    input wire [3:0] data_in,
    input wire shift,      // 0: parallel load, 1: shift mode
    input wire dir,        // 0: shift right, 1: shift left (only used in shift mode)
    output reg [3:0] data_out
);

reg [3:0] reg_data;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        reg_data <= 4'b0000;
    end else begin
        if (!shift) begin
            // Parallel load mode
            reg_data <= data_in;
        end else begin
            // Shift mode
            if (dir == 1'b0) begin
                // Shift right, MSB gets 0
                reg_data <= {1'b0, reg_data[3:1]};
            end else begin
                // Shift left, LSB gets 0
                reg_data <= {reg_data[2:0], 1'b0};
            end
        end
    end
end

always @(*) begin
    data_out = reg_data;
end

endmodule

