                $display("ASSERTION FAILED at time %0t: %s Expected: %b, Got: %b", $time, tname, expected, actual);
                error_count = error_count + 1;
            end
        end
    endtask

    // Main stimulus and test vector generation
    initial begin
        fd = $fopen("test_vectors.txt", "w");
        if (fd) $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        error_count = 0;
        test_count = 0;

        // Apply reset
        rst = 1;
        data_in = 4'b0000;
        shift = 0;
        dir = 0;
        @(negedge clk);
        @(negedge clk);
        rst = 0;
        reg_model = 4'b0000;

        // Test 1: Parallel load all possible data_in values
        for (i = 0; i < 16; i = i + 1) begin
            data_in = i[3:0];
            shift = 0;
            dir = 0; // Don't care in parallel load
            @(negedge clk);
            reg_model = data_in;
            #1;
            $fdisplay(fd, "%b %b %b %b %b %b", clk, rst, data_in, shift, dir, data_out);
            testname = "Parallel load";
            check_output(reg_model, data_out, testname);
            test_count = test_count + 1;
        end

        // Test 2: Shift right from all possible initial values
        for (i = 0; i < 16; i = i + 1) begin
            // Parallel load
            data_in = i[3:0];
            shift = 0;
            dir = 0;
            @(negedge clk);
            reg_model = data_in;
            #1;
            $fdisplay(fd, "%b %b %b %b %b %b", clk, rst, data_in, shift, dir, data_out);
            testname = "Shift right init";
            check_output(reg_model, data_out, testname);
            test_count = test_count + 1;

            // Shift right 3 times
            shift = 1;
            dir = 0;
            for (j = 0; j < 3; j = j + 1) begin
                @(negedge clk);
                reg_model = {1'b0, reg_model[3:1]};
                #1;
                $fdisplay(fd, "%b %b %b %b %b %b", clk, rst, data_in, shift, dir, data_out);
                testname = "Shift right";
                check_output(reg_model, data_out, testname);
                test_count = test_count + 1;
            end
        end

        // Test 3: Shift left from all possible initial values
        for (i = 0; i < 16; i = i + 1) begin
            // Parallel load
            data_in = i[3:0];
            shift = 0;
            dir = 1;
            @(negedge clk);
            reg_model = data_in;
            #1;
            $fdisplay(fd, "%b %b %b %b %b %b", clk, rst, data_in, shift, dir, data_out);
            testname = "Shift left init";
            check_output(reg_model, data_out, testname);
            test_count = test_count + 1;

            // Shift left 3 times
            shift = 1;
            dir = 1;
            for (j = 0; j < 3; j = j + 1) begin
                @(negedge clk);
                reg_model = {reg_model[2:0], 1'b0};
                #1;
                $fdisplay(fd, "%b %b %b %b %b %b", clk, rst, data_in, shift, dir, data_out);
                testname = "Shift left";
                check_output(reg_model, data_out, testname);
                test_count = test_count + 1;
            end
        end

        // Test 4: Reset during operation
        data_in = 4'b1010;
        shift = 0;
        dir = 0;
        @(negedge clk);
        reg_model = data_in;
        #1;
        $fdisplay(fd, "%b %b %b %b %b %b", clk, rst, data_in, shift, dir, data_out);
        testname = "Pre-reset";
        check_output(reg_model, data_out, testname);
        test_count = test_count + 1;

        // Now shift right once
        shift = 1;
        dir = 0;
        @(negedge clk);
        reg_model = {1'b0, reg_model[3:1]};
        #1;
        $fdisplay(fd, "%b %b %b %b %b %b", clk, rst, data_in, shift, dir, data_out);
        testname = "Pre-reset shift";
        check_output(reg_model, data_out, testname);
        test_count = test_count + 1;

        // Assert reset
        rst = 1;
        @(negedge clk);
        reg_model = 4'b0000;
        #1;
        $fdisplay(fd, "%b %b %b %b %b %b", clk, rst, data_in, shift, dir, data_out);
        testname = "Reset";
        check_output(reg_model, data_out, testname);
        test_count = test_count + 1;
        rst = 0;

        // Test 5: Mixed operations
        // Parallel load
        data_in = 4'b1100;
        shift = 0;
        dir = 0;
        @(negedge clk);
        reg_model = data_in;
        #1;
        $fdisplay(fd, "%b %b %b %b %b %b", clk, rst, data_in, shift, dir, data_out);
        testname = "Mixed load";
        check_output(reg_model, data_out, testname);
        test_count = test_count + 1;

        // Shift left
        shift = 1;
        dir = 1;
        @(negedge clk);
        reg_model = {reg_model[2:0], 1'b0};
        #1;
        $fdisplay(fd, "%b %b %b %b %b %b", clk, rst, data_in, shift, dir, data_out);
        testname = "Mixed shift left";
        check_output(reg_model, data_out, testname);
        test_count = test_count + 1;

        // Shift right
        shift = 1;
        dir = 0;
        @(negedge clk);
        reg_model = {1'b0, reg_model[3:1]};
        #1;
        $fdisplay(fd, "%b %b %b %b %b %b", clk, rst, data_in, shift, dir, data_out);
        testname = "Mixed shift right";
        check_output(reg_model, data_out, testname);
        test_count = test_count + 1;

        // Parallel load again
        shift = 0;
        data_in = 4'b0011;
        @(negedge clk);
        reg_model = data_in;
        #1;
        $fdisplay(fd, "%b %b %b %b %b %b", clk, rst, data_in, shift, dir, data_out);
        testname = "Mixed load2";
        check_output(reg_model, data_out, testname);
        test_count = test_count + 1;

        // Final report
        $display("Testbench completed: %0d tests, %0d errors", test_count, error_count);
        $fclose(fd);
        $finish;
    end

endmodule

