                $display("ASSERTION FAILED: in=%b shift=%b out=%b expected=%b at time %0t", in_v, shift_v, out_v, expected_v, $time);
                error_count = error_count + 1;
            end
        end
    endtask

    // Main stimulus
    initial begin
        fd = $fopen("test_vectors.txt", "w");
        if (fd) $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        error_count = 0;
        test_count = 0;

        // Test all shift types for a wide range of inputs
        // 16 (all) input values x 4 shift types = 64
        // Add 36 random/edge cases for at least 100 vectors

        // Exhaustive for all inputs and shift types
        for (i = 0; i < 16; i = i + 1) begin
            for (j = 0; j < 4; j = j + 1) begin
                in = i[3:0];
                shift = j[1:0];
                #1; // Allow combinational logic to settle

                // Compute expected output
                case (shift)
                    2'b00: expected_out = in << 1; // Logical left shift
                    2'b01: expected_out = in >> 1; // Logical right shift
                    2'b10: expected_out = in << 1; // Arithmetic left shift (same as logical)
                    2'b11: expected_out = {in[3], in[3:1]}; // Arithmetic right shift
                    default: expected_out = 4'b0000;
                endcase

                // Write test vector: in[3:0] shift[1:0] out[3:0]
                $fdisplay(fd, "%b%b %b", in, shift, out);

                // Assertion
                check_output(in, shift, out, expected_out);

                test_count = test_count + 1;
            end
        end

        // Add 36 more random/edge test cases
        repeat (36) begin
            in = $random % 16;
            shift = $random % 4;
            #1;

            case (shift)
                2'b00: expected_out = in << 1;
                2'b01: expected_out = in >> 1;
                2'b10: expected_out = in << 1;
                2'b11: expected_out = {in[3], in[3:1]};
                default: expected_out = 4'b0000;
            endcase

            $fdisplay(fd, "%b%b %b", in, shift, out);

            check_output(in, shift, out, expected_out);

            test_count = test_count + 1;
        end

        $display("Testbench completed: %0d tests, %0d errors", test_count, error_count);
        $fclose(fd);
        $finish;
    end

endmodule

