        // $fdisplay(fd, "d clk ena clrn prn | q");

        // Initialize all signals
        d = 0;
        ena = 0;
        clrn = 1;
        prn = 1;

        // Wait for global reset
        #10;

        // Test asynchronous clear (clrn)
        d = 1; ena = 1; clrn = 1; prn = 1;
        @(negedge clk);
        #1;
        clrn = 0;
        #1;
        @(negedge clk);
        #1;
        $fdisplay(fd, "%b %b %b %b %b %b", d, clk, ena, clrn, prn, q);
        check_output(1'b0);
        test_count = test_count + 1;
        clrn = 1;
        #2;

        // Test asynchronous preset (prn)
        d = 0; ena = 1; clrn = 1; prn = 1;
        @(negedge clk);
        #1;
        prn = 0;
        #1;
        @(negedge clk);
        #1;
        $fdisplay(fd, "%b %b %b %b %b %b", d, clk, ena, clrn, prn, q);
        check_output(1'b1);
        test_count = test_count + 1;
        prn = 1;
        #2;

        // Test synchronous load with enable
        d = 1; ena = 1; clrn = 1; prn = 1;
        @(negedge clk);
        @(posedge clk);
        #1;
        $fdisplay(fd, "%b %b %b %b %b %b", d, clk, ena, clrn, prn, q);
        check_output(1'b1);
        test_count = test_count + 1;

        d = 0; ena = 1;
        @(negedge clk);
        @(posedge clk);
        #1;
        $fdisplay(fd, "%b %b %b %b %b %b", d, clk, ena, clrn, prn, q);
        check_output(1'b0);
        test_count = test_count + 1;

        // Test synchronous load with enable low (should hold value)
        d = 1; ena = 0;
        @(negedge clk);
        @(posedge clk);
        #1;
        $fdisplay(fd, "%b %b %b %b %b %b", d, clk, ena, clrn, prn, q);
        check_output(1'b0);
        test_count = test_count + 1;

        // Test all input combinations (except clk, which is toggling)
        for (i = 0; i < 32; i = i + 1) begin
            {d, ena, clrn, prn} = i[3:0];
            // Avoid illegal state where both clrn and prn are low
            if (!(clrn == 0 && prn == 0)) begin
                @(negedge clk);
                @(posedge clk);
                #1;
                $fdisplay(fd, "%b %b %b %b %b %b", d, clk, ena, clrn, prn, q);
                // Expected behavior
                if (!clrn)
                    check_output(1'b0);
                else if (!prn)
                    check_output(1'b1);
                else if (ena)
                    check_output(d);
                // else hold previous value (cannot check without knowing previous)
                test_count = test_count + 1;
            end
        end

        // Randomized test vectors to reach at least 100 tests
        repeat (100 - test_count) begin
            d = $random % 2;
            ena = $random % 2;
            clrn = $random % 2;
            prn = $random % 2;
