                else if (!prn)
                    check_output(1'b1);
                else if (ena)
                    check_output(d);
                test_count = test_count + 1;
            end
        end

        $display("Test completed. Total tests: %0d, Errors: %0d", test_count, error_count);

        $fclose(fd);
        $finish;
    end

