module square_wave_generator(
    input wire clk,
    output reg square_wave
);

    // 50MHz / 500 = 100kHz toggle rate, so period is 1kHz (toggle every 500 clk cycles)
    reg [8:0] counter; // 9 bits is enough to count to 500

    always @(posedge clk) begin
        if (counter == 499) begin
            counter <= 0;
            square_wave <= ~square_wave;
        end else begin
            counter <= counter + 1;
        end
    end

    // Initialize outputs and counter (synthesizable in most tools, ignored in simulation for iverilog)
    initial begin
        counter = 0;
        square_wave = 0;
    end

endmodule

