  address,
  clock,
  reset_n,

  // outputs:
  readdata
);

test:
`timescale 1ns/1ps

module soc_design_SystemID_tb;

  // Inputs
  reg [31:0] address;
  reg clock;
  reg reset_n;

  // Outputs
  wire [31:0] readdata;

  // DUT instantiation
  soc_design_SystemID dut (
    .address(address),
    .clock(clock),
    .reset_n(reset_n),
    .readdata(readdata)
  );

  // File handling
  integer fd;
  integer error_count;
  integer i;
  reg [31:0] test_addr [0:99];
  reg [31:0] expected_readdata;
  reg [31:0] observed_readdata;

  // Clock generation
  initial begin
    clock = 0;
    forever #5 clock = ~clock;
  end

  // Timeout mechanism
  initial begin
    #10000;
    $display("ERROR: Simulation timed out!");
    $finish;
  end

  // Test vector generation
  initial begin
    // Open file
    fd = $fopen("test_vectors.txt", "w");
    if (fd) $display("File opened successfully");
    else begin
      $display("Failed to open file");
      $finish;
    end

    error_count = 0;

    // Generate test addresses
    test_addr[0] = 32'h0;
    test_addr[1] = 32'h1;
    test_addr[2] = 32'hFFFFFFFF;
    test_addr[3] = 32'h590d8d31;
    test_addr[4] = 32'hFF;
    test_addr[5] = 32'hA5A5A5A5;
    test_addr[6] = 32'h5A5A5A5A;
    test_addr[7] = 32'h0000FFFF;
    test_addr[8] = 32'hFFFF0000;
    test_addr[9] = 32'h12345678;
    // Fill the rest with random values
    for (i = 10; i < 100; i = i + 1) begin
      test_addr[i] = $random;
    end

    // Reset sequence
    address = 32'h0;
    reset_n = 0;
    @(negedge clock);
    @(negedge clock);
    reset_n = 1;
    @(negedge clock);

    // Test with reset asserted
    address = 32'h0;
    reset_n = 0;
    @(negedge clock);
    #1;
    observed_readdata = readdata;
    expected_readdata = 32'h0;
    $fdisplay(fd, "%h %b %h %h", address, reset_n, observed_readdata, expected_readdata);
    if (observed_readdata !== expected_readdata) begin
      $display("ERROR: Reset test failed. address=%h reset_n=%b readdata=%h expected=%h", address, reset_n, observed_readdata, expected_readdata);
      error_count = error_count + 1;
    end
    reset_n = 1;
    @(negedge clock);

    // Main test loop
    for (i = 0; i < 100; i = i + 1) begin
      address = test_addr[i];
      @(negedge clock);
      #1;
      observed_readdata = readdata;
      if (address == 32'h0)
        expected_readdata = 32'hff;
      else
        expected_readdata = 32'h590d8d31;

      $fdisplay(fd, "%h %b %h %h", address, reset_n, observed_readdata, expected_readdata);

      // Assertion
      if (observed_readdata !== expected_readdata) begin
        $display("ERROR: Test %0d failed. address=%h reset_n=%b readdata=%h expected=%h", i, address, reset_n, observed_readdata, expected_readdata);
        error_count = error_count + 1;
      end
    end

    // Test with reset in the middle
    address = 32'h1;
    reset_n = 0;
    @(negedge clock);
    #1;
    observed_readdata = readdata;
    expected_readdata = 32'h0;
    $fdisplay(fd, "%h %b %h %h", address, reset_n, observed_readdata, expected_readdata);
    if (observed_readdata !== expected_readdata) begin
      $display("ERROR: Mid-test reset failed. address=%h reset_n=%b readdata=%h expected=%h", address, reset_n, observed_readdata, expected_readdata);
      error_count = error_count + 1;
    end
    reset_n = 1;
    @(negedge clock);

    // Close file
    $fclose(fd);

    // Report results
    if (error_count == 0)
      $display("All tests PASSED.");
    else
      $display("Total errors: %0d", error_count);

    $finish;
