module clock_gate_tb;

  // Inputs
  reg CLK;
  reg EN;
  reg TE;
  reg RST;

  // Output
  wire ENCLK;

  // DUT instantiation
  clock_gate dut (
    .CLK(CLK),
    .EN(EN),
    .TE(TE),
    .RST(RST),
    .ENCLK(ENCLK)
  );

  // File descriptor
  integer fd;
  integer error_count;
  integer test_count;
  integer i;
  reg expected_ENCLK;
  reg prev_ENCLK;

  // Timeout mechanism
  parameter TIMEOUT = 10000;

  // Clock generation
  initial begin
    CLK = 0;
    forever #5 CLK = ~CLK;
  end

  // Test vector generation and checking
  initial begin
    fd = $fopen("test_vectors.txt", "w");
    if (fd) $display("File opened successfully");
    else begin
      $display("Failed to open file");
      $finish;
    end

    error_count = 0;
    test_count = 0;

    // Write header
    $fdisplay(fd, "CLK EN TE RST | ENCLK");

    // Initialize signals
    EN = 0;
    TE = 0;
    RST = 0;
    prev_ENCLK = 0;

    // Wait for global reset
    #12;

    // Exhaustive test for all input combinations over several clock cycles
    for (i = 0; i < 100; i = i + 1) begin
      // Randomize inputs
      EN = $random % 2;
      TE = $random % 2;
      RST = $random % 2;

      // Wait for posedge
      @(posedge CLK);

      // Compute expected output
      if (RST) begin
        expected_ENCLK = 1'b0;
      end else if (EN) begin
        expected_ENCLK = CLK;
      end else begin
        expected_ENCLK = 1'b0;
      end

      // Wait for output to settle
      #1;

      // Write test vector to file
      $fdisplay(fd, "%b %b %b %b | %b", CLK, EN, TE, RST, ENCLK);

      // Assertion
      if (ENCLK !== expected_ENCLK) begin
        $display("ERROR at time %0t: CLK=%b EN=%b TE=%b RST=%b | ENCLK=%b (expected %b)", $time, CLK, EN, TE, RST, ENCLK, expected_ENCLK);
        error_count = error_count + 1;
      end

      test_count = test_count + 1;

      // Timeout check
      if ($time > TIMEOUT) begin
        $display("TIMEOUT: Simulation exceeded %0d time units", TIMEOUT);
        $fclose(fd);
        $finish;
      end
    end

    // Additional edge case tests
    // Test reset
    EN = 1; TE = 0; RST = 1;
    @(posedge CLK); #1;
    $fdisplay(fd, "%b %b %b %b | %b", CLK, EN, TE, RST, ENCLK);
    if (ENCLK !== 1'b0) begin
      $display("ERROR at time %0t: Reset failed. ENCLK=%b (expected 0)", $time, ENCLK);
      error_count = error_count + 1;
    end
    test_count = test_count + 1;

    // Test enable
    EN = 1; TE = 0; RST = 0;
    @(posedge CLK); #1;
    $fdisplay(fd, "%b %b %b %b | %b", CLK, EN, TE, RST, ENCLK);
    if (ENCLK !== CLK) begin
      $display("ERROR at time %0t: Enable failed. ENCLK=%b (expected %b)", $time, ENCLK, CLK);
      error_count = error_count + 1;
    end
    test_count = test_count + 1;

    // Test disable
    EN = 0; TE = 0; RST = 0;
    @(posedge CLK); #1;
    $fdisplay(fd, "%b %b %b %b | %b", CLK, EN, TE, RST, ENCLK);
    if (ENCLK !== 1'b0) begin
      $display("ERROR at time %0t: Disable failed. ENCLK=%b (expected 0)", $time, ENCLK);
      error_count = error_count + 1;
    end
    test_count = test_count + 1;

    // Test with TE high (should have no effect)
    EN = 1; TE = 1; RST = 0;
    @(posedge CLK); #1;
    $fdisplay(fd, "%b %b %b %b | %b", CLK, EN, TE, RST, ENCLK);
    if (ENCLK !== CLK) begin
      $display("ERROR at time %0t: TE high failed. ENCLK=%b (expected %b)", $time, ENCLK, CLK);
      error_count = error_count + 1;
    end
    test_count = test_count + 1;

    // Final report
    $display("Testbench completed: %0d tests, %0d errors", test_count, error_count);

    $fclose(fd);
    $finish;
  end

  // Timeout mechanism (independent)
  initial begin
    #TIMEOUT;
    $display("TIMEOUT: Simulation exceeded %0d time units", TIMEOUT);
    $finish;
  end

endmodule

