module adder_subtractor_4bit (
    input  [3:0] A,
    input  [3:0] B,
    input        C,          // Control: 0 = add, 1 = subtract
    output [3:0] S,
    output       C_out
);
    wire [3:0] B_xor_C;
    wire       carry_out;
    wire [4:0] sum; // 4 bits + carry

    // For subtraction, invert B (C=1), for addition pass B as is (C=0)
    assign B_xor_C = B ^ {4{C}};

    // Perform operation: A + (B xor C) + C
    // When C=0: A + B + 0
    // When C=1: A + (~B) + 1 = A - B (2's complement)
    assign sum = {1'b0, A} + {1'b0, B_xor_C} + C;

    assign S     = sum[3:0];
    assign C_out = sum[4];

endmodule

