    // 3. divisor = max value
    div = 32'h0000_0000; divisor = 32'hFFFF_FFFF; #1;
    expected_rem = 32'h0000_0000 % 32'hFFFF_FFFF;
    $fdisplay(fd, "%h %h %h", div, divisor, rem);
    check_result(div, divisor, rem, expected_rem);

    div = 32'hFFFF_FFFF; divisor = 32'hFFFF_FFFF; #1;
    expected_rem = 32'hFFFF_FFFF % 32'hFFFF_FFFF;
    $fdisplay(fd, "%h %h %h", div, divisor, rem);
    check_result(div, divisor, rem, expected_rem);

    div = 32'h7FFF_FFFF; divisor = 32'hFFFF_FFFF; #1;
    expected_rem = 32'h7FFF_FFFF % 32'hFFFF_FFFF;
    $fdisplay(fd, "%h %h %h", div, divisor, rem);
    check_result(div, divisor, rem, expected_rem);

    // 4. div = 0
    div = 32'h0000_0000; divisor = 32'h0000_0002; #1;
    expected_rem = 32'h0000_0000 % 32'h0000_0002;
    $fdisplay(fd, "%h %h %h", div, divisor, rem);
    check_result(div, divisor, rem, expected_rem);

    // 5. div < divisor
    div = 32'h0000_0005; divisor = 32'h0000_000A; #1;
    expected_rem = 32'h0000_0005 % 32'h0000_000A;
    $fdisplay(fd, "%h %h %h", div, divisor, rem);
    check_result(div, divisor, rem, expected_rem);

    // 6. div == divisor
    div = 32'h0000_000A; divisor = 32'h0000_000A; #1;
    expected_rem = 32'h0000_000A % 32'h0000_000A;
    $fdisplay(fd, "%h %h %h", div, divisor, rem);
    check_result(div, divisor, rem, expected_rem);

    // 7. div > divisor
    div = 32'h0000_0014; divisor = 32'h0000_000A; #1;
    expected_rem = 32'h0000_0014 % 32'h0000_000A;
    $fdisplay(fd, "%h %h %h", div, divisor, rem);
    check_result(div, divisor, rem, expected_rem);

    // 8. Random and systematic test vectors (at least 90 more)
    for (i = 0; i < 90; i = i + 1) begin
      // Avoid divisor = 0 except for a few cases above
      div = $random;
      divisor = $random;
      if (divisor == 0)
        divisor = i + 1; // ensure nonzero

      #1;
      expected_rem = div % divisor;
      $fdisplay(fd, "%h %h %h", div, divisor, rem);
      check_result(div, divisor, rem, expected_rem);
    end

    $display("Testbench completed with %0d errors.", error_count);
    $fclose(fd);
    $finish;
  end

endmodule

