`timescale 1ns/1ps

module counter_tb;

    // Inputs
    reg CLK;
    reg RST;
    reg UP_DOWN;

    // Outputs
    wire [3:0] Q;

    // File descriptor
    integer fd;
    integer error_count;
    integer test_count;
    integer i;
    reg [3:0] expected_Q;
    reg [3:0] Q_prev;

    // Instantiate the Unit Under Test (UUT)
    counter uut (
        .CLK(CLK),
        .RST(RST),
        .UP_DOWN(UP_DOWN),
        .Q(Q)
    );

    // Clock generation
    initial begin
        CLK = 0;
        forever #5 CLK = ~CLK; // 100MHz clock
    end

    // Timeout mechanism
    initial begin
        #10000;
        $display("ERROR: Simulation timeout at time %0t ns", $time);
        $finish;
    end

    // Error checking task
    task check_output;
        input [3:0] expected;
        input [3:0] actual;
        input [31:0] vector_num;
        begin
            if (expected !== actual) begin
                $display("ASSERTION FAILED at vector %0d, time %0t: Expected Q=%b, Got Q=%b", vector_num, $time, expected, actual);
                error_count = error_count + 1;
            end
        end
    endtask

    // Main stimulus and file writing
    initial begin
        fd = $fopen("test_vectors.txt", "w");
        if (fd) $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        error_count = 0;
        test_count = 0;

        // Initialize signals
        RST = 1'b1;
        UP_DOWN = 1'b0;
        Q_prev = 4'b0000;
        expected_Q = 4'b0000;

        // Apply reset
        @(negedge CLK);
        #1;
        $fdisplay(fd, "%b %b %b %b", CLK, RST, UP_DOWN, Q);
        check_output(4'b0000, Q, test_count);
        test_count = test_count + 1;

        // Release reset
        RST = 1'b0;
        @(negedge CLK);
        #1;
        $fdisplay(fd, "%b %b %b %b", CLK, RST, UP_DOWN, Q);
        expected_Q = 4'b1111; // Since Q-1 from 0 is 15 (wrap around)
        check_output(expected_Q, Q, test_count);
        Q_prev = Q;
        test_count = test_count + 1;

        // Test up counting
        UP_DOWN = 1'b1;
        for (i = 0; i < 20; i = i + 1) begin
            @(negedge CLK);
            #1;
            $fdisplay(fd, "%b %b %b %b", CLK, RST, UP_DOWN, Q);
            expected_Q = Q_prev + 1;
            check_output(expected_Q, Q, test_count);
            Q_prev = Q;
            test_count = test_count + 1;
        end

        // Test down counting
        UP_DOWN = 1'b0;
        for (i = 0; i < 20; i = i + 1) begin
            @(negedge CLK);
            #1;
            $fdisplay(fd, "%b %b %b %b", CLK, RST, UP_DOWN, Q);
            expected_Q = Q_prev - 1;
            check_output(expected_Q, Q, test_count);
            Q_prev = Q;
            test_count = test_count + 1;
        end

        // Test reset in the middle
        RST = 1'b1;
        @(negedge CLK);
        #1;
        $fdisplay(fd, "%b %b %b %b", CLK, RST, UP_DOWN, Q);
        expected_Q = 4'b0000;
        check_output(expected_Q, Q, test_count);
        Q_prev = Q;
        test_count = test_count + 1;

        RST = 1'b0;
        UP_DOWN = 1'b1;
        for (i = 0; i < 10; i = i + 1) begin
            @(negedge CLK);
            #1;
            $fdisplay(fd, "%b %b %b %b", CLK, RST, UP_DOWN, Q);
            expected_Q = Q_prev + 1;
            check_output(expected_Q, Q, test_count);
            Q_prev = Q;
            test_count = test_count + 1;
        end

        // Test alternating UP_DOWN
        for (i = 0; i < 30; i = i + 1) begin
            UP_DOWN = i[0]; // alternate
            @(negedge CLK);
            #1;
            $fdisplay(fd, "%b %b %b %b", CLK, RST, UP_DOWN, Q);
            if (UP_DOWN)
                expected_Q = Q_prev + 1;
            else
                expected_Q = Q_prev - 1;
            check_output(expected_Q, Q, test_count);
            Q_prev = Q;
            test_count = test_count + 1;
        end

        // Test multiple resets
        for (i = 0; i < 5; i = i + 1) begin
            RST = 1'b1;
            @(negedge CLK);
            #1;
            $fdisplay(fd, "%b %b %b %b", CLK, RST, UP_DOWN, Q);
            expected_Q = 4'b0000;
            check_output(expected_Q, Q, test_count);
            Q_prev = Q;
            test_count = test_count + 1;

            RST = 1'b0;
            UP_DOWN = ~UP_DOWN;
            @(negedge CLK);
            #1;
            $fdisplay(fd, "%b %b %b %b", CLK, RST, UP_DOWN, Q);
            if (UP_DOWN)
                expected_Q = Q_prev + 1;
            else
                expected_Q = Q_prev - 1;
            check_output(expected_Q, Q, test_count);
            Q_prev = Q;
            test_count = test_count + 1;
        end

        $display("Test completed with %0d vectors, %0d errors.", test_count, error_count);
        $fclose(fd);
        $finish;
    end

endmodule

