`timescale 1ns/1ps

module four_and_one_control_tb;

    // Inputs
    reg A1, A2, A3, A4, B1;
    reg VPWR, VGND, VPB, VNB;
    // Output
    wire Y;

    // DUT instantiation
    four_and_one_control dut (
        .A1(A1),
        .A2(A2),
        .A3(A3),
        .A4(A4),
        .B1(B1),
        .VPWR(VPWR),
        .VGND(VGND),
        .VPB(VPB),
        .VNB(VNB),
        .Y(Y)
    );

    integer fd;
    integer i;
    integer error_count;
    reg expected_Y;
    reg [4:0] input_vec;
    reg [3:0] supply_vec;
    integer test_count;

    // Timeout mechanism
    initial begin
        #10000;
        $display("Timeout reached at time %0t. Finishing simulation.", $time);
        $finish;
    end

    // Error checking task
    task check_output;
        input expected;
        begin
            if (Y !== expected) begin
                $display("ERROR at time %0t: Inputs: %b %b %b %b %b %b %b %b %b | Output Y: %b | Expected: %b", 
                    $time, A1, A2, A3, A4, B1, VPWR, VGND, VPB, VNB, Y, expected);
                error_count = error_count + 1;
            end
        end
    endtask

    initial begin
        fd = $fopen("test_vectors.txt", "w");
        if (fd)
            $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        error_count = 0;
        test_count = 0;

        // Loop over at least 100 test vectors (cover all logic input combinations and some supply variations)
        // 5 logic inputs: 32 combinations, try 4 supply combos for each = 128 tests
        for (i = 0; i < 128; i = i + 1) begin
            // Logic inputs
            input_vec = i[4:0];
            {A1, A2, A3, A4, B1} = input_vec;

            // Supply pins: cycle through 4 representative combinations
            // 00: VPWR=1, VGND=0, VPB=1, VNB=0 (normal)
            // 01: VPWR=1, VGND=0, VPB=0, VNB=1 (body bias)
            // 10: VPWR=0, VGND=1, VPB=1, VNB=0 (reverse supplies)
            // 11: VPWR=1, VGND=1, VPB=1, VNB=1 (all high)
            supply_vec = i[7:5];
            case (supply_vec)
                3'b000: begin VPWR=1; VGND=0; VPB=1; VNB=0; end
                3'b001: begin VPWR=1; VGND=0; VPB=0; VNB=1; end
                3'b010: begin VPWR=0; VGND=1; VPB=1; VNB=0; end
                3'b011: begin VPWR=1; VGND=1; VPB=1; VNB=1; end
                default: begin VPWR=1; VGND=0; VPB=1; VNB=0; end
            endcase

            #1; // Allow signals to propagate

            // Compute expected output
            if (B1 == 0)
                expected_Y = A1 & A2 & A3 & A4;
            else
                expected_Y = ~(A1 & A2 & A3 & A4);

            // Write test vector to file: A1 A2 A3 A4 B1 VPWR VGND VPB VNB Y
            $fdisplay(fd, "%b %b %b %b %b %b %b %b %b %b", 
                A1, A2, A3, A4, B1, VPWR, VGND, VPB, VNB, Y);

            // Assertion
            check_output(expected_Y);

            test_count = test_count + 1;
        end

        $display("Testbench completed. Total tests: %0d, Errors: %0d", test_count, error_count);
        $fclose(fd);
        $finish;
    end

endmodule

