module priority_encoder8 (
    input  wire [7:0] I,       // Inputs: I[7] is highest priority, I[0] is lowest
    output reg  [2:0] O        // Output code: O[2:0]
);

always @(*) begin
    casex (I)
        8'b1xxxxxxx: O = 3'd7;
        8'b01xxxxxx: O = 3'd6;
        8'b001xxxxx: O = 3'd5;
        8'b0001xxxx: O = 3'd4;
        8'b00001xxx: O = 3'd3;
        8'b000001xx: O = 3'd2;
        8'b0000001x: O = 3'd1;
        8'b00000001: O = 3'd0;
        default:     O = 3'd0;
    endcase
end

endmodule

