module dff_async_set_reset (
    input wire CLK,
    input wire D,
    input wire SET,
    input wire RESET,
    output reg Q,
    output reg Q_bar
);

always @(posedge CLK or posedge SET or posedge RESET) begin
    if (SET) begin
        Q     <= 1'b1;
        Q_bar <= 1'b1;
    end else if (RESET) begin
        Q     <= 1'b0;
        Q_bar <= 1'b0;
    end else begin
        Q     <= D;
        Q_bar <= ~D;
    end
end

