module dff_async_set_reset (
    input wire clk,
    input wire reset,   // Asynchronous active-low reset
    input wire set,     // Asynchronous active-low set
    input wire d,
    output reg q,
    output reg q_bar
);

always @(posedge clk or negedge reset or negedge set) begin
    if (!reset) begin
        q     <= 1'b0;
        q_bar <= 1'b0;
    end else if (!set) begin
        q     <= 1'b1;
        q_bar <= 1'b1;
    end else begin
        q     <= d;
        q_bar <= ~d;
    end
end

endmodule

