module binary_counter(
    input wire clk,
    input wire reset,
    output reg [3:0] count
);

    reg [21:0] divider_cnt;

    // The divider counts 0 to 4_999_999 (for 50,000,000 Hz / 10,000,000 = 5_000_000 cycles per second for 0.2 Hz)
    // But since we want the 4-bit counter to reach its max (15) after 1 second,
    // we want to increment the counter at a rate of 16 increments per second.
    // So, increment every 50_000_000 / 16 = 3_125_000 cycles.

    parameter DIVIDER_MAX = 22'd3_125_000 - 1; // Counts from 0 to 3,124,999

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            divider_cnt <= 22'd0;
            count <= 4'd0;
        end else begin
            if (divider_cnt == DIVIDER_MAX) begin
                divider_cnt <= 22'd0;
                count <= count + 1'b1;
            end else begin
                divider_cnt <= divider_cnt + 1'b1;
            end
        end
    end

endmodule

