        begin
            if (reset) begin
                divider_cnt_ref = 22'd0;
                count_ref = 4'd0;
            end else begin
                if (divider_cnt_ref == DIVIDER_MAX) begin
                    divider_cnt_ref = 22'd0;
                    count_ref = count_ref + 1'b1;
                end else begin
                    divider_cnt_ref = divider_cnt_ref + 1'b1;
                end
            end
        end
    endtask

    // Error checking task
    task check_outputs;
        begin
            if (count !== count_ref) begin
                $display("ERROR at time %0t: count mismatch! Expected: %0d, Got: %0d", $time, count_ref, count);
                error_count = error_count + 1;
            end
        end
    endtask

    // Save test vector
    task save_vector;
        input reg clk_in;
        input reg reset_in;
        input reg [3:0] count_out;
        begin
