        #(CLK_PERIOD);
        save_vector(clk, reset, count);
        ref_model(clk, reset);
        check_outputs();

        reset = 0;
        #(CLK_PERIOD);

        // Run for at least 100 test vectors (covering resets, normal operation, wrap-around)
        // We'll generate more than 100 vectors by running for 50*DIVIDER_MAX cycles (should wrap count several times)
        repeat (100) begin
            // Randomly assert reset every 25 cycles
            if ((test_num % 25) == 0 && test_num != 0) begin
                reset = 1;
                #(CLK_PERIOD);
                save_vector(clk, reset, count);
                ref_model(clk, reset);
                check_outputs();
                reset = 0;
                #(CLK_PERIOD);
            end

            // Step through divider cycles
            repeat (DIVIDER_MAX/20) begin // Shorten for simulation, but enough to see counter increment
                #(CLK_PERIOD);
                save_vector(clk, reset, count);
                ref_model(clk, reset);
                check_outputs();
                test_num = test_num + 1;
                if ($time - start_time > TIMEOUT) begin
                    $display("TIMEOUT at time %0t", $time);
                    $fclose(fd);
                    $finish;
                end
            end

            // After divider cycles, check increment
            #(CLK_PERIOD);
            save_vector(clk, reset, count);
            ref_model(clk, reset);
            check_outputs();
            test_num = test_num + 1;
            if ($time - start_time > TIMEOUT) begin
                $display("TIMEOUT at time %0t", $time);
                $fclose(fd);
                $finish;
            end
        end

        $display("Test completed with %0d errors.", error_count);
        $fclose(fd);
        $finish;
    end

