module my_module (
    input  wire A1,
    input  wire A2,
    input  wire B1,
    input  wire B2,
    input  wire C1,
    input  wire VPWR,
    input  wire VGND,
    input  wire VPB,
    input  wire VNB,
    output wire Y
);

    reg y_reg;

    always @(*) begin
        // Default output
        y_reg = 1'b0;

        if (A1 == 1'b1 && A2 == 1'b0) begin
            // Case 1: A1=1, A2=0 => Y=1
            y_reg = 1'b1;
        end
        else if (A1 == 1'b0 && A2 == 1'b1) begin
            // Case 2: A1=0, A2=1 => Y=0
            y_reg = 1'b0;
        end
        else if (A1 == 1'b1 && A2 == 1'b1) begin
            // Case 3: A1=1, A2=1 => Y=1 if B1 or B2=1
            if (B1 || B2)
                y_reg = 1'b1;
            else
                y_reg = 1'b0;
        end
        else if (A1 == 1'b0 && A2 == 1'b0) begin
