            end
        end
    endtask

    // Function to compute expected output
    function automatic compute_expected_X;
        input reg A, B, C, D;
        begin
            compute_expected_X = ( ~A & ~B & ~C &  D) |
                                ( ~A & ~B &  C & ~D) |
                                ( ~A &  B & ~C & ~D) |
                                ( ~A &  B &  C &  D) |
                                (  A & ~B & ~C & ~D) |
                                (  A & ~B &  C &  D) |
                                (  A &  B & ~C &  D) |
                                (  A &  B &  C & ~D);
        end
    endfunction

