module counter (
  // inputs:
  clk,
  reset,

  // outputs:
  count
);

  // inputs
  input clk;
  input reset;

  // outputs
  output reg [3:0] count;

  always @(posedge clk) begin
    if (reset) begin
      count <= 4'b0000;
    end else begin
      count <= count + 1'b1;
    end
  end

endmodule

