        en = 0;
        @(negedge clk);
        golden_count = 4'b0000;
        $fdisplay(fd, "%b %b %b %b", clk, rst, en, count);
        check_output(golden_count, count, 1);

        rst = 0;
        @(negedge clk);
        $fdisplay(fd, "%b %b %b %b", clk, rst, en, count);
        check_output(golden_count, count, 2);

        // Test 2: Enable counting
        en = 1;
        for (i = 3; i <= 22; i = i + 1) begin
            @(negedge clk);
            if (en) golden_count = golden_count + 1;
            $fdisplay(fd, "%b %b %b %b", clk, rst, en, count);
            check_output(golden_count, count, i);
        end

        // Test 3: Disable enable, counter should hold
        en = 0;
        for (i = 23; i <= 32; i = i + 1) begin
            @(negedge clk);
            $fdisplay(fd, "%b %b %b %b", clk, rst, en, count);
            check_output(golden_count, count, i);
