        // Test 4: Assert reset in the middle of operation
        rst = 1;
        @(negedge clk);
        golden_count = 4'b0000;
        $fdisplay(fd, "%b %b %b %b", clk, rst, en, count);
        check_output(golden_count, count, 33);

        rst = 0;
        @(negedge clk);
        $fdisplay(fd, "%b %b %b %b", clk, rst, en, count);
        check_output(golden_count, count, 34);

