            @(negedge clk);
            if (en) golden_count = golden_count + 1;
            $fdisplay(fd, "%b %b %b %b", clk, rst, en, count);
            check_output(golden_count, count, i);
        end

        // Test 6: Randomized test vectors
        for (i = 55; i <= 100; i = i + 1) begin
            // Randomize rst and en
            rst = $random % 2;
            en = $random % 2;
            @(negedge clk);
            if (rst)
                golden_count = 4'b0000;
            else if (en)
                golden_count = golden_count + 1;
            $fdisplay(fd, "%b %b %b %b", clk, rst, en, count);
            check_output(golden_count, count, i);
        end

        // Close file
        $fclose(fd);

        // Report result
        if (error_count == 0)
            $display("All test vectors passed.");
