module selector_module(
    input [1:0] SEL,
    input signed [7:0] A,
    input signed [7:0] B,
    output reg [7:0] OUT
);

    wire signed [7:0] sum, diff;
    wire signed [15:0] prod_full;
    wire signed [7:0] prod;
    wire signed [7:0] quo;

    assign sum = A + B;
    assign diff = A - B;
    assign prod_full = A * B;
    assign prod = prod_full[7:0]; // Take the lower 8 bits for product
    assign quo = A / B;

    always @(*) begin
        case (SEL)
            2'b00: OUT = sum;
            2'b01: OUT = diff;
            2'b10: OUT = prod;
            2'b11: OUT = quo;
            default: OUT = 8'b0; // optional for completeness
        endcase
    end

endmodule

