  wire eq;

  // DUT instantiation
  comparator dut (
    .A(A),
    .B(B),
    .op(op),
    .eq(eq)
  );

  // File descriptor
  integer fd;
  integer error_count;
  integer test_count;
  integer i, j, k;
  reg expected_eq;

  // Timeout mechanism
  initial begin
    #10000;
    $display("Timeout reached at time %0t. Finishing simulation.", $time);
    $finish;
  end

  // Error checking task
  task check_result;
    input [3:0] A_in;
    input [3:0] B_in;
    input [1:0] op_in;
    input eq_out;
    input expected;
    begin
      if (eq_out !== expected) begin
        $display("ERROR: A=%0d B=%0d op=%0d eq=%0d (expected %0d) at time %0t", A_in, B_in, op_in, eq_out, expected, $time);
        error_count = error_count + 1;
      end
    end
  endtask

  // Main stimulus
  initial begin
    error_count = 0;
    test_count = 0;
    fd = $fopen("test_vectors.txt", "w");
    if (fd)
      $display("File opened successfully");
    else begin
      $display("Failed to open file");
      $finish;
    end

    // Write header (optional, can be commented out if not needed)
    // $fdisplay(fd, "A[3:0] B[3:0] op[1:0] eq");

    // Exhaustive for op, partial for A/B (to get at least 100 vectors)
    // Try all op, and for A/B, sweep some values and some randoms

    // 1. Full sweep for op, A, B for small range (0-7)
    for (k = 0; k < 4; k = k + 1) begin // op
      for (i = 0; i < 8; i = i + 1) begin // A
        for (j = 0; j < 8; j = j + 1) begin // B
          A = i;
          B = j;
          op = k[1:0];
          #1;
          // Compute expected result
          case (op)
            2'b00: expected_eq = (A == B);
            2'b01: expected_eq = (A > B);
            2'b10: expected_eq = (A < B);
            2'b11: expected_eq = (A != B);
            default: expected_eq = 0;
          endcase
          // Write to file: A B op eq
          $fdisplay(fd, "%b %b %b %b", A, B, op, eq);
          test_count = test_count + 1;
          check_result(A, B, op, eq, expected_eq);
        end
      end
    end

    // 2. Add random vectors to reach at least 100 vectors
    while (test_count < 100) begin
      A = $random % 16;
      B = $random % 16;
      op = $random % 4;
      #1;
      case (op)
        2'b00: expected_eq = (A == B);
        2'b01: expected_eq = (A > B);
        2'b10: expected_eq = (A < B);
        2'b11: expected_eq = (A != B);
        default: expected_eq = 0;
      endcase
      $fdisplay(fd, "%b %b %b %b", A, B, op, eq);
      test_count = test_count + 1;
      check_result(A, B, op, eq, expected_eq);
    end

    $display("Testbench completed. Total tests: %0d, Errors: %0d", test_count, error_count);
    $fclose(fd);
    $finish;
  end

endmodule

