        reset_array[i] = 1'b0;
        enable_array[i] = 1'b1;
        data_in_array[i] = 5'd1;
      end else if (i == 3) begin
        reset_array[i] = 1'b1; // Another reset
        enable_array[i] = 1'b0;
        data_in_array[i] = 5'd0;
      end else begin
        reset_array[i] = ($random % 10 == 0) ? 1'b1 : 1'b0; // 10% chance of reset
        enable_array[i] = ($random % 2);
        data_in_array[i] = $random % 32;
      end
    end
