        error_count = 0;
        test_count = 0;
        rst = 0;
        ctrl = 0;
        prev_out = 2'b00;

        // Apply reset and check
        @(negedge clk);
        rst = 1; ctrl = 0;
        @(negedge clk);
        expected_out = 2'b00;
        #1;
        $fdisplay(fd, "%b %b %b %b", clk, rst, ctrl, out);
        check_output(expected_out);
        test_count = test_count + 1;

        // Release reset
        rst = 0;
        @(negedge clk);
        prev_out = out;

        // Test all transitions for at least 100 cycles
        for (i = 0; i < 100; i = i + 1) begin
            // Alternate ctrl every 10 cycles, randomize rst occasionally
            if (i % 10 == 0) ctrl = ~ctrl;
            if (i % 33 == 0) rst = 1; else rst = 0;

            @(negedge clk);
            // Compute expected_out
            if (rst) begin
                expected_out = 2'b00;
            end else begin
                if (ctrl) begin
                    expected_out = (prev_out == 2'b11) ? 2'b00 : prev_out + 1;
                end else begin
                    expected_out = (prev_out == 2'b00) ? 2'b11 : prev_out - 1;
                end
            end

            #1; // Allow output to settle
            $fdisplay(fd, "%b %b %b %b", clk, rst, ctrl, out);
            check_output(expected_out);

            prev_out = out;
            test_count = test_count + 1;
        end

        // Exhaustive test for all input combinations from all states
        for (prev_out = 0; prev_out < 4; prev_out = prev_out + 1) begin
            // Set DUT to prev_out state
            rst = 1; ctrl = 0;
            @(negedge clk);
            rst = 0;
            @(negedge clk);
            // Force DUT to prev_out by incrementing/decrementing
            while (out != prev_out) begin
                if (out < prev_out) begin
                    ctrl = 1;
                end else begin
                    ctrl = 0;
                end
                @(negedge clk);
            end
            // Now test both ctrl=0 and ctrl=1, with and without rst
            for (ctrl = 0; ctrl <= 1; ctrl = ctrl + 1) begin
                for (rst = 0; rst <= 1; rst = rst + 1) begin
                    @(negedge clk);
                    if (rst) begin
                        expected_out = 2'b00;
                    end else begin
                        if (ctrl) begin
                            expected_out = (prev_out == 2'b11) ? 2'b00 : prev_out + 1;
                        end else begin
                            expected_out = (prev_out == 2'b00) ? 2'b11 : prev_out - 1;
                        end
                    end
                    #1;
                    $fdisplay(fd, "%b %b %b %b", clk, rst, ctrl, out);
                    check_output(expected_out);
                    test_count = test_count + 1;
                end
            end
        end

        $display("Test completed: %0d vectors, %0d errors", test_count, error_count);
        $fclose(fd);
        $finish;
    end

endmodule

