    integer error_count;
    integer test_count;
    integer i;

    // Instantiate the DUT
    d_ff_async_reset uut (
        .CK(CK),
        .D(D),
        .RST(RST),
        .Q(Q),
        .QN(QN)
    );

    // Clock generation
    initial begin
        CK = 0;
        forever #5 CK = ~CK; // 10ns clock period
    end

    // Timeout mechanism
    initial begin
        #10000;
        $display("TIMEOUT: Simulation exceeded time limit at %0t ns", $time);
        $finish;
    end

    // Task to check outputs and report errors
    task check_output;
        input reg expected_Q;
        input reg expected_QN;
        begin
            if ((Q !== expected_Q) || (QN !== expected_QN)) begin
                $display("ERROR at time %0t: D=%b RST=%b Q=%b QN=%b (expected Q=%b QN=%b)", $time, D, RST, Q, QN, expected_Q, expected_QN);
                error_count = error_count + 1;
            end
        end
    endtask

    // Main stimulus and test vector generation
    initial begin
        fd = $fopen("test_vectors.txt", "w");
        if (fd)
            $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        error_count = 0;
        test_count = 0;

        // Header (optional, comment out if not needed)
        // $fdisplay(fd, "CK D RST Q QN");

        // Initialize
        D = 0;
        RST = 1;
        @(negedge CK);

        // Test asynchronous reset
        // 1. Assert reset low, check Q=0, QN=1
        D = 1'bx;
        RST = 0;
        @(negedge CK);
        #1;
        $fdisplay(fd, "%b %b %b %b %b", CK, D, RST, Q, QN);
        check_output(1'b0, 1'b1);
        test_count = test_count + 1;

        // 2. Deassert reset, set D=0, check Q follows D on next clock
        RST = 1;
        D = 0;
        @(negedge CK);
        @(posedge CK);
        #1;
        $fdisplay(fd, "%b %b %b %b %b", CK, D, RST, Q, QN);
        check_output(1'b0, 1'b1);
        test_count = test_count + 1;

        // 3. D=1, clock, check Q=1, QN=0
        D = 1;
        @(negedge CK);
        @(posedge CK);
        #1;
        $fdisplay(fd, "%b %b %b %b %b", CK, D, RST, Q, QN);
        check_output(1'b1, 1'b0);
        test_count = test_count + 1;

        // 4. D=0, clock, check Q=0, QN=1
        D = 0;
        @(negedge CK);
        @(posedge CK);
        #1;
        $fdisplay(fd, "%b %b %b %b %b", CK, D, RST, Q, QN);
        check_output(1'b0, 1'b1);
        test_count = test_count + 1;

        // 5. Assert reset asynchronously during operation
        D = 1;
        @(negedge CK);
        RST = 0;
        #2;
        $fdisplay(fd, "%b %b %b %b %b", CK, D, RST, Q, QN);
        check_output(1'b0, 1'b1);
        test_count = test_count + 1;

        // 6. Deassert reset, D=1, clock, check Q=1, QN=0
        RST = 1;
        @(negedge CK);
        @(posedge CK);
        #1;
        $fdisplay(fd, "%b %b %b %b %b", CK, D, RST, Q, QN);
        check_output(1'b1, 1'b0);
        test_count = test_count + 1;

        // 7. Randomized test vectors (cover at least 100 vectors)
        for (i = 0; i < 94; i = i + 1) begin
            // Randomize D and RST
            D = $random % 2;
            RST = $random % 2;
            @(negedge CK);
            if (!RST) begin
                #1;
                $fdisplay(fd, "%b %b %b %b %b", CK, D, RST, Q, QN);
                check_output(1'b0, 1'b1);
            end else begin
                @(posedge CK);
                #1;
                $fdisplay(fd, "%b %b %b %b %b", CK, D, RST, Q, QN);
                check_output(D, ~D);
            end
            test_count = test_count + 1;
        end

        // 8. Exhaustive test for all input combinations (optional, for completeness)
        for (D = 0; D <= 1; D = D + 1) begin
            for (RST = 0; RST <= 1; RST = RST + 1) begin
                @(negedge CK);
                if (!RST) begin
                    #1;
                    $fdisplay(fd, "%b %b %b %b %b", CK, D, RST, Q, QN);
                    check_output(1'b0, 1'b1);
                end else begin
                    @(posedge CK);
                    #1;
                    $fdisplay(fd, "%b %b %b %b %b", CK, D, RST, Q, QN);
                    check_output(D, ~D);
                end
                test_count = test_count + 1;
            end
        end

        $display("Testbench completed: %0d tests, %0d errors", test_count, error_count);
        $fclose(fd);
        $finish;
    end

endmodule

