module adder_subtractor_16bit (
    input  [15:0] A,
    input  [15:0] B,
    input         CIN,
    input         MODE,  // 0: add, 1: subtract
    output [15:0] Q
);

    wire [15:0] B_mod;
    wire        carry_in;
    wire [16:0] sum;

    // If MODE=0, B_mod = B (addition)
    // If MODE=1, B_mod = ~B (subtraction: two's complement)
    assign B_mod = (MODE) ? ~B : B;
    assign carry_in = (MODE) ? CIN : CIN; // Carry-in used as is (typically 1 for subtraction)

    // For subtraction: Q = A + ~B + 1
    // For addition:    Q = A +  B + CIN
    assign sum = A + B_mod + (carry_in ^ MODE);

    assign Q = sum[15:0];

endmodule

