module reverse16(
    input  [15:0] in,
    output reg [15:0] out
);

    // Function to reverse 8 bits
    function [7:0] reverse8;
        input [7:0] x;
        integer i;
        begin
            for (i = 0; i < 8; i = i + 1)
                reverse8[i] = x[7-i];
        end
    endfunction

    always @(*) begin
        out[15:8] = reverse8(in[15:8]); // Reverse upper 8 bits
        out[7:0]  = reverse8(in[7:0]);  // Reverse lower 8 bits
    end

endmodule

