        else begin
            $display("Failed to open file");
            $finish;
        end

        // Write header (optional, can be commented out)
        // $fdisplay(fd, "clk rst count");

        // Initialize
        rst = 0;
        expected_count = 0;
        error_count = 0;

        // Apply reset for two clock cycles
        @(negedge clk);
        @(negedge clk);
        rst = 1; // Deassert reset

        // Test sequence: 100 cycles
        for (i = 0; i < 100; i = i + 1) begin
            @(negedge clk);
            // Write test vector: clk rst count
            $fdisplay(fd, "%b %b %04b", clk, rst, count);

            // Check expected value
            if (i == 0) begin
                expected_count = 1; // After reset, first increment
            end else begin
                expected_count = expected_count + 1;
            end

            // Assertion
            if (count !== expected_count) begin
                $display("ERROR at time %0t: count=%b, expected=%b", $time, count, expected_count);
                error_count = error_count + 1;
            end
        end

