        @(negedge clk);
        rst = 0; // Assert reset
        @(negedge clk);
        $fdisplay(fd, "%b %b %04b", clk, rst, count);
        if (count !== 0) begin
            $display("ERROR after reset at time %0t: count=%b, expected=0000", $time, count);
            error_count = error_count + 1;
        end
        rst = 1; // Deassert reset
        expected_count = 1; // After reset, should increment from 0 to 1

        // Continue counting for 10 more cycles
        for (i = 0; i < 10; i = i + 1) begin
            @(negedge clk);
            $fdisplay(fd, "%b %b %04b", clk, rst, count);
            if (count !== expected_count) begin
                $display("ERROR after mid-reset at time %0t: count=%b, expected=%b", $time, count, expected_count);
