module calculator_tb;

    // Inputs
    reg [7:0] num1;
    reg [7:0] num2;
    reg [2:0] op;

    // Outputs
    wire [7:0] result;

    // File descriptor
    integer fd;
    integer i, j, k;
    integer error_count;
    reg [7:0] expected_result;
    reg [127:0] op_name;

    // Instantiate the calculator module
    calculator uut (
        .result(result),
        .num1(num1),
        .num2(num2),
        .op(op)
    );

    // Timeout mechanism
    initial begin
        #10000;
        $display("TIMEOUT: Simulation exceeded time limit at time %0t", $time);
        $finish;
    end

    // Error checking task
    task check_result;
        input [7:0] exp;
        input [7:0] got;
        input [7:0] in1;
        input [7:0] in2;
        input [2:0] op_in;
        begin
            if (exp !== got) begin
                $display("ERROR: num1=%0d num2=%0d op=%0d Expected=%0d Got=%0d at time %0t", in1, in2, op_in, exp, got, $time);
                error_count = error_count + 1;
            end
        end
    endtask

    // Main stimulus
    initial begin
        error_count = 0;
        fd = $fopen("test_vectors.txt", "w");
        if (fd)
            $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        // Write header (optional)
        // $fdisplay(fd, "num1 num2 op result");

        // Test all opcodes with representative values
        // For 3'b000: addition
        op = 3'b000;
        op_name = "ADD";
        for (i = 0; i < 20; i = i + 1) begin
            num1 = $random % 256;
            num2 = $random % 256;
            #1;
            expected_result = num1 + num2;
            check_result(expected_result, result, num1, num2, op);
            $fdisplay(fd, "%0d %0d %0d %0d", num1, num2, op, result);
        end

        // For 3'b001: subtraction
        op = 3'b001;
        op_name = "SUB";
        for (i = 0; i < 20; i = i + 1) begin
            num1 = $random % 256;
            num2 = $random % 256;
            #1;
            expected_result = num1 - num2;
            check_result(expected_result, result, num1, num2, op);
            $fdisplay(fd, "%0d %0d %0d %0d", num1, num2, op, result);
        end

        // For 3'b010: multiplication
        op = 3'b010;
        op_name = "MUL";
        for (i = 0; i < 20; i = i + 1) begin
            num1 = $random % 16; // limit to avoid overflow
            num2 = $random % 16;
            #1;
            expected_result = num1 * num2;
            check_result(expected_result, result, num1, num2, op);
            $fdisplay(fd, "%0d %0d %0d %0d", num1, num2, op, result);
        end

        // For 3'b011: division
        op = 3'b011;
        op_name = "DIV";
        for (i = 0; i < 20; i = i + 1) begin
            num1 = $random % 256;
            num2 = ($random % 255) + 1; // avoid division by zero
            #1;
            expected_result = num1 / num2;
            check_result(expected_result, result, num1, num2, op);
            $fdisplay(fd, "%0d %0d %0d %0d", num1, num2, op, result);
        end

        // For default case: opcodes 3'b100 to 3'b111
        for (k = 4; k < 8; k = k + 1) begin
            op = k[2:0];
            for (i = 0; i < 5; i = i + 1) begin
                num1 = $random % 256;
                num2 = $random % 256;
                #1;
                expected_result = 8'b0;
                check_result(expected_result, result, num1, num2, op);
                $fdisplay(fd, "%0d %0d %0d %0d", num1, num2, op, result);
            end
        end

        // Edge cases
        // Addition overflow
        op = 3'b000;
        num1 = 8'hFF; num2 = 8'h01; #1;
        expected_result = num1 + num2;
        check_result(expected_result, result, num1, num2, op);
        $fdisplay(fd, "%0d %0d %0d %0d", num1, num2, op, result);

        // Subtraction underflow
        op = 3'b001;
        num1 = 8'h00; num2 = 8'h01; #1;
        expected_result = num1 - num2;
        check_result(expected_result, result, num1, num2, op);
        $fdisplay(fd, "%0d %0d %0d %0d", num1, num2, op, result);

        // Multiplication overflow
        op = 3'b010;
        num1 = 8'hFF; num2 = 8'h02; #1;
        expected_result = num1 * num2;
        check_result(expected_result, result, num1, num2, op);
        $fdisplay(fd, "%0d %0d %0d %0d", num1, num2, op, result);

        // Division by 1
        op = 3'b011;
        num1 = 8'hAA; num2 = 8'h01; #1;
        expected_result = num1 / num2;
        check_result(expected_result, result, num1, num2, op);
        $fdisplay(fd, "%0d %0d %0d %0d", num1, num2, op, result);

        // Division by maximum
        op = 3'b011;
        num1 = 8'hFF; num2 = 8'hFF; #1;
        expected_result = num1 / num2;
        check_result(expected_result, result, num1, num2, op);
        $fdisplay(fd, "%0d %0d %0d %0d", num1, num2, op, result);

        // Division by zero (should not occur in module, but test anyway)
        op = 3'b011;
        num1 = 8'hAA; num2 = 8'h00; #1;
        // In Verilog, division by zero yields X, so expected_result is X
        if (result !== 8'bx) begin
            $display("WARNING: Division by zero did not yield X as expected");
        end
        $fdisplay(fd, "%0d %0d %0d %0d", num1, num2, op, result);

        // Default op code with random values
        op = 3'b101;
        num1 = 8'h12; num2 = 8'h34; #1;
        expected_result = 8'b0;
        check_result(expected_result, result, num1, num2, op);
        $fdisplay(fd, "%0d %0d %0d %0d", num1, num2, op, result);

        $display("Testbench completed with %0d errors.", error_count);
        $fclose(fd);
        $finish;
