    preload_memory(0, 36'h123456789);
    preload_memory(1, 36'hABCDEF012);
    preload_memory(2, 36'h0FEDCBA98);
    preload_memory(3, 36'h000000001);
    preload_memory(4, 36'hFFFFFFFFF);
    preload_memory(5, 36'h13579BDF0);

    // Test a set of known addresses (first 10)
    for (i = 0; i < 10; i = i + 1) begin
      test_addr(i);
    end

    // Test a set of random addresses
    for (i = 0; i < 80; i = i + 1) begin
      test_addr($random % MEM_DEPTH);
    end

    // Test some edge cases: lowest, highest, out-of-range
    test_addr(0);
    test_addr(MEM_DEPTH-1);
    test_addr(MEM_DEPTH); // Out of range
    test_addr(MEM_DEPTH+1); // Out of range
    test_addr({ADDR_WIDTH{1'b1}}); // All ones, should be out of range

    // Close file
    $fclose(fd);

    // Report errors
    if (error_count == 0)
      $display("All test cases passed!");
    else
      $display("Testbench completed with %0d errors.", error_count);

    $finish;
  end

  // Timeout mechanism
  initial begin
    #TIMEOUT;
    $display("ERROR: Simulation timed out after %0d time units.", TIMEOUT);
    timeout_flag = 1;
    $finish;
  end

  // Task to preload memory in DUT
  task preload_memory;
    input [ADDR_WIDTH-1:0] preload_addr;
    input [DATA_WIDTH-1:0] preload_data;
    begin
      dut.mem[preload_addr] = preload_data;
    end
  endtask

  // Task to check and log test vectors
  task test_addr;
    input [ADDR_WIDTH-1:0] test_addr_val;
    begin
      // Apply input
      @(negedge clk);
      addr = test_addr_val;

      // Wait for output to update on next clock edge
      @(posedge clk);
      #1; // Small delay to allow data to settle

      // Determine expected data
      if (test_addr_val < MEM_DEPTH)
        expected_data = dut.mem[test_addr_val];
      else
        expected_data = 36'd0;

      // Write test vector to file: addr data
      $fdisplay(fd, "%h %h", test_addr_val, data);

      // Assertion
      if (data !== expected_data) begin
        $display("ERROR at time %0t: addr=%h, expected data=%h, got data=%h", $time, test_addr_val, expected_data, data);
        error_count = error_count + 1;
      end
    end
  endtask

