module combinational_circuit_tb;

    // Inputs
    reg [3:0] A;
    reg [1:0] B;
    reg C;
    reg D;
    reg E;

    // Output
    wire X;

    // DUT instantiation
    combinational_circuit dut (
        .A(A),
        .B(B),
        .C(C),
        .D(D),
        .E(E),
        .X(X)
    );

    // File descriptor
    integer fd;
    integer error_count;
    integer test_count;
    integer i, j, k, l, m;
    reg expected_X;

    // Timeout mechanism
    initial begin
        #10000;
        $display("Timeout reached at time %0t. Finishing simulation.", $time);
        $finish;
    end

    // Error checking task
    task check_output;
        input [3:0] tA;
        input [1:0] tB;
        input tC;
        input tD;
        input tE;
        input tX;
        input tExpected_X;
        begin
            if (tX !== tExpected_X) begin
                $display("ASSERTION FAILED at time %0t: A=%0d B=%0d C=%0d D=%0d E=%0d | X=%0d (expected %0d)", 
                    $time, tA, tB, tC, tD, tE, tX, tExpected_X);
                error_count = error_count + 1;
            end
        end
    endtask

    // Main stimulus
    initial begin
        error_count = 0;
        test_count = 0;
        fd = $fopen("test_vectors.txt", "w");
        if (fd) $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        // Write header (optional, can be commented out if not needed)
        // $fdisplay(fd, "A[3:0] B[1:0] C D E X");

        // Exhaustive for small input space, random for the rest to reach at least 100 vectors
        // 4-bit A: 16, 2-bit B: 4, C:2, D:2, E:2 => 16*4*2*2*2 = 1024, but we will sample 100+ vectors

        // First, cover all combinations for A in [0:7], B in [0:3], C/D/E in [0:1] (covers 8*4*8=256)
        for (i = 0; i < 8; i = i + 1) begin
            for (j = 0; j < 4; j = j + 1) begin
                for (k = 0; k < 2; k = k + 1) begin
                    for (l = 0; l < 2; l = l + 1) begin
                        for (m = 0; m < 2; m = m + 1) begin
                            A = i;
                            B = j;
                            C = k;
                            D = l;
                            E = m;
                            #1; // Allow propagation

                            // Compute expected output
                            if ((A <= 5) && (B == 2))
                                expected_X = 1;
                            else if ((C == 1) && (D == 0) && (E == 1))
                                expected_X = 1;
                            else
                                expected_X = 0;

                            // Write to file: A[3:0] B[1:0] C D E X
                            $fdisplay(fd, "%b %b %b %b %b %b", A, B, C, D, E, X);

                            // Assertion
                            check_output(A, B, C, D, E, X, expected_X);

                            test_count = test_count + 1;
                        end
                    end
                end
            end
        end

        // If less than 100 vectors, pad with random tests (should not happen, but for completeness)
        while (test_count < 100) begin
            A = $random % 16;
            B = $random % 4;
            C = $random % 2;
            D = $random % 2;
            E = $random % 2;
            #1;

            if ((A <= 5) && (B == 2))
                expected_X = 1;
            else if ((C == 1) && (D == 0) && (E == 1))
                expected_X = 1;
            else
                expected_X = 0;

            $fdisplay(fd, "%b %b %b %b %b %b", A, B, C, D, E, X);
            check_output(A, B, C, D, E, X, expected_X);
            test_count = test_count + 1;
        end

        $display("Testbench completed. Total tests: %0d, Errors: %0d", test_count, error_count);
        $fclose(fd);
        $finish;
    end

endmodule

