    .reset(reset),
    .count_out(count_out)
  );

  // File handling
  integer fd;
  integer error_count;
  integer i;
  reg [3:0] expected_count;
  reg [3:0] prev_count;

  // Timeout parameters
  integer max_sim_time = 10000; // ns
  reg timeout_flag;

  // Clock generation: 10ns period
  initial begin
    clk = 0;
    forever #5 clk = ~clk;
  end

  // Timeout mechanism
  initial begin
    timeout_flag = 0;
    #max_sim_time;
    $display("ERROR: Simulation timeout at time %0t ns", $time);
    timeout_flag = 1;
    $finish;
  end

  // Error checking task
  task check_output;
    input [3:0] expected;
    input [3:0] actual;
    input integer vec_num;
    begin
      if (expected !== actual) begin
        $display("ASSERTION FAILED at vector %0d, time %0t: Expected count_out=%0d, Got count_out=%0d", vec_num, $time, expected, actual);
        error_count = error_count + 1;
      end
    end
  endtask

  // Main stimulus and test vector writing
  initial begin
    fd = $fopen("test_vectors.txt", "w");
    if (fd) $display("File opened successfully");
    else begin
      $display("Failed to open file");
      $finish;
    end

    error_count = 0;
    reset = 1;
    expected_count = 0;
    prev_count = 0;

    // Apply reset for 2 clock cycles
    @(negedge clk);
    $fdisplay(fd, "%b %b %b", clk, reset, count_out);
    check_output(0, count_out, 0);

    @(negedge clk);
    $fdisplay(fd, "%b %b %b", clk, reset, count_out);
    check_output(0, count_out, 1);

    // Release reset
    reset = 0;

    // Run at least 100 test vectors (including reset cycles)
    for (i = 2; i < 102; i = i + 1) begin
      @(negedge clk);

      // Write test vector: clk reset count_out
      $fdisplay(fd, "%b %b %b", clk, reset, count_out);

      // Compute expected count
      if (reset) begin
        expected_count = 0;
      end else begin
        expected_count = prev_count + 1;
      end

      check_output(expected_count, count_out, i);

      prev_count = count_out;

      // Randomly assert reset at some points to test reset functionality
      if ((i == 30) || (i == 60) || (i == 90)) begin
        reset = 1;
      end else if ((i == 31) || (i == 61) || (i == 91)) begin
        reset = 0;
      end
    end

    $display("Test completed with %0d errors.", error_count);
    $fclose(fd);
    $finish;
  end

endmodule

