        $finish;
    end

    // Function to compute expected Z
    function automatic expected_lut5;
        input [4:0] vec;
        begin
            case (vec)
                5'b00000: expected_lut5 = 1;
                5'b00001: expected_lut5 = 0;
                5'b00010: expected_lut5 = 0;
                5'b00011: expected_lut5 = 1;
                5'b00100: expected_lut5 = 1;
                5'b00101: expected_lut5 = 0;
                5'b00110: expected_lut5 = 0;
                5'b00111: expected_lut5 = 1;
                5'b01000: expected_lut5 = 1;
                5'b01001: expected_lut5 = 0;
                5'b01010: expected_lut5 = 0;
                5'b01011: expected_lut5 = 1;
                5'b01100: expected_lut5 = 1;
                5'b01101: expected_lut5 = 0;
                5'b01110: expected_lut5 = 0;
                5'b01111: expected_lut5 = 1;
                default: expected_lut5 = 1;
            endcase
        end
    endfunction

    // Task to check result and report errors
    task check_result;
        input [4:0] vec;
        input actual_Z;
        input expected_Z;
        begin
            if (actual_Z !== expected_Z) begin
                $display("ERROR: At time %0t, Input={SEL,D,C,B,A}=%b, Expected Z=%b, Got Z=%b", $time, vec, expected_Z, actual_Z);
