module ycbcr_thresholding_tb;

    // Inputs
    reg [7:0] Y, Cb, Cr, Ta, Tb, Tc, Td;
    // Output
    wire [7:0] binary;

    // DUT instantiation
    ycbcr_thresholding dut (
        .Y(Y),
        .Cb(Cb),
        .Cr(Cr),
        .Ta(Ta),
        .Tb(Tb),
        .Tc(Tc),
        .Td(Td),
        .binary(binary)
    );

    // File handling
    integer fd;
    integer error_count;
    integer test_count;
    integer i, j, k, l, m, n, p, q;
    reg [7:0] expected_binary;

    // Timeout mechanism
    initial begin
        #10000;
        $display("Timeout reached at time %0t. Simulation stopped.", $time);
        $finish;
    end

    // Task to check result and report errors
    task check_result;
        input [7:0] Y_t, Cb_t, Cr_t, Ta_t, Tb_t, Tc_t, Td_t, binary_t, expected_t;
        begin
            if (binary_t !== expected_t) begin
                $display("ERROR: Y=%0d Cb=%0d Cr=%0d Ta=%0d Tb=%0d Tc=%0d Td=%0d | binary=%0d expected=%0d at time %0t",
                         Y_t, Cb_t, Cr_t, Ta_t, Tb_t, Tc_t, Td_t, binary_t, expected_t, $time);
                error_count = error_count + 1;
            end
            // Assertion (SystemVerilog style, but also works in Verilog-2001 as if-statement)
            if (binary_t !== expected_t) begin
                $stop;
            end
        end
    endtask

    // Main stimulus
    initial begin
        error_count = 0;
        test_count = 0;
        fd = $fopen("test_vectors.txt", "w");
        if (fd) $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        // Write header (optional, can be commented out if not needed)
        // $fdisplay(fd, "Y Cb Cr Ta Tb Tc Td binary");

        // 1. Exhaustive test for a small subset (corner cases)
        for (i = 0; i < 2; i = i + 1) begin
            for (j = 0; j < 2; j = j + 1) begin
                for (k = 0; k < 2; k = k + 1) begin
                    for (l = 0; l < 2; l = l + 1) begin
                        for (m = 0; m < 2; m = m + 1) begin
                            for (n = 0; n < 2; n = n + 1) begin
                                for (p = 0; p < 2; p = p + 1) begin
                                    for (q = 0; q < 2; q = q + 1) begin
                                        // Assign values (0 or 255 for corners)
                                        Y  = i ? 8'd255 : 8'd0;
                                        Cb = j ? 8'd255 : 8'd0;
                                        Cr = k ? 8'd255 : 8'd0;
                                        Ta = l ? 8'd255 : 8'd0;
                                        Tb = m ? 8'd255 : 8'd0;
                                        Tc = n ? 8'd255 : 8'd0;
                                        Td = p ? 8'd255 : 8'd0;
                                        #1;
                                        // Compute expected output
                                        if (Y >= Ta && Y <= Tb && Cb >= Tc && Cb <= Td && Cr >= Tc && Cr <= Td)
                                            expected_binary = 8'b1;
                                        else
                                            expected_binary = 8'b0;
                                        // Write to file
                                        $fdisplay(fd, "%0d %0d %0d %0d %0d %0d %0d %0d", Y, Cb, Cr, Ta, Tb, Tc, Td, binary);
                                        // Check result
                                        check_result(Y, Cb, Cr, Ta, Tb, Tc, Td, binary, expected_binary);
                                        test_count = test_count + 1;
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end

        // 2. Randomized and representative test cases to reach at least 100 vectors
        for (i = 0; i < 92; i = i + 1) begin
            // Random but controlled values
            Y  = $random % 256;
            Cb = $random % 256;
            Cr = $random % 256;
            Ta = $random % 256;
            Tb = Ta + ($random % (256 - Ta)); // Ensure Tb >= Ta
            Tc = $random % 256;
            Td = Tc + ($random % (256 - Tc)); // Ensure Td >= Tc
            #1;
            if (Y >= Ta && Y <= Tb && Cb >= Tc && Cb <= Td && Cr >= Tc && Cr <= Td)
                expected_binary = 8'b1;
            else
                expected_binary = 8'b0;
            $fdisplay(fd, "%0d %0d %0d %0d %0d %0d %0d %0d", Y, Cb, Cr, Ta, Tb, Tc, Td, binary);
            check_result(Y, Cb, Cr, Ta, Tb, Tc, Td, binary, expected_binary);
            test_count = test_count + 1;
        end

        $display("Test completed: %0d vectors, %0d errors.", test_count, error_count);
        $fclose(fd);
        $finish;
    end

endmodule

