module counter_tb;

    // Inputs
    reg clk;
    reg en;
    // Output
    wire [3:0] out;

    // DUT instantiation
    counter uut (
        .clk(clk),
        .en(en),
        .out(out)
    );

    // File handling
    integer fd;
    integer error_count;
    integer test_num;
    integer i;
    reg [3:0] expected_out;
    reg [3:0] prev_out;

    // Timeout mechanism
    parameter TIMEOUT = 10000;

    // Clock generation: 10ns period
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    // Error checking task
    task check_output;
        input [3:0] expected;
        input [3:0] actual;
        input integer test_idx;
        begin
            if (expected !== actual) begin
                $display("ASSERTION FAILED at test %0d: expected %0d, got %0d at time %0t", test_idx, expected, actual, $time);
                error_count = error_count + 1;
            end
        end
    endtask

    // Main stimulus
    initial begin
        fd = $fopen("test_vectors.txt", "w");
        if (fd) $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        error_count = 0;
        en = 0;
        expected_out = 0;
        prev_out = 0;

        // Reset output to 0 at start
        force uut.out = 0;
        #1;
        release uut.out;
        #1;

        // Write header (optional, can be commented out)
        // $fdisplay(fd, "clk en out");

        // Generate at least 100 test vectors
        for (test_num = 0; test_num < 100; test_num = test_num + 1) begin
            // Randomize enable signal
            en = $random % 2;

            // Wait for rising edge of clk
            @(posedge clk);

            // Save previous output
            prev_out = expected_out;

            // Calculate expected output
            if (en)
                expected_out = prev_out + 1;
            else
                expected_out = prev_out;

            // Wait for output to update (should be at posedge clk)
            #1;

            // Write test vector: clk en out
            $fdisplay(fd, "%0d %0d %0d", clk, en, out);

            // Assertion
            check_output(expected_out, out, test_num);

            // Timeout check
            if ($time > TIMEOUT) begin
                $display("Simulation TIMEOUT at time %0t", $time);
                $fclose(fd);
                $finish;
            end
        end

        // Additional test: check wrap-around
        en = 1;
        for (i = 0; i < 20; i = i + 1) begin
            @(posedge clk);
            prev_out = expected_out;
            expected_out = prev_out + 1;
            #1;
            $fdisplay(fd, "%0d %0d %0d", clk, en, out);
            check_output(expected_out, out, 100 + i);
            if ($time > TIMEOUT) begin
                $display("Simulation TIMEOUT at time %0t", $time);
                $fclose(fd);
                $finish;
            end
        end

        $display("Simulation completed with %0d errors.", error_count);
        $fclose(fd);
        $finish;
    end

    // Timeout mechanism (failsafe)
    initial begin
        #TIMEOUT;
        $display("Simulation TIMEOUT (failsafe) at time %0t", $time);
        $fclose(fd);
        $finish;
    end

