module shift_register_tb;

    // Inputs
    reg CLK;
    reg LOAD;
    reg SHIFT;
    reg [3:0] DATA_IN;

    // Outputs
    wire [3:0] DATA_OUT;

    // Instantiate the Unit Under Test (UUT)
    shift_register uut (
        .CLK(CLK),
        .LOAD(LOAD),
        .SHIFT(SHIFT),
        .DATA_IN(DATA_IN),
        .DATA_OUT(DATA_OUT)
    );

    // File descriptor
    integer fd;
    integer error_count;
    integer test_count;
    integer i, j, k, l, m;
    reg [3:0] expected_data;
    reg [3:0] golden_data;
    reg [3:0] test_vectors_data [0:99];
    reg [3:0] test_vectors_load [0:99];
    reg [3:0] test_vectors_shift [0:99];
    reg [3:0] test_vectors_datain [0:99];
    reg [3:0] test_vectors_dataout [0:99];

    // Clock generation
    initial begin
        CLK = 0;
        forever #5 CLK = ~CLK;
    end

    // Timeout mechanism
    initial begin
        #10000;
        $display("ERROR: Simulation timed out at time %0t", $time);
        $finish;
    end

    // Main test process
    initial begin
        fd = $fopen("test_vectors.txt", "w");
        if (fd) $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        error_count = 0;
        test_count = 0;

        // Initialize inputs
        LOAD = 0;
        SHIFT = 0;
        DATA_IN = 4'b0000;

        // Wait for global reset
        #12;

        // Test 1: LOAD operation for all DATA_IN values
        for (i = 0; i < 16; i = i + 1) begin
            @(negedge CLK);
            LOAD = 1;
            SHIFT = 0;
            DATA_IN = i[3:0];
            @(negedge CLK);
            LOAD = 0;
            SHIFT = 0;
            DATA_IN = 4'b0000;
            @(posedge CLK);
            #1;
            expected_data = i[3:0];
            write_vector_and_check(LOAD, SHIFT, i[3:0], DATA_OUT, expected_data);
        end

        // Test 2: SHIFT operation after LOAD
        for (j = 0; j < 8; j = j + 1) begin
            @(negedge CLK);
            LOAD = 1;
            SHIFT = 0;
            DATA_IN = (j * 2 + 1);
            @(negedge CLK);
            LOAD = 0;
            SHIFT = 0;
            DATA_IN = 4'b0000;
            @(posedge CLK);
            golden_data = (j * 2 + 1);
            // Perform 4 shifts
            for (k = 0; k < 4; k = k + 1) begin
                @(negedge CLK);
                LOAD = 0;
                SHIFT = 1;
                @(negedge CLK);
                LOAD = 0;
                SHIFT = 0;
                @(posedge CLK);
                golden_data = {1'b0, golden_data[3:1]};
                #1;
                write_vector_and_check(LOAD, 1'b1, 4'b0000, DATA_OUT, golden_data);
            end
        end

        // Test 3: LOAD has priority over SHIFT
        for (l = 0; l < 8; l = l + 1) begin
            @(negedge CLK);
            LOAD = 1;
            SHIFT = 1;
            DATA_IN = l[3:0];
            @(negedge CLK);
            LOAD = 0;
            SHIFT = 0;
            DATA_IN = 4'b0000;
            @(posedge CLK);
            #1;
            expected_data = l[3:0];
            write_vector_and_check(1'b1, 1'b1, l[3:0], DATA_OUT, expected_data);
        end

        // Test 4: No operation (neither LOAD nor SHIFT)
        @(negedge CLK);
        LOAD = 1;
        SHIFT = 0;
        DATA_IN = 4'b1010;
        @(negedge CLK);
        LOAD = 0;
        SHIFT = 0;
        DATA_IN = 4'b0000;
        @(posedge CLK);
        golden_data = 4'b1010;
        for (m = 0; m < 5; m = m + 1) begin
            @(negedge CLK);
            LOAD = 0;
            SHIFT = 0;
            @(negedge CLK);
            LOAD = 0;
            SHIFT = 0;
            @(posedge CLK);
            #1;
            write_vector_and_check(1'b0, 1'b0, 4'b0000, DATA_OUT, golden_data);
        end

        // Test 5: Randomized test vectors
        for (i = 0; i < 60; i = i + 1) begin
            @(negedge CLK);
            LOAD = $random % 2;
            SHIFT = $random % 2;
            DATA_IN = $random % 16;
            @(negedge CLK);
            LOAD = 0;
            SHIFT = 0;
            @(posedge CLK);
            #1;
            // Compute expected value
            if (LOAD)
                expected_data = DATA_IN;
            else if (SHIFT)
                expected_data = {1'b0, DATA_OUT[3:1]};
            else
                expected_data = DATA_OUT;
            write_vector_and_check(LOAD, SHIFT, DATA_IN, DATA_OUT, expected_data);
        end

        $display("Test completed with %0d errors out of %0d tests.", error_count, test_count);
        $fclose(fd);
        $finish;
    end

    // Task to write test vector and check result
    task write_vector_and_check;
        input load_in;
        input shift_in;
        input [3:0] datain_in;
        input [3:0] dataout_actual;
        input [3:0] dataout_expected;
        begin
            test_count = test_count + 1;
