module register_tb;

    // Parameters
    parameter DATA_WIDTH = 8;
    parameter NUM_TESTS = 100;

    // DUT signals
    reg clk;
    reg rst;
    reg [DATA_WIDTH-1:0] data_in;
    reg enable;
    wire [DATA_WIDTH-1:0] data_out;

    // File handling
    integer fd;
    integer i;
    integer error_count;
    reg [DATA_WIDTH-1:0] expected_data;
    reg [DATA_WIDTH-1:0] reg_model;

    // Timeout
    integer start_time;
    integer TIMEOUT = 10000;

    // Instantiate the DUT
    register #(
        .DATA_WIDTH(DATA_WIDTH)
    ) dut (
        .clk(clk),
        .rst(rst),
        .data_in(data_in),
        .enable(enable),
        .data_out(data_out)
    );

    // Clock generation
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    // Error checking task
    task check_output;
        input [DATA_WIDTH-1:0] expected;
        input [DATA_WIDTH-1:0] actual;
        input integer test_num;
        begin
            if (expected !== actual) begin
                $display("ERROR at test %0d: expected %0h, got %0h at time %0t", test_num, expected, actual, $time);
                error_count = error_count + 1;
            end
        end
    endtask

    // Main stimulus
    initial begin
        // Open file
        fd = $fopen("test_vectors.txt", "w");
        if (fd) $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        // Write header (optional)
        // $fdisplay(fd, "clk rst enable data_in data_out");

        // Initialize
        error_count = 0;
        reg_model = 0;
        rst = 0;
        enable = 0;
        data_in = 0;
        @(negedge clk);

        // Apply reset
        rst = 1;
        enable = 0;
        data_in = $random;
        @(negedge clk);
        // Model reset
        reg_model = 0;
        // Write vector
        $fdisplay(fd, "%b %b %b %0h %0h", clk, rst, enable, data_in, data_out);
        check_output(0, data_out, 0);

        rst = 0;
        @(negedge clk);

        // Start time for timeout
        start_time = $time;

        // Main test loop
        for (i = 1; i <= NUM_TESTS; i = i + 1) begin
            // Randomize inputs
            enable = $random % 2;
            data_in = $random;
            // Occasionally assert reset
            if ((i % 17) == 0) rst = 1;
            else rst = 0;

            @(negedge clk);

            // Model behavior
            if (rst) reg_model = 0;
            else if (enable) reg_model = data_in;

            // Write test vector to file
            $fdisplay(fd, "%b %b %b %0h %0h", clk, rst, enable, data_in, data_out);

            // Assertion
            check_output(reg_model, data_out, i);

            // Timeout check
            if (($time - start_time) > TIMEOUT) begin
                $display("TIMEOUT: Simulation exceeded %0d time units", TIMEOUT);
                $fclose(fd);
                $finish;
            end
        end

        // Additional edge cases
        // Test: enable=0, data_in changes, output should not change
        rst = 0;
        enable = 1;
        data_in = 8'hAA;
        @(negedge clk);
        reg_model = data_in;
        $fdisplay(fd, "%b %b %b %0h %0h", clk, rst, enable, data_in, data_out);
        check_output(reg_model, data_out, NUM_TESTS+1);

        enable = 0;
        data_in = 8'h55;
        @(negedge clk);
        // reg_model should not change
        $fdisplay(fd, "%b %b %b %0h %0h", clk, rst, enable, data_in, data_out);
        check_output(reg_model, data_out, NUM_TESTS+2);

        // Test: reset overrides enable
        rst = 1;
        enable = 1;
        data_in = 8'hFF;
        @(negedge clk);
        reg_model = 0;
        $fdisplay(fd, "%b %b %b %0h %0h", clk, rst, enable, data_in, data_out);
        check_output(reg_model, data_out, NUM_TESTS+3);

        // Close file and finish
        $display("Simulation completed with %0d errors.", error_count);
        $fclose(fd);
