module flip_flop_tb;

    // Inputs
    reg CLK;
    reg D;
    reg RST;
    reg EN;

    // Output
    wire Q;

    // File descriptor
    integer fd;
    integer error_count;
    integer test_count;
    integer i;
    reg expected_Q;
    reg prev_Q;

    // Timeout mechanism
    parameter TIMEOUT = 10000;

    // Instantiate the flip_flop module
    flip_flop uut (
        .CLK(CLK),
        .D(D),
        .RST(RST),
        .EN(EN),
        .Q(Q)
    );

    // Clock generation: 10ns period
    initial begin
        CLK = 0;
        forever #5 CLK = ~CLK;
    end

    // Task to check output and report errors
    task check_output;
        input reg expected;
        begin
            if (Q !== expected) begin
                $display("ERROR at time %0t: D=%b EN=%b RST=%b Q=%b (expected %b)", $time, D, EN, RST, Q, expected);
                error_count = error_count + 1;
            end
        end
    endtask

    // Main stimulus
    initial begin
        // Open file for writing test vectors
        fd = $fopen("test_vectors.txt", "w");
        if (fd)
            $display("File opened successfully");
        else begin
            $display("Failed to open file");
            $finish;
        end

        error_count = 0;
        test_count = 0;
        D = 0;
        RST = 0;
        EN = 0;
        prev_Q = 0;
        expected_Q = 0;

        // Initial reset
        RST = 1;
        EN = 0;
        D = 0;
        @(negedge CLK);
        @(posedge CLK);
        #1;
        expected_Q = 0;
        check_output(expected_Q);
        $fdisplay(fd, "%b %b %b %b %b", CLK, D, RST, EN, Q);
        test_count = test_count + 1;

        RST = 0;
        EN = 0;
        D = 0;
        @(negedge CLK);

        // Generate 100+ test vectors with various combinations
        for (i = 0; i < 100; i = i + 1) begin
            // Randomize inputs
            D   = $random % 2;
            EN  = $random % 2;
            RST = (i % 17 == 0) ? 1 : 0; // Periodic reset
            @(negedge CLK);
            @(posedge CLK);
            #1;

            // Compute expected Q
            if (RST)
                expected_Q = 0;
            else if (EN)
                expected_Q = D;
            else
                expected_Q = prev_Q;

            check_output(expected_Q);

            // Write test vector: CLK D RST EN Q
            $fdisplay(fd, "%b %b %b %b %b", CLK, D, RST, EN, Q);

            prev_Q = expected_Q;
            test_count = test_count + 1;
        end

        // Exhaustive test for all input combinations (D, EN, RST) for one clock edge
        for (D = 0; D <= 1; D = D + 1) begin
            for (EN = 0; EN <= 1; EN = EN + 1) begin
                for (RST = 0; RST <= 1; RST = RST + 1) begin
                    @(negedge CLK);
                    @(posedge CLK);
                    #1;
                    if (RST)
                        expected_Q = 0;
                    else if (EN)
                        expected_Q = D;
                    else
                        expected_Q = prev_Q;

                    check_output(expected_Q);
                    $fdisplay(fd, "%b %b %b %b %b", CLK, D, RST, EN, Q);

                    prev_Q = expected_Q;
                    test_count = test_count + 1;
                end
            end
        end

        // Final report
        $display("Test completed with %0d test vectors, %0d errors.", test_count, error_count);

        // Close file
        $fclose(fd);

        $finish;
    end

    // Timeout mechanism
    initial begin
        #TIMEOUT;
        $display("TIMEOUT: Simulation exceeded %0d time units.", TIMEOUT);
        $fclose(fd);
        $finish;
    end

endmodule

