        // Also include some corner cases

        // 1. Exhaustive for SEL and EN, D0-D3 = simple patterns
        for (i = 0; i < 4; i = i + 1) begin
            for (j = 0; j < 2; j = j + 1) begin
                D0 = 8'h00;
                D1 = 8'hFF;
                D2 = 8'hAA;
                D3 = 8'h55;
                SEL = i[1:0];
                EN = j[0];
                #1;
                // Compute expected output
                if (EN) begin
                    case (SEL)
                        2'b00: exp_Y = D0;
                        2'b01: exp_Y = D1;
                        2'b10: exp_Y = D2;
                        2'b11: exp_Y = D3;
                        default: exp_Y = 8'bx;
                    endcase
                end else begin
                    exp_Y = 8'b0;
                end
                // Write to file
                $fdisplay(fd, "%h %h %h %h %b %b %h", D0, D1, D2, D3, SEL, EN, Y);
                // Check output
                check_output(exp_Y, Y, D0, D1, D2, D3, SEL, EN);
                test_count = test_count + 1;
            end
        end

        // 2. All EN=0 cases (should always output 0)
        for (i = 0; i < 10; i = i + 1) begin
            D0 = $random;
            D1 = $random;
            D2 = $random;
            D3 = $random;
            SEL = $random % 4;
            EN = 0;
            #1;
            exp_Y = 8'b0;
            $fdisplay(fd, "%h %h %h %h %b %b %h", D0, D1, D2, D3, SEL, EN, Y);
            check_output(exp_Y, Y, D0, D1, D2, D3, SEL, EN);
            test_count = test_count + 1;
        end

        // 3. All EN=1, SEL sweeps, D0-D3 random
        for (i = 0; i < 4; i = i + 1) begin
            D0 = $random;
            D1 = $random;
            D2 = $random;
            D3 = $random;
            SEL = i[1:0];
            EN = 1;
            #1;
            case (SEL)
                2'b00: exp_Y = D0;
                2'b01: exp_Y = D1;
                2'b10: exp_Y = D2;
                2'b11: exp_Y = D3;
                default: exp_Y = 8'bx;
            endcase
            $fdisplay(fd, "%h %h %h %h %b %b %h", D0, D1, D2, D3, SEL, EN, Y);
            check_output(exp_Y, Y, D0, D1, D2, D3, SEL, EN);
            test_count = test_count + 1;
        end

        // 4. Corner cases: all zeros, all ones, alternating bits
        D0 = 8'h00; D1 = 8'h00; D2 = 8'h00; D3 = 8'h00; EN = 1;
        for (i = 0; i < 4; i = i + 1) begin
            SEL = i[1:0];
            #1;
            case (SEL)
                2'b00: exp_Y = D0;
                2'b01: exp_Y = D1;
                2'b10: exp_Y = D2;
                2'b11: exp_Y = D3;
                default: exp_Y = 8'bx;
            endcase
            $fdisplay(fd, "%h %h %h %h %b %b %h", D0, D1, D2, D3, SEL, EN, Y);
            check_output(exp_Y, Y, D0, D1, D2, D3, SEL, EN);
            test_count = test_count + 1;
        end

        D0 = 8'hFF; D1 = 8'hFF; D2 = 8'hFF; D3 = 8'hFF; EN = 1;
        for (i = 0; i < 4; i = i + 1) begin
            SEL = i[1:0];
            #1;
            case (SEL)
                2'b00: exp_Y = D0;
                2'b01: exp_Y = D1;
                2'b10: exp_Y = D2;
                2'b11: exp_Y = D3;
                default: exp_Y = 8'bx;
            endcase
            $fdisplay(fd, "%h %h %h %h %b %b %h", D0, D1, D2, D3, SEL, EN, Y);
            check_output(exp_Y, Y, D0, D1, D2, D3, SEL, EN);
            test_count = test_count + 1;
        end

        D0 = 8'hAA; D1 = 8'h55; D2 = 8'hAA; D3 = 8'h55; EN = 1;
        for (i = 0; i < 4; i = i + 1) begin
            SEL = i[1:0];
            #1;
            case (SEL)
                2'b00: exp_Y = D0;
                2'b01: exp_Y = D1;
                2'b10: exp_Y = D2;
                2'b11: exp_Y = D3;
                default: exp_Y = 8'bx;
            endcase
            $fdisplay(fd, "%h %h %h %h %b %b %h", D0, D1, D2, D3, SEL, EN, Y);
            check_output(exp_Y, Y, D0, D1, D2, D3, SEL, EN);
            test_count = test_count + 1;
        end

        // 5. Randomized tests to reach at least 100 vectors
        for (i = 0; i < 60; i = i + 1) begin
            D0 = $random;
            D1 = $random;
            D2 = $random;
            D3 = $random;
            SEL = $random % 4;
            EN = $random % 2;
            #1;
            if (EN) begin
                case (SEL)
                    2'b00: exp_Y = D0;
                    2'b01: exp_Y = D1;
                    2'b10: exp_Y = D2;
                    2'b11: exp_Y = D3;
                    default: exp_Y = 8'bx;
                endcase
            end else begin
                exp_Y = 8'b0;
            end
            $fdisplay(fd, "%h %h %h %h %b %b %h", D0, D1, D2, D3, SEL, EN, Y);
            check_output(exp_Y, Y, D0, D1, D2, D3, SEL, EN);
            test_count = test_count + 1;
        end

        $display("Testbench completed. Total tests: %0d, Errors: %0d", test_count, error_count);

        // Close file
        $fclose(fd);

        $finish;
    end

endmodule
